const CLIENT_CSV_HEADERS: string[] = [
  "first_name",
  "last_name",
  "email",
  "phone",
  "status",
  "preferred_language",
  "package_slug",
  "admin_notes",
  "address_line1",
  "address_line2",
  "city",
  "state",
  "zip",
  "date_of_birth",
  "external_ref",
];
const CLIENT_CSV_REQUIRED_HEADERS: string[] = [
  "first_name",
  "last_name",
  "email",
];
const CLIENT_CSV_ALLOWED_STATUS: string[] = [
  "pending_payment",
  "onboarding",
  "active",
  "paused",
  "cancelled",
];
const CLIENT_CSV_ALLOWED_LANGUAGE: string[] = ["en", "es"];
const BULK_IMPORT_MAX_ROWS = 500;
const BULK_IMPORT_MAX_FILE_BYTES = 5 * 1024 * 1024;
const BULK_IMPORT_JOB_TTL_MS = 60 * 60 * 1000; // 1 hour
const BULK_IMPORT_FORBIDDEN_COLUMNS: string[] = [
  "password",
  "password_hash",
  "ssn",
  "social_security",
];

/** Off by default in production unless explicitly enabled. */
function resolveBulkCsvImportEnabled(): boolean {
  if (process.env.BULK_CSV_IMPORT_ENABLED === "0") return false;
  if (process.env.NODE_ENV === "production") {
    return (
      process.env.BULK_CSV_IMPORT_ENABLED === "1" ||
      process.env.BULK_CSV_IMPORT_ALLOW_PRODUCTION === "1"
    );
  }
  return true;
}

function sanitizeCsvCell(value: string | null | undefined): string {
  if (value == null) return "";
  // eslint-disable-next-line no-control-regex
  return String(value)
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "")
    .trim();
}

function normalizePhoneLast10(phone: string | null | undefined): string | null {
  if (!phone) return null;
  const digits = String(phone).replace(/\D/g, "");
  if (digits.length < 10) return null;
  return digits.slice(-10);
}

// Keep in sync with api/clientPhoneGuards.ts
const PLACEHOLDER_PHONE_LAST10 = new Set([
  "0000000000",
  "1111111111",
  "2222222222",
  "3333333333",
  "4444444444",
  "5555555555",
  "6666666666",
  "7777777777",
  "8888888888",
  "9999999999",
  "1234567890",
  "0123456789",
  "0987654321",
]);

/** Fake / staff-placeholder phones that must never create a client. */
function isPlaceholderPhone(phone: string | null | undefined): boolean {
  const last10 = normalizePhoneLast10(phone);
  if (!last10) return false;
  if (PLACEHOLDER_PHONE_LAST10.has(last10)) return true;
  if (/^(\d)\1{9}$/.test(last10)) return true;
  return false;
}

/**
 * Likely bot / gibberish person names (public Get Started spam).
 * Conservative: only flags when both names look synthetic.
 */
function looksLikeSpamPersonName(
  firstName: string | null | undefined,
  lastName: string | null | undefined,
): boolean {
  const first = String(firstName || "")
    .trim()
    .toLowerCase();
  const last = String(lastName || "")
    .trim()
    .toLowerCase();
  if (!first || !last) return false;

  const junkExact = new Set([
    "test",
    "testing",
    "demo",
    "asdf",
    "qwerty",
    "xxx",
    "sample",
    "fake",
    "none",
    "n/a",
    "na",
    "tbd",
    "unknown",
    "crmcontact",
  ]);
  if (junkExact.has(first) || junkExact.has(last)) return true;
  if (first.includes("test") && last.includes("test")) return true;

  const lettersOnly = (s: string) => s.replace(/[^a-z]/g, "");
  const vowelRatio = (s: string) => {
    const letters = lettersOnly(s);
    if (letters.length < 3) return 1;
    const vowels = (letters.match(/[aeiou]/g) || []).length;
    return vowels / letters.length;
  };

  const f = lettersOnly(first);
  const l = lettersOnly(last);
  if (
    f.length >= 4 &&
    l.length >= 4 &&
    vowelRatio(f) <= 0.26 &&
    vowelRatio(l) <= 0.26
  ) {
    return true;
  }

  if (/^[a-z]{5,}$/.test(f) && /^[a-z]{5,}$/.test(l)) {
    const entropy = (s: string) => new Set(s).size / s.length;
    if (
      entropy(f) >= 0.8 &&
      entropy(l) >= 0.8 &&
      vowelRatio(f) < 0.3 &&
      vowelRatio(l) < 0.3
    ) {
      return true;
    }
  }

  return false;
}

/** Dotted Gmail locals common in bot signups: a.b.c.d.e@gmail.com */
function looksLikeSpamEmail(email: string | null | undefined): boolean {
  const e = String(email || "")
    .trim()
    .toLowerCase();
  if (!e || !e.includes("@")) return false;
  const [local, domain] = e.split("@");
  if (!local || !domain) return false;
  if (domain.endsWith(".test") || domain === "example.com") return true;
  const dotParts = local.split(".").filter(Boolean);
  if (dotParts.length >= 4 && domain === "gmail.com") return true;
  return false;
}

const WEB_LEAD_REVIEW_LABEL = "web_lead_review";

function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

/** Reserved / integration-test domains that must never receive real team alerts. */
export function isUndeliverableNotifyEmail(email: string): boolean {
  const domain = String(email || "")
    .trim()
    .toLowerCase()
    .split("@")[1];
  if (!domain) return true;
  return (
    domain === "example.test" ||
    domain === "example.com" ||
    domain === "example.org" ||
    domain === "example.net" ||
    domain.endsWith(".test") ||
    domain.endsWith(".invalid") ||
    domain === "localhost"
  );
}

function isValidDateIso(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const d = new Date(`${value}T00:00:00Z`);
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === value;
}

