const MISSING_DB_VARS = ["DB_HOST", "DB_USER", "DB_PASSWORD", "DB_NAME"].filter(
  (k) => !process.env[k],
);
if (MISSING_DB_VARS.length > 0) {
  console.error(
    `❌ Missing required env vars: ${MISSING_DB_VARS.join(", ")}. All API routes will return 503.`,
  );
}

// Production = deployed on Vercel with a production environment. Local =
// anything else that isn't production, unless explicitly opted out — this
// keeps CI/staging runs without ALLOW_INSECURE_DEFAULTS from silently
// falling back to insecure defaults just because VERCEL isn't set there.
const IS_PROD =
  process.env.VERCEL_ENV === "production" ||
  process.env.NODE_ENV === "production";
const IS_LOCAL =
  !IS_PROD &&
  (process.env.ALLOW_INSECURE_DEFAULTS === "true" || !process.env.VERCEL);

/**
 * Stay under Vercel serverless request body limits (~4.5MB including multipart
 * overhead). Shared by MMS, admin case docs, report-wizard PDFs, and related
 * multipart routes. MCP base64 tools use the same 4MB decoded ceiling.
 */
const VERCEL_SAFE_UPLOAD_MAX_BYTES = 4 * 1024 * 1024;
/** In-memory encrypted blobs for VITEST CDN stubs (vitest:// URLs are not fetchable). */
const vitestCdnPlaintextByUrl = new Map<string, Buffer>();
/** Twilio concatenated SMS ceiling (Conversations hub + MCP send_sms). */
const SMS_MAX_BODY_CHARS = 1600;

/**
 * Affiliates feature flag. Set AFFILIATES_ENABLED=0|false to hide the admin
 * Affiliates / My Affiliate sections (lock icon), block those routes' APIs,
 * and disable public /r/:slug resolve until subscription pricing is ready.
 * Unset or 1|true = enabled (default).
 */
function affiliatesFeatureEnabled(): boolean {
  const v = String(process.env.AFFILIATES_ENABLED ?? "1")
    .trim()
    .toLowerCase();
  return v !== "0" && v !== "false" && v !== "off" && v !== "no";
}

/** Social DM inbox (Meta FB/IG) — env-gated until Graph messaging is live. */
function socialDmFeatureStatus(): {
  enabled: boolean;
  credentials_present: boolean;
  mode: "disabled" | "needs_credentials" | "ready" | "live";
} {
  const enabled =
    process.env.SOCIAL_DM_INBOX_ENABLED === "1" ||
    process.env.SOCIAL_DM_INBOX_ENABLED === "true";
  const credentials_present = !!(
    process.env.META_WEBHOOK_VERIFY_TOKEN ||
    process.env.META_PAGE_ACCESS_TOKEN ||
    process.env.META_APP_SECRET
  );
  let mode: "disabled" | "needs_credentials" | "ready" | "live" = "disabled";
  if (enabled && credentials_present) mode = "live";
  else if (enabled) mode = "needs_credentials";
  else if (credentials_present) mode = "ready";
  return { enabled, credentials_present, mode };
}

/**
 * Admin AI Ask — single kill switch. Off by default.
 * Set ADMIN_AI_ENABLED=1|true|on|yes to enable for super_admin + admin.
 */
function adminAiFeatureEnabled(): boolean {
  const v = String(process.env.ADMIN_AI_ENABLED ?? "0")
    .trim()
    .toLowerCase();
  return v === "1" || v === "true" || v === "on" || v === "yes";
}

function adminAiRoleAllowed(role: string | null | undefined): boolean {
  return role === "super_admin" || role === "admin";
}

