type AdminAiToolResult =
  | { ok: true; data: unknown }
  | {
      ok: true;
      dry_run: true;
      preview?: unknown;
      message?: string;
      data?: unknown;
    }
  | {
      ok: false;
      error: string;
      message: string;
      /** Machine-readable refuse reason (e.g. contact_required). */
      code?: string;
      /** Extra payload (e.g. ambiguous staff matches). */
      data?: unknown;
      /** Present when the action must be finished in the OFG CRM admin UI. */
      crm_required?: AdminAiCrmRequiredPayload;
    };

/** Standardized MCP → human handoff when a tool cannot complete the request. */
type AdminAiCrmRequiredPayload = {
  crm_required: true;
  reason: string;
  /** Paste-ready instruction for the staff user — surface this verbatim. */
  user_message: string;
  crm_href: string;
  crm_action: string;
  details?: Record<string, unknown>;
};

function adminAiBuildCrmHref(opts: {
  clientId?: number | null;
  caseId?: number | null;
  fundingId?: number | null;
}): string {
  if (opts.fundingId != null && Number(opts.fundingId) > 0) {
    return `/admin/funding?id=${Number(opts.fundingId)}`;
  }
  if (opts.clientId != null && Number(opts.clientId) > 0) {
    return `/admin/pipeline?client=${Number(opts.clientId)}`;
  }
  if (opts.caseId != null && Number(opts.caseId) > 0) {
    return `/admin/pipeline?case=${Number(opts.caseId)}`;
  }
  return "/admin/pipeline";
}

function adminAiCrmRequired(opts: {
  reason: string;
  userMessage: string;
  clientId?: number | null;
  caseId?: number | null;
  fundingId?: number | null;
  crmAction?: string;
  details?: Record<string, unknown>;
}): AdminAiCrmRequiredPayload {
  const href = adminAiBuildCrmHref(opts);
  const base = String(opts.userMessage || "").trim();
  const user_message = base.includes(href)
    ? base
    : `${base}${base.endsWith(".") ? "" : "."} Open CRM: ${href}`;
  return {
    crm_required: true,
    reason: opts.reason,
    user_message,
    crm_href: href,
    crm_action:
      opts.crmAction || "Complete this in the OFG CRM (admin portal)",
    ...(opts.details ? { details: opts.details } : {}),
  };
}

function adminAiClampLimit(raw: unknown, fallback = 10): number {
  const n = Number(raw);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(20, Math.max(1, Math.floor(n)));
}

function adminAiTruncateJson(value: unknown): string {
  const s = JSON.stringify(value);
  if (s.length <= ADMIN_AI_TOOL_RESULT_MAX) return s;
  return `${s.slice(0, ADMIN_AI_TOOL_RESULT_MAX)}…[truncated]`;
}

/** LLM / JSON sometimes stores escapes as literal `\u00e9`, `\n`, `\t`. */
export function decodeLiteralUnicodeEscapes(input: string): string {
  if (!input || !input.includes("\\")) return input;
  if (!/\\[nrtu]/.test(input)) return input;
  return input
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex: string) =>
      String.fromCharCode(parseInt(hex, 16)),
    )
    .replace(/\\n/g, "\n")
    .replace(/\\r/g, "\r")
    .replace(/\\t/g, "\t");
}

/** Trim + decode + clip — use for all Claude / tool string fields before store or display. */
function clipDecodedStr(s: unknown, max: number): string | null {
  if (typeof s !== "string") return null;
  const t = decodeLiteralUnicodeEscapes(s.trim());
  if (!t) return null;
  return t.slice(0, max);
}

function normalizeWorkTaskTitle(raw: unknown): string {
  return decodeLiteralUnicodeEscapes(String(raw ?? "").trim()).slice(0, 255);
}

function normalizeWorkTaskDescription(raw: unknown): string | null {
  const s = decodeLiteralUnicodeEscapes(String(raw ?? "").trim());
  if (!s) return null;
  return s.slice(0, 5000);
}

async function adminAiResolveCaseRow(
  args: Record<string, unknown>,
  scopedAffiliateIds?: number[],
): Promise<RowDataPacket | null> {
  const caseId =
    args.case_id != null && Number(args.case_id) > 0
      ? Number(args.case_id)
      : null;
  const caseNumber =
    typeof args.case_number === "string" && args.case_number.trim()
      ? args.case_number.trim().slice(0, 64)
      : null;
  if (!caseId && !caseNumber) return null;

  const where = ["cr.status <> 'cancelled'"];
  const params: any[] = [];
  if (caseId) {
    where.push("cr.id = ?");
    params.push(caseId);
  } else {
    where.push("cr.case_number = ?");
    params.push(caseNumber);
  }
  if (scopedAffiliateIds && scopedAffiliateIds.length > 0) {
    where.push("c.affiliate_id IN (?)");
    params.push(scopedAffiliateIds);
  }

  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT cr.id, cr.case_number, cr.client_id, cr.pipeline_stage, cr.status,
            cr.package_id, cr.created_at, cr.pipeline_stage_changed_at,
            c.first_name, c.last_name, c.email, c.phone, c.status AS client_status,
            c.preferred_language, c.assigned_admin_id, c.affiliate_id,
            p.name AS package_name,
            a.first_name AS assignee_first_name, a.last_name AS assignee_last_name
     FROM credit_repair_cases cr
     JOIN clients c ON c.id = cr.client_id
     LEFT JOIN packages p ON p.id = cr.package_id
     LEFT JOIN admins a ON a.id = c.assigned_admin_id
     WHERE ${where.join(" AND ")}
     LIMIT 1`,
    params,
  );
  return rows[0] || null;
}

/** Resolve client_id from client_id or case_id/case_number (affiliate-scoped). */
async function adminAiResolveClientId(
  args: Record<string, unknown>,
  scopedAffiliateIds?: number[],
): Promise<
  | {
      ok: true;
      clientId: number;
      caseId: number | null;
      caseNumber: string | null;
    }
  | { ok: false; error: "invalid_args" | "not_found"; message: string }
> {
  const clientId =
    args.client_id != null && Number(args.client_id) > 0
      ? Number(args.client_id)
      : null;
  if (clientId) {
    const where = ["c.id = ?"];
    const params: any[] = [clientId];
    if (scopedAffiliateIds && scopedAffiliateIds.length > 0) {
      where.push("c.affiliate_id IN (?)");
      params.push(scopedAffiliateIds);
    }
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT c.id FROM clients c WHERE ${where.join(" AND ")} LIMIT 1`,
      params,
    );
    if (!rows[0]) {
      return {
        ok: false,
        error: "not_found",
        message:
          "Client not found. Use search_clients — OFG client_id is not a HubSpot contact id.",
      };
    }
    return {
      ok: true,
      clientId,
      caseId: null,
      caseNumber: null,
    };
  }

  const caseRow = await adminAiResolveCaseRow(args, scopedAffiliateIds);
  if (
    args.case_id != null ||
    (typeof args.case_number === "string" && args.case_number.trim())
  ) {
    if (!caseRow) {
      return { ok: false, error: "not_found", message: "Case not found" };
    }
    return {
      ok: true,
      clientId: Number(caseRow.client_id),
      caseId: Number(caseRow.id),
      caseNumber: caseRow.case_number ? String(caseRow.case_number) : null,
    };
  }

  return {
    ok: false,
    error: "invalid_args",
    message: "client_id, case_id, or case_number is required",
  };
}

function adminAiConfirmTrue(raw: unknown): boolean {
  return raw === true || raw === "true" || raw === 1 || raw === "1";
}

/** Optional booleans that default true when omitted (Claude often omits). */
function adminAiBoolDefaultTrue(raw: unknown): boolean {
  if (raw === undefined || raw === null || raw === "") return true;
  if (raw === false || raw === "false" || raw === 0 || raw === "0") return false;
  return adminAiConfirmTrue(raw);
}

/** Writes require confirm=true AND exact confirm_phrase CONFIRM. */
const ADMIN_AI_WRITE_CONFIRM_PHRASE = "CONFIRM";

function adminAiWriteConfirmed(
  args: Record<string, unknown>,
): { ok: true } | { ok: false; message: string } {
  if (!adminAiConfirmTrue(args.confirm)) {
    return {
      ok: false,
      message:
        'Dry-run only. After the user approves, re-call with confirm=true and confirm_phrase="CONFIRM".',
    };
  }
  if (
    String(args.confirm_phrase || "").trim() !== ADMIN_AI_WRITE_CONFIRM_PHRASE
  ) {
    return {
      ok: false,
      message: `confirm=true also requires confirm_phrase=\"${ADMIN_AI_WRITE_CONFIRM_PHRASE}\" (exact).`,
    };
  }
  return { ok: true };
}

type AdminAiEmailAttachment = {
  filename: string;
  content: Buffer;
  contentType: string;
  source:
    | "case_document"
    | "round_report"
    | "base64"
    | null;
  source_id?: number | null;
};

async function adminAiLoadEmailAttachment(opts: {
  args: Record<string, unknown>;
  clientId: number | null;
}): Promise<
  | { ok: true; attachment: AdminAiEmailAttachment | null }
  | { ok: false; error: string; message: string }
> {
  const docId =
    opts.args.attachment_case_document_id != null &&
    Number(opts.args.attachment_case_document_id) > 0
      ? Number(opts.args.attachment_case_document_id)
      : null;
  const reportId =
    opts.args.attachment_round_report_id != null &&
    Number(opts.args.attachment_round_report_id) > 0
      ? Number(opts.args.attachment_round_report_id)
      : null;
  const b64Raw =
    typeof opts.args.attachment_base64 === "string"
      ? String(opts.args.attachment_base64).trim()
      : "";
  const sources = [docId, reportId, b64Raw ? true : null].filter(Boolean);
  if (sources.length === 0) {
    return { ok: true, attachment: null };
  }
  if (sources.length > 1) {
    return {
      ok: false,
      error: "invalid_args",
      message:
        "Use only one of attachment_case_document_id, attachment_round_report_id, or attachment_base64",
    };
  }

  const maxBytes = VERCEL_SAFE_UPLOAD_MAX_BYTES;

  if (docId) {
    if (!opts.clientId) {
      return {
        ok: false,
        error: "invalid_args",
        message:
          "attachment_case_document_id requires a client_id (or case) so ownership can be verified",
      };
    }
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, client_id, file_name, mime_type, file_size, storage_provider,
              storage_key, encrypted, enc_iv, enc_tag
       FROM client_documents WHERE id = ? LIMIT 1`,
      [docId],
    );
    if (!rows[0] || Number(rows[0].client_id) !== opts.clientId) {
      return {
        ok: false,
        error: "not_found",
        message: "Case document not found for this client",
      };
    }
    const doc = rows[0];
    if (Number(doc.file_size || 0) > maxBytes) {
      return {
        ok: false,
        error: "too_large",
        message: `Attachment exceeds ${Math.round(maxBytes / (1024 * 1024))}MB limit`,
      };
    }
    let buf: Buffer;
    try {
      if (doc.storage_provider === "cdn") {
        const cdnRes = await fetch(String(doc.storage_key));
        if (!cdnRes.ok) {
          return {
            ok: false,
            error: "send_failed",
            message: "Could not download case document from storage",
          };
        }
        const raw = Buffer.from(await cdnRes.arrayBuffer());
        buf =
          doc.encrypted && doc.enc_iv && doc.enc_tag
            ? decryptFile(raw, String(doc.enc_iv), String(doc.enc_tag))
            : raw;
      } else {
        const raw = await fs.promises.readFile(
          path.join(UPLOADS_DIR, String(doc.storage_key)),
        );
        buf =
          doc.encrypted && doc.enc_iv && doc.enc_tag
            ? decryptFile(raw, String(doc.enc_iv), String(doc.enc_tag))
            : raw;
      }
    } catch (e: any) {
      return {
        ok: false,
        error: "send_failed",
        message: String(e?.message || "Failed to load case document").slice(
          0,
          300,
        ),
      };
    }
    if (buf.length > maxBytes) {
      return {
        ok: false,
        error: "too_large",
        message: `Attachment exceeds ${Math.round(maxBytes / (1024 * 1024))}MB limit`,
      };
    }
    return {
      ok: true,
      attachment: {
        filename: String(doc.file_name || `document-${docId}.bin`),
        content: buf,
        contentType: String(doc.mime_type || "application/octet-stream"),
        source: "case_document",
        source_id: docId,
      },
    };
  }

  if (reportId) {
    if (!opts.clientId) {
      return {
        ok: false,
        error: "invalid_args",
        message:
          "attachment_round_report_id requires a client_id (or case) so ownership can be verified",
      };
    }
    // Wizard publish stores the file in round_report_pdfs; legacy rows may only
    // have client_round_reports.pdf_storage_key.
    const pdfRow = await findRoundReportPdfRow({
      clientId: opts.clientId,
      roundReportId: reportId,
    });
    if (pdfRow) {
      const buf = await loadRoundReportPdfBytes(pdfRow);
      if (!buf || buf.length === 0) {
        return {
          ok: false,
          error: "send_failed",
          message: "Could not download round report PDF from storage",
        };
      }
      if (buf.length > maxBytes) {
        return {
          ok: false,
          error: "too_large",
          message: `Attachment exceeds ${Math.round(maxBytes / (1024 * 1024))}MB limit`,
        };
      }
      const fname =
        String(pdfRow.file_name || "").trim() ||
        `OFG_Progress_Report_R${pdfRow.round_number}.pdf`;
      return {
        ok: true,
        attachment: {
          filename: fname,
          content: buf,
          contentType: "application/pdf",
          source: "round_report",
          source_id: reportId,
        },
      };
    }
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, client_id, round_number, pdf_file_name, pdf_storage_key,
              pdf_storage_provider, pdf_encrypted, pdf_enc_iv, pdf_enc_tag
       FROM client_round_reports
       WHERE id = ? AND pdf_storage_key IS NOT NULL LIMIT 1`,
      [reportId],
    );
    if (!rows[0] || Number(rows[0].client_id) !== opts.clientId) {
      return {
        ok: false,
        error: "not_found",
        message: "Round report PDF not found for this client",
      };
    }
    const rep = rows[0];
    let buf: Buffer;
    try {
      if (rep.pdf_storage_provider === "cdn") {
        const cdnRes = await fetch(String(rep.pdf_storage_key));
        if (!cdnRes.ok) {
          return {
            ok: false,
            error: "send_failed",
            message: "Could not download round report PDF from storage",
          };
        }
        const raw = Buffer.from(await cdnRes.arrayBuffer());
        buf =
          rep.pdf_encrypted && rep.pdf_enc_iv && rep.pdf_enc_tag
            ? decryptFile(raw, String(rep.pdf_enc_iv), String(rep.pdf_enc_tag))
            : raw;
      } else {
        const raw = await fs.promises.readFile(
          path.join(UPLOADS_DIR, String(rep.pdf_storage_key)),
        );
        buf =
          rep.pdf_encrypted && rep.pdf_enc_iv && rep.pdf_enc_tag
            ? decryptFile(raw, String(rep.pdf_enc_iv), String(rep.pdf_enc_tag))
            : raw;
      }
    } catch (e: any) {
      return {
        ok: false,
        error: "send_failed",
        message: String(e?.message || "Failed to load round report PDF").slice(
          0,
          300,
        ),
      };
    }
    if (buf.length > maxBytes) {
      return {
        ok: false,
        error: "too_large",
        message: `Attachment exceeds ${Math.round(maxBytes / (1024 * 1024))}MB limit`,
      };
    }
    const fname =
      String(rep.pdf_file_name || "").trim() ||
      `OFG_Progress_Report_R${rep.round_number}.pdf`;
    return {
      ok: true,
      attachment: {
        filename: fname,
        content: buf,
        contentType: "application/pdf",
        source: "round_report",
        source_id: reportId,
      },
    };
  }

  // base64 path
  const filename = String(opts.args.attachment_filename || "")
    .trim()
    .replace(/[/\\]/g, "_")
    .slice(0, 180);
  if (!filename) {
    return {
      ok: false,
      error: "invalid_args",
      message: "attachment_filename is required with attachment_base64",
    };
  }
  if (
    !/\.(pdf|png|jpe?g|gif|webp|txt|csv)$/i.test(filename)
  ) {
    return {
      ok: false,
      error: "invalid_args",
      message:
        "attachment_filename must end in .pdf, .png, .jpg, .jpeg, .gif, .webp, .txt, or .csv",
    };
  }
  let b64 = b64Raw;
  const dataUrl = /^data:([^;]+);base64,(.+)$/i.exec(b64);
  let contentType = "application/octet-stream";
  if (dataUrl) {
    contentType = dataUrl[1] || contentType;
    b64 = dataUrl[2];
  } else if (/\.pdf$/i.test(filename)) {
    contentType = "application/pdf";
  } else if (/\.png$/i.test(filename)) {
    contentType = "image/png";
  } else if (/\.jpe?g$/i.test(filename)) {
    contentType = "image/jpeg";
  }
  let buf: Buffer;
  try {
    buf = Buffer.from(b64.replace(/\s/g, ""), "base64");
  } catch {
    return {
      ok: false,
      error: "invalid_args",
      message: "attachment_base64 is not valid base64",
    };
  }
  if (!buf.length) {
    return {
      ok: false,
      error: "invalid_args",
      message: "attachment_base64 decoded to empty file",
    };
  }
  if (buf.length > maxBytes) {
    return {
      ok: false,
      error: "too_large",
      message: `Attachment exceeds ${Math.round(maxBytes / (1024 * 1024))}MB limit`,
    };
  }
  return {
    ok: true,
    attachment: {
      filename,
      content: buf,
      contentType,
      source: "base64",
      source_id: null,
    },
  };
}

/** When MCP marks a split paid, mirror admin PUT: ledger row + commission. */
async function adminAiRecordManualSplitPayment(opts: {
  splitId: number;
  clientId: number;
  caseId: number;
  amountCents: number;
  currency?: string | null;
  label?: string | null;
  paymentMethod?: string | null;
}): Promise<number | null> {
  const methodRaw = String(opts.paymentMethod || "")
    .trim()
    .toLowerCase();
  const allowedMethods = ["cash", "zelle", "venmo", "card_offline", "other"];
  const paymentMethod = allowedMethods.includes(methodRaw) ? methodRaw : null;
  const metadata = paymentMethod
    ? JSON.stringify({ payment_method: paymentMethod, source: "admin_ai" })
    : null;
  const [manualPayment] = await pool.query<ResultSetHeader>(
    `INSERT INTO payments
       (client_id, case_id, split_id, amount_cents, currency,
        status, provider, provider_transaction_id, metadata_json, paid_at)
     VALUES (?, ?, ?, ?, ?, 'succeeded', 'manual', ?, ?, NOW())`,
    [
      opts.clientId,
      opts.caseId,
      opts.splitId,
      opts.amountCents,
      opts.currency || "USD",
      `manual-ai-${crypto.randomUUID()}`,
      metadata,
    ],
  );
  const paymentId = Number(manualPayment.insertId);
  await pool.query(
    `UPDATE payment_splits SET payments_id = ? WHERE id = ? AND payments_id IS NULL`,
    [paymentId, opts.splitId],
  );
  try {
    await recordEnrollmentCommissions(
      opts.clientId,
      paymentId,
      opts.amountCents,
    );
  } catch (e: any) {
    console.error("[admin-ai] split paid commission", e?.message ?? e);
  }
  try {
    await notifyAdminsPaymentByClientId({
      clientId: opts.clientId,
      amountCents: opts.amountCents,
      caseId: opts.caseId,
      packageOrLabel: String(opts.label || "Installment"),
      kind: "installment",
    });
  } catch (e: any) {
    console.error("[admin-ai] split paid notify", e?.message ?? e);
  }
  return paymentId;
}

/**
 * Find an existing installment on the same case with the same due date + amount.
 * Used to prevent duplicate pending/paid twins when MCP/admin records payment
 * by inserting a new row instead of updating the open one.
 */
async function findMatchingPaymentSplit(opts: {
  caseId: number;
  dueDate: string;
  amountCents: number;
  statuses: Array<"pending" | "processing" | "paid" | "overdue" | "cancelled">;
}): Promise<RowDataPacket | null> {
  if (!(opts.caseId > 0) || !opts.statuses.length) return null;
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT *
     FROM payment_splits
     WHERE case_id = ?
       AND due_date = ?
       AND amount_cents = ?
       AND status IN (?)
     ORDER BY id ASC
     LIMIT 1`,
    [opts.caseId, opts.dueDate, opts.amountCents, opts.statuses],
  );
  return rows[0] || null;
}

async function adminAiHubspotPushPreview(adminId: number): Promise<string> {
  const mode = hubspotAuthMode();
  if (!mode) return "ofg_only_hubspot_not_configured";
  if (!(await adminCanExtractHubspot(adminId))) {
    return "ofg_only_admin_lacks_hubspot_extract";
  }
  const tokens = await loadHubspotTokens(adminId);
  if (!tokens?.access_token) {
    return mode === "oauth"
      ? "ofg_only_connect_hubspot_oauth"
      : "ofg_only_hubspot_token_unavailable";
  }
  return mode === "service_key"
    ? "will_push_on_create_service_key"
    : "will_push_on_create_oauth";
}

async function adminAiFindPhoneDuplicates(
  phone: string,
  scopedAffiliateIds?: number[],
): Promise<Array<Record<string, unknown>>> {
  const last10 = normalizePhoneLast10(phone);
  if (!last10) return [];
  // Include ALL statuses (incl. cancelled) so cancelled phones still block twins.
  const where = ["c.phone IS NOT NULL"];
  const params: any[] = [];
  if (scopedAffiliateIds && scopedAffiliateIds.length > 0) {
    where.push("c.affiliate_id IN (?)");
    params.push(scopedAffiliateIds);
  }
  // Narrow candidates; exact last-10 match in JS via normalizePhoneLast10
  where.push("c.phone LIKE ?");
  params.push(`%${last10.slice(-4)}`);
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT c.id, c.first_name, c.last_name, c.email, c.phone, c.status,
            c.pipeline_stage, c.preferred_language
     FROM clients c
     WHERE ${where.join(" AND ")}
     ORDER BY c.id DESC
     LIMIT 100`,
    params,
  );
  return rows
    .filter((r) => normalizePhoneLast10(String(r.phone || "")) === last10)
    .slice(0, 10)
    .map((r) => ({
      id: r.id,
      name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
      email: r.email,
      phone: r.phone,
      status: r.status,
      pipeline_stage: r.pipeline_stage,
      preferred_language: r.preferred_language,
      href: `/admin/pipeline?client=${r.id}`,
    }));
}

function adminPipelineHref(clientId: number, caseId?: unknown): string {
  const cid = Number(clientId);
  const kid = Number(caseId);
  if (Number.isFinite(kid) && kid > 0) {
    return `/admin/pipeline?client=${cid}&case=${kid}`;
  }
  return `/admin/pipeline?client=${cid}`;
}

function adminOnProspectBoard(row: {
  status?: unknown;
  pipeline_stage?: unknown;
  client_pipeline_stage?: unknown;
  case_stage?: unknown;
  case_status?: unknown;
}): boolean {
  const status = String(row.status || "");
  const stage = String(row.pipeline_stage || row.client_pipeline_stage || "");
  const caseStage = row.case_stage != null ? String(row.case_stage) : "";
  const caseStatus = row.case_status != null ? String(row.case_status) : "";
  if (status === "cancelled" || status === "funding") return false;
  const enrolled =
    !!caseStage && caseStage !== "prospect" && caseStatus !== "cancelled";
  if (enrolled) return false;
  return status === "prospect" || stage === "prospect";
}

/** Curated CRM tools for Admin Ask (read + guided writes). */
async function executeAdminAiTool(
  rawName: string,
  argsIn: Record<string, unknown>,
  ctx: { adminId: number },
): Promise<AdminAiToolResult> {
  const name = resolveAdminAiToolName(String(rawName || "").trim());
  const args = argsIn && typeof argsIn === "object" ? argsIn : {};
  try {
    const scope = await getAffiliateScope(ctx.adminId);
    const scopedIds = scope?.scopedAffiliateIds;

    if (name === "search_clients") {
      const q = String(args.q || "")
        .trim()
        .slice(0, 120);
      if (!q) {
        return { ok: false, error: "invalid_args", message: "q is required" };
      }
      const limit = adminAiClampLimit(args.limit, 10);
      const ident = clientIdentitySearchSql(q);
      const like = likeContains(q);
      const where = [
        `(${ident.sql} OR EXISTS (
            SELECT 1 FROM credit_repair_cases cr0
            WHERE cr0.client_id = c.id AND cr0.case_number LIKE ? ESCAPE '!'
          ))`,
      ];
      const params: any[] = [...ident.params, like];
      if (scopedIds && scopedIds.length > 0) {
        where.push("c.affiliate_id IN (?)");
        params.push(scopedIds);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT c.id, c.first_name, c.last_name, c.email, c.status,
                c.pipeline_stage AS client_pipeline_stage, c.preferred_language,
                (
                  SELECT cr.id FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_id,
                (
                  SELECT cr.case_number FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_number,
                (
                  SELECT cr.pipeline_stage FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_stage,
                (
                  SELECT cr.status FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_status
         FROM clients c
         WHERE ${where.join(" AND ")}
         ORDER BY c.updated_at DESC, c.id DESC
         LIMIT ?`,
        [...params, limit],
      );
      const fundingWhere: string[] = [];
      const fundingParams: any[] = [];
      {
        const s = fundingApplicationSearchSql(q);
        fundingWhere.push(s.sql);
        fundingParams.push(...s.params);
      }
      const [fundingRows] = await pool.query<RowDataPacket[]>(
        `SELECT fa.id, fa.funding_type, fa.status, fa.first_name, fa.last_name,
                fa.email, fa.phone, fa.preferred_language, fa.client_id, fa.created_at
         FROM funding_applications fa
         WHERE ${fundingWhere.join(" AND ")}
         ORDER BY fa.updated_at DESC, fa.id DESC
         LIMIT ?`,
        [...fundingParams, limit],
      );
      return {
        ok: true,
        data: {
          clients: rows.map((r) => ({
            id: r.id,
            name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            email: r.email,
            status: r.status,
            client_pipeline_stage: r.client_pipeline_stage,
            preferred_language: r.preferred_language,
            case_id: r.case_id,
            case_number: r.case_number,
            case_stage: r.case_stage,
            case_status: r.case_status,
            on_prospect_board: adminOnProspectBoard({
              status: r.status,
              client_pipeline_stage: r.client_pipeline_stage,
              case_stage: r.case_stage,
              case_status: r.case_status,
            }),
            href: adminPipelineHref(Number(r.id), r.case_id),
          })),
          funding_applications: fundingRows.map((r) => ({
            id: Number(r.id),
            funding_type: r.funding_type,
            status: r.status,
            name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            email: r.email,
            phone: r.phone || null,
            preferred_language: r.preferred_language,
            client_id: r.client_id ? Number(r.client_id) : null,
            href: `/admin/funding?id=${r.id}`,
          })),
        },
      };
    }

    if (
      name === "search_contacts" ||
      name === "get_contact" ||
      name === "create_contact" ||
      name === "update_contact" ||
      name === "convert_contact" ||
      name === "send_contact_sms" ||
      name === "send_contact_email"
    ) {
      // CRM Contacts are admin-only (same as denyAffiliateAccess on REST routes)
      if (scope) {
        return {
          ok: false,
          error: "forbidden",
          message: "Contacts tools are not available to affiliate accounts",
        };
      }
    }

    if (name === "search_contacts") {
      const q = String(args.q || "")
        .trim()
        .slice(0, 120);
      if (!q) {
        return { ok: false, error: "invalid_args", message: "q is required" };
      }
      const limit = adminAiClampLimit(args.limit, 10);
      const like = likeContains(q);
      const parts = [
        `c.email LIKE ? ESCAPE '!'`,
        `c.first_name LIKE ? ESCAPE '!'`,
        `c.last_name LIKE ? ESCAPE '!'`,
        `CONCAT(c.first_name,' ',c.last_name) LIKE ? ESCAPE '!'`,
        `c.phone LIKE ? ESCAPE '!'`,
      ];
      const params: any[] = [like, like, like, like, like];
      const digits = String(q || "").replace(/\D/g, "");
      if (digits.length >= 7 && digits.length <= 15) {
        parts.push(`${mysqlPhoneDigitsExpr("c.phone")} LIKE ?`);
        params.push(`%${digits}%`);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT c.id, c.first_name, c.last_name, c.email, c.phone,
                c.preferred_language, c.city, c.state
         FROM contacts c
         WHERE c.deleted_at IS NULL
           AND c.converted_client_id IS NULL
           AND (${parts.join(" OR ")})
         ORDER BY c.updated_at DESC, c.id DESC
         LIMIT ?`,
        [...params, limit],
      );
      return {
        ok: true,
        data: {
          contacts: rows.map((r) => ({
            id: Number(r.id),
            name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            email: r.email,
            phone: r.phone,
            preferred_language: r.preferred_language === "es" ? "es" : "en",
            city: r.city || null,
            state: r.state || null,
            href: `/admin/contacts`,
          })),
        },
      };
    }

    if (name === "get_contact") {
      const contactId =
        args.contact_id != null && Number(args.contact_id) > 0
          ? Number(args.contact_id)
          : 0;
      if (!contactId) {
        return {
          ok: false,
          error: "invalid_args",
          message: "contact_id is required",
        };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM contacts
         WHERE id = ? AND deleted_at IS NULL
         LIMIT 1`,
        [contactId],
      );
      if (!rows[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Contact not found",
        };
      }
      const mapped = mapCrmContactRow(rows[0]);
      return {
        ok: true,
        data: {
          ...mapped,
          name: `${mapped.first_name} ${mapped.last_name}`.trim(),
          href: `/admin/contacts`,
          on_pipeline: mapped.converted_client_id != null,
          guidance:
            mapped.converted_client_id != null
              ? `Already converted to client_id=${mapped.converted_client_id}. Open /admin/pipeline?client=${mapped.converted_client_id}.`
              : "Address-book contact (not on Pipeline). Use convert_contact to add as prospect when ready.",
        },
      };
    }

    if (name === "search_referrers") {
      const q = String(args.q || "")
        .trim()
        .slice(0, 120);
      if (!q) {
        return { ok: false, error: "invalid_args", message: "q is required" };
      }
      const limit = adminAiClampLimit(args.limit, 10);
      const like = likeContains(q);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT r.id, r.first_name, r.last_name, r.email, r.phone, r.company,
                r.category, r.preferred_language, r.status,
                (SELECT COUNT(*) FROM clients c WHERE c.referrer_id = r.id) AS clients_count
         FROM referrers r
         WHERE r.first_name LIKE ? ESCAPE '!'
            OR r.last_name LIKE ? ESCAPE '!'
            OR CONCAT(r.first_name,' ',r.last_name) LIKE ? ESCAPE '!'
            OR COALESCE(r.email,'') LIKE ? ESCAPE '!'
            OR COALESCE(r.phone,'') LIKE ? ESCAPE '!'
            OR COALESCE(r.company,'') LIKE ? ESCAPE '!'
         ORDER BY r.status = 'active' DESC, r.updated_at DESC, r.id DESC
         LIMIT ?`,
        [like, like, like, like, like, like, limit],
      );
      return {
        ok: true,
        data: {
          referrers: rows.map((r) => ({
            id: r.id,
            name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            email: r.email,
            phone: r.phone,
            company: r.company,
            category: r.category,
            preferred_language: r.preferred_language,
            status: r.status,
            clients_count: Number(r.clients_count || 0),
            has_email: !!(r.email && String(r.email).trim()),
          })),
        },
      };
    }

    if (name === "update_referrer") {
      const referrerId = Number(args.referrer_id);
      if (!Number.isFinite(referrerId) || referrerId <= 0) {
        return {
          ok: false,
          error: "invalid_args",
          message: "referrer_id is required",
        };
      }
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, phone, company, status
         FROM referrers WHERE id = ? LIMIT 1`,
        [referrerId],
      );
      if (!existing[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Referrer not found",
        };
      }
      const patch: Record<string, string | null> = {};
      if (args.email !== undefined) {
        const email = String(args.email || "")
          .trim()
          .toLowerCase();
        if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Invalid email address",
          };
        }
        patch.email = email || null;
      }
      if (args.phone !== undefined) {
        patch.phone = String(args.phone || "").trim() || null;
      }
      if (args.company !== undefined) {
        patch.company = String(args.company || "").trim() || null;
      }
      if (args.first_name !== undefined) {
        const v = String(args.first_name || "").trim();
        if (!v) {
          return {
            ok: false,
            error: "invalid_args",
            message: "first_name cannot be empty",
          };
        }
        patch.first_name = v;
      }
      if (args.last_name !== undefined) {
        const v = String(args.last_name || "").trim();
        if (!v) {
          return {
            ok: false,
            error: "invalid_args",
            message: "last_name cannot be empty",
          };
        }
        patch.last_name = v;
      }
      if (args.status !== undefined) {
        const status = String(args.status || "").trim();
        if (status !== "active" && status !== "inactive") {
          return {
            ok: false,
            error: "invalid_args",
            message: "status must be active or inactive",
          };
        }
        patch.status = status;
      }
      if (Object.keys(patch).length === 0) {
        return {
          ok: false,
          error: "invalid_args",
          message:
            "Provide at least one of email, phone, company, first_name, last_name, status",
        };
      }
      const preview = {
        referrer_id: referrerId,
        current: {
          name: `${existing[0].first_name || ""} ${existing[0].last_name || ""}`.trim(),
          email: existing[0].email,
          phone: existing[0].phone,
          company: existing[0].company,
          status: existing[0].status,
        },
        patch,
      };
      if (!adminAiWriteConfirmed(args).ok) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show referrer update. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const sets = Object.keys(patch).map((k) => `${k} = ?`);
      await pool.query(
        `UPDATE referrers SET ${sets.join(", ")} WHERE id = ?`,
        [...Object.values(patch), referrerId],
      );
      const [updated] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, phone, company, category, status
         FROM referrers WHERE id = ? LIMIT 1`,
        [referrerId],
      );
      return {
        ok: true,
        data: { referrer: updated[0], href: `/admin/referrers` },
      };
    }

    if (name === "update_client") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const clientId = resolved.clientId;
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, phone, preferred_language,
                assigned_admin_id, status
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      if (!existing[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Client not found",
        };
      }

      const patch: Record<string, string | number | null> = {};
      if (args.email !== undefined) {
        const email = String(args.email || "")
          .trim()
          .toLowerCase();
        if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Invalid email address",
          };
        }
        patch.email = email || null;
      }
      if (args.phone !== undefined) {
        patch.phone = String(args.phone || "").trim().slice(0, 20) || null;
      }
      if (args.first_name !== undefined) {
        const v = String(args.first_name || "").trim().slice(0, 100);
        if (!v) {
          return {
            ok: false,
            error: "invalid_args",
            message: "first_name cannot be empty",
          };
        }
        patch.first_name = v;
      }
      if (args.last_name !== undefined) {
        const v = String(args.last_name || "").trim().slice(0, 100);
        if (!v) {
          return {
            ok: false,
            error: "invalid_args",
            message: "last_name cannot be empty",
          };
        }
        patch.last_name = v;
      }
      if (args.preferred_language !== undefined) {
        const lang = String(args.preferred_language || "").trim();
        if (lang !== "en" && lang !== "es") {
          return {
            ok: false,
            error: "invalid_args",
            message: "preferred_language must be en or es",
          };
        }
        patch.preferred_language = lang;
      }
      const namedOwner = await resolveMcpStaffAssignee({
        adminId: args.assigned_admin_id,
        name: args.assigned_admin_name,
        email: args.assigned_admin_email,
      });
      if (namedOwner.ok === false) return namedOwner;
      if (namedOwner.requested) {
        patch.assigned_admin_id = namedOwner.id;
      } else if (
        patch.preferred_language === "en" ||
        patch.preferred_language === "es"
      ) {
        const ownerId = await resolveLanguageOwnerAdminId(
          patch.preferred_language,
        );
        patch.assigned_admin_id = ownerId;
      }

      if (Object.keys(patch).length === 0) {
        return {
          ok: false,
          error: "invalid_args",
          message:
            "Provide at least one of email, phone, first_name, last_name, preferred_language, assigned_admin_id / assigned_admin_name",
        };
      }

      const nextEmail =
        patch.email !== undefined
          ? (patch.email as string | null)
          : existing[0].email
            ? String(existing[0].email)
            : null;
      const nextPhone =
        patch.phone !== undefined
          ? (patch.phone as string | null)
          : existing[0].phone
            ? String(existing[0].phone)
            : null;
      if (!nextEmail && !nextPhone) {
        return {
          ok: false,
          error: "invalid_args",
          message: "Email or phone is required — cannot clear both",
          code: "contact_required",
        };
      }

      const preview = {
        client_id: clientId,
        case_id: resolved.caseId,
        case_number: resolved.caseNumber,
        current: {
          name: `${existing[0].first_name || ""} ${existing[0].last_name || ""}`.trim(),
          email: existing[0].email,
          phone: existing[0].phone,
          preferred_language: existing[0].preferred_language,
          assigned_admin_id: existing[0].assigned_admin_id,
        },
        patch,
        note:
          namedOwner.requested
            ? "assigned_admin_* sets the People owner and is not overwritten by preferred_language."
            : patch.preferred_language != null
              ? "preferred_language change also updates assigned_admin_id to the language owner."
              : undefined,
      };

      if (!adminAiWriteConfirmed(args).ok) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show client contact/language update. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const sets = Object.keys(patch).map((k) => `${k} = ?`);
      try {
        await pool.query(
          `UPDATE clients SET ${sets.join(", ")} WHERE id = ?`,
          [...Object.values(patch), clientId],
        );
      } catch (err: any) {
        if (err?.code === "ER_DUP_ENTRY") {
          return {
            ok: false,
            error: "duplicate_email",
            message: "That email is already used by another client",
          };
        }
        throw err;
      }

      const [updated] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, phone, preferred_language,
                assigned_admin_id, status, pipeline_stage
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      return {
        ok: true,
        data: {
          client: updated[0],
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "attach_referrer") {
      const clientId = Number(args.client_id);
      if (!Number.isFinite(clientId) || clientId <= 0) {
        return {
          ok: false,
          error: "invalid_args",
          message: "client_id is required",
        };
      }
      if (scopedIds && scopedIds.length > 0) {
        const [aff] = await pool.query<RowDataPacket[]>(
          `SELECT affiliate_id FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        const affId = aff[0]?.affiliate_id ? Number(aff[0].affiliate_id) : null;
        if (affId == null || !scopedIds.includes(affId)) {
          return {
            ok: false,
            error: "forbidden",
            message: "Client outside affiliate scope",
          };
        }
      }
      const [clientRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      if (!clientRows[0]) {
        return { ok: false, error: "not_found", message: "Client not found" };
      }
      let referrerId =
        args.referrer_id != null && Number(args.referrer_id) > 0
          ? Number(args.referrer_id)
          : null;
      const inlineFirst = String(args.referrer_first_name || "").trim();
      const inlineLast = String(args.referrer_last_name || "").trim();
      const inlineEmail = String(args.referrer_email || "")
        .trim()
        .toLowerCase();
      const inlinePhone = String(args.referrer_phone || "").trim();
      const inlineCompany = String(args.referrer_company || "").trim();
      const categoryRaw = String(args.referral_category || "").trim();
      const allowedCat = ["realtor_broker", "one_off", "affiliate_partner"];
      let createInline = false;
      if (!referrerId) {
        if (!inlineFirst || !inlineLast) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "referrer_id OR referrer_first_name + referrer_last_name required",
          };
        }
        if (!allowedCat.includes(categoryRaw)) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "referral_category (realtor_broker|one_off|affiliate_partner) required when creating a referrer",
          };
        }
        if (inlineEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(inlineEmail)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Invalid referrer_email",
          };
        }
        createInline = true;
      } else {
        const [refRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, status FROM referrers WHERE id = ? LIMIT 1`,
          [referrerId],
        );
        if (!refRows[0] || String(refRows[0].status) !== "active") {
          return {
            ok: false,
            error: "not_found",
            message: "referrer_id not found or inactive",
          };
        }
      }
      const existing = await listClientReferrerLinks(clientId);
      if (
        referrerId &&
        existing.some((l) => Number(l.referrer_id) === referrerId)
      ) {
        return {
          ok: false,
          error: "conflict",
          message: "Referrer already attached to this client",
        };
      }
      if (existing.length >= MAX_CLIENT_REFERRERS) {
        return {
          ok: false,
          error: "conflict",
          message: `Client already has ${MAX_CLIENT_REFERRERS} referral partners (max)`,
        };
      }
      const roleRaw = String(args.role || "").trim().toLowerCase();
      const hasPrimary = existing.some((l) => String(l.role) === "primary");
      let role =
        roleRaw === "primary" ||
        roleRaw === "secondary" ||
        roleRaw === "tertiary"
          ? roleRaw
          : hasPrimary
            ? "secondary"
            : "primary";
      const notifyOnRound = true; // Always on — César Sep 2026 (no toggle)
      const preview = {
        client_id: clientId,
        client_name:
          `${clientRows[0].first_name || ""} ${clientRows[0].last_name || ""}`.trim(),
        referrer_id: referrerId,
        create_referrer: createInline
          ? {
              first_name: inlineFirst,
              last_name: inlineLast,
              email: inlineEmail || null,
              phone: inlinePhone || null,
              company: inlineCompany || null,
              category: categoryRaw,
            }
          : null,
        role,
        notify_on_round: notifyOnRound,
        existing_slots: existing.length,
      };
      if (!adminAiWriteConfirmed(args).ok) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show attach preview. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      if (createInline) {
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO referrers
             (category, first_name, last_name, email, phone, company, preferred_language, status)
           VALUES (?, ?, ?, ?, ?, ?, 'en', 'active')`,
          [
            categoryRaw,
            inlineFirst,
            inlineLast,
            inlineEmail || null,
            inlinePhone || null,
            inlineCompany || null,
          ],
        );
        referrerId = Number(ins.insertId);
      }
      const links = existing.map((l) => ({
        referrer_id: Number(l.referrer_id),
        role: String(l.role || "secondary"),
        notify_on_round: true,
      }));
      if (role === "primary") {
        for (const l of links) {
          if (l.role === "primary") l.role = "secondary";
        }
        links.unshift({
          referrer_id: referrerId!,
          role: "primary",
          notify_on_round: notifyOnRound,
        });
      } else {
        links.push({
          referrer_id: referrerId!,
          role,
          notify_on_round: notifyOnRound,
        });
      }
      const normalized = links.slice(0, MAX_CLIENT_REFERRERS).map((l, i) => ({
        referrer_id: l.referrer_id,
        role: roleForSortOrder(i),
        notify_on_round: l.notify_on_round,
      }));
      await replaceClientReferrers(clientId, normalized);
      const partnerLinks = await listClientReferrerLinks(clientId);
      return {
        ok: true,
        data: {
          client_id: clientId,
          attached_referrer_id: referrerId,
          referrers: partnerLinks.map(mapClientReferrerLinkRow),
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "get_case") {
      const hasId = args.case_id != null && Number(args.case_id) > 0;
      const hasNumber =
        typeof args.case_number === "string" && !!args.case_number.trim();
      if (!hasId && !hasNumber) {
        return {
          ok: false,
          error: "invalid_args",
          message: "case_id or case_number is required",
        };
      }
      const row = await adminAiResolveCaseRow(args, scopedIds);
      if (!row) {
        return { ok: false, error: "not_found", message: "Case not found" };
      }
      const [taskRows] = await pool.query<RowDataPacket[]>(
        `SELECT
           SUM(CASE WHEN ott.is_required = 1 AND ctc.admin_review_status = 'approved' THEN 1 ELSE 0 END) AS tasks_approved,
           SUM(CASE WHEN ott.is_required = 1 THEN 1 ELSE 0 END) AS tasks_required,
           SUM(CASE WHEN ctc.status = 'completed' AND ctc.admin_review_status = 'pending' THEN 1 ELSE 0 END) AS tasks_pending_review
         FROM client_task_completions ctc
         JOIN onboarding_task_templates ott ON ott.id = ctc.task_template_id AND ott.is_active = 1
         WHERE ctc.case_id = ?`,
        [row.id],
      );
      const [payRows] = await pool.query<RowDataPacket[]>(
        `SELECT
           EXISTS (
             SELECT 1 FROM payments py
             WHERE py.client_id = ? AND py.status = 'succeeded'
           ) OR EXISTS (
             SELECT 1 FROM payment_splits ps
             WHERE ps.client_id = ? AND ps.status = 'paid'
           ) AS is_payment_received,
           EXISTS (
             SELECT 1 FROM payment_splits ps
             WHERE ps.client_id = ? AND ps.status = 'overdue'
           ) AS has_overdue_split,
           EXISTS (
             SELECT 1 FROM payment_splits ps WHERE ps.client_id = ?
           ) AS has_split_plan`,
        [row.client_id, row.client_id, row.client_id, row.client_id],
      );
      const pay = (payRows[0] || {}) as RowDataPacket;
      const payment_badge = Number(pay.is_payment_received)
        ? "paid"
        : Number(pay.has_overdue_split)
          ? "overdue"
          : Number(pay.has_split_plan)
            ? "split_plan"
            : "unpaid";
      const assignee =
        row.assignee_first_name || row.assignee_last_name
          ? `${row.assignee_first_name || ""} ${row.assignee_last_name || ""}`.trim()
          : null;
      return {
        ok: true,
        data: {
          case_id: row.id,
          case_number: row.case_number,
          client_id: row.client_id,
          client_name: `${row.first_name || ""} ${row.last_name || ""}`.trim(),
          email: row.email,
          client_status: row.client_status,
          pipeline_stage: row.pipeline_stage,
          status: row.status,
          package_name: row.package_name || null,
          assignee,
          preferred_language: row.preferred_language,
          tasks_approved: Number(taskRows[0]?.tasks_approved || 0),
          tasks_required: Number(taskRows[0]?.tasks_required || 0),
          tasks_pending_review: Number(taskRows[0]?.tasks_pending_review || 0),
          payment_badge,
          href: `/admin/pipeline?case=${row.id}`,
        },
      };
    }

    if (name === "pipeline_summary") {
      const search =
        typeof args.search === "string" ? args.search.trim().slice(0, 120) : "";
      const stage = typeof args.stage === "string" ? args.stage.trim() : "";
      const language =
        args.language === "en" || args.language === "es" ? args.language : "";

      const caseWhere = [
        "cr.status NOT IN ('cancelled')",
        "cr.pipeline_stage <> 'prospect'",
      ];
      const caseArgs: any[] = [];
      const prospectWhere = [adminProspectLeadSql()];
      const prospectArgs: any[] = [];

      if (scopedIds && scopedIds.length > 0) {
        caseWhere.push("c.affiliate_id IN (?)");
        caseArgs.push(scopedIds);
        prospectWhere.push("c.affiliate_id IN (?)");
        prospectArgs.push(scopedIds);
      }
      if (language) {
        caseWhere.push("c.preferred_language = ?");
        caseArgs.push(language);
        prospectWhere.push("c.preferred_language = ?");
        prospectArgs.push(language);
      }
      if (search) {
        const ident = clientIdentitySearchSql(search);
        const s = likeContains(search);
        caseWhere.push(`(${ident.sql} OR cr.case_number LIKE ? ESCAPE '!')`);
        caseArgs.push(...ident.params, s);
        prospectWhere.push(ident.sql);
        prospectArgs.push(...ident.params);
      }

      const includeProspects =
        !stage || stage === "prospect" || stage === "all";
      const includeCases = stage !== "prospect";

      let prospectTotal = 0;
      if (includeProspects) {
        const [pRows] = await pool.query<RowDataPacket[]>(
          `SELECT COUNT(*) AS total FROM clients c WHERE ${prospectWhere.join(" AND ")}`,
          prospectArgs,
        );
        prospectTotal = Number(pRows[0]?.total || 0);
      }

      const columns: Record<string, { total: number }> = {
        prospect: { total: prospectTotal },
      };
      for (const st of ADMIN_AI_CASE_STAGES) columns[st] = { total: 0 };

      if (includeCases) {
        const stageFilter =
          stage &&
          stage !== "all" &&
          stage !== "prospect" &&
          (ADMIN_AI_CASE_STAGES as readonly string[]).includes(stage)
            ? stage
            : null;
        const where = stageFilter
          ? [...caseWhere, "cr.pipeline_stage = ?"]
          : [...caseWhere];
        const argsSql = stageFilter
          ? [...caseArgs, stageFilter]
          : [...caseArgs];
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT cr.pipeline_stage AS stage, COUNT(*) AS total
           FROM credit_repair_cases cr
           JOIN clients c ON c.id = cr.client_id
           WHERE ${where.join(" AND ")}
           GROUP BY cr.pipeline_stage`,
          argsSql,
        );
        for (const r of rows) {
          const st = String(r.stage);
          if (columns[st]) columns[st] = { total: Number(r.total || 0) };
        }
      }

      return {
        ok: true,
        data: {
          columns,
          href: "/admin/pipeline",
        },
      };
    }

    if (
      name === "list_funding_applications" ||
      name === "get_funding_application" ||
      name === "update_funding_status" ||
      name === "funding_pipeline_summary" ||
      name === "create_funding_application" ||
      name === "convert_funding_application" ||
      name === "upload_funding_document"
    ) {
      if (name === "funding_pipeline_summary") {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT fa.status AS status, COUNT(*) AS total
           FROM funding_applications fa
           GROUP BY fa.status`,
        );
        const statuses = [
          "draft",
          "awaiting_docs",
          "submitted",
          "under_review",
          "complete",
          "converted",
          "cancelled",
        ] as const;
        const columns: Record<string, { total: number }> = {};
        for (const st of statuses) columns[st] = { total: 0 };
        let total = 0;
        for (const r of rows) {
          const st = String(r.status || "");
          const n = Number(r.total || 0);
          total += n;
          if (columns[st]) columns[st] = { total: n };
          else columns[st] = { total: n };
        }
        return {
          ok: true,
          data: {
            columns,
            total,
            href: "/admin/funding",
          },
        };
      }

      if (name === "list_funding_applications") {
        const limit = Math.min(50, Math.max(1, Number(args.limit) || 20));
        const where: string[] = ["1=1"];
        const qArgs: unknown[] = [];
        const st = String(args.status || "").trim();
        if (st) {
          where.push("fa.status = ?");
          qArgs.push(st);
        }
        const search = String(args.search || "").trim();
        if (search) {
          const s = fundingApplicationSearchSql(search);
          where.push(s.sql);
          qArgs.push(...s.params);
        }
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT fa.id, fa.funding_type, fa.status, fa.first_name, fa.last_name,
                  fa.email, fa.phone, fa.preferred_language, fa.created_at, fa.submitted_at
           FROM funding_applications fa
           WHERE ${where.join(" AND ")}
           ORDER BY fa.created_at DESC
           LIMIT ${limit}`,
          qArgs,
        );
        return {
          ok: true,
          data: {
            applications: rows,
            href: "/admin/funding",
          },
        };
      }

      if (name === "create_funding_application") {
        let firstName = String(args.first_name || "").trim();
        let lastName = String(args.last_name || "").trim();
        let email = String(args.email || "")
          .trim()
          .toLowerCase();
        let phone = args.phone ? String(args.phone).trim() : null;
        const fundingType =
          args.funding_type === "credit_card_stacking"
            ? "credit_card_stacking"
            : args.funding_type === "bank_statements"
              ? "bank_statements"
              : null;
        let preferredLanguage =
          args.preferred_language === "es" ? ("es" as const) : ("en" as const);
        const statusRaw = String(args.status || "awaiting_docs");
        const allowedInitial = new Set([
          "awaiting_docs",
          "submitted",
          "under_review",
          "complete",
        ]);
        const status = allowedInitial.has(statusRaw)
          ? statusRaw
          : "awaiting_docs";
        let postalCode =
          args.postal_code != null
            ? String(args.postal_code).trim() || null
            : null;
        let state =
          args.state != null ? String(args.state).trim() || null : null;
        const llcName =
          args.llc_name != null ? String(args.llc_name).trim() || null : null;
        const llcAddress =
          args.llc_address != null
            ? String(args.llc_address).trim() || null
            : null;
        const linkedClientId =
          args.client_id != null && Number(args.client_id) > 0
            ? Number(args.client_id)
            : null;

        if (linkedClientId) {
          const [cRows] = await pool.query<RowDataPacket[]>(
            `SELECT id, first_name, last_name, email, phone, zip, state, preferred_language
             FROM clients WHERE id = ? LIMIT 1`,
            [linkedClientId],
          );
          if (!cRows[0]) {
            return {
              ok: false,
              error: "not_found",
              message: "client_id not found",
            };
          }
          if (scopedIds && scopedIds.length > 0) {
            const [aff] = await pool.query<RowDataPacket[]>(
              `SELECT affiliate_id FROM clients WHERE id = ? LIMIT 1`,
              [linkedClientId],
            );
            const affId = aff[0]?.affiliate_id
              ? Number(aff[0].affiliate_id)
              : null;
            if (affId == null || !scopedIds.includes(affId)) {
              return {
                ok: false,
                error: "forbidden",
                message: "Client outside affiliate scope",
              };
            }
          }
          const c = cRows[0];
          if (!firstName) firstName = String(c.first_name || "").trim();
          if (!lastName) lastName = String(c.last_name || "").trim();
          if (!email && c.email) email = String(c.email).trim().toLowerCase();
          if (!phone && c.phone) phone = String(c.phone).trim();
          if (!postalCode && c.zip) postalCode = String(c.zip).trim();
          if (!state && c.state) state = String(c.state).trim();
          if (args.preferred_language == null && c.preferred_language === "es") {
            preferredLanguage = "es";
          }
        }

        if (!fundingType) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "funding_type must be credit_card_stacking or bank_statements",
          };
        }
        if (!firstName || !lastName) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "first_name and last_name are required (or pass client_id with those on file)",
          };
        }
        if (!email && !phone) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "email or phone is required with name (or pass client_id)",
          };
        }
        if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Invalid email address",
          };
        }
        if (phone && !normalizePhoneLast10(phone)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Invalid phone number",
          };
        }

        const preview = {
          first_name: firstName,
          last_name: lastName,
          email: email || null,
          phone,
          funding_type: fundingType,
          preferred_language: preferredLanguage,
          status,
          client_id: linkedClientId,
          postal_code: postalCode,
          state,
          llc_name: llcName,
          llc_address: llcAddress,
        };
        if (!adminAiWriteConfirmed(args).ok) {
          return {
            ok: true,
            data: {
              dry_run: true,
              ready: true,
              preview,
              required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
              guidance: `Show this funding application preview. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
            },
          };
        }

        const clientId = await ensureFundingClientId({
          email: email || null,
          firstName,
          lastName,
          phone,
          preferredLanguage,
          postalCode,
          state,
        });
        const publicToken = crypto.randomUUID();
        const submittedAt =
          status === "submitted" ||
          status === "under_review" ||
          status === "complete"
            ? new Date()
            : null;
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO funding_applications
             (public_token, funding_type, status, first_name, last_name, email, phone,
              postal_code, state, preferred_language, llc_name, llc_address, client_id,
              submitted_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            publicToken,
            fundingType,
            status,
            firstName,
            lastName,
            email || null,
            phone,
            postalCode,
            state,
            preferredLanguage,
            llcName,
            llcAddress,
            clientId,
            submittedAt,
          ],
        );
        const applicationId = Number(ins.insertId);
        await notifyFundingApplicationCreated({
          applicationId,
          clientId,
          clientName: `${firstName} ${lastName}`.trim(),
          clientEmail: email || phone || "no-email",
          firstName,
          preferredLanguage,
          fundingType,
          status,
          publicToken,
        });
        const [created] = await pool.query<RowDataPacket[]>(
          `SELECT id, funding_type, status, first_name, last_name, email, phone,
                  preferred_language, client_id, created_at
           FROM funding_applications WHERE id = ? LIMIT 1`,
          [applicationId],
        );
        return {
          ok: true,
          data: {
            application: created[0],
            client_id: clientId,
            href: `/admin/funding?id=${applicationId}`,
          },
        };
      }

      const appId = Number(args.funding_application_id);
      if (!Number.isFinite(appId) || appId <= 0) {
        return {
          ok: false,
          error: "invalid_args",
          message: "funding_application_id required",
        };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, funding_type, status, first_name, last_name, email, phone,
                preferred_language, llc_name, state, postal_code, client_id,
                submitted_at, created_at, updated_at, public_token,
                docs_complete_notified_at
         FROM funding_applications WHERE id = ? LIMIT 1`,
        [appId],
      );
      if (!rows[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Funding application not found",
        };
      }
      if (name === "get_funding_application") {
        const docs = await listFundingDocsUploaded(appId);
        return {
          ok: true,
          data: {
            application: rows[0],
            docs_uploaded: docs,
            href: `/admin/funding?id=${appId}`,
          },
        };
      }

      if (name === "convert_funding_application") {
        if (String(rows[0].status) === "converted") {
          return {
            ok: false,
            error: "conflict",
            message: "Application already converted",
          };
        }
        const preview = {
          funding_application_id: appId,
          from_status: rows[0].status,
          to_status: "converted",
          client: `${rows[0].first_name} ${rows[0].last_name}`.trim(),
          email: rows[0].email,
          existing_client_id: rows[0].client_id
            ? Number(rows[0].client_id)
            : null,
          will_set_client_status: "prospect",
        };
        if (!adminAiWriteConfirmed(args).ok) {
          return {
            ok: true,
            data: {
              dry_run: true,
              ready: true,
              preview,
              required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
              guidance: `Show convert preview (funding → CR prospect). After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
            },
          };
        }
        let clientId = rows[0].client_id ? Number(rows[0].client_id) : null;
        if (!clientId) {
          clientId = await ensureFundingClientId({
            email: String(rows[0].email),
            firstName: String(rows[0].first_name),
            lastName: String(rows[0].last_name),
            phone: rows[0].phone ? String(rows[0].phone) : null,
            preferredLanguage:
              rows[0].preferred_language === "es" ? "es" : "en",
            postalCode: rows[0].postal_code
              ? String(rows[0].postal_code)
              : null,
            state: rows[0].state ? String(rows[0].state) : null,
          });
        }
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET status = 'prospect', pipeline_stage = 'prospect'
           WHERE id = ?`,
          [clientId],
        );
        await attachLabelsBySlug(clientId, ["funding_convert"]).catch(() => {});
        await pool.query<ResultSetHeader>(
          `UPDATE funding_applications SET
             status = 'converted',
             client_id = ?,
             converted_prospect_client_id = ?,
             converted_at = NOW(),
             converted_by_admin_id = ?
           WHERE id = ?`,
          [clientId, clientId, ctx.adminId || null, appId],
        );
        const [updated] = await pool.query<RowDataPacket[]>(
          `SELECT id, funding_type, status, first_name, last_name, email, client_id,
                  converted_at FROM funding_applications WHERE id = ?`,
          [appId],
        );
        return {
          ok: true,
          data: {
            application: updated[0],
            client_id: clientId,
            href: `/admin/pipeline?client=${clientId}`,
            funding_href: `/admin/funding?id=${appId}`,
          },
        };
      }

      if (name === "upload_funding_document") {
        const docTypeRaw = String(args.doc_type || "").trim();
        const docType = (FUNDING_DOC_SLOTS as readonly string[]).includes(
          docTypeRaw,
        )
          ? (docTypeRaw as FundingDocSlot)
          : null;
        const fileName = String(args.file_name || "")
          .trim()
          .replace(/[/\\]/g, "_")
          .slice(0, 255);
        const mimeType = adminAiDocMimeFromFilename(
          fileName,
          typeof args.mime_type === "string" ? args.mime_type : null,
        );
        const fileBase64Raw =
          typeof args.file_base64 === "string" ? args.file_base64 : "";
        const fileBuffer = fileBase64Raw
          ? adminAiDecodeFileBase64(fileBase64Raw)
          : null;

        if (isFundingApplicationLocked(String(rows[0].status))) {
          return {
            ok: false,
            error: "conflict",
            message: `Application is locked (status=${rows[0].status})`,
          };
        }

        const validationErrors: string[] = [];
        if (!docType) {
          validationErrors.push(
            `doc_type must be one of ${FUNDING_DOC_SLOTS.join(", ")}`,
          );
        }
        if (!fileName) validationErrors.push("file_name is required");
        if (!mimeType) {
          validationErrors.push(
            "Unsupported file type. Use JPEG, PNG, HEIC, or PDF.",
          );
        }
        if (fileBase64Raw && !fileBuffer) {
          validationErrors.push("file_base64 is not valid base64");
        }
        if (fileBuffer && fileBuffer.length > ADMIN_AI_DOC_MAX_BYTES) {
          validationErrors.push(
            `File exceeds ${ADMIN_AI_DOC_MAX_BYTES} bytes (~${Math.round(ADMIN_AI_DOC_MAX_BYTES / (1024 * 1024))}MB)`,
          );
        }

        const fundingCrmRequired =
          fileBuffer && fileBuffer.length > ADMIN_AI_DOC_MAX_BYTES
            ? adminAiCrmRequired({
                reason: "file_too_large",
                userMessage: `This funding document is too large for ATLAS (~${Math.round(ADMIN_AI_DOC_MAX_BYTES / (1024 * 1024))}MB max). Compress under 4MB and upload on the Funding board in CRM.`,
                fundingId: appId,
                clientId: rows[0].client_id
                  ? Number(rows[0].client_id)
                  : null,
                crmAction: "Upload on Funding board in CRM",
                details: {
                  source_byte_length: fileBuffer.length,
                  atlas_max_bytes: ADMIN_AI_DOC_MAX_BYTES,
                },
              })
            : null;

        const preview = {
          funding_application_id: appId,
          client: `${rows[0].first_name} ${rows[0].last_name}`.trim(),
          doc_type: docType,
          file_name: fileName || null,
          mime_type: mimeType,
          file_bytes: fileBuffer ? fileBuffer.length : null,
          has_file_base64: !!fileBase64Raw,
          validation_errors: validationErrors,
        };
        const uploadReady =
          validationErrors.length === 0 &&
          !!docType &&
          !!fileBuffer &&
          !!mimeType;
        if (!uploadReady || !adminAiWriteConfirmed(args).ok) {
          return {
            ok: true,
            data: {
              dry_run: true,
              ready: uploadReady,
              preview,
              missing_fields: !fileBase64Raw
                ? ["file_base64"]
                : validationErrors.length
                  ? validationErrors
                  : undefined,
              ...(fundingCrmRequired
                ? { crm_required: fundingCrmRequired }
                : {}),
              required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
              guidance: fundingCrmRequired
                ? fundingCrmRequired.user_message
                : uploadReady
                  ? `Show doc_type and filename. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`
                  : "Fix validation / provide file_base64, then confirm.",
            },
          };
        }

        if (!docType || !fileBuffer || !mimeType) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Upload validation failed",
          };
        }

        let clientId = rows[0].client_id ? Number(rows[0].client_id) : null;
        if (!clientId) {
          clientId = await ensureFundingClientId({
            email: String(rows[0].email),
            firstName: String(rows[0].first_name),
            lastName: String(rows[0].last_name),
            phone: rows[0].phone ? String(rows[0].phone) : null,
            preferredLanguage:
              rows[0].preferred_language === "es" ? "es" : "en",
            postalCode: rows[0].postal_code
              ? String(rows[0].postal_code)
              : null,
            state: rows[0].state ? String(rows[0].state) : null,
          });
          await pool.query<ResultSetHeader>(
            `UPDATE funding_applications SET client_id = ? WHERE id = ?`,
            [clientId, appId],
          );
        }

        const multerLike = {
          buffer: fileBuffer,
          originalname: fileName,
          mimetype: mimeType,
          size: fileBuffer.length,
        } as Express.Multer.File;

        const docId = await persistFundingDocument({
          clientId,
          fundingApplicationId: appId,
          docType,
          file: multerLike,
        });
        const docs = await listFundingDocsUploaded(appId);
        const allComplete = FUNDING_DOC_SLOTS.every((s) => docs.includes(s));
        const clientName =
          `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim();
        await notifyFundingDocUpload({
          applicationId: appId,
          clientId,
          clientName,
          clientEmail: String(rows[0].email),
          docType,
          allDocsComplete: allComplete,
        });
        await maybeNotifyFundingClientDocsComplete({
          applicationId: appId,
          clientId,
          email: String(rows[0].email),
          phone: rows[0].phone ? String(rows[0].phone) : null,
          firstName: String(rows[0].first_name || ""),
          preferredLanguage:
            rows[0].preferred_language === "es" ? "es" : "en",
          docsCompleteNotifiedAt: rows[0].docs_complete_notified_at
            ? String(rows[0].docs_complete_notified_at)
            : null,
        });
        return {
          ok: true,
          data: {
            document_id: docId,
            docs_uploaded: docs,
            all_docs_complete: allComplete,
            href: `/admin/funding?id=${appId}`,
          },
        };
      }

      // update_funding_status
      const nextStatus = String(args.status || "").trim();
      const allowed = [
        "draft",
        "awaiting_docs",
        "submitted",
        "under_review",
        "complete",
        "cancelled",
      ];
      if (!allowed.includes(nextStatus)) {
        return {
          ok: false,
          error: "invalid_args",
          message: `status must be one of ${allowed.join(", ")}`,
        };
      }
      if (String(rows[0].status) === "converted") {
        return {
          ok: false,
          error: "conflict",
          message: "Converted applications cannot change status",
        };
      }
      const preview = {
        funding_application_id: appId,
        from_status: rows[0].status,
        to_status: nextStatus,
        client: `${rows[0].first_name} ${rows[0].last_name}`.trim(),
      };
      if (!adminAiWriteConfirmed(args).ok) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show status change. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      await pool.query(
        `UPDATE funding_applications SET status = ? WHERE id = ? AND status <> 'converted'`,
        [nextStatus, appId],
      );
      const [updated] = await pool.query<RowDataPacket[]>(
        `SELECT id, status, first_name, last_name, email FROM funding_applications WHERE id = ?`,
        [appId],
      );
      return {
        ok: true,
        data: { application: updated[0], href: `/admin/funding?id=${appId}` },
      };
    }

    if (name === "list_progress_reports" || name === "get_progress_report") {
      const hasId = args.case_id != null && Number(args.case_id) > 0;
      const hasNumber =
        typeof args.case_number === "string" && !!args.case_number.trim();
      if (!hasId && !hasNumber) {
        return {
          ok: false,
          error: "invalid_args",
          message: "case_id or case_number is required",
        };
      }
      const row = await adminAiResolveCaseRow(args, scopedIds);
      if (!row) {
        return { ok: false, error: "not_found", message: "Case not found" };
      }
      if (name === "list_progress_reports") {
        const [reports] = await pool.query<RowDataPacket[]>(
          `SELECT id, round_number, score_before, score_after, items_removed,
                  items_disputed, report_locale, pdf_file_name, created_at,
                  wizard_session_id,
                  CASE WHEN pdf_storage_key IS NOT NULL THEN 1 ELSE 0 END AS has_legacy_pdf
           FROM client_round_reports
           WHERE client_id = ? AND (case_id = ? OR case_id IS NULL)
           ORDER BY round_number ASC`,
          [row.client_id, row.id],
        );
        const [pdfRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, round_number, round_report_id, file_name
           FROM round_report_pdfs
           WHERE client_id = ?
           ORDER BY id DESC`,
          [row.client_id],
        );
        const pdfByReportId = new Map<number, RowDataPacket>();
        const pdfByRound = new Map<number, RowDataPacket>();
        for (const p of pdfRows) {
          const rid = p.round_report_id != null ? Number(p.round_report_id) : 0;
          const rn = Number(p.round_number);
          if (rid > 0 && !pdfByReportId.has(rid)) pdfByReportId.set(rid, p);
          if (Number.isFinite(rn) && !pdfByRound.has(rn)) pdfByRound.set(rn, p);
        }
        const [drafts] = await pool.query<RowDataPacket[]>(
          `SELECT id, round_number, status, before_source,
                  before_reused_from_session_id, extraction_meta, updated_at,
                  error_message
           FROM report_wizard_sessions
           WHERE case_id = ?
             AND status IN ('draft','extracting','review','generating','failed')
           ORDER BY round_number ASC, id DESC`,
          [row.id],
        );
        const wizard_drafts = drafts.map((d) => {
          const meta =
            typeof d.extraction_meta === "string"
              ? (() => {
                  try {
                    return JSON.parse(d.extraction_meta);
                  } catch {
                    return null;
                  }
                })()
              : d.extraction_meta;
          return {
            session_id: Number(d.id),
            round: Number(d.round_number),
            status: d.status,
            before_source: d.before_source ?? null,
            before_reused_from_session_id: d.before_reused_from_session_id
              ? Number(d.before_reused_from_session_id)
              : null,
            confidence: meta?.confidence ?? null,
            scores_suspicious:
              meta?.confidence &&
              typeof meta.confidence === "object" &&
              Object.values(meta.confidence as Record<string, number>).some(
                (c) => typeof c === "number" && c < 0.6,
              )
                ? true
                : false,
            error_message: d.error_message
              ? String(d.error_message).slice(0, 240)
              : null,
            updated_at: d.updated_at,
          };
        });
        return {
          ok: true,
          data: {
            case_id: row.id,
            case_number: row.case_number,
            client_id: row.client_id,
            reports: reports.map((r) => {
              const reportId = Number(r.id);
              const rn = Number(r.round_number);
              const pdf =
                pdfByReportId.get(reportId) || pdfByRound.get(rn) || null;
              const hasPdf = !!pdf || !!Number(r.has_legacy_pdf);
              return {
                id: reportId,
                round: rn,
                score_before: r.score_before,
                score_after: r.score_after,
                items_removed: r.items_removed,
                items_disputed: r.items_disputed,
                report_locale: r.report_locale,
                has_pdf: hasPdf,
                pdf_id: pdf ? Number(pdf.id) : null,
                pdf_file_name: pdf
                  ? String(pdf.file_name || r.pdf_file_name || "")
                  : r.pdf_file_name
                    ? String(r.pdf_file_name)
                    : null,
                wizard_session_id: r.wizard_session_id
                  ? Number(r.wizard_session_id)
                  : null,
                created_at: r.created_at,
              };
            }),
            wizard_drafts,
            guidance:
              "To publish or continue a round PDF, open CRM Reports → Generate (OFG Progress Report Wizard). When has_pdf/pdf_id is set, resend via send_round_report (secure email + SMS). MCP upsert_progress_report is staff notes only.",
            href: `/admin/pipeline?client=${row.client_id}&case=${row.id}`,
          },
        };
      }

      const round = Number(args.round);
      const caseMaxRounds = await loadCaseMaxRounds(pool, Number(row.id));
      if (
        !Number.isFinite(round) ||
        round < 1 ||
        round > caseMaxRounds
      ) {
        return {
          ok: false,
          error: "invalid_args",
          message: `round must be 1–${caseMaxRounds}`,
        };
      }
      const [reports] = await pool.query<RowDataPacket[]>(
        `SELECT id, round_number, score_before, score_after, items_removed,
                items_disputed, summary_md, bureau_scores_json, file_strength_score,
                report_locale, created_at, wizard_session_id,
                CASE WHEN pdf_storage_key IS NOT NULL THEN 1 ELSE 0 END AS has_legacy_pdf
         FROM client_round_reports
         WHERE client_id = ? AND round_number = ?
           AND (case_id = ? OR case_id IS NULL)
         ORDER BY id DESC
         LIMIT 1`,
        [row.client_id, round, row.id],
      );
      const [wizRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, status, before_source, before_reused_from_session_id,
                extraction_meta, error_message, updated_at, published_at,
                output_pdf_id, round_report_id
         FROM report_wizard_sessions
         WHERE case_id = ? AND round_number = ?
         ORDER BY id DESC
         LIMIT 1`,
        [row.id, round],
      );
      if (!reports[0] && !wizRows[0]) {
        return {
          ok: false,
          error: "not_found",
          message: `No progress report for round ${round}`,
          crm_required: adminAiCrmRequired({
            reason: "progress_report_wizard",
            userMessage: `No Round ${round} report yet. Open the client → Reports → Generate (OFG Progress Report Wizard) to upload Before/After PDFs and publish.`,
            clientId: Number(row.client_id),
            caseId: Number(row.id),
            crmAction: "open_reports_wizard",
            details: { round },
          }),
        };
      }
      const r = reports[0];
      let bureau_scores: unknown = null;
      if (r) {
        try {
          bureau_scores =
            typeof r.bureau_scores_json === "string"
              ? JSON.parse(r.bureau_scores_json)
              : r.bureau_scores_json;
        } catch {
          bureau_scores = null;
        }
      }
      const summary = r
        ? decodeLiteralUnicodeEscapes(String(r.summary_md || "")).slice(0, 1500)
        : null;
      const wiz = wizRows[0] || null;
      let wizMeta: Record<string, unknown> | null = null;
      if (wiz?.extraction_meta) {
        try {
          wizMeta =
            typeof wiz.extraction_meta === "string"
              ? JSON.parse(wiz.extraction_meta)
              : (wiz.extraction_meta as Record<string, unknown>);
        } catch {
          wizMeta = null;
        }
      }
      const pdf = await findRoundReportPdfRow({
        clientId: Number(row.client_id),
        pdfId: wiz?.output_pdf_id ? Number(wiz.output_pdf_id) : null,
        roundReportId: r?.id
          ? Number(r.id)
          : wiz?.round_report_id
            ? Number(wiz.round_report_id)
            : null,
        roundNumber: round,
      });
      const hasPdf = !!pdf || !!(r && Number(r.has_legacy_pdf));
      return {
        ok: true,
        data: {
          case_id: row.id,
          case_number: row.case_number,
          client_id: row.client_id,
          round,
          round_report_id: r ? Number(r.id) : null,
          score_before: r?.score_before ?? null,
          score_after: r?.score_after ?? null,
          items_removed: r?.items_removed ?? null,
          items_disputed: r?.items_disputed ?? null,
          file_strength_score: r?.file_strength_score ?? null,
          report_locale: r?.report_locale ?? null,
          bureau_scores,
          summary_excerpt: summary || null,
          has_pdf: hasPdf,
          pdf_id: pdf ? Number(pdf.id) : null,
          pdf_file_name: pdf
            ? String(pdf.file_name || "")
            : null,
          created_at: r?.created_at ?? null,
          wizard: wiz
            ? {
                session_id: Number(wiz.id),
                status: wiz.status,
                before_source: wiz.before_source ?? null,
                before_reused_from_session_id: wiz.before_reused_from_session_id
                  ? Number(wiz.before_reused_from_session_id)
                  : null,
                confidence: wizMeta?.confidence ?? null,
                scores_suspicious:
                  wizMeta?.confidence &&
                  typeof wizMeta.confidence === "object" &&
                  Object.values(
                    wizMeta.confidence as Record<string, number>,
                  ).some((c) => typeof c === "number" && c < 0.6)
                    ? true
                    : false,
                error_message: wiz.error_message
                  ? String(wiz.error_message).slice(0, 240)
                  : null,
                published_at: wiz.published_at ?? null,
                updated_at: wiz.updated_at,
              }
            : null,
          guidance: hasPdf
            ? `Branded PDF is available (pdf_id=${pdf ? Number(pdf.id) : "legacy"}). Resend to the client with send_round_report (dry-run then confirm) using pdf_id or round_number=${round}.`
            : "No branded PDF on file yet. Publish via CRM Reports → Generate (OFG Progress Report Wizard). This tool is read-only for status.",
          href: `/admin/pipeline?client=${row.client_id}&case=${row.id}`,
        },
      };
    }

    if (name === "search_admins") {
      const q = String(args.q || "").trim();
      const limit = adminAiClampLimit(args.limit, 20);
      const staff = await loadAssignableStaffAdmins();
      const matched = q ? matchStaffAdmins(staff, q) : staff;
      return {
        ok: true,
        data: {
          admins: matched.slice(0, limit).map((r) => ({
            id: r.id,
            name: `${r.first_name} ${r.last_name}`.trim(),
            first_name: r.first_name,
            last_name: r.last_name,
            email: r.email,
            phone: r.phone || null,
            has_phone: !!(r.phone && String(r.phone).trim()),
            role: r.role,
            language_owner_for: r.language_owner_for,
          })),
        },
      };
    }

    if (name === "search_work_tasks") {
      const q = String(args.q || "")
        .trim()
        .slice(0, 120);
      const limit = adminAiClampLimit(args.limit, 10);
      const statusRaw = String(args.status || "").trim();
      const status =
        statusRaw === "backlog" || statusRaw === "doing" || statusRaw === "done"
          ? statusRaw
          : null;
      if (!q && !status) {
        return {
          ok: false,
          error: "invalid_args",
          message: "q or status is required",
        };
      }
      const where = ["1=1"];
      const params: any[] = [];
      if (status) {
        where.push("t.status = ?");
        params.push(status);
      }
      if (q) {
        const like = likeContains(q);
        where.push(`(
          t.title LIKE ? ESCAPE '!'
          OR COALESCE(t.description,'') LIKE ? ESCAPE '!'
          OR COALESCE(cr.case_number,'') LIKE ? ESCAPE '!'
          OR COALESCE(c.first_name,'') LIKE ? ESCAPE '!'
          OR COALESCE(c.last_name,'') LIKE ? ESCAPE '!'
          OR CONCAT(COALESCE(c.first_name,''), ' ', COALESCE(c.last_name,'')) LIKE ? ESCAPE '!'
          OR COALESCE(a.first_name,'') LIKE ? ESCAPE '!'
          OR COALESCE(a.last_name,'') LIKE ? ESCAPE '!'
          OR CONCAT(COALESCE(a.first_name,''), ' ', COALESCE(a.last_name,'')) LIKE ? ESCAPE '!'
        )`);
        params.push(like, like, like, like, like, like, like, like, like);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT t.id, t.title, t.status, t.priority, t.due_at, t.case_id,
                t.assignee_admin_id, cr.case_number,
                c.id AS client_id, c.first_name, c.last_name,
                a.first_name AS assignee_first, a.last_name AS assignee_last
         FROM admin_work_tasks t
         LEFT JOIN credit_repair_cases cr ON cr.id = t.case_id
         LEFT JOIN clients c ON c.id = cr.client_id
         LEFT JOIN admins a ON a.id = t.assignee_admin_id
         WHERE ${where.join(" AND ")}
         ORDER BY t.due_at IS NULL, t.due_at ASC, t.id DESC
         LIMIT ?`,
        [...params, limit],
      );
      return {
        ok: true,
        data: {
          tasks: rows.map((r) => ({
            id: r.id,
            title: decodeLiteralUnicodeEscapes(String(r.title)),
            status: r.status,
            priority: r.priority,
            due_at: r.due_at,
            case_id: r.case_id,
            case_number: r.case_number,
            client_id: r.client_id,
            client_name:
              r.first_name || r.last_name
                ? `${r.first_name || ""} ${r.last_name || ""}`.trim()
                : null,
            assignee:
              r.assignee_first || r.assignee_last
                ? `${r.assignee_first || ""} ${r.assignee_last || ""}`.trim()
                : null,
            href: r.client_id
              ? `/admin/pipeline?client=${r.client_id}`
              : "/admin/my-tasks",
          })),
        },
      };
    }

    if (name === "get_client") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT c.id, c.first_name, c.last_name, c.email, c.phone, c.status,
                c.pipeline_stage, c.preferred_language, c.city, c.state, c.zip,
                c.affiliate_id, c.contract_signed_at, c.package_id,
                c.referral_category, c.referrer_id,
                c.created_at, c.updated_at,
                LEFT(COALESCE(c.admin_notes,''), 400) AS notes_excerpt,
                p.name AS package_name,
                a.first_name AS assignee_first, a.last_name AS assignee_last,
                r.first_name AS ref_first, r.last_name AS ref_last,
                r.email AS ref_email, r.phone AS ref_phone,
                r.company AS ref_company, r.status AS ref_status,
                r.preferred_language AS ref_lang,
                (
                  SELECT cr.id FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_id,
                (
                  SELECT cr.case_number FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_number,
                (
                  SELECT cr.pipeline_stage FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_stage,
                (
                  SELECT cr.status FROM credit_repair_cases cr
                  WHERE cr.client_id = c.id AND cr.status <> 'cancelled'
                  ORDER BY cr.id DESC LIMIT 1
                ) AS case_status
         FROM clients c
         LEFT JOIN packages p ON p.id = c.package_id
         LEFT JOIN admins a ON a.id = c.assigned_admin_id
         LEFT JOIN referrers r ON r.id = c.referrer_id
         WHERE c.id = ?
         LIMIT 1`,
        [resolved.clientId],
      );
      if (!rows[0]) {
        return { ok: false, error: "not_found", message: "Client not found" };
      }
      const r = rows[0];
      const partnerLinks = await listClientReferrerLinks(Number(r.id));
      let referrersPayload = partnerLinks
        .map(mapClientReferrerLinkRow)
        .map((link) => ({
          id: link.referrer_id,
          role: link.role,
          sort_order: link.sort_order,
          notify_on_round: link.notify_on_round,
          name: link.referrer
            ? `${link.referrer.first_name || ""} ${link.referrer.last_name || ""}`.trim()
            : "",
          email: link.referrer?.email ?? null,
          phone: link.referrer?.phone ?? null,
          company: link.referrer?.company ?? null,
          category: link.referrer?.category ?? null,
          status: link.referrer?.status ?? null,
          preferred_language: link.referrer?.preferred_language ?? null,
          has_email: !!(
            link.referrer?.email && String(link.referrer.email).trim()
          ),
        }));
      // Legacy clients may only have clients.referrer_id until backfilled/synced
      if (!referrersPayload.length && r.referrer_id) {
        referrersPayload = [
          {
            id: Number(r.referrer_id),
            role: "primary",
            sort_order: 0,
            notify_on_round: true,
            name: `${r.ref_first || ""} ${r.ref_last || ""}`.trim(),
            email: r.ref_email || null,
            phone: r.ref_phone || null,
            company: r.ref_company || null,
            category: null,
            status: r.ref_status || null,
            preferred_language: r.ref_lang || null,
            has_email: !!(r.ref_email && String(r.ref_email).trim()),
          },
        ];
      }
      return {
        ok: true,
        data: {
          client_id: r.id,
          name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
          email: r.email,
          phone: r.phone,
          status: r.status,
          client_pipeline_stage: r.pipeline_stage,
          preferred_language: r.preferred_language,
          city: r.city,
          state: r.state,
          zip: r.zip,
          package_name: r.package_name || null,
          assignee:
            r.assignee_first || r.assignee_last
              ? `${r.assignee_first || ""} ${r.assignee_last || ""}`.trim()
              : null,
          affiliate_id: r.affiliate_id,
          contract_signed_at: r.contract_signed_at,
          notes_excerpt: r.notes_excerpt
            ? decodeLiteralUnicodeEscapes(String(r.notes_excerpt))
            : null,
          referral_category: r.referral_category || null,
          /** @deprecated Prefer `referrers[]` — primary partner only (legacy). */
          referrer: r.referrer_id
            ? {
                id: Number(r.referrer_id),
                name: `${r.ref_first || ""} ${r.ref_last || ""}`.trim(),
                email: r.ref_email || null,
                phone: r.ref_phone || null,
                company: r.ref_company || null,
                status: r.ref_status || null,
                preferred_language: r.ref_lang || null,
                has_email: !!(r.ref_email && String(r.ref_email).trim()),
              }
            : null,
          referrers: referrersPayload,
          case_id: r.case_id,
          case_number: r.case_number,
          case_stage: r.case_stage,
          case_status: r.case_status,
          on_prospect_board: adminOnProspectBoard({
            status: r.status,
            pipeline_stage: r.pipeline_stage,
            case_stage: r.case_stage,
            case_status: r.case_status,
          }),
          href: adminPipelineHref(Number(r.id), r.case_id),
          funding_applications: (
            await pool.query<RowDataPacket[]>(
              `SELECT fa.id, fa.funding_type, fa.status, fa.first_name, fa.last_name,
                      fa.email, fa.preferred_language, fa.created_at, fa.submitted_at,
                      fa.converted_at
               FROM funding_applications fa
               WHERE fa.client_id = ?
               ORDER BY fa.updated_at DESC, fa.id DESC
               LIMIT 20`,
              [r.id],
            )
          )[0].map((fa) => ({
            id: Number(fa.id),
            funding_type: fa.funding_type,
            status: fa.status,
            name: `${fa.first_name || ""} ${fa.last_name || ""}`.trim(),
            email: fa.email,
            preferred_language: fa.preferred_language,
            created_at: fa.created_at,
            submitted_at: fa.submitted_at || null,
            converted_at: fa.converted_at || null,
            href: `/admin/funding?id=${fa.id}`,
          })),
        },
      };
    }

    if (name === "list_case_documents") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const where = ["d.client_id = ?"];
      const params: any[] = [resolved.clientId];
      if (resolved.caseId) {
        where.push("(d.case_id = ? OR d.case_id IS NULL)");
        params.push(resolved.caseId);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT d.id, d.doc_type, d.pipeline_round, d.file_name, d.file_size,
                d.mime_type, d.review_status, d.rejection_reason,
                d.uploaded_at, d.reviewed_at, d.case_id
         FROM client_documents d
         WHERE ${where.join(" AND ")}
         ORDER BY d.uploaded_at DESC
         LIMIT 40`,
        params,
      );
      const types = [
        "id_front",
        "id_back",
        "ssn_card",
        "proof_of_address",
      ] as const;
      const byType = new Map<string, RowDataPacket>();
      for (const r of rows) {
        const t = String(r.doc_type);
        if (!byType.has(t)) byType.set(t, r);
      }
      return {
        ok: true,
        data: {
          client_id: resolved.clientId,
          case_id: resolved.caseId,
          case_number: resolved.caseNumber,
          required_checklist: types.map((t) => ({
            doc_type: t,
            present: byType.has(t),
            review_status: byType.get(t)?.review_status || null,
          })),
          documents: rows.map((r) => ({
            id: r.id,
            doc_type: r.doc_type,
            pipeline_round: r.pipeline_round,
            file_name: r.file_name,
            file_size: r.file_size,
            mime_type: r.mime_type,
            review_status: r.review_status,
            rejection_reason: r.rejection_reason
              ? String(r.rejection_reason).slice(0, 200)
              : null,
            uploaded_at: r.uploaded_at,
            reviewed_at: r.reviewed_at,
            case_id: r.case_id,
          })),
          href: `/admin/pipeline?client=${resolved.clientId}`,
        },
      };
    }

    if (name === "list_payments") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const limit = adminAiClampLimit(args.limit, 10);
      const where = ["p.client_id = ?"];
      const params: any[] = [resolved.clientId];
      if (resolved.caseId) {
        where.push("(p.case_id = ? OR p.case_id IS NULL)");
        params.push(resolved.caseId);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT p.id, p.amount_cents, p.currency, p.status, p.provider,
                p.paid_at, p.created_at, p.case_id, p.split_id,
                p.discount_cents, pk.name AS package_name
         FROM payments p
         LEFT JOIN packages pk ON pk.id = p.package_id
         WHERE ${where.join(" AND ")}
         ORDER BY COALESCE(p.paid_at, p.created_at) DESC, p.id DESC
         LIMIT ?`,
        [...params, limit],
      );
      const [sumRows] = await pool.query<RowDataPacket[]>(
        `SELECT
           COALESCE(SUM(CASE WHEN status = 'succeeded' THEN amount_cents ELSE 0 END), 0) AS paid_cents,
           COUNT(*) AS payment_count
         FROM payments
         WHERE client_id = ?`,
        [resolved.clientId],
      );
      return {
        ok: true,
        data: {
          client_id: resolved.clientId,
          case_id: resolved.caseId,
          case_number: resolved.caseNumber,
          paid_cents_total: Number(sumRows[0]?.paid_cents || 0),
          payment_count: Number(sumRows[0]?.payment_count || 0),
          payments: rows.map((r) => ({
            id: r.id,
            amount_cents: r.amount_cents,
            currency: r.currency,
            status: r.status,
            provider: r.provider,
            package_name: r.package_name || null,
            paid_at: r.paid_at,
            created_at: r.created_at,
            case_id: r.case_id,
            split_id: r.split_id,
            discount_cents: r.discount_cents,
          })),
          href: `/admin/pipeline?client=${resolved.clientId}`,
        },
      };
    }

    if (name === "list_installments") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const limit = adminAiClampLimit(args.limit, 15);
      const statusRaw = String(args.status || "")
        .trim()
        .toLowerCase();
      const where = ["ps.client_id = ?"];
      const params: any[] = [resolved.clientId];
      if (resolved.caseId) {
        where.push("ps.case_id = ?");
        params.push(resolved.caseId);
      }
      if (statusRaw === "open") {
        where.push("ps.status IN ('pending','overdue')");
      } else if (
        statusRaw === "pending" ||
        statusRaw === "processing" ||
        statusRaw === "paid" ||
        statusRaw === "overdue" ||
        statusRaw === "cancelled"
      ) {
        where.push("ps.status = ?");
        params.push(statusRaw);
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT ps.id, ps.case_id, ps.label, ps.amount_cents, ps.currency,
                ps.due_date, ps.status, ps.paid_at, ps.completion_source,
                ps.send_payment_link, cr.case_number,
                pst.token AS payment_token
         FROM payment_splits ps
         LEFT JOIN credit_repair_cases cr ON cr.id = ps.case_id
         LEFT JOIN payment_split_tokens pst ON pst.split_id = ps.id AND pst.used_at IS NULL
         WHERE ${where.join(" AND ")}
         ORDER BY
           FIELD(ps.status, 'overdue', 'pending', 'processing', 'paid', 'cancelled'),
           ps.due_date ASC, ps.id ASC
         LIMIT ?`,
        [...params, limit],
      );
      const [agg] = await pool.query<RowDataPacket[]>(
        `SELECT
           COALESCE(SUM(CASE WHEN status IN ('pending','overdue') THEN amount_cents ELSE 0 END), 0) AS owed_cents,
           COALESCE(SUM(CASE WHEN status = 'overdue' THEN amount_cents ELSE 0 END), 0) AS overdue_cents,
           COALESCE(SUM(CASE WHEN status = 'paid' THEN amount_cents ELSE 0 END), 0) AS paid_cents,
           SUM(status = 'overdue') AS overdue_count,
           SUM(status IN ('pending','overdue')) AS open_count
         FROM payment_splits
         WHERE client_id = ?${resolved.caseId ? " AND case_id = ?" : ""}`,
        resolved.caseId
          ? [resolved.clientId, resolved.caseId]
          : [resolved.clientId],
      );
      return {
        ok: true,
        data: {
          client_id: resolved.clientId,
          case_id: resolved.caseId,
          case_number: resolved.caseNumber,
          owed_cents: Number(agg[0]?.owed_cents || 0),
          overdue_cents: Number(agg[0]?.overdue_cents || 0),
          paid_cents: Number(agg[0]?.paid_cents || 0),
          overdue_count: Number(agg[0]?.overdue_count || 0),
          open_count: Number(agg[0]?.open_count || 0),
          installments: rows.map((r) => ({
            id: r.id,
            case_id: r.case_id,
            case_number: r.case_number,
            label: r.label,
            amount_cents: r.amount_cents,
            currency: r.currency,
            due_date: r.due_date,
            status: r.status,
            paid_at: r.paid_at,
            completion_source: r.completion_source,
            send_payment_link: !!r.send_payment_link,
            payment_link: r.payment_token
              ? `${APP_URL}/pay/${r.payment_token}`
              : null,
          })),
          href: `/admin/pipeline?client=${resolved.clientId}`,
        },
      };
    }

    if (name === "list_clients_owing") {
      const limit = adminAiClampLimit(args.limit, 15);
      const modeRaw = String(args.mode || "overdue")
        .trim()
        .toLowerCase();
      const mode =
        modeRaw === "pending" || modeRaw === "open" || modeRaw === "overdue"
          ? modeRaw
          : "overdue";
      const search =
        typeof args.search === "string" ? args.search.trim().slice(0, 120) : "";

      const where = ["c.status <> 'cancelled'"];
      const params: any[] = [];
      if (mode === "overdue") {
        // DB status=overdue OR past-due pending (no cron flips pending→overdue).
        where.push(
          `(ps.status = 'overdue' OR (ps.status = 'pending' AND ps.due_date < CURDATE()))`,
        );
      } else if (mode === "pending") {
        where.push("ps.status = 'pending'");
      } else {
        where.push("ps.status IN ('pending','overdue')");
      }
      if (scopedIds && scopedIds.length > 0) {
        where.push("c.affiliate_id IN (?)");
        params.push(scopedIds);
      }
      if (search) {
        const like = likeContains(search);
        where.push(`(
          c.email LIKE ? ESCAPE '!'
          OR c.first_name LIKE ? ESCAPE '!'
          OR c.last_name LIKE ? ESCAPE '!'
          OR CONCAT(c.first_name,' ',c.last_name) LIKE ? ESCAPE '!'
          OR COALESCE(cr.case_number,'') LIKE ? ESCAPE '!'
        )`);
        params.push(like, like, like, like, like);
      }

      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT ps.id AS split_id, ps.label, ps.amount_cents, ps.currency,
                ps.due_date, ps.status, ps.case_id, ps.client_id,
                cr.case_number, cr.pipeline_stage,
                c.first_name, c.last_name, c.email, c.phone, c.status AS client_status,
                DATEDIFF(CURDATE(), ps.due_date) AS days_past_due
         FROM payment_splits ps
         JOIN clients c ON c.id = ps.client_id
         LEFT JOIN credit_repair_cases cr ON cr.id = ps.case_id
         WHERE ${where.join(" AND ")}
         ORDER BY
           FIELD(ps.status, 'overdue', 'pending'),
           ps.due_date ASC, ps.id ASC
         LIMIT ?`,
        [...params, limit],
      );

      const [tot] = await pool.query<RowDataPacket[]>(
        `SELECT
           COALESCE(SUM(ps.amount_cents), 0) AS owed_cents,
           COUNT(*) AS installment_count,
           COUNT(DISTINCT ps.client_id) AS client_count
         FROM payment_splits ps
         JOIN clients c ON c.id = ps.client_id
         LEFT JOIN credit_repair_cases cr ON cr.id = ps.case_id
         WHERE ${where.join(" AND ")}`,
        params,
      );

      return {
        ok: true,
        data: {
          mode,
          owed_cents: Number(tot[0]?.owed_cents || 0),
          installment_count: Number(tot[0]?.installment_count || 0),
          client_count: Number(tot[0]?.client_count || 0),
          installments: rows.map((r) => ({
            split_id: r.split_id,
            client_id: r.client_id,
            client_name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            email: r.email,
            phone: r.phone,
            client_status: r.client_status,
            case_id: r.case_id,
            case_number: r.case_number,
            pipeline_stage: r.pipeline_stage,
            label: r.label,
            amount_cents: r.amount_cents,
            currency: r.currency,
            due_date: r.due_date,
            status: r.status,
            days_past_due: Number(r.days_past_due || 0),
            href: `/admin/pipeline?client=${r.client_id}`,
          })),
          href: "/admin/payments",
        },
      };
    }

    if (name === "list_round_schedule") {
      const hasId = args.case_id != null && Number(args.case_id) > 0;
      const hasNumber =
        typeof args.case_number === "string" && !!args.case_number.trim();
      if (!hasId && !hasNumber) {
        return {
          ok: false,
          error: "invalid_args",
          message: "case_id or case_number is required",
        };
      }
      const caseRow = await adminAiResolveCaseRow(args, scopedIds);
      if (!caseRow) {
        return { ok: false, error: "not_found", message: "Case not found" };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT round_1_date, round_2_date, round_3_date, round_4_date, round_5_date,
                interval_days, last_sent_at, calendar_send_count
         FROM case_round_schedules
         WHERE case_id = ?
         LIMIT 1`,
        [caseRow.id],
      );
      if (!rows[0]) {
        return {
          ok: true,
          data: {
            case_id: caseRow.id,
            case_number: caseRow.case_number,
            client_id: caseRow.client_id,
            scheduled: false,
            message: "No round calendar schedule set for this case",
            href: `/admin/pipeline?case=${caseRow.id}`,
          },
        };
      }
      const s = rows[0];
      return {
        ok: true,
        data: {
          case_id: caseRow.id,
          case_number: caseRow.case_number,
          client_id: caseRow.client_id,
          scheduled: true,
          interval_days: s.interval_days,
          last_sent_at: s.last_sent_at,
          calendar_send_count: s.calendar_send_count,
          rounds: [
            { round: 1, date: s.round_1_date },
            { round: 2, date: s.round_2_date },
            { round: 3, date: s.round_3_date },
            { round: 4, date: s.round_4_date },
            { round: 5, date: s.round_5_date },
          ],
          href: `/admin/pipeline?case=${caseRow.id}`,
        },
      };
    }

    if (
      name === "create_prospect" ||
      name === "create_contact" ||
      name === "update_contact" ||
      name === "convert_contact" ||
      name === "send_contact_sms" ||
      name === "send_contact_email" ||
      name === "create_work_task" ||
      name === "update_work_task" ||
      name === "add_case_note" ||
      name === "upload_case_document" ||
      name === "send_email" ||
      name === "send_round_report" ||
      name === "send_sms" ||
      name === "update_pipeline_stage" ||
      name === "convert_prospect" ||
      name === "update_client" ||
      name === "update_client_status" ||
      name === "upsert_progress_report" ||
      name === "set_case_payment_plan" ||
      name === "upsert_payment_splits" ||
      name === "update_payment_split" ||
      name === "create_coupon"
    ) {
      // Any affiliate scope (including orphan empty scopedIds) blocks writes
      if (scope) {
        return {
          ok: false,
          error: "forbidden",
          message: "Write tools are not available to affiliate accounts",
        };
      }
    }

    if (name === "create_contact") {
      const firstName = String(args.first_name || "")
        .trim()
        .slice(0, 100);
      const lastName = String(args.last_name || "")
        .trim()
        .slice(0, 100);
      const phoneRaw = String(args.phone || "")
        .trim()
        .slice(0, 20);
      const emailRaw = String(args.email || "")
        .trim()
        .toLowerCase()
        .slice(0, 255);
      const phone = phoneRaw || null;
      const email = emailRaw || null;
      const langExplicit =
        args.preferred_language === "es" || args.preferred_language === "en"
          ? (args.preferred_language as "en" | "es")
          : null;
      const lang = langExplicit || "en";
      const notesRaw =
        args.notes != null
          ? args.notes
          : args.admin_notes != null
            ? args.admin_notes
            : "";
      const notes = decodeLiteralUnicodeEscapes(String(notesRaw || ""))
        .trim()
        .slice(0, 5000);
      const addressLine1 =
        String(args.address_line1 || "")
          .trim()
          .slice(0, 255) || null;
      const addressLine2 =
        String(args.address_line2 || "")
          .trim()
          .slice(0, 255) || null;
      const city =
        String(args.city || "")
          .trim()
          .slice(0, 100) || null;
      const state =
        String(args.state || "")
          .trim()
          .slice(0, 50) || null;
      const zip =
        String(args.zip || "")
          .trim()
          .slice(0, 20) || null;

      const missing: string[] = [];
      if (!firstName) missing.push("first_name");
      if (!lastName) missing.push("last_name");
      if (!phone && !email) missing.push("phone or email");
      if (email && !isValidEmail(email)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "email is invalid",
        };
      }
      let phoneNormalized: string | null = phone;
      if (phone && !normalizePhoneLast10(phone)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "phone must include at least 10 digits",
        };
      }
      if (phoneNormalized) {
        phoneNormalized = toSmsE164(phoneNormalized).slice(0, 20);
      }

      const duplicates = await findCrmContactDuplicates({
        phone: phoneNormalized,
        email,
      });
      const hasDups =
        duplicates.clients.length > 0 || duplicates.contacts.length > 0;
      const namedOwner = await resolveMcpStaffAssignee({
        adminId: args.assigned_admin_id,
        name: args.assigned_admin_name,
        email: args.assigned_admin_email,
      });
      if (namedOwner.ok === false) return namedOwner;
      const ownerId = namedOwner.requested
        ? namedOwner.id
        : await resolveLanguageOwnerAdminId(lang);
      const preview = {
        first_name: firstName || null,
        last_name: lastName || null,
        phone: phoneNormalized,
        email,
        preferred_language: lang,
        notes: notes || null,
        address_line1: addressLine1,
        address_line2: addressLine2,
        city,
        state,
        zip,
        assigned_admin_id: ownerId ?? ctx.adminId,
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            duplicates,
            guidance:
              "Ask the user for the missing fields, then call create_contact again (still confirm=false) until ready. Use create_prospect instead if they should go on Pipeline immediately.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            duplicates,
            requires_confirm_duplicate: hasDups,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: hasDups
              ? `Matching phone/email found. Show duplicates. If they still want a new contact, re-call with confirm=true, confirm_duplicate=true, and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`
              : `Show this address-book preview (not Pipeline). After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      if (hasDups && !adminAiConfirmTrue(args.confirm_duplicate)) {
        return {
          ok: false,
          error: "duplicate",
          message:
            "Matching phone or email already exists. Set confirm_duplicate=true only after the user approves creating another contact.",
        };
      }

      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO contacts
           (first_name, last_name, email, phone, address_line1, address_line2,
            city, state, zip, preferred_language, admin_notes,
            assigned_admin_id, created_by_admin_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          firstName,
          lastName,
          email,
          phoneNormalized,
          addressLine1,
          addressLine2,
          city,
          state,
          zip,
          lang,
          notes || null,
          ownerId ?? ctx.adminId,
          ctx.adminId,
        ],
      );
      const contactId = Number(ins.insertId);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM contacts WHERE id = ? LIMIT 1`,
        [contactId],
      );
      return {
        ok: true,
        data: {
          created: true,
          contact: mapCrmContactRow(rows[0]),
          href: `/admin/contacts`,
          guidance:
            "Saved to CRM Contacts (not on Pipeline). Use convert_contact when ready to add as prospect.",
        },
      };
    }

    if (name === "update_contact") {
      const contactId =
        args.contact_id != null && Number(args.contact_id) > 0
          ? Number(args.contact_id)
          : 0;
      if (!contactId) {
        return {
          ok: false,
          error: "invalid_args",
          message: "contact_id is required",
        };
      }
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM contacts
         WHERE id = ? AND deleted_at IS NULL AND converted_client_id IS NULL
         LIMIT 1`,
        [contactId],
      );
      if (!existing[0]) {
        return {
          ok: false,
          error: "not_found",
          message:
            "Contact not found (or already converted/deleted). Use search_contacts.",
        };
      }
      const cur = existing[0];
      const firstName =
        args.first_name != null
          ? String(args.first_name).trim().slice(0, 100)
          : String(cur.first_name || "");
      const lastName =
        args.last_name != null
          ? String(args.last_name).trim().slice(0, 100)
          : String(cur.last_name || "");
      const email =
        args.email !== undefined
          ? String(args.email || "")
              .trim()
              .toLowerCase()
              .slice(0, 255) || null
          : cur.email != null
            ? String(cur.email)
            : null;
      let phoneNormalized: string | null =
        args.phone !== undefined
          ? String(args.phone || "")
              .trim()
              .slice(0, 40) || null
          : cur.phone != null
            ? String(cur.phone)
            : null;
      if (args.phone !== undefined && phoneNormalized) {
        if (!normalizePhoneLast10(phoneNormalized)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "phone must include at least 10 digits",
          };
        }
        phoneNormalized = toSmsE164(phoneNormalized).slice(0, 20);
      } else if (phoneNormalized && !normalizePhoneLast10(phoneNormalized)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "phone must include at least 10 digits",
        };
      }
      const lang =
        args.preferred_language === "es"
          ? "es"
          : args.preferred_language === "en"
            ? "en"
            : cur.preferred_language === "es"
              ? "es"
              : "en";
      const notesProvided = args.notes !== undefined || args.admin_notes !== undefined;
      const notesRaw = notesProvided
        ? args.notes !== undefined
          ? args.notes
          : args.admin_notes
        : cur.admin_notes;
      const notes = notesProvided
        ? decodeLiteralUnicodeEscapes(String(notesRaw || ""))
            .trim()
            .slice(0, 5000) || null
        : cur.admin_notes != null
          ? String(cur.admin_notes)
          : null;
      const addressLine1 =
        args.address_line1 !== undefined
          ? String(args.address_line1 || "")
              .trim()
              .slice(0, 255) || null
          : cur.address_line1;
      const addressLine2 =
        args.address_line2 !== undefined
          ? String(args.address_line2 || "")
              .trim()
              .slice(0, 255) || null
          : cur.address_line2;
      const city =
        args.city !== undefined
          ? String(args.city || "")
              .trim()
              .slice(0, 100) || null
          : cur.city;
      const state =
        args.state !== undefined
          ? String(args.state || "")
              .trim()
              .slice(0, 50) || null
          : cur.state;
      const zip =
        args.zip !== undefined
          ? String(args.zip || "")
              .trim()
              .slice(0, 20) || null
          : cur.zip;

      if (!firstName || !lastName) {
        return {
          ok: false,
          error: "invalid_args",
          message: "first_name and last_name are required",
        };
      }
      if (!email && !phoneNormalized) {
        return {
          ok: false,
          error: "invalid_args",
          message: "email or phone is required",
        };
      }
      if (email && !isValidEmail(email)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "email is invalid",
        };
      }

      const duplicates = await findCrmContactDuplicates({
        phone: phoneNormalized,
        email,
        excludeContactId: contactId,
      });
      const hasDups =
        duplicates.clients.length > 0 || duplicates.contacts.length > 0;
      const namedOwner = await resolveMcpStaffAssignee({
        adminId: args.assigned_admin_id,
        name: args.assigned_admin_name,
        email: args.assigned_admin_email,
      });
      if (namedOwner.ok === false) return namedOwner;
      const ownerId = namedOwner.requested
        ? namedOwner.id
        : cur.assigned_admin_id != null
          ? Number(cur.assigned_admin_id)
          : null;
      const preview = {
        contact_id: contactId,
        first_name: firstName,
        last_name: lastName,
        phone: phoneNormalized,
        email,
        preferred_language: lang,
        assigned_admin_id: ownerId,
        notes,
        address_line1: addressLine1,
        address_line2: addressLine2,
        city,
        state,
        zip,
      };

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            duplicates,
            requires_confirm_duplicate: hasDups,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: hasDups
              ? `Matching phone/email found. Show duplicates. If they still want to save, re-call with confirm=true, confirm_duplicate=true, and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`
              : `Show this contact update. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      if (hasDups && !adminAiConfirmTrue(args.confirm_duplicate)) {
        return {
          ok: false,
          error: "duplicate",
          message:
            "Matching phone or email already exists. Set confirm_duplicate=true only after the user approves.",
        };
      }

      await pool.query(
        `UPDATE contacts SET
           first_name = ?, last_name = ?, email = ?, phone = ?,
           address_line1 = ?, address_line2 = ?, city = ?, state = ?, zip = ?,
           preferred_language = ?, admin_notes = ?, assigned_admin_id = ?
         WHERE id = ?`,
        [
          firstName,
          lastName,
          email,
          phoneNormalized,
          addressLine1,
          addressLine2,
          city,
          state,
          zip,
          lang,
          notes,
          ownerId,
          contactId,
        ],
      );
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM contacts WHERE id = ? LIMIT 1`,
        [contactId],
      );
      return {
        ok: true,
        data: {
          updated: true,
          contact: mapCrmContactRow(rows[0]),
          href: `/admin/contacts`,
        },
      };
    }

    if (name === "convert_contact") {
      const contactId =
        args.contact_id != null && Number(args.contact_id) > 0
          ? Number(args.contact_id)
          : 0;
      if (!contactId) {
        return {
          ok: false,
          error: "invalid_args",
          message: "contact_id is required",
        };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM contacts
         WHERE id = ? AND deleted_at IS NULL AND converted_client_id IS NULL
         LIMIT 1`,
        [contactId],
      );
      if (!rows[0]) {
        return {
          ok: false,
          error: "not_found",
          message:
            "Contact not found (or already converted/deleted). Use search_contacts.",
        };
      }
      const c = rows[0];
      const phone = c.phone ? String(c.phone) : null;
      const email = c.email ? String(c.email).toLowerCase() : null;
      if (!phone && !email) {
        return {
          ok: false,
          error: "invalid_args",
          message:
            "Contact needs phone or email before convert. Use update_contact first.",
        };
      }

      const phoneDups = phone ? await adminAiFindPhoneDuplicates(phone) : [];
      let emailDupClientId: number | null = null;
      if (email) {
        const [emailDup] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM clients WHERE LOWER(email) = ? LIMIT 1`,
          [email],
        );
        if (emailDup[0]) emailDupClientId = Number(emailDup[0].id);
      }
      const existingClientId =
        phoneDups.length > 0
          ? Number(phoneDups[0].id)
          : emailDupClientId != null
            ? emailDupClientId
            : null;
      const lang = c.preferred_language === "es" ? "es" : "en";
      const namedOwner = await resolveMcpStaffAssignee({
        adminId: args.assigned_admin_id,
        name: args.assigned_admin_name,
        email: args.assigned_admin_email,
      });
      if (namedOwner.ok === false) return namedOwner;
      const ownerId = namedOwner.requested
        ? namedOwner.id
        : c.assigned_admin_id != null
          ? Number(c.assigned_admin_id)
          : ((await resolveLanguageOwnerAdminId(lang)) ?? ctx.adminId);
      const preview = {
        contact_id: contactId,
        first_name: c.first_name,
        last_name: c.last_name,
        phone,
        email,
        preferred_language: lang,
        assigned_admin_id: ownerId,
        status: "prospect",
        pipeline_stage: "prospect",
        notes: c.admin_notes
          ? decodeLiteralUnicodeEscapes(String(c.admin_notes)).slice(0, 400)
          : null,
        will_link_existing_client_id: existingClientId,
      };

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            phone_duplicates: phoneDups,
            email_duplicate_client_id: emailDupClientId,
            existing_client_id: existingClientId,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance:
              existingClientId != null
                ? `Phone/email matches existing client_id=${existingClientId}. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}" to LINK this contact to that client (no new prospect).`
                : `Show convert preview (contact → Pipeline prospect). After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      // Hard-block twins: link contact to existing client when phone/email matches.
      if (existingClientId != null) {
        await pool.query(
          `UPDATE conversations
           SET client_id = ?, contact_id = NULL
           WHERE contact_id = ?`,
          [existingClientId, contactId],
        );
        await pool.query(
          `UPDATE contacts
           SET converted_client_id = ?, converted_at = NOW()
           WHERE id = ?`,
          [existingClientId, contactId],
        );
        return {
          ok: true,
          data: {
            existing: true,
            converted: true,
            linked_existing: true,
            contact_id: contactId,
            client_id: existingClientId,
            preferred_language: lang,
            href: `/admin/pipeline?client=${existingClientId}`,
            message: `Contact linked to existing client_id=${existingClientId} (no twin created).`,
          },
        };
      }

      let clientId: number;
      try {
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO clients
             (first_name, last_name, phone, email, status, pipeline_stage,
              preferred_language, assigned_admin_id, admin_notes,
              address_line1, address_line2, city, state, zip)
           VALUES (?, ?, ?, ?, 'prospect', 'prospect', ?, ?, ?, ?, ?, ?, ?, ?)`,
          [
            c.first_name,
            c.last_name,
            phone,
            email,
            lang,
            ownerId,
            c.admin_notes,
            c.address_line1,
            c.address_line2,
            c.city,
            c.state,
            c.zip,
          ],
        );
        clientId = Number(ins.insertId);
      } catch (e: any) {
        if (
          e?.code === "ER_DUP_ENTRY" ||
          /Duplicate/i.test(String(e?.message))
        ) {
          const [dup] = await pool.query<RowDataPacket[]>(
            `SELECT id FROM clients WHERE LOWER(email) = ? LIMIT 1`,
            [email],
          );
          if (dup[0]) {
            const dupId = Number(dup[0].id);
            await pool.query(
              `UPDATE conversations
               SET client_id = ?, contact_id = NULL
               WHERE contact_id = ?`,
              [dupId, contactId],
            );
            await pool.query(
              `UPDATE contacts
               SET converted_client_id = ?, converted_at = NOW()
               WHERE id = ?`,
              [dupId, contactId],
            );
            return {
              ok: true,
              data: {
                existing: true,
                converted: true,
                linked_existing: true,
                contact_id: contactId,
                client_id: dupId,
                preferred_language: lang,
                href: `/admin/pipeline?client=${dupId}`,
                message: `Contact linked to existing client_id=${dupId} (no twin created).`,
              },
            };
          }
          return {
            ok: false,
            error: "duplicate",
            message: "A client with this email already exists.",
          };
        }
        throw e;
      }
      await pool.query(
        `UPDATE conversations
         SET client_id = ?, contact_id = NULL
         WHERE contact_id = ?`,
        [clientId, contactId],
      );
      await pool.query(
        `UPDATE contacts
         SET converted_client_id = ?, converted_at = NOW()
         WHERE id = ?`,
        [clientId, contactId],
      );
      return {
        ok: true,
        data: {
          converted: true,
          contact_id: contactId,
          client_id: clientId,
          preferred_language: lang,
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "send_contact_sms") {
      const contactId =
        args.contact_id != null && Number(args.contact_id) > 0
          ? Number(args.contact_id)
          : 0;
      const rawBody = decodeLiteralUnicodeEscapes(
        String(args.body || args.message || ""),
      ).trim();
      if ([...rawBody].length > SMS_MAX_BODY_CHARS) {
        return {
          ok: false,
          error: "sms_body_too_long",
          message: `SMS body exceeds ${SMS_MAX_BODY_CHARS} characters`,
        };
      }
      const body = rawBody;
      const missing: string[] = [];
      if (!contactId) missing.push("contact_id");
      if (!body) missing.push("body");

      let contactName: string | null = null;
      let toPhone: string | null = null;
      let conversationClosed = false;
      let fromE164: string | null = null;
      let fromAdminId = ctx.adminId;

      if (missing.length === 0) {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, phone, deleted_at, converted_client_id
           FROM contacts WHERE id = ? LIMIT 1`,
          [contactId],
        );
        if (!rows[0] || rows[0].deleted_at) {
          return {
            ok: false,
            error: "not_found",
            message:
              "Contact not found (or soft-deleted). Use search_contacts.",
          };
        }
        if (rows[0].converted_client_id != null) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "Contact was already converted to a pipeline prospect. Use send_sms with that client_id instead.",
          };
        }
        contactName =
          `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim();
        toPhone = rows[0].phone ? String(rows[0].phone).trim() : null;
        if (!toPhone) {
          return {
            ok: false,
            error: "no_phone",
            message:
              "Contact has no phone on file. Use update_contact to set phone, then retry.",
          };
        }
        const fromResolved = await resolveMcpSmsFromE164(ctx.adminId, args);
        if (fromResolved.ok === false) return fromResolved;
        fromE164 = fromResolved.e164;
        fromAdminId = fromResolved.from_admin_id;
        conversationClosed = await contactComposeBlockedByClosed({
          crmContactId: contactId,
        });
      }

      const preview = {
        audience: "contact" as const,
        contact_id: contactId || null,
        contact_name: contactName,
        to: toPhone,
        from: fromE164,
        body,
        conversation_closed: conversationClosed,
        will_log_conversations_hub: true,
        will_log_contact_note: true,
        note: conversationClosed
          ? "Conversation is closed. On confirm, it will reopen and the SMS will send via Conversations hub + contact admin_notes."
          : "Dry-run does not send. On confirm, SMS sends via Twilio into Conversations hub and appends [SMS …] to contacts.admin_notes.",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect contact_id (from search_contacts) and body. Do not pass client_id here — use send_sms for pipeline clients.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the exact To / From / body. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let reopened = false;
      if (conversationClosed) {
        await setContactConversationStatus({
          crmContactId: contactId,
          status: "open",
          adminId: ctx.adminId,
        });
        reopened = true;
      }

      let messageId: number | null = null;
      let conversationId: number | null = null;
      let providerMessageId: string | null = null;
      let providerStatus: string | null = null;
      let contactNoteAppended = false;

      try {
        const result = await deliverHubConversationMessage({
          adminId: fromAdminId,
          crmContactId: contactId,
          channel: "sms",
          textBody: body,
        });
        messageId = result.message_id;
        conversationId = result.conversation_id;
        contactNoteAppended = !!result.contact_note_appended;
        const [mrows] = await pool.query<RowDataPacket[]>(
          `SELECT provider_message_id, provider_status, error_message
           FROM conversation_messages WHERE id = ? LIMIT 1`,
          [result.message_id],
        );
        providerMessageId = mrows[0]?.provider_message_id
          ? String(mrows[0].provider_message_id)
          : null;
        providerStatus = mrows[0]?.provider_status
          ? String(mrows[0].provider_status)
          : result.provider_status;
        if (!result.ok && result.error) {
          return {
            ok: false,
            error: "send_failed",
            message: String(result.error).slice(0, 400),
          };
        }
      } catch (e: any) {
        const msg = String(e?.message || e);
        if (
          msg === "conversation_closed" ||
          e?.code === "conversation_closed"
        ) {
          return {
            ok: false,
            error: "conversation_closed",
            message:
              "Conversation is still closed. Reopen in Conversations, then retry send_contact_sms.",
          };
        }
        return {
          ok: false,
          error: "send_failed",
          message: msg.slice(0, 400),
        };
      }

      return {
        ok: true,
        data: {
          sent: true,
          audience: "contact",
          contact_id: contactId,
          contact_name: contactName,
          to: toPhone,
          from: fromE164,
          body,
          message_id: messageId,
          conversation_id: conversationId,
          provider_message_id: providerMessageId,
          provider_status: providerStatus,
          reopened,
          sent_at: new Date().toISOString(),
          note_appended: contactNoteAppended,
          contact_note_appended: contactNoteAppended,
          href: `/admin/conversations?contact=${contactId}`,
        },
      };
    }

    if (name === "send_contact_email") {
      const contactId =
        args.contact_id != null && Number(args.contact_id) > 0
          ? Number(args.contact_id)
          : 0;
      const subject = decodeLiteralUnicodeEscapes(String(args.subject || ""))
        .trim()
        .slice(0, 200);
      const body = decodeLiteralUnicodeEscapes(String(args.body || ""))
        .trim()
        .slice(0, 8000);
      const missing: string[] = [];
      if (!contactId) missing.push("contact_id");
      if (!subject) missing.push("subject");
      if (!body) missing.push("body");

      let contactName: string | null = null;
      let toEmail: string | null = null;
      let toLang: "en" | "es" = "en";

      if (missing.length === 0) {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, email, preferred_language,
                  deleted_at, converted_client_id
           FROM contacts WHERE id = ? LIMIT 1`,
          [contactId],
        );
        if (!rows[0] || rows[0].deleted_at) {
          return {
            ok: false,
            error: "not_found",
            message:
              "Contact not found (or soft-deleted). Use search_contacts.",
          };
        }
        if (rows[0].converted_client_id != null) {
          return {
            ok: false,
            error: "invalid_args",
            message:
              "Contact was already converted to a pipeline prospect. Use send_email with that client_id instead.",
          };
        }
        contactName =
          `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim();
        toEmail = rows[0].email ? String(rows[0].email).trim() : null;
        toLang = rows[0].preferred_language === "es" ? "es" : "en";
        if (!toEmail) {
          return {
            ok: false,
            error: "no_email",
            message:
              "Contact has no email on file. Use update_contact to set email, then retry.",
          };
        }
        if (!isValidEmail(toEmail)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "Contact email is invalid. Fix with update_contact.",
          };
        }
      }

      const preview = {
        audience: "contact" as const,
        contact_id: contactId || null,
        contact_name: contactName,
        to: toEmail,
        subject,
        body,
        will_log_contact_note: true,
        note: "Dry-run does not send. On confirm, branded email is sent via OFG mailer and [EMAIL …] is appended to contacts.admin_notes.",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect contact_id (from search_contacts), subject, and body. Do not pass client_id here — use send_email for pipeline clients.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the exact To / subject / body. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      const isEs = toLang === "es";
      const firstName =
        (contactName || "").split(/\s+/).filter(Boolean)[0] ||
        (isEs ? "amigo" : "there");
      const bodyLooksGreeted = /^(hi|hola|hello|dear)\b/i.test(body);
      const safeBodyHtml = escapeHtml(body).replace(/\r?\n/g, "<br/>");
      const greetingHtml = bodyLooksGreeted
        ? ""
        : `<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">${
            isEs ? "Hola" : "Hi"
          } ${escapeHtml(firstName)},</p>`;
      const html = emailLayout({
        title: subject,
        preheader: subject,
        bodyHtml: `${greetingHtml}<div style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">${safeBodyHtml}</div>`,
        lang: toLang,
      });

      try {
        await sendEmail({
          to: toEmail as string,
          subject,
          html,
        });
      } catch (e: any) {
        return {
          ok: false,
          error: "send_failed",
          message: String(e?.message || "Email send failed").slice(0, 400),
        };
      }

      const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
      const stamped = `[EMAIL ${ts} UTC] Sent to ${toEmail}\nSubject: ${subject}\n${body.slice(0, 1500)}`;
      const contactNoteAppended = await appendContactFileNote(
        contactId,
        stamped,
      );

      return {
        ok: true,
        data: {
          sent: true,
          audience: "contact",
          contact_id: contactId,
          contact_name: contactName,
          to: toEmail,
          subject,
          note_appended: contactNoteAppended,
          contact_note_appended: contactNoteAppended,
          href: `/admin/contacts`,
        },
      };
    }

    if (name === "create_prospect") {
      const firstName = String(args.first_name || "")
        .trim()
        .slice(0, 100);
      const lastName = String(args.last_name || "")
        .trim()
        .slice(0, 100);
      // clients.phone / referrers.phone are VARCHAR(20)
      const phoneRaw = String(args.phone || "")
        .trim()
        .slice(0, 20);
      const emailRaw = String(args.email || "")
        .trim()
        .toLowerCase()
        .slice(0, 255);
      const langExplicit =
        args.preferred_language === "es" || args.preferred_language === "en"
          ? (args.preferred_language as "en" | "es")
          : null;
      const lang = langExplicit || "en";
      const notes = decodeLiteralUnicodeEscapes(String(args.notes || ""))
        .trim()
        .slice(0, 2000);
      const refCatRaw = String(args.referral_category || "").trim();
      const allowedRef = ["realtor_broker", "one_off", "affiliate_partner"];
      const refCategory = allowedRef.includes(refCatRaw) ? refCatRaw : null;
      const refIdArg =
        args.referrer_id != null && Number(args.referrer_id) > 0
          ? Number(args.referrer_id)
          : null;
      const refFirst = String(args.referrer_first_name || "")
        .trim()
        .slice(0, 100);
      const refLast = String(args.referrer_last_name || "")
        .trim()
        .slice(0, 100);
      const refPhone = String(args.referrer_phone || "")
        .trim()
        .slice(0, 20);
      const refEmailRaw = String(args.referrer_email || "")
        .trim()
        .toLowerCase()
        .slice(0, 255);

      const missing: string[] = [];
      if (!firstName) missing.push("first_name");
      if (!lastName) missing.push("last_name");
      if (!phoneRaw) missing.push("phone");
      if (!langExplicit) {
        missing.push("preferred_language (en or es)");
      }
      if (
        refCategory === "realtor_broker" &&
        !refIdArg &&
        (!refFirst || !refLast)
      ) {
        missing.push(
          "referrer_first_name + referrer_last_name (realtor is the partner, not the client)",
        );
      }
      if (emailRaw && !isValidEmail(emailRaw)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "email is invalid",
        };
      }
      if (refEmailRaw && !isValidEmail(refEmailRaw)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "referrer_email is invalid",
        };
      }
      const phoneLast10 = normalizePhoneLast10(phoneRaw);
      if (phoneRaw && !phoneLast10) {
        return {
          ok: false,
          error: "invalid_args",
          message: "phone must include at least 10 digits",
        };
      }
      if (phoneRaw && isPlaceholderPhone(phoneRaw)) {
        return {
          ok: false,
          error: "placeholder_phone",
          message:
            "This phone looks like a placeholder (e.g. 555… / all same digits). Use the client's real phone.",
        };
      }

      const duplicates = phoneLast10
        ? await adminAiFindPhoneDuplicates(phoneRaw, scopedIds)
        : [];
      let emailExistingId: number | null = null;
      if (emailRaw) {
        const [emailDup] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM clients WHERE email = ? LIMIT 1`,
          [emailRaw],
        );
        if (emailDup[0]) emailExistingId = Number(emailDup[0].id);
      }
      const existingFromPhone =
        duplicates.length > 0 ? Number(duplicates[0].id) : null;
      const existingClientId = existingFromPhone ?? emailExistingId;
      if (existingClientId != null) {
        const href = `/admin/pipeline?client=${existingClientId}`;
        return {
          ok: true,
          data: {
            existing: true,
            client_id: existingClientId,
            href,
            phone_duplicates: duplicates,
            email_duplicate_client_id: emailExistingId,
            message: existingFromPhone
              ? `Phone already belongs to client_id=${existingClientId}. Open that record — a second client was not created.`
              : `Email already belongs to client_id=${existingClientId}. Open that record — a second client was not created.`,
          },
        };
      }

      const namedOwner = await resolveMcpStaffAssignee({
        adminId: args.assigned_admin_id,
        name: args.assigned_admin_name,
        email: args.assigned_admin_email,
      });
      if (namedOwner.ok === false) return namedOwner;
      const ownerId = namedOwner.requested
        ? namedOwner.id
        : langExplicit
          ? await resolveLanguageOwnerAdminId(langExplicit)
          : null;
      const [ownerRows] = ownerId
        ? await pool.query<RowDataPacket[]>(
            `SELECT id, first_name, last_name, email, preferred_language
             FROM admins WHERE id = ? LIMIT 1`,
            [ownerId],
          )
        : ([[], undefined] as any);
      const owner = ownerRows?.[0]
        ? {
            id: Number(ownerRows[0].id),
            name: `${ownerRows[0].first_name || ""} ${ownerRows[0].last_name || ""}`.trim(),
            email: ownerRows[0].email,
            preferred_language: ownerRows[0].preferred_language,
          }
        : null;

      const preview = {
        first_name: firstName || null,
        last_name: lastName || null,
        phone: phoneRaw || null,
        email: emailRaw || null,
        preferred_language: langExplicit,
        assigned_admin: owner,
        referral_category: refCategory,
        referrer: refIdArg
          ? { referrer_id: refIdArg }
          : refFirst
            ? {
                first_name: refFirst,
                last_name: refLast,
                phone: refPhone || null,
                email: refEmailRaw || null,
                category: refCategory || "realtor_broker",
              }
            : null,
        notes: notes || null,
        status: "prospect",
        pipeline_stage: "prospect",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            phone_duplicates: duplicates,
            guidance:
              "Ask the user for the missing fields, then call create_prospect again (still confirm=false) until ready.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            phone_duplicates: duplicates,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show this preview. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let referrerId = refIdArg;
      if (referrerId) {
        const [refRows] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM referrers WHERE id = ? AND status = 'active' LIMIT 1`,
          [referrerId],
        );
        if (!refRows[0]) {
          return {
            ok: false,
            error: "invalid_args",
            message: "referrer_id not found or inactive",
          };
        }
      }

      const noteLine = notes
        ? `[AI intake ${new Date().toISOString().slice(0, 10)}] ${notes}`
        : null;

      const conn = await pool.getConnection();
      let clientId = 0;
      try {
        await conn.beginTransaction();
        if (!referrerId && refFirst && refLast) {
          const cat = refCategory || "realtor_broker";
          const [refIns] = await conn.query<ResultSetHeader>(
            `INSERT INTO referrers
               (category, first_name, last_name, phone, email, preferred_language, status)
             VALUES (?, ?, ?, ?, ?, ?, 'active')`,
            [
              cat,
              refFirst,
              refLast,
              refPhone || null,
              refEmailRaw || null,
              lang,
            ],
          );
          referrerId = Number(refIns.insertId);
        }
        const [ins] = await conn.query<ResultSetHeader>(
          `INSERT INTO clients (
             first_name, last_name, email, phone, status, pipeline_stage,
             preferred_language, assigned_admin_id, admin_notes,
             referral_category, referrer_id
           ) VALUES (?, ?, ?, ?, 'prospect', 'prospect', ?, ?, ?, ?, ?)`,
          [
            firstName,
            lastName,
            emailRaw || null,
            phoneRaw,
            lang,
            ownerId,
            noteLine,
            refCategory,
            referrerId,
          ],
        );
        clientId = Number(ins.insertId);
        await conn.commit();
      } catch (e) {
        await conn.rollback();
        throw e;
      } finally {
        conn.release();
      }

      const labelSlugs = referralCategoryLabelSlugs(refCategory);
      if (labelSlugs.length > 0) {
        await attachLabelsBySlug(clientId, labelSlugs).catch((e: any) =>
          console.error("[admin-ai] create_prospect labels", e?.message ?? e),
        );
      }
      return {
        ok: true,
        data: {
          created: true,
          client_id: clientId,
          name: `${firstName} ${lastName}`.trim(),
          phone: phoneRaw,
          email: emailRaw || null,
          preferred_language: lang,
          assigned_admin: owner,
          referrer_id: referrerId,
          referral_category: refCategory,
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "create_work_task") {
      const title = normalizeWorkTaskTitle(args.title);
      const description = normalizeWorkTaskDescription(args.description) ?? "";
      const missing: string[] = [];
      if (!title) missing.push("title");

      const lang =
        args.preferred_language === "es"
          ? "es"
          : args.preferred_language === "en"
            ? "en"
            : null;
      const namedStaff = await resolveMcpStaffAssignee({
        adminId: args.assignee_admin_id,
        name: args.assignee_name,
        email: args.assignee_email,
      });
      if (namedStaff.ok === false) return namedStaff;
      let assigneeId = namedStaff.requested ? namedStaff.id : null;
      if (!assigneeId) {
        if (!lang) {
          missing.push(
            "assignee_admin_id / assignee_name (when a person is named) or preferred_language (en|es) to route to the DB language owner",
          );
        } else {
          assigneeId = await resolveLanguageOwnerAdminId(lang);
          if (!assigneeId) {
            return {
              ok: false,
              error: "no_language_owner",
              message: `No active language owner in DB for preferred_language=${lang} (set admins.language_owner_for)`,
            };
          }
        }
      }

      const priorityRaw = String(args.priority || "medium");
      const priority = ["low", "medium", "high", "urgent"].includes(priorityRaw)
        ? priorityRaw
        : "medium";
      const dueRaw = args.due_at != null ? String(args.due_at).trim() : "";
      let dueAt: string | null = null;
      if (dueRaw) {
        const d = new Date(
          dueRaw.length === 10 ? `${dueRaw}T12:00:00Z` : dueRaw,
        );
        if (isNaN(d.getTime())) {
          return {
            ok: false,
            error: "invalid_args",
            message: "due_at must be ISO datetime or YYYY-MM-DD",
          };
        }
        dueAt = d.toISOString().slice(0, 19).replace("T", " ");
      }
      const labels = Array.isArray(args.labels)
        ? args.labels
            .map((l) => decodeLiteralUnicodeEscapes(String(l)))
            .slice(0, 20)
        : [];
      const pushHubspot = adminAiConfirmTrue(args.push_hubspot);

      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let clientId: number | null = null;
      if (
        args.case_id != null ||
        (typeof args.case_number === "string" && args.case_number.trim())
      ) {
        const caseRow = await adminAiResolveCaseRow(args, scopedIds);
        if (!caseRow) {
          return { ok: false, error: "not_found", message: "Case not found" };
        }
        caseId = Number(caseRow.id);
        caseNumber = caseRow.case_number ? String(caseRow.case_number) : null;
        clientId = Number(caseRow.client_id);
      } else if (args.client_id != null && Number(args.client_id) > 0) {
        clientId = Number(args.client_id);
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM clients WHERE id = ? AND status <> 'cancelled' LIMIT 1`,
          [clientId],
        );
        if (!cRows[0]) {
          return { ok: false, error: "not_found", message: "Client not found" };
        }
        if (!(await assertClientInAffiliateScope(clientId, scope))) {
          return { ok: false, error: "not_found", message: "Client not found" };
        }
        const [cr] = await pool.query<RowDataPacket[]>(
          `SELECT id, case_number FROM credit_repair_cases
           WHERE client_id = ? AND status <> 'cancelled'
           ORDER BY id DESC LIMIT 1`,
          [clientId],
        );
        if (cr[0]) {
          caseId = Number(cr[0].id);
          caseNumber = cr[0].case_number ? String(cr[0].case_number) : null;
        }
      }

      let assigneeMeta: Record<string, unknown> | null = null;
      if (assigneeId) {
        const [aRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, email, preferred_language, status
           FROM admins WHERE id = ? LIMIT 1`,
          [assigneeId],
        );
        if (!aRows[0] || aRows[0].status !== "active") {
          return {
            ok: false,
            error: "invalid_args",
            message: "assignee_admin_id not found or inactive",
          };
        }
        assigneeMeta = {
          id: Number(aRows[0].id),
          name: `${aRows[0].first_name || ""} ${aRows[0].last_name || ""}`.trim(),
          email: aRows[0].email,
          preferred_language: aRows[0].preferred_language,
        };
      }

      const hubspotCapability = await adminAiHubspotPushPreview(ctx.adminId);
      const preview = {
        title,
        description: description || null,
        status: "backlog",
        priority,
        due_at: dueAt,
        labels,
        assignee: assigneeMeta,
        preferred_language: lang,
        case_id: caseId,
        case_number: caseNumber,
        client_id: clientId,
        push_hubspot: pushHubspot,
        hubspot: pushHubspot
          ? hubspotCapability
          : "ofg_only_push_hubspot_false",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect missing fields from the user, then call again with confirm=false until ready.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show this task preview. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}". Never set status=done.`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO admin_work_tasks
           (title, description, status, priority, due_at, labels_json, source,
            assignee_admin_id, case_id, created_by_admin_id)
         VALUES (?, ?, 'backlog', ?, ?, ?, 'optimum', ?, ?, ?)`,
        [
          title,
          description || null,
          priority,
          dueAt,
          JSON.stringify(labels),
          assigneeId,
          caseId,
          ctx.adminId,
        ],
      );
      const taskId = Number(ins.insertId);

      let hubspot: Record<string, unknown> = {
        pushed: false,
        reason: "push_hubspot=false (OFG-only; set true to sync)",
      };
      if (pushHubspot) {
        if (!(await adminCanExtractHubspot(ctx.adminId))) {
          hubspot = {
            pushed: false,
            reason: "Admin lacks HubSpot extract permission",
          };
        } else {
          const tokens = await loadHubspotTokens(ctx.adminId);
          if (!tokens?.access_token) {
            hubspot = {
              pushed: false,
              reason:
                hubspotAuthMode() === "oauth"
                  ? "Connect HubSpot OAuth for this admin (or set HUBSPOT_SERVICE_KEY)"
                  : "HubSpot not configured",
              auth_mode: hubspotAuthMode(),
            };
          } else {
            try {
              const hsId = await createHubspotTask(tokens.access_token, {
                title,
                description: description || null,
                status: "backlog",
                priority: priority as WorkTaskPriority,
                due_at: dueAt,
              });
              await pool.query(
                `UPDATE admin_work_tasks
                 SET hubspot_task_id = ?, source = 'optimum', last_synced_at = NOW(),
                     pending_push = 0, sync_error = NULL
                 WHERE id = ?`,
                [hsId, taskId],
              );
              hubspot = {
                pushed: true,
                hubspot_task_id: hsId,
                auth_mode: hubspotAuthMode(),
              };
            } catch (e: any) {
              const msg = String(e?.message || e).slice(0, 400);
              await pool.query(
                `UPDATE admin_work_tasks SET sync_error = ? WHERE id = ?`,
                [msg, taskId],
              );
              hubspot = {
                pushed: false,
                error: msg,
                auth_mode: hubspotAuthMode(),
              };
            }
          }
        }
      }

      if (assigneeId && assigneeId !== ctx.adminId) {
        try {
          const [rows] = await pool.query<RowDataPacket[]>(
            `SELECT email, first_name, phone, preferred_language, notification_prefs_json
             FROM admins WHERE id = ? AND status = 'active' LIMIT 1`,
            [assigneeId],
          );
          if (rows[0]?.email) {
            const adminLang = rows[0].preferred_language === "es" ? "es" : "en";
            const admin: TeamAdminRecipient = {
              id: assigneeId,
              email: String(rows[0].email),
              first_name: String(rows[0].first_name || "there"),
              phone: rows[0].phone ? String(rows[0].phone) : null,
              preferred_language: adminLang,
              prefs: parseAdminNotificationPrefs(
                rows[0].notification_prefs_json,
              ),
            };
            const link = `${APP_URL}/admin/my-tasks`;
            const emailTpl = tplAdminWorkTaskAssigned({
              adminFirstName: admin.first_name,
              title,
              linkUrl: link,
              lang: adminLang,
            });
            await deliverAdminNotificationChannels({
              admin,
              eventKey: "work_task_assigned",
              tpl: {
                subject: emailTpl.subject,
                html: emailTpl.html,
                inAppTitle:
                  adminLang === "es"
                    ? `Tarea asignada: ${title}`.slice(0, 200)
                    : `Task assigned: ${title}`.slice(0, 200),
                inAppBody:
                  adminLang === "es"
                    ? "Abre Mis Tareas para revisar la asignación."
                    : "Open My Tasks to review the assignment.",
                linkUrl: link,
                smsBody:
                  adminLang === "es"
                    ? `Optimum: tarea asignada — ${title}`.slice(0, 160)
                    : `Optimum: task assigned — ${title}`.slice(0, 160),
              },
            });
          }
        } catch (e: any) {
          console.error("[admin-ai] create_work_task notify", e?.message ?? e);
        }
      }

      return {
        ok: true,
        data: {
          created: true,
          task_id: taskId,
          title,
          status: "backlog",
          priority,
          due_at: dueAt,
          assignee: assigneeMeta,
          case_id: caseId,
          case_number: caseNumber,
          hubspot,
          href: "/admin/my-tasks",
        },
      };
    }

    if (name === "update_work_task") {
      const taskId =
        args.task_id != null && Number(args.task_id) > 0
          ? Number(args.task_id)
          : 0;
      if (!taskId) {
        return {
          ok: false,
          error: "invalid_args",
          message: "task_id is required (from search_work_tasks)",
        };
      }
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM admin_work_tasks WHERE id = ? LIMIT 1`,
        [taskId],
      );
      if (!existing[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Work task not found. Use search_work_tasks.",
        };
      }
      const cur = existing[0];
      const namedStaff = await resolveMcpStaffAssignee({
        adminId: args.assignee_admin_id,
        name: args.assignee_name,
        email: args.assignee_email,
      });
      if (namedStaff.ok === false) return namedStaff;

      const patch: Record<string, unknown> = {};
      if (args.title != null) {
        const title = normalizeWorkTaskTitle(args.title);
        if (!title) {
          return {
            ok: false,
            error: "invalid_args",
            message: "title cannot be empty",
          };
        }
        patch.title = title;
      }
      if (args.description !== undefined) {
        patch.description = normalizeWorkTaskDescription(args.description);
      }
      if (args.status != null) {
        const status = String(args.status);
        if (!["backlog", "doing", "done"].includes(status)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "status must be backlog, doing, or done",
          };
        }
        patch.status = status;
      }
      if (args.priority != null) {
        const priority = String(args.priority);
        if (!["low", "medium", "high", "urgent"].includes(priority)) {
          return {
            ok: false,
            error: "invalid_args",
            message: "priority must be low, medium, high, or urgent",
          };
        }
        patch.priority = priority;
      }
      if (args.due_at !== undefined) {
        const dueRaw = String(args.due_at || "").trim();
        if (!dueRaw) {
          patch.due_at = null;
        } else {
          const d = new Date(
            dueRaw.length === 10 ? `${dueRaw}T12:00:00Z` : dueRaw,
          );
          if (isNaN(d.getTime())) {
            return {
              ok: false,
              error: "invalid_args",
              message: "due_at must be ISO datetime, YYYY-MM-DD, or empty",
            };
          }
          patch.due_at = d.toISOString().slice(0, 19).replace("T", " ");
        }
      }
      if (args.labels !== undefined) {
        patch.labels_json = JSON.stringify(
          Array.isArray(args.labels)
            ? args.labels
                .map((l) => decodeLiteralUnicodeEscapes(String(l)))
                .slice(0, 20)
            : [],
        );
      }
      if (namedStaff.requested) {
        patch.assignee_admin_id = namedStaff.id;
      }

      let caseId: number | null | undefined;
      if (
        args.case_id != null ||
        (typeof args.case_number === "string" && args.case_number.trim()) ||
        (args.client_id != null && Number(args.client_id) > 0)
      ) {
        if (
          args.case_id != null ||
          (typeof args.case_number === "string" && args.case_number.trim())
        ) {
          const caseRow = await adminAiResolveCaseRow(args, scopedIds);
          if (!caseRow) {
            return { ok: false, error: "not_found", message: "Case not found" };
          }
          caseId = Number(caseRow.id);
        } else {
          const clientId = Number(args.client_id);
          const [cr] = await pool.query<RowDataPacket[]>(
            `SELECT id FROM credit_repair_cases
             WHERE client_id = ? AND status <> 'cancelled'
             ORDER BY id DESC LIMIT 1`,
            [clientId],
          );
          caseId = cr[0] ? Number(cr[0].id) : null;
        }
        patch.case_id = caseId;
      }

      if (Object.keys(patch).length === 0) {
        return {
          ok: false,
          error: "invalid_args",
          message:
            "Provide at least one of title, description, status, priority, due_at, labels, assignee_admin_id / assignee_name, case_id",
        };
      }

      const preview = {
        task_id: taskId,
        current: {
          title: cur.title,
          status: cur.status,
          priority: cur.priority,
          due_at: cur.due_at,
          assignee_admin_id: cur.assignee_admin_id,
        },
        patch,
      };

      if (!adminAiWriteConfirmed(args).ok) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show this task update. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const sets = Object.keys(patch).map((k) => `${k} = ?`);
      if (cur.hubspot_task_id) sets.push("pending_push = 1");
      if (args.due_at !== undefined) sets.push("due_notified_at = NULL");
      await pool.query(
        `UPDATE admin_work_tasks SET ${sets.join(", ")} WHERE id = ?`,
        [...Object.values(patch), taskId],
      );

      const nextAssignee = namedStaff.requested
        ? namedStaff.id
        : cur.assignee_admin_id != null
          ? Number(cur.assignee_admin_id)
          : null;
      const prevAssignee =
        cur.assignee_admin_id != null ? Number(cur.assignee_admin_id) : null;
      if (nextAssignee && nextAssignee !== prevAssignee) {
        try {
          const [rows] = await pool.query<RowDataPacket[]>(
            `SELECT email, first_name, phone, preferred_language, notification_prefs_json
             FROM admins WHERE id = ? AND status = 'active' LIMIT 1`,
            [nextAssignee],
          );
          if (rows[0]?.email) {
            const adminLang = rows[0].preferred_language === "es" ? "es" : "en";
            const title = String(patch.title ?? cur.title);
            const admin: TeamAdminRecipient = {
              id: nextAssignee,
              email: String(rows[0].email),
              first_name: String(rows[0].first_name || "there"),
              phone: rows[0].phone ? String(rows[0].phone) : null,
              preferred_language: adminLang,
              prefs: parseAdminNotificationPrefs(
                rows[0].notification_prefs_json,
              ),
            };
            const link = `${APP_URL}/admin/my-tasks`;
            const emailTpl = tplAdminWorkTaskAssigned({
              adminFirstName: admin.first_name,
              title,
              linkUrl: link,
              lang: adminLang,
            });
            await deliverAdminNotificationChannels({
              admin,
              eventKey: "work_task_assigned",
              tpl: {
                subject: emailTpl.subject,
                html: emailTpl.html,
                inAppTitle:
                  adminLang === "es"
                    ? `Tarea asignada: ${title}`.slice(0, 200)
                    : `Task assigned: ${title}`.slice(0, 200),
                inAppBody:
                  adminLang === "es"
                    ? "Abre Mis Tareas para revisar la asignación."
                    : "Open My Tasks to review the assignment.",
                linkUrl: link,
                smsBody:
                  adminLang === "es"
                    ? `Optimum: tarea asignada — ${title}`.slice(0, 160)
                    : `Optimum: task assigned — ${title}`.slice(0, 160),
              },
            });
          }
        } catch (e: any) {
          console.error("[admin-ai] update_work_task notify", e?.message ?? e);
        }
      }

      const [fresh] = await pool.query<RowDataPacket[]>(
        `SELECT t.id, t.title, t.status, t.priority, t.due_at, t.assignee_admin_id,
                t.case_id, a.first_name, a.last_name, a.email
         FROM admin_work_tasks t
         LEFT JOIN admins a ON a.id = t.assignee_admin_id
         WHERE t.id = ? LIMIT 1`,
        [taskId],
      );
      const row = fresh[0];
      return {
        ok: true,
        data: {
          updated: true,
          task_id: taskId,
          title: row?.title,
          status: row?.status,
          priority: row?.priority,
          due_at: row?.due_at,
          assignee: row?.assignee_admin_id
            ? {
                id: Number(row.assignee_admin_id),
                name: `${row.first_name || ""} ${row.last_name || ""}`.trim(),
                email: row.email,
              }
            : null,
          case_id: row?.case_id != null ? Number(row.case_id) : null,
          href: "/admin/my-tasks",
        },
      };
    }

    if (name === "add_case_note") {
      const note = decodeLiteralUnicodeEscapes(String(args.note || ""))
        .trim()
        .slice(0, 4000);
      const sourceRaw = String(args.source || "other").toLowerCase();
      const source = ["sms", "call", "email", "other"].includes(sourceRaw)
        ? sourceRaw
        : "other";
      const missing: string[] = [];
      if (!note) missing.push("note");
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let clientName: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        clientName = cRows[0]
          ? `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim()
          : null;
      }

      const stamped = `[${source.toUpperCase()} ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC] ${note}`;
      const preview = {
        client_id: clientId,
        client_name: clientName,
        case_id: caseId,
        case_number: caseNumber,
        source,
        note_to_append: stamped,
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Ask for the client/case and the exact note text (SMS/call summary).",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the exact note. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      await pool.query(
        `UPDATE clients
         SET admin_notes = CONCAT(
               COALESCE(admin_notes, ''),
               CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
               ?
             )
         WHERE id = ?`,
        [stamped, clientId],
      );

      return {
        ok: true,
        data: {
          created: true,
          client_id: clientId,
          client_name: clientName,
          case_id: caseId,
          case_number: caseNumber,
          note_appended: stamped,
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "upload_case_document") {
      const docTypeRaw = String(args.doc_type || "").trim();
      const docType = CASE_DOC_TYPES.includes(
        docTypeRaw as (typeof CASE_DOC_TYPES)[number],
      )
        ? docTypeRaw
        : "";
      const fileName = String(args.file_name || "")
        .trim()
        .replace(/[/\\]/g, "_")
        .slice(0, 255);
      const mimeType = adminAiDocMimeFromFilename(
        fileName,
        typeof args.mime_type === "string" ? args.mime_type : null,
      );
      const fileBase64Raw =
        typeof args.file_base64 === "string" ? args.file_base64 : "";
      const fileBuffer = fileBase64Raw
        ? adminAiDecodeFileBase64(fileBase64Raw)
        : null;

      const missing: string[] = [];
      if (!docType) missing.push("doc_type");
      if (!fileName) missing.push("file_name");
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let clientName: string | null = null;
      let pipelineRound: string | null = null;

      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;

        if (!caseId) {
          const primaryCaseId = await resolvePrimaryActiveCaseId(
            pool,
            clientId,
          );
          if (primaryCaseId) {
            const [cr] = await pool.query<RowDataPacket[]>(
              `SELECT id, case_number, pipeline_stage FROM credit_repair_cases
               WHERE id = ? LIMIT 1`,
              [primaryCaseId],
            );
            if (cr[0]) {
              caseId = Number(cr[0].id);
              caseNumber = cr[0].case_number ? String(cr[0].case_number) : null;
              pipelineRound = (cr[0].pipeline_stage as string) || null;
            }
          }
        } else {
          const [cr] = await pool.query<RowDataPacket[]>(
            `SELECT pipeline_stage FROM credit_repair_cases WHERE id = ? LIMIT 1`,
            [caseId],
          );
          pipelineRound = (cr[0]?.pipeline_stage as string) || null;
        }

        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        clientName = cRows[0]
          ? `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim()
          : null;
      }

      const validationErrors: string[] = [];
      let crmRequired: AdminAiCrmRequiredPayload | null = null;
      if (!caseId) {
        validationErrors.push(
          "No active case found for this client. Convert the prospect or enroll a case first.",
        );
        crmRequired = adminAiCrmRequired({
          reason: "no_active_case",
          userMessage:
            "ATLAS cannot attach a case document until this lead has an enrolled OFG case. Convert the prospect in CRM first (Pipeline → Convert), then retry upload or upload from the client panel.",
          clientId,
          crmAction: "Convert prospect / enroll case in Pipeline",
        });
      }
      if (!mimeType) {
        validationErrors.push(
          "Unsupported file type. Use JPEG, PNG, HEIC, or PDF with a matching extension or mime_type.",
        );
        crmRequired = adminAiCrmRequired({
          reason: "unsupported_mime",
          userMessage:
            "ATLAS only accepts JPEG, PNG, HEIC, or PDF for case documents. Upload this file in the CRM client panel instead (or convert to PDF first).",
          clientId,
          caseId,
          crmAction: "Upload documents in Pipeline → client panel",
          details: { file_name: fileName || null },
        });
      }
      if (fileBase64Raw && !fileBuffer) {
        validationErrors.push("file_base64 is not valid base64");
      }
      if (fileBuffer && fileBuffer.length > ADMIN_AI_DOC_MAX_BYTES) {
        const mb = (fileBuffer.length / (1024 * 1024)).toFixed(1);
        const limitMb = Math.round(ADMIN_AI_DOC_MAX_BYTES / (1024 * 1024));
        validationErrors.push(
          `File exceeds ${ADMIN_AI_DOC_MAX_BYTES} bytes (~${limitMb}MB). Use the CRM upload (max ~4MB) or compress the file.`,
        );
        crmRequired = adminAiCrmRequired({
          reason: "file_too_large",
          userMessage: `This file is ~${mb}MB — too large for ATLAS (~${limitMb}MB max). Compress it under 4MB and upload in the CRM (Pipeline → client panel → Upload documents), or use Report Wizard for credit-report PDFs.`,
          clientId,
          caseId,
          crmAction: "Upload in Pipeline → client panel (max 4MB)",
          details: {
            source_byte_length: fileBuffer.length,
            atlas_max_bytes: ADMIN_AI_DOC_MAX_BYTES,
            crm_max_bytes: VERCEL_SAFE_UPLOAD_MAX_BYTES,
          },
        });
      }
      const expectedBytes =
        args.expected_byte_length != null
          ? Number(args.expected_byte_length)
          : null;
      if (
        fileBuffer &&
        expectedBytes != null &&
        Number.isFinite(expectedBytes) &&
        expectedBytes > 0 &&
        fileBuffer.length !== expectedBytes
      ) {
        validationErrors.push(
          `Integrity check failed: decoded file_base64 is ${fileBuffer.length} bytes but expected_byte_length=${expectedBytes}. Re-encode the full file (truncated base64).`,
        );
        crmRequired = adminAiCrmRequired({
          reason: "integrity_failed",
          userMessage: `ATLAS received a truncated file (${fileBuffer.length} bytes vs expected ${expectedBytes}). Re-send the complete attachment in chat, or upload the original file in the CRM client panel.`,
          clientId,
          caseId,
          crmAction: "Re-send full file via ATLAS, or upload in CRM",
          details: {
            decoded_bytes: fileBuffer.length,
            expected_byte_length: expectedBytes,
          },
        });
      }
      const expectedSha =
        typeof args.expected_sha256 === "string"
          ? String(args.expected_sha256).trim().toLowerCase()
          : "";
      const sourceSha = fileBuffer ? sha256BufferHex(fileBuffer) : null;
      if (fileBuffer && expectedSha) {
        if (!/^[a-f0-9]{64}$/.test(expectedSha)) {
          validationErrors.push(
            "expected_sha256 must be a 64-character lowercase hex SHA-256 digest",
          );
        } else if (sourceSha !== expectedSha) {
          validationErrors.push(
            `Integrity check failed: SHA-256 mismatch (got ${sourceSha}, expected ${expectedSha}). Re-send the complete file_base64.`,
          );
          crmRequired = adminAiCrmRequired({
            reason: "integrity_failed",
            userMessage:
              "ATLAS SHA-256 check failed — the file bytes do not match the source. Re-send the complete attachment, or upload the original file in the CRM client panel.",
            clientId,
            caseId,
            crmAction: "Re-send full file via ATLAS, or upload in CRM",
            details: {
              source_sha256: sourceSha,
              expected_sha256: expectedSha,
            },
          });
        }
      }

      const preview = {
        client_id: clientId,
        client_name: clientName,
        case_id: caseId,
        case_number: caseNumber,
        doc_type: docType || null,
        file_name: fileName || null,
        mime_type: mimeType,
        file_size_bytes: fileBuffer?.length ?? null,
        source_byte_length: fileBuffer?.length ?? null,
        source_sha256: sourceSha,
        has_file_bytes: !!fileBuffer,
        expected_byte_length: expectedBytes,
        expected_sha256: expectedSha || null,
        integrity_ok:
          !!fileBuffer &&
          (expectedBytes == null ||
            !Number.isFinite(expectedBytes) ||
            expectedBytes <= 0 ||
            fileBuffer.length === expectedBytes) &&
          (!expectedSha || sourceSha === expectedSha),
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect client/case, doc_type (id_front/id_back/ssn_card/proof_of_address/other), file_name, and file_base64 from the attachment.",
          },
        };
      }

      if (validationErrors.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            validation_errors: validationErrors,
            preview,
            ...(crmRequired ? { crm_required: crmRequired } : {}),
            guidance: crmRequired
              ? crmRequired.user_message
              : validationErrors.join(" "),
          },
        };
      }

      if (!fileBuffer) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: ["file_base64"],
            preview,
            guidance:
              "Dry-run metadata looks good. Re-call with file_base64 to preview size, then confirm=true after user approval.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the client, case, doc_type, and filename. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      try {
        const inserted = await persistAdminCaseDocumentUpload({
          clientId: clientId!,
          caseId: caseId!,
          docType,
          buffer: fileBuffer,
          fileName,
          mimeType: mimeType!,
          adminId: ctx.adminId,
          pipelineRound,
        });
        const autoAdvanced = await maybeAutoAdvanceDocsReadyFromTasks({
          clientId: clientId!,
          caseId: caseId!,
          adminId: ctx.adminId,
        });
        const [uploadedRow] = await pool.query<RowDataPacket[]>(
          `SELECT uploaded_at FROM client_documents WHERE id = ? LIMIT 1`,
          [inserted.id],
        );
        return {
          ok: true,
          data: {
            uploaded: true,
            document_id: inserted.id,
            client_id: clientId,
            client_name: clientName,
            case_id: caseId,
            case_number: caseNumber,
            doc_type: inserted.doc_type,
            file_name: inserted.file_name,
            file_size: inserted.file_size,
            mime_type: inserted.mime_type,
            review_status: inserted.review_status,
            uploaded_at: uploadedRow[0]?.uploaded_at ?? null,
            task_synced: inserted.task_synced,
            auto_advanced_docs_ready: autoAdvanced,
            source_byte_length: fileBuffer!.length,
            source_sha256: sha256BufferHex(fileBuffer!),
            stored_byte_length: inserted.file_size,
            integrity_ok: inserted.file_size === fileBuffer!.length,
            href: `/admin/pipeline?client=${clientId}`,
          },
        };
      } catch (e: any) {
        return {
          ok: false,
          error: "upload_failed",
          message: String(e?.message || e || "Document upload failed"),
        };
      }
    }

    if (name === "run_credit_analysis") {
      const clientIdArg = Number(args.client_id);
      const fileName = String(args.file_name || "")
        .trim()
        .replace(/[/\\]/g, "_")
        .slice(0, 255);
      const fileBase64Raw =
        typeof args.file_base64 === "string" ? args.file_base64 : "";
      const fileBuffer = fileBase64Raw
        ? adminAiDecodeFileBase64(fileBase64Raw)
        : null;
      const mimeType = adminAiDocMimeFromFilename(
        fileName,
        "application/pdf",
      );
      const clientGoal = args.client_goal
        ? String(args.client_goal).trim().slice(0, 255)
        : null;
      const notes = args.notes
        ? decodeLiteralUnicodeEscapes(String(args.notes)).trim()
        : null;
      const emailOptIn = args.email_opt_in === true;
      const repName = args.rep_name ? String(args.rep_name).trim() : null;
      const agentPhone = args.agent_phone
        ? String(args.agent_phone).trim()
        : null;

      const missing: string[] = [];
      if (!clientIdArg || clientIdArg <= 0) missing.push("client_id");
      if (!fileName) missing.push("file_name");

      let clientId: number | null = null;
      let clientName: string | null = null;
      let clientEmail: string | null = null;
      let clientPreferredLang: "en" | "es" = "en";
      let isProspect = false;

      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(
          { client_id: clientIdArg },
          scopedIds,
        );
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, email, first_name, last_name, phone, preferred_language, status, pipeline_stage
           FROM clients WHERE id = ? LIMIT 1`,
          [resolved.clientId],
        );
        if (!cRows[0]) {
          return { ok: false, error: "not_found", message: "Client not found" };
        }
        clientId = Number(cRows[0].id);
        clientName = `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim();
        clientEmail = String(cRows[0].email || "");
        clientPreferredLang = cRows[0].preferred_language === "es" ? "es" : "en";
        isProspect = isProspectClientRow(cRows[0]);
      }

      const textLanguage: "en" | "es" =
        args.text_language === "es"
          ? "es"
          : args.text_language === "en"
            ? "en"
            : clientPreferredLang;

      const validationErrors: string[] = [];
      if (clientId && !isProspect) {
        validationErrors.push(
          "Client is not a prospect — credit analysis is for pre-sale leads only.",
        );
      }
      if (mimeType !== "application/pdf") {
        validationErrors.push(
          "Credit analysis requires a PDF credit report (application/pdf).",
        );
      }
      if (fileBase64Raw && !fileBuffer) {
        validationErrors.push("file_base64 is not valid base64");
      }
      if (fileBuffer && fileBuffer.length > ADMIN_AI_DOC_MAX_BYTES) {
        validationErrors.push(
          `File exceeds ${ADMIN_AI_DOC_MAX_BYTES} bytes (~4MB). Compress the PDF first.`,
        );
      }

      const preview = {
        client_id: clientId,
        client_name: clientName,
        client_email: clientEmail,
        is_prospect: isProspect,
        file_name: fileName || null,
        mime_type: mimeType,
        file_size_bytes: fileBuffer?.length ?? null,
        text_language: textLanguage,
        client_goal: clientGoal,
        email_opt_in: emailOptIn,
        has_file_bytes: !!fileBuffer,
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Provide client_id (from search_clients) and file_name (.pdf), then file_base64 from the credit report attachment.",
          },
        };
      }

      if (validationErrors.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            validation_errors: validationErrors,
            preview,
            guidance: validationErrors.join(" "),
          },
        };
      }

      if (!fileBuffer) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: ["file_base64"],
            preview,
            guidance:
              "Client looks valid. Re-call with file_base64 (PDF) to preview size, then confirm after user approval.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Preview: run free credit analysis for ${clientName} (${clientEmail}). After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      const [prospectRows] = await pool.query<RowDataPacket[]>(
        `SELECT status, pipeline_stage FROM clients WHERE id = ? LIMIT 1`,
        [clientId!],
      );
      if (!prospectRows[0] || !isProspectClientRow(prospectRows[0])) {
        return {
          ok: false,
          error: "conflict",
          message:
            "Client is no longer a prospect. Credit analysis is for pre-sale leads only.",
        };
      }

      const [cRows] = await pool.query<RowDataPacket[]>(
        `SELECT email, first_name, last_name, phone, preferred_language
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId!],
      );
      const c = cRows[0];
      const firstName = String(c.first_name || "").trim();
      const lastName = String(c.last_name || "").trim();
      const email = String(c.email || "").trim().toLowerCase();
      const phone = String(c.phone || "").trim();
      const lang: "en" | "es" = textLanguage;

      try {
        const result = await executeCreditAnalysisUpload({
          mode: "agent",
          firstName,
          lastName,
          email,
          phone,
          textLanguage: lang,
          clientGoal,
          notes,
          agentPhone,
          repName,
          emailOptIn,
          file: {
            buffer: fileBuffer,
            originalname: fileName,
            mimetype: mimeType!,
          },
          fixedClientId: clientId!,
          sourceLabel: "agent_submission",
        });
        return {
          ok: true,
          data: {
            analysis_id: result.id,
            client_id: result.client_id,
            extraction_status: result.extraction_status,
            scores: result.scores,
            suggested_labels: result.suggested_labels,
            email_sent: result.email_sent,
            claude_enhanced: result.claude_enhanced === true,
            generated_at: result.generated_at,
            middle_score: result.analyst?.middle_score ?? null,
            goal_score: result.analyst?.goal_score ?? null,
            href: `/admin/pipeline?client=${clientId}`,
            guidance:
              "Analysis saved. Open the client panel Analysis tab or share the narrative from analysis_html in CRM.",
          },
        };
      } catch (e: any) {
        return {
          ok: false,
          error: "analysis_failed",
          message: String(e?.message || e || "Credit analysis failed"),
        };
      }
    }

    if (name === "send_email") {
      const subject = decodeLiteralUnicodeEscapes(String(args.subject || ""))
        .trim()
        .slice(0, 200);
      const body = decodeLiteralUnicodeEscapes(String(args.body || ""))
        .trim()
        .slice(0, 8000);
      const referrerIdArg =
        args.referrer_id != null && Number(args.referrer_id) > 0
          ? Number(args.referrer_id)
          : null;
      const hasClientKey =
        (args.client_id != null && Number(args.client_id) > 0) ||
        (args.case_id != null && Number(args.case_id) > 0) ||
        (typeof args.case_number === "string" && !!args.case_number.trim());
      const namedTo = await resolveMcpStaffAssignee({
        adminId: args.to_admin_id,
        name: args.to_admin_name,
        email: args.to_admin_email,
      });
      if (namedTo.ok === false) return namedTo;
      const staffTo = namedTo.requested ? namedTo : null;
      const audience: "client" | "referrer" | "staff" = staffTo
        ? "staff"
        : referrerIdArg
          ? "referrer"
          : "client";
      let includeDocUploadLink = adminAiConfirmTrue(
        args.include_doc_upload_link,
      );
      if (audience !== "client") includeDocUploadLink = false;

      const missing: string[] = [];
      if (!subject) missing.push("subject");
      if (!body) missing.push("body");
      if (!referrerIdArg && !hasClientKey && !staffTo) {
        missing.push(
          "client_id / case_id / case_number, referrer_id, or to_admin_id / to_admin_name",
        );
      }

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let clientName: string | null = null;
      let clientEmail: string | null = null;
      let clientLang: "en" | "es" = "en";
      let referrerId: number | null = referrerIdArg;
      let referrerName: string | null = null;
      let referrerEmail: string | null = null;
      let referrerLang: "en" | "es" = "en";
      let toEmail: string | null = null;
      let toName: string | null = null;
      let toLang: "en" | "es" = "en";

      if (missing.length === 0 && staffTo) {
        toEmail = staffTo.meta.email ? String(staffTo.meta.email).trim() : null;
        toName = staffTo.meta.name;
        toLang = staffTo.meta.preferred_language === "es" ? "es" : "en";
        if (!toEmail) {
          return {
            ok: false,
            error: "no_email",
            message:
              "That staff member has no email on file. Use search_admins and pick someone with email.",
          };
        }
      }

      if (missing.length === 0 && referrerId && audience === "referrer") {
        const [refRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, email, preferred_language, status
           FROM referrers WHERE id = ? LIMIT 1`,
          [referrerId],
        );
        if (!refRows[0]) {
          return {
            ok: false,
            error: "not_found",
            message:
              "Referrer not found. Use search_referrers or get_client.referrer.id.",
          };
        }
        if (String(refRows[0].status) !== "active") {
          return {
            ok: false,
            error: "invalid_args",
            message: "Cannot email an inactive referrer",
          };
        }
        referrerName =
          `${refRows[0].first_name || ""} ${refRows[0].last_name || ""}`.trim();
        referrerEmail = refRows[0].email
          ? String(refRows[0].email).trim()
          : null;
        referrerLang = refRows[0].preferred_language === "es" ? "es" : "en";
        if (!referrerEmail) {
          return {
            ok: false,
            error: "no_email",
            message:
              "Referrer has no email on file. Add it on the partner record, then retry.",
          };
        }
        toEmail = referrerEmail;
        toName = referrerName;
        toLang = referrerLang;
      }

      if (missing.length === 0 && hasClientKey) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name, email, preferred_language, status
           FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        if (!cRows[0]) {
          return {
            ok: false,
            error: "not_found",
            message:
              "Client not found. Use search_clients — OFG client_id is not a HubSpot contact id.",
          };
        }
        clientName =
          `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim();
        clientEmail = cRows[0].email ? String(cRows[0].email).trim() : null;
        clientLang = cRows[0].preferred_language === "es" ? "es" : "en";
        const clientStatus = String(cRows[0].status || "");
        if (audience === "client" && clientStatus === "cancelled") {
          return {
            ok: false,
            error: "invalid_args",
            message: "Cannot email a cancelled client",
          };
        }
        if (audience === "client" && !clientEmail) {
          return {
            ok: false,
            error: "no_email",
            message:
              "Client has no email on file. Use update_client to set email first, or use another channel.",
          };
        }
        if (!caseId) {
          const [cr] = await pool.query<RowDataPacket[]>(
            `SELECT id, case_number FROM credit_repair_cases
             WHERE client_id = ? AND status <> 'cancelled'
             ORDER BY id DESC LIMIT 1`,
            [clientId],
          );
          if (cr[0]) {
            caseId = Number(cr[0].id);
            caseNumber = cr[0].case_number ? String(cr[0].case_number) : null;
          }
        }
        if (audience === "client") {
          toEmail = clientEmail;
          toName = clientName;
          toLang = clientLang;
        }
      }

      const attachmentLoad = await adminAiLoadEmailAttachment({
        args,
        clientId,
      });
      if (attachmentLoad.ok === false) {
        return {
          ok: false,
          error: attachmentLoad.error,
          message: attachmentLoad.message,
        };
      }
      const attachment = attachmentLoad.attachment;

      const preview = {
        audience,
        client_id: clientId,
        client_name: clientName,
        case_id: caseId,
        case_number: caseNumber,
        referrer_id: referrerId,
        referrer_name: referrerName,
        to: toEmail,
        subject,
        body,
        include_doc_upload_link: includeDocUploadLink,
        attachment: attachment
          ? {
              filename: attachment.filename,
              content_type: attachment.contentType,
              byte_length: attachment.content.length,
              source: attachment.source,
              source_id: attachment.source_id ?? null,
            }
          : null,
        will_log_client_note: audience === "client",
        will_log_referrer_note: audience === "referrer",
        note:
          audience === "referrer"
            ? "Dry-run does not send. On confirm, email goes to the referrer; a note is saved on the partner record" +
              (clientId ? " and on the linked client's file." : ".")
            : audience === "staff"
              ? "Dry-run does not send. On confirm, email goes to that staff member (no client file note unless this is a client/referrer send)."
              : "Dry-run does not send or mint links. On confirm, email is sent via OFG mailer and an EMAIL note is appended.",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect subject + body, and client_id (OFG), referrer_id, or to_admin_id / to_admin_name.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the exact To / subject / body. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let portalUrl: string | null = null;
      let mintedRawToken: string | null = null;
      if (includeDocUploadLink && audience === "client" && clientId) {
        mintedRawToken = await createOnboardingToken(clientId);
        portalUrl = `${APP_URL}/portal/onboarding/${mintedRawToken}`;
      }

      const isEs = toLang === "es";
      const firstName =
        (toName || "").split(/\s+/).filter(Boolean)[0] ||
        (isEs ? (audience === "referrer" ? "socio" : "cliente") : "there");
      const bodyLooksGreeted = /^(hi|hola|hello|dear)\b/i.test(body);
      const safeBodyHtml = escapeHtml(body).replace(/\r?\n/g, "<br/>");
      const greetingHtml = bodyLooksGreeted
        ? ""
        : `<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">${
            isEs ? "Hola" : "Hi"
          } ${escapeHtml(firstName)},</p>`;
      const uploadBlock =
        portalUrl != null
          ? `<p style="margin:20px 0 12px;font-size:15px;line-height:1.6;color:#334155;">${
              isEs
                ? "Usa este enlace seguro para subir tus documentos:"
                : "Use this secure link to upload your documents:"
            }</p>${emailButton(
              portalUrl,
              isEs ? "Subir documentos" : "Upload documents",
            )}`
          : "";
      const html = emailLayout({
        title: subject,
        preheader: subject,
        bodyHtml: `${greetingHtml}<div style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">${safeBodyHtml}</div>${uploadBlock}`,
        lang: toLang,
      });

      try {
        await sendEmail({
          to: toEmail as string,
          subject,
          html,
          attachments: attachment
            ? [
                {
                  filename: attachment.filename,
                  content: attachment.content,
                  contentType: attachment.contentType,
                },
              ]
            : undefined,
        });
      } catch (e: any) {
        if (mintedRawToken) {
          try {
            await pool.query(
              `DELETE FROM onboarding_tokens WHERE token_hash = ?`,
              [sha256(mintedRawToken)],
            );
          } catch (cleanupErr: any) {
            console.error(
              "[admin-ai] send_email token cleanup",
              cleanupErr?.message ?? cleanupErr,
            );
          }
        }
        return {
          ok: false,
          error: "send_failed",
          message: String(e?.message || "Email send failed").slice(0, 400),
        };
      }

      if (portalUrl && clientId && audience === "client") {
        notifyLanguageOwnerDocUploadLink({
          clientId,
          firstName,
          lastName: (toName || "").split(/\s+/).slice(1).join(" ") || "",
          clientEmail: toEmail as string,
          lang: toLang,
          portalUrl,
          caseId,
        }).catch((e: any) =>
          console.error("[admin-ai] send_email owner notify", e?.message ?? e),
        );
      }

      const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
      const noteParts = [`Subject: ${subject}`, body.slice(0, 1500)];
      if (portalUrl) noteParts.push(`Doc upload link: ${portalUrl}`);
      if (attachment) {
        noteParts.push(
          `Attachment: ${attachment.filename} (${attachment.content.length} bytes)`,
        );
      }
      let clientNoteAppended = false;
      let referrerNoteAppended = false;
      if (audience === "client" && clientId) {
        const stamped = `[EMAIL ${ts} UTC] Sent to ${toEmail}\n${noteParts.join("\n")}`;
        try {
          await pool.query(
            `UPDATE clients
             SET admin_notes = CONCAT(
                   COALESCE(admin_notes, ''),
                   CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
                   ?
                 )
             WHERE id = ?`,
            [stamped.slice(0, 8000), clientId],
          );
          clientNoteAppended = true;
        } catch (noteErr: any) {
          console.error(
            "[admin-ai] send_email client note",
            noteErr?.message ?? noteErr,
          );
        }
      }
      if (audience === "referrer" && referrerId) {
        const about = clientName
          ? ` re: ${clientName}${clientId ? ` (client_id=${clientId})` : ""}`
          : "";
        const refStamped = `[EMAIL ${ts} UTC] Sent to ${toEmail}${about}\n${noteParts.join("\n")}`;
        try {
          await pool.query(
            `UPDATE referrers
             SET notes = CONCAT(
                   COALESCE(notes, ''),
                   CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE '\n' END,
                   ?
                 )
             WHERE id = ?`,
            [refStamped.slice(0, 8000), referrerId],
          );
          referrerNoteAppended = true;
        } catch (noteErr: any) {
          console.error(
            "[admin-ai] send_email referrer note",
            noteErr?.message ?? noteErr,
          );
        }
        if (clientId) {
          const clientStamped = `[EMAIL REFERRER ${ts} UTC] Sent to ${toEmail} (${referrerName || `referrer_id=${referrerId}`})\n${noteParts.join("\n")}`;
          try {
            await pool.query(
              `UPDATE clients
               SET admin_notes = CONCAT(
                     COALESCE(admin_notes, ''),
                     CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
                     ?
                   )
               WHERE id = ?`,
              [clientStamped.slice(0, 8000), clientId],
            );
            clientNoteAppended = true;
          } catch (noteErr: any) {
            console.error(
              "[admin-ai] send_email client-of-referrer note",
              noteErr?.message ?? noteErr,
            );
          }
        }
      }

      return {
        ok: true,
        data: {
          sent: true,
          audience,
          client_id: clientId,
          client_name: clientName,
          case_id: caseId,
          case_number: caseNumber,
          referrer_id: referrerId,
          referrer_name: referrerName,
          to: toEmail,
          subject,
          include_doc_upload_link: includeDocUploadLink,
          doc_upload_link: portalUrl,
          attachment: attachment
            ? {
                filename: attachment.filename,
                content_type: attachment.contentType,
                byte_length: attachment.content.length,
                source: attachment.source,
                source_id: attachment.source_id ?? null,
              }
            : null,
          note_appended: clientNoteAppended || referrerNoteAppended,
          client_note_appended: clientNoteAppended,
          referrer_note_appended: referrerNoteAppended,
          href: clientId
            ? `/admin/pipeline?client=${clientId}`
            : "/admin/clients",
        },
      };
    }

    if (name === "send_round_report") {
      const alsoEmail = adminAiBoolDefaultTrue(args.also_email);
      const alsoSms = adminAiBoolDefaultTrue(args.also_sms);
      const attachPdf = adminAiBoolDefaultTrue(args.attach_pdf);
      const notifyPartners = adminAiBoolDefaultTrue(args.notify_partners);
      const pdfIdArg =
        args.pdf_id != null && Number(args.pdf_id) > 0
          ? Number(args.pdf_id)
          : null;
      const roundReportIdArg =
        args.round_report_id != null && Number(args.round_report_id) > 0
          ? Number(args.round_report_id)
          : null;
      const roundNumberArg =
        args.round_number != null && Number(args.round_number) > 0
          ? Number(args.round_number)
          : null;

      const hasClientKey =
        (args.client_id != null && Number(args.client_id) > 0) ||
        (args.case_id != null && Number(args.case_id) > 0) ||
        (typeof args.case_number === "string" && !!args.case_number.trim());

      const missing: string[] = [];
      if (!hasClientKey) missing.push("client_id / case_id / case_number");
      if (!pdfIdArg && !roundReportIdArg && !roundNumberArg) {
        missing.push("pdf_id / round_report_id / round_number");
      }
      if (!alsoEmail && !alsoSms && !notifyPartners) {
        return {
          ok: false,
          error: "invalid_args",
          message:
            "Set also_email, also_sms, and/or notify_partners (at least one must be true)",
        };
      }

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            guidance:
              "Use list_progress_reports to get client_id + pdf_id (or id / round), then dry-run send_round_report.",
          },
        };
      }

      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const clientId = resolved.clientId;
      let caseId = resolved.caseId;
      let caseNumber = resolved.caseNumber;

      const [cRows] = await pool.query<RowDataPacket[]>(
        `SELECT first_name, last_name, email, phone, preferred_language, status
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      if (!cRows[0]) {
        return {
          ok: false,
          error: "not_found",
          message: "Client not found",
        };
      }
      const client = cRows[0];
      if (String(client.status) === "cancelled") {
        return {
          ok: false,
          error: "invalid_args",
          message: "Cannot send round report to a cancelled client",
        };
      }
      const clientName =
        `${client.first_name || ""} ${client.last_name || ""}`.trim();
      const clientEmail = client.email ? String(client.email).trim() : null;
      const clientPhone = client.phone ? String(client.phone).trim() : null;
      const lang = client.preferred_language === "es" ? "es" : "en";

      if (!caseId) {
        const [cr] = await pool.query<RowDataPacket[]>(
          `SELECT id, case_number FROM credit_repair_cases
           WHERE client_id = ? AND status <> 'cancelled'
           ORDER BY id DESC LIMIT 1`,
          [clientId],
        );
        if (cr[0]) {
          caseId = Number(cr[0].id);
          caseNumber = cr[0].case_number ? String(cr[0].case_number) : null;
        }
      }

      let pdfRow: RowDataPacket | null = null;
      if (pdfIdArg) {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT id, client_id, round_number, round_report_id, file_name,
                  storage_key, storage_provider, encrypted, enc_iv, enc_tag
           FROM round_report_pdfs WHERE id = ? LIMIT 1`,
          [pdfIdArg],
        );
        pdfRow = rows[0] || null;
        if (!pdfRow || Number(pdfRow.client_id) !== clientId) {
          return {
            ok: false,
            error: "not_found",
            message: "Round PDF not found for this client (check pdf_id)",
          };
        }
      } else if (roundReportIdArg) {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT id, client_id, round_number, round_report_id, file_name,
                  storage_key, storage_provider, encrypted, enc_iv, enc_tag
           FROM round_report_pdfs
           WHERE client_id = ? AND round_report_id = ?
           ORDER BY id DESC LIMIT 1`,
          [clientId, roundReportIdArg],
        );
        pdfRow = rows[0] || null;
        if (!pdfRow) {
          return {
            ok: false,
            error: "not_found",
            message:
              "No round_report_pdfs row for that round_report_id. Publish from CRM Reports → Generate, or pass pdf_id.",
          };
        }
      } else if (roundNumberArg) {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT id, client_id, round_number, round_report_id, file_name,
                  storage_key, storage_provider, encrypted, enc_iv, enc_tag
           FROM round_report_pdfs
           WHERE client_id = ? AND round_number = ?
           ORDER BY id DESC LIMIT 1`,
          [clientId, roundNumberArg],
        );
        pdfRow = rows[0] || null;
        if (!pdfRow) {
          return {
            ok: false,
            error: "not_found",
            message: `No published Round ${roundNumberArg} PDF for this client. Publish from CRM Reports → Generate first.`,
          };
        }
      }

      if (!pdfRow) {
        return {
          ok: false,
          error: "not_found",
          message: "Could not resolve Round PDF",
        };
      }

      const pdfId = Number(pdfRow.id);
      const roundNumber = Number(pdfRow.round_number);
      const roundReportId =
        pdfRow.round_report_id != null ? Number(pdfRow.round_report_id) : null;

      let scoreBefore: number | null = null;
      let scoreAfter: number | null = null;
      let itemsRemoved = 0;
      if (roundReportId) {
        const [rr] = await pool.query<RowDataPacket[]>(
          `SELECT score_before, score_after, items_removed
           FROM client_round_reports WHERE id = ? AND client_id = ? LIMIT 1`,
          [roundReportId, clientId],
        );
        if (rr[0]) {
          scoreBefore =
            rr[0].score_before != null ? Number(rr[0].score_before) : null;
          scoreAfter =
            rr[0].score_after != null ? Number(rr[0].score_after) : null;
          itemsRemoved = Number(rr[0].items_removed || 0);
        }
      } else {
        const [rr] = await pool.query<RowDataPacket[]>(
          `SELECT id, score_before, score_after, items_removed
           FROM client_round_reports
           WHERE client_id = ? AND round_number = ?
           ORDER BY id DESC LIMIT 1`,
          [clientId, roundNumber],
        );
        if (rr[0]) {
          scoreBefore =
            rr[0].score_before != null ? Number(rr[0].score_before) : null;
          scoreAfter =
            rr[0].score_after != null ? Number(rr[0].score_after) : null;
          itemsRemoved = Number(rr[0].items_removed || 0);
        }
      }

      if (alsoEmail && !clientEmail && !notifyPartners) {
        return {
          ok: false,
          error: "no_email",
          message:
            "Client has no email on file. Use update_client to set email, or set also_email=false and also_sms=true (or notify_partners=true for partners only).",
        };
      }
      if (alsoSms && !clientPhone && !alsoEmail && !notifyPartners) {
        return {
          ok: false,
          error: "no_phone",
          message:
            "Client has no phone on file. Use update_client to set phone, or set also_sms=false and also_email=true (or notify_partners=true for partners only).",
        };
      }

      const partnerEmailStats =
        await countLinkedReferrerPartnersWithEmail(clientId);

      const portalUrl = `${APP_URL}/portal/reports`;
      const triggerEvent = `round_${roundNumber}_complete`;
      const smsPreviewBody = smsClientReminderBody({
        triggerEvent,
        firstName: String(client.first_name || ""),
        lang,
        portalUrl: "[secure_pdf_url]",
      });
      const emailTplPreview = tplRoundComplete({
        firstName: String(client.first_name || ""),
        roundNumber,
        scoreBefore,
        scoreAfter,
        itemsRemoved,
        portalUrl,
        securePdfUrl: "[secure_pdf_url]",
        lang,
      });

      const preview = {
        client_id: clientId,
        client_name: clientName,
        case_id: caseId,
        case_number: caseNumber,
        pdf_id: pdfId,
        round_report_id: roundReportId,
        round_number: roundNumber,
        file_name: String(pdfRow.file_name || ""),
        also_email: alsoEmail,
        also_sms: alsoSms,
        attach_pdf: attachPdf,
        notify_partners: notifyPartners,
        partners_linked: partnerEmailStats.linked,
        partners_with_email: partnerEmailStats.withEmail,
        to_email: alsoEmail ? clientEmail : null,
        to_phone: alsoSms ? clientPhone : null,
        email_subject: emailTplPreview.subject,
        sms_preview: alsoSms ? smsPreviewBody : null,
        secure_link_ttl_hours: ROUND_PDF_DOWNLOAD_TTL_HOURS,
        note: "Dry-run does not mint tokens or send. On confirm: mint secure PDF URL, email Round-complete template, optional SMS + partner emails.",
      };

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show Round ${roundNumber} secure email/SMS preview. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let pdfAttachment:
        | { filename: string; content: Buffer; contentType: string }
        | undefined;
      if (attachPdf || notifyPartners) {
        const buf = await loadRoundReportPdfBytes(pdfRow);
        if (buf && buf.length > 0) {
          pdfAttachment = {
            filename:
              String(pdfRow.file_name || "").trim() ||
              `OFG_Progress_Report_R${roundNumber}.pdf`,
            content: buf,
            contentType: "application/pdf",
          };
        } else if (attachPdf || notifyPartners) {
          return {
            ok: false,
            error: "send_failed",
            message:
              "Could not load Round PDF bytes from storage. Try again or finish in CRM Reports.",
          };
        }
      }

      let securePdfUrl = "";
      try {
        const dlToken = await createRoundReportDownloadToken(pdfId, clientId);
        securePdfUrl = `${APP_URL}/api/public/round-report-pdf/${dlToken}`;
      } catch (e: any) {
        return {
          ok: false,
          error: "send_failed",
          message: String(e?.message || "Failed to mint secure PDF link").slice(
            0,
            300,
          ),
        };
      }

      let emailSent = false;
      let smsSent = false;
      let partnersEmailed = 0;

      if (alsoEmail && clientEmail) {
        const tpl = tplRoundComplete({
          firstName: String(client.first_name || ""),
          roundNumber,
          scoreBefore,
          scoreAfter,
          itemsRemoved,
          portalUrl,
          securePdfUrl,
          lang,
        });
        try {
          await sendEmail({
            to: clientEmail,
            subject: tpl.subject,
            html: tpl.html,
            attachments:
              attachPdf && pdfAttachment ? [pdfAttachment] : undefined,
          });
          emailSent = true;
        } catch (e: any) {
          return {
            ok: false,
            error: "send_failed",
            message: `${String(e?.message || "Email send failed").slice(0, 300)} (secure link was minted: ${securePdfUrl})`,
          };
        }
      }

      if (alsoSms && clientPhone) {
        const smsResult = await maybeSendClientReminderSms({
          clientId,
          triggerEvent,
          alsoSms: true,
          portalUrl: securePdfUrl,
          smsFromAdminId: ctx.adminId,
        }).catch((e: any) => {
          console.error("[admin-ai] send_round_report sms", e?.message ?? e);
          return { sent: false, reason: "error" as string };
        });
        smsSent = !!smsResult.sent;
      }

      if (notifyPartners && pdfAttachment) {
        partnersEmailed = await emailLinkedReferrerPartnersRoundPdf({
          clientId,
          roundNumber,
          clientName: clientName || "Client",
          langFallback: lang,
          pdfAttachment,
        });
      }

      if (roundReportId && (emailSent || smsSent)) {
        await pool
          .query(
            `UPDATE client_round_reports
             SET delivered_via_email = IF(?, 1, delivered_via_email),
                 delivered_via_sms = IF(?, 1, delivered_via_sms)
             WHERE id = ?`,
            [emailSent ? 1 : 0, smsSent ? 1 : 0, roundReportId],
          )
          .catch(() => null);
      }

      const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
      const noteBits = [
        `[ROUND REPORT ${ts} UTC] Resent Round ${roundNumber} via MCP`,
        emailSent ? `Email → ${clientEmail}` : null,
        smsSent ? `SMS → ${clientPhone}` : null,
        `Secure PDF: ${securePdfUrl}`,
        attachPdf && pdfAttachment
          ? `Attached: ${pdfAttachment.filename}`
          : null,
        partnersEmailed > 0 ? `Partners emailed: ${partnersEmailed}` : null,
      ].filter(Boolean);
      try {
        await pool.query(
          `UPDATE clients
           SET admin_notes = CONCAT(
                 COALESCE(admin_notes, ''),
                 CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
                 ?
               )
           WHERE id = ?`,
          [noteBits.join("\n").slice(0, 8000), clientId],
        );
      } catch (noteErr: any) {
        console.error(
          "[admin-ai] send_round_report note",
          noteErr?.message ?? noteErr,
        );
      }

      return {
        ok: true,
        data: {
          sent: true,
          client_id: clientId,
          client_name: clientName,
          case_id: caseId,
          case_number: caseNumber,
          pdf_id: pdfId,
          round_report_id: roundReportId,
          round_number: roundNumber,
          email_sent: emailSent,
          sms_sent: smsSent,
          partners_emailed: partnersEmailed,
          attach_pdf: !!(attachPdf && pdfAttachment),
          secure_pdf_url: securePdfUrl,
          secure_link_ttl_hours: ROUND_PDF_DOWNLOAD_TTL_HOURS,
          href: `/admin/pipeline?client=${clientId}${caseId ? `&case=${caseId}` : ""}`,
        },
      };
    }

    if (name === "list_ofg_phone_numbers") {
      const [roleRows] = await pool.query<RowDataPacket[]>(
        `SELECT role FROM admins WHERE id = ? LIMIT 1`,
        [ctx.adminId],
      );
      const role = String(roleRows[0]?.role || "");
      const listAll = args.all === true && role === "super_admin";
      const [rows] = await pool.query<RowDataPacket[]>(
        listAll
          ? `SELECT n.id, n.e164, n.friendly_name, n.twilio_sid, n.assigned_admin_id,
                    n.is_active, n.capabilities_json,
                    CONCAT(a.first_name,' ',a.last_name) AS assigned_admin_name
             FROM admin_phone_numbers n
             LEFT JOIN admins a ON a.id = n.assigned_admin_id
             WHERE n.is_active = 1
             ORDER BY n.id ASC`
          : `SELECT n.id, n.e164, n.friendly_name, n.twilio_sid, n.assigned_admin_id,
                    n.is_active, n.capabilities_json,
                    CONCAT(a.first_name,' ',a.last_name) AS assigned_admin_name
             FROM admin_phone_numbers n
             LEFT JOIN admins a ON a.id = n.assigned_admin_id
             WHERE n.is_active = 1 AND n.assigned_admin_id = ?
             ORDER BY n.id ASC`,
        listAll ? [] : [ctx.adminId],
      );
      const twilioConfigured = isTwilioConfigured();
      return {
        ok: true,
        data: {
          twilio_configured: twilioConfigured,
          scope: listAll ? "all_active" : "assigned_to_acting_admin",
          numbers: rows.map(mapPhoneNumberRow),
          acting_admin_from: listAll
            ? null
            : rows[0]
              ? String(rows[0].e164)
              : null,
          note: !twilioConfigured
            ? "Twilio credentials are not configured on the platform — SMS cannot send until TWILIO_ACCOUNT_SID + TWILIO_AUTH_TOKEN are set."
            : rows.length === 0
              ? "No active OFG numbers assigned to this admin. Assign one in People → Phone numbers before send_sms/send_text."
              : "Twilio is configured and at least one OFG business number is assigned. Use acting_admin_from (or numbers[].e164) as the From line for send_text/send_sms.",
        },
      };
    }

    if (name === "list_sms") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const clientId = resolved.clientId;
      const rawLimit = Number(args.limit);
      const limit = Number.isFinite(rawLimit)
        ? Math.min(50, Math.max(1, Math.floor(rawLimit)))
        : 20;
      const [convRows] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM conversations WHERE client_id = ?`,
        [clientId],
      );
      const convIds = convRows.map((r) => Number(r.id)).filter((id) => id > 0);
      if (!convIds.length) {
        return {
          ok: true,
          data: {
            client_id: clientId,
            messages: [],
            note: "No Conversations hub threads yet for this client.",
            href: `/admin/conversations?client=${clientId}`,
          },
        };
      }
      const [msgs] = await pool.query<RowDataPacket[]>(
        `SELECT m.id, m.conversation_id, m.direction, m.channel, m.body,
                m.provider_message_id, m.provider_status, m.error_message,
                m.created_at, m.media_url IS NOT NULL AS has_media,
                m.call_duration_sec, m.recording_url IS NOT NULL AS has_recording,
                m.call_insights_status, m.call_insights_json, m.metadata_json
         FROM conversation_messages m
         WHERE m.conversation_id IN (?)
         ORDER BY m.id DESC
         LIMIT ?`,
        [convIds, limit],
      );
      return {
        ok: true,
        data: {
          client_id: clientId,
          messages: msgs
            .map((m) => {
              const channel = String(m.channel || "sms");
              let insightsSummary: string | null = null;
              let insightsStatus: string | null = m.call_insights_status
                ? String(m.call_insights_status)
                : null;
              if (channel === "call" && m.call_insights_json) {
                try {
                  const raw =
                    typeof m.call_insights_json === "string"
                      ? JSON.parse(m.call_insights_json)
                      : m.call_insights_json;
                  const bullets = Array.isArray(raw?.summary_bullets)
                    ? raw.summary_bullets.map(String)
                    : [];
                  const label = raw?.sentiment?.label
                    ? String(raw.sentiment.label)
                    : null;
                  insightsSummary = [
                    label ? `sentiment:${label}` : null,
                    ...bullets.slice(0, 3),
                  ]
                    .filter(Boolean)
                    .join(" · ")
                    .slice(0, 400);
                } catch {
                  insightsSummary = null;
                }
              }
              let isVoicemail = false;
              try {
                const meta =
                  typeof m.metadata_json === "string"
                    ? JSON.parse(m.metadata_json)
                    : m.metadata_json;
                isVoicemail = !!(meta && meta.is_voicemail);
              } catch {
                isVoicemail = false;
              }
              return {
                id: Number(m.id),
                conversation_id: Number(m.conversation_id),
                direction: String(m.direction || ""),
                channel,
                body: decodeLiteralUnicodeEscapes(String(m.body || "")).slice(
                  0,
                  500,
                ),
                has_media: Number(m.has_media) === 1,
                has_recording: Number(m.has_recording) === 1,
                call_duration_sec:
                  m.call_duration_sec != null
                    ? Number(m.call_duration_sec)
                    : null,
                is_voicemail: isVoicemail,
                call_insights_status: insightsStatus,
                insights_summary: insightsSummary,
                provider_message_id: m.provider_message_id
                  ? String(m.provider_message_id)
                  : null,
                provider_status: m.provider_status
                  ? String(m.provider_status)
                  : null,
                error_message: m.error_message
                  ? String(m.error_message).slice(0, 200)
                  : null,
                created_at: m.created_at,
              };
            })
            .reverse(),
          href: `/admin/conversations?client=${clientId}`,
        },
      };
    }

    if (name === "get_call_insights") {
      const resolved = await adminAiResolveClientId(args, scopedIds);
      if (resolved.ok === false) {
        return {
          ok: false,
          error: resolved.error,
          message: resolved.message,
        };
      }
      const clientId = resolved.clientId;
      const messageIdArg =
        args.message_id != null && Number(args.message_id) > 0
          ? Number(args.message_id)
          : null;
      const rawLimit = Number(args.limit);
      const limit = Number.isFinite(rawLimit)
        ? Math.min(10, Math.max(1, Math.floor(rawLimit)))
        : 3;

      const [convRows] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM conversations WHERE client_id = ?`,
        [clientId],
      );
      const convIds = convRows.map((r) => Number(r.id)).filter((id) => id > 0);
      if (!convIds.length) {
        return {
          ok: true,
          data: {
            client_id: clientId,
            calls: [],
            note: "No Conversations hub threads yet for this client.",
            href: `/admin/conversations?client=${clientId}`,
            call_insights_enabled: callInsightsFeatureEnabled(),
          },
        };
      }

      const where = [
        "m.conversation_id IN (?)",
        "m.channel = 'call'",
        "m.recording_url IS NOT NULL",
      ];
      const params: any[] = [convIds];
      if (messageIdArg) {
        where.push("m.id = ?");
        params.push(messageIdArg);
      }
      params.push(messageIdArg ? 1 : limit);

      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT m.id, m.conversation_id, m.direction, m.body, m.created_at,
                m.call_duration_sec, m.recording_url IS NOT NULL AS has_recording,
                m.call_insights_status, m.call_transcript, m.call_insights_json,
                m.call_insights_error, m.metadata_json
         FROM conversation_messages m
         WHERE ${where.join(" AND ")}
         ORDER BY m.id DESC
         LIMIT ?`,
        params,
      );

      const calls = rows.map((m) => {
        let insights: unknown = null;
        if (m.call_insights_json) {
          try {
            insights =
              typeof m.call_insights_json === "string"
                ? JSON.parse(m.call_insights_json)
                : m.call_insights_json;
          } catch {
            insights = null;
          }
        }
        let isVoicemail = false;
        try {
          const meta =
            typeof m.metadata_json === "string"
              ? JSON.parse(m.metadata_json)
              : m.metadata_json;
          isVoicemail = !!(meta && meta.is_voicemail);
        } catch {
          isVoicemail = false;
        }
        const transcript = m.call_transcript
          ? decodeLiteralUnicodeEscapes(String(m.call_transcript))
          : null;
        return {
          message_id: Number(m.id),
          conversation_id: Number(m.conversation_id),
          direction: String(m.direction || ""),
          body: decodeLiteralUnicodeEscapes(String(m.body || "")).slice(0, 240),
          is_voicemail: isVoicemail,
          call_duration_sec:
            m.call_duration_sec != null ? Number(m.call_duration_sec) : null,
          has_recording: Number(m.has_recording) === 1,
          call_insights_status: m.call_insights_status
            ? String(m.call_insights_status)
            : null,
          call_insights_error: m.call_insights_error
            ? String(m.call_insights_error).slice(0, 200)
            : null,
          insights,
          transcript_preview: transcript
            ? transcript.slice(0, 800)
            : null,
          transcript_full:
            transcript && transcript.length <= 12000
              ? transcript
              : transcript
                ? `${transcript.slice(0, 12000)}…`
                : null,
          created_at: m.created_at,
        };
      });

      return {
        ok: true,
        data: {
          client_id: clientId,
          calls,
          call_insights_enabled: callInsightsFeatureEnabled(),
          href: `/admin/conversations?client=${clientId}`,
          guidance: callInsightsFeatureEnabled()
            ? "When status is pending/processing, ask again after the next cron cycle. Use insights for staff coaching — do not invent details missing from transcript."
            : "CALL_INSIGHTS_ENABLED is off on this environment — recordings still play in CRM but Claude resumes are not generated.",
        },
      };
    }

    if (name === "send_sms") {
      const rawBody = decodeLiteralUnicodeEscapes(
        String(args.body || args.message || ""),
      ).trim();
      if ([...rawBody].length > SMS_MAX_BODY_CHARS) {
        return {
          ok: false,
          error: "sms_body_too_long",
          message: `SMS body exceeds ${SMS_MAX_BODY_CHARS} characters`,
        };
      }
      const body = rawBody;
      const referrerIdArg =
        args.referrer_id != null && Number(args.referrer_id) > 0
          ? Number(args.referrer_id)
          : null;
      const hasClientKey =
        (args.client_id != null && Number(args.client_id) > 0) ||
        (args.case_id != null && Number(args.case_id) > 0) ||
        (typeof args.case_number === "string" && !!args.case_number.trim());

      const namedTo = await resolveMcpStaffAssignee({
        adminId: args.to_admin_id,
        name: args.to_admin_name,
        email: args.to_admin_email,
      });
      if (namedTo.ok === false) return namedTo;
      const staffTo = namedTo.requested ? namedTo : null;

      const missing: string[] = [];
      if (!body) missing.push("body");
      if (!referrerIdArg && !hasClientKey && !staffTo) {
        missing.push(
          "client_id / case_id / case_number, referrer_id, or to_admin_id / to_admin_name",
        );
      }

      const fromResolved = await resolveMcpSmsFromE164(ctx.adminId, args);
      if (fromResolved.ok === false) return fromResolved;
      const fromE164 = fromResolved.e164;
      const fromAdminId = fromResolved.from_admin_id;

      const audience: "client" | "referrer" | "staff" = staffTo
        ? "staff"
        : referrerIdArg
          ? "referrer"
          : "client";

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let clientName: string | null = null;
      let clientPhone: string | null = null;
      let clientStatus: string | null = null;
      let referrerId: number | null = referrerIdArg;
      let referrerName: string | null = null;
      let referrerPhone: string | null = null;
      let toPhone: string | null = null;
      let toName: string | null = null;
      let conversationClosed = false;

      if (missing.length === 0 && staffTo) {
        const [staffRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, phone
           FROM admins WHERE id = ? AND status = 'active' LIMIT 1`,
          [staffTo.id],
        );
        if (!staffRows[0]) {
          return {
            ok: false,
            error: "assignee_not_found",
            message: "Staff not found or inactive. Use search_admins.",
          };
        }
        toName =
          `${staffRows[0].first_name || ""} ${staffRows[0].last_name || ""}`.trim();
        toPhone = staffRows[0].phone ? String(staffRows[0].phone).trim() : null;
        if (!toPhone) {
          return {
            ok: false,
            error: "no_phone",
            message:
              "That staff member has no phone on file. Add a cell in People, then retry.",
          };
        }
      }

      if (missing.length === 0 && referrerId && audience === "referrer") {
        const [refRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, phone, status
           FROM referrers WHERE id = ? LIMIT 1`,
          [referrerId],
        );
        if (!refRows[0]) {
          return {
            ok: false,
            error: "not_found",
            message:
              "Referrer not found. Use search_referrers or get_client.referrer.id.",
          };
        }
        if (String(refRows[0].status) !== "active") {
          return {
            ok: false,
            error: "invalid_args",
            message: "Cannot SMS an inactive referrer",
          };
        }
        referrerName =
          `${refRows[0].first_name || ""} ${refRows[0].last_name || ""}`.trim();
        referrerPhone = refRows[0].phone
          ? String(refRows[0].phone).trim()
          : null;
        if (!referrerPhone) {
          return {
            ok: false,
            error: "no_phone",
            message:
              "Referrer has no phone on file. Add a phone on the partner record, then retry.",
          };
        }
        toPhone = referrerPhone;
        toName = referrerName;
      }

      if (missing.length === 0 && audience !== "staff" && (hasClientKey || audience === "client")) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          if (audience === "client") {
            return {
              ok: false,
              error: resolved.error,
              message: resolved.message,
            };
          }
        } else {
          clientId = resolved.clientId;
          caseId = resolved.caseId;
          caseNumber = resolved.caseNumber;
          const [cRows] = await pool.query<RowDataPacket[]>(
            `SELECT first_name, last_name, phone, status
             FROM clients WHERE id = ? LIMIT 1`,
            [clientId],
          );
          if (!cRows[0]) {
            return {
              ok: false,
              error: "not_found",
              message:
                "Client not found. Use search_clients — OFG client_id is not a HubSpot contact id.",
            };
          }
          clientName =
            `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim();
          clientPhone = cRows[0].phone ? String(cRows[0].phone).trim() : null;
          clientStatus = String(cRows[0].status || "");
          if (audience === "client" && clientStatus === "cancelled") {
            return {
              ok: false,
              error: "invalid_args",
              message: "Cannot SMS a cancelled client",
            };
          }
          if (audience === "client" && !clientPhone) {
            return {
              ok: false,
              error: "no_phone",
              message:
                "Client has no phone on file. Add a phone in the CRM first.",
            };
          }
          if (!caseId) {
            const [cr] = await pool.query<RowDataPacket[]>(
              `SELECT id, case_number FROM credit_repair_cases
               WHERE client_id = ? AND status <> 'cancelled'
               ORDER BY id DESC LIMIT 1`,
              [clientId],
            );
            if (cr[0]) {
              caseId = Number(cr[0].id);
              caseNumber = cr[0].case_number ? String(cr[0].case_number) : null;
            }
          }
          if (audience === "client") {
            toPhone = clientPhone;
            toName = clientName;
            conversationClosed = await contactComposeBlockedByClosed({
              clientId,
            });
          }
        }
      }

      const preview = {
        audience,
        client_id: clientId,
        client_name: clientName,
        case_id: caseId,
        case_number: caseNumber,
        referrer_id: referrerId,
        referrer_name: referrerName,
        to: toPhone,
        from: fromE164,
        body,
        conversation_closed: conversationClosed,
        will_log_conversations_hub: audience === "client",
        will_log_client_note: audience === "client",
        will_log_referrer_note: audience === "referrer",
        note:
          audience === "referrer"
            ? "Dry-run does not send. On confirm, SMS goes to the referrer from the OFG number; a note is saved on the partner record" +
              (clientId ? " and on the linked client's file." : ".")
            : audience === "staff"
              ? "Dry-run does not send. On confirm, SMS goes to that staff member's phone from the chosen OFG From line."
              : conversationClosed
                ? "Conversation is closed. On confirm, it will reopen and the SMS will send via Conversations hub."
                : "Dry-run does not send. On confirm, SMS sends via Twilio from the OFG number into Conversations hub + SMS case note.",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Collect body, and client_id (OFG), referrer_id, or to_admin_id / to_admin_name. Optional from_admin_* / from_phone_number_id to pick the OFG From line.",
          },
        };
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the exact To / From / body. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }

      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let reopened = false;
      if (audience === "client" && clientId && conversationClosed) {
        await setContactConversationStatus({
          clientId,
          status: "open",
          adminId: ctx.adminId,
        });
        reopened = true;
      }

      const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
      let messageId: number | null = null;
      let conversationId: number | null = null;
      let providerMessageId: string | null = null;
      let providerStatus: string | null = null;

      if (audience === "client" && clientId) {
        try {
          const result = await deliverHubConversationMessage({
            adminId: fromAdminId,
            clientId,
            channel: "sms",
            textBody: body,
          });
          messageId = result.message_id;
          conversationId = result.conversation_id;
          const [mrows] = await pool.query<RowDataPacket[]>(
            `SELECT provider_message_id, provider_status, error_message
             FROM conversation_messages WHERE id = ? LIMIT 1`,
            [result.message_id],
          );
          providerMessageId = mrows[0]?.provider_message_id
            ? String(mrows[0].provider_message_id)
            : null;
          providerStatus = mrows[0]?.provider_status
            ? String(mrows[0].provider_status)
            : result.provider_status;
          if (!result.ok && result.error) {
            return {
              ok: false,
              error: "send_failed",
              message: String(result.error).slice(0, 400),
            };
          }
        } catch (e: any) {
          const msg = String(e?.message || e);
          if (
            msg === "conversation_closed" ||
            e?.code === "conversation_closed"
          ) {
            return {
              ok: false,
              error: "conversation_closed",
              message:
                "Conversation is still closed. Reopen in Conversations, then retry send_sms.",
            };
          }
          return {
            ok: false,
            error: "send_failed",
            message: msg.slice(0, 400),
          };
        }
      } else if ((audience === "referrer" || audience === "staff") && toPhone) {
        try {
          const sent = await sendSms({
            to: toPhone,
            body,
            from: fromE164,
          });
          providerMessageId = sent?.sid ? String(sent.sid) : null;
          providerStatus = sent?.status ? String(sent.status) : "queued";
        } catch (e: any) {
          return {
            ok: false,
            error: "send_failed",
            message: String(e?.message || "SMS send failed").slice(0, 400),
          };
        }
      }

      let clientNoteAppended = false;
      let referrerNoteAppended = false;
      const noteParts = [body.slice(0, 1500)];
      if (providerMessageId) {
        noteParts.push(`Twilio SID: ${providerMessageId}`);
      }
      if (audience === "client" && clientId) {
        clientNoteAppended = await appendClientFileSmsNote(
          clientId,
          formatSmsClientFileNote({
            direction: "sent",
            ts,
            peerPhone: toPhone || "",
            body: noteParts[0],
            providerMessageId,
          }),
        );
      }
      if (audience === "referrer" && referrerId) {
        const about = clientName
          ? ` re: ${clientName}${clientId ? ` (client_id=${clientId})` : ""}`
          : "";
        const refStamped = `[SMS ${ts} UTC] Sent to ${toPhone}${about}\n${noteParts.join("\n")}`;
        try {
          await pool.query(
            `UPDATE referrers
             SET notes = CONCAT(
                   COALESCE(notes, ''),
                   CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE '\n' END,
                   ?
                 )
             WHERE id = ?`,
            [refStamped.slice(0, 8000), referrerId],
          );
          referrerNoteAppended = true;
        } catch (noteErr: any) {
          console.error(
            "[admin-ai] send_sms referrer note",
            noteErr?.message ?? noteErr,
          );
        }
        if (clientId) {
          clientNoteAppended = await appendClientFileSmsNote(
            clientId,
            formatSmsClientFileNote({
              direction: "sent",
              ts,
              peerPhone: toPhone || "",
              body: noteParts[0],
              providerMessageId,
              tag: "REFERRER",
              peerLabel: referrerName || `referrer_id=${referrerId}`,
            }),
          );
        }
      }

      return {
        ok: true,
        data: {
          sent: true,
          audience,
          client_id: clientId,
          client_name: clientName,
          case_id: caseId,
          case_number: caseNumber,
          referrer_id: referrerId,
          referrer_name: referrerName,
          to: toPhone,
          from: fromE164,
          body,
          message_id: messageId,
          conversation_id: conversationId,
          provider_message_id: providerMessageId,
          provider_status: providerStatus,
          reopened,
          sent_at: new Date().toISOString(),
          note_appended: clientNoteAppended || referrerNoteAppended,
          client_note_appended: clientNoteAppended,
          referrer_note_appended: referrerNoteAppended,
          href: clientId
            ? `/admin/conversations?client=${clientId}`
            : "/admin/conversations",
        },
      };
    }

    if (name === "update_pipeline_stage") {
      const stage = String(args.stage || "").trim();
      const allowed = [
        "new_client",
        "docs_ready",
        "round_1",
        "round_2",
        "round_3",
        "round_4",
        "round_5",
        "completed",
        "cancelled",
      ];
      const notes =
        decodeLiteralUnicodeEscapes(String(args.notes || ""))
          .trim()
          .slice(0, 2000) || null;
      const missing: string[] = [];
      if (!allowed.includes(stage))
        missing.push("stage (valid pipeline stage)");
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      let fromStage: string | null = null;
      let clientStatus: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;
        if (!caseId) {
          caseId = await resolveActiveCaseId(pool, clientId, null);
        }
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT pipeline_stage, status FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        fromStage = cRows[0] ? String(cRows[0].pipeline_stage) : null;
        clientStatus = cRows[0] ? String(cRows[0].status) : null;
        if (caseId) {
          const [cr] = await pool.query<RowDataPacket[]>(
            `SELECT pipeline_stage, case_number FROM credit_repair_cases WHERE id = ? LIMIT 1`,
            [caseId],
          );
          if (cr[0]) {
            fromStage = String(cr[0].pipeline_stage);
            caseNumber = cr[0].case_number
              ? String(cr[0].case_number)
              : caseNumber;
          }
        }
      }

      const preview = {
        client_id: clientId,
        case_id: caseId,
        case_number: caseNumber,
        from_stage: fromStage,
        to_stage: stage || null,
        client_status: clientStatus,
        notes,
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance: "Provide OFG client/case and a valid stage.",
          },
        };
      }

      if (fromStage === "prospect" || clientStatus === "prospect") {
        if (stage !== "cancelled") {
          return {
            ok: false,
            error: "use_convert_prospect",
            message:
              "Prospects must use convert_prospect to become New Client. Use stage=cancelled to close a lost prospect.",
          };
        }
      }

      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show stage change. After approval, re-call with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      if (stage === "docs_ready" && caseId) {
        const gate = await assertDocsReadyTaskGate(caseId);
        if (gate.ok === false) {
          return {
            ok: false,
            error: "tasks_incomplete",
            message: gate.message,
          };
        }
      }

      const result = await advanceCasePipeline(pool, {
        clientId: clientId!,
        caseId,
        stage,
        adminId: ctx.adminId,
        notes,
      });

      // Keep status/case.status aligned when closing via stage=cancelled
      if (stage === "cancelled" && !result.unchanged) {
        await pool.query(
          `UPDATE clients SET status = 'cancelled' WHERE id = ? AND status <> 'cancelled'`,
          [clientId],
        );
        if (result.caseId) {
          await pool.query(
            `UPDATE credit_repair_cases
             SET status = 'cancelled'
             WHERE id = ? AND status <> 'cancelled'`,
            [result.caseId],
          );
        }
      }

      // Mirror admin stage POST side effects (reminders / referrer / CRC)
      if (!result.unchanged && clientId) {
        if (stage === "docs_ready") {
          triggerReminderFlow("docs_ready", clientId).catch((e: any) =>
            console.error("[admin-ai] stage docs_ready flow", e?.message ?? e),
          );
        }
        if (stage === "completed") {
          triggerReminderFlow("completed", clientId).catch((e: any) =>
            console.error("[admin-ai] stage completed flow", e?.message ?? e),
          );
        }
        if (ROUND_STAGE_LABELS[stage]) {
          notifyReferrerRoundUpdate(clientId, stage).catch((e: any) =>
            console.error("[admin-ai] stage referrer notify", e?.message ?? e),
          );
        }
        crcSyncClient(clientId).catch((e: any) =>
          console.error("[admin-ai] stage crc sync", e?.message ?? e),
        );
      }

      return {
        ok: true,
        data: {
          updated: !result.unchanged,
          unchanged: result.unchanged,
          client_id: clientId,
          case_id: result.caseId,
          from_stage: result.fromStage,
          to_stage: stage,
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "convert_prospect" || name === "preview_convert_prospect") {
      const forcePreview = name === "preview_convert_prospect";
      const clientId =
        args.client_id != null && Number(args.client_id) > 0
          ? Number(args.client_id)
          : null;
      const packageId =
        args.package_id != null && Number(args.package_id) > 0
          ? Number(args.package_id)
          : null;
      const notes =
        decodeLiteralUnicodeEscapes(String(args.notes || ""))
          .trim()
          .slice(0, 2000) || null;
      if (!clientId) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: ["client_id"],
            guidance: "Provide OFG prospect client_id from search_clients.",
          },
        };
      }
      // Preview is read-only (not in write-tool affiliate block) — still isolate.
      if (!(await assertClientInAffiliateScope(clientId, scope))) {
        return {
          ok: false,
          error: "not_found",
          message:
            "Prospect not found. Use search_clients — OFG client_id is not a HubSpot contact id.",
        };
      }
      const [clientRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, status, pipeline_stage
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      if (!clientRows[0]) {
        return {
          ok: false,
          error: "not_found",
          message:
            "Prospect not found. Use search_clients — OFG client_id is not a HubSpot contact id.",
        };
      }
      const client = clientRows[0];
      const preview = {
        client_id: clientId,
        name: `${client.first_name || ""} ${client.last_name || ""}`.trim(),
        email: client.email,
        current_status: client.status,
        current_stage: client.pipeline_stage,
        to_status: "onboarding",
        to_stage: "new_client",
        package_id: packageId,
        notes,
      };
      const convertible = await assertClientConvertibleToEnrolled(
        clientId,
        client.status,
      );
      if (convertible.ok === false) {
        return {
          ok: false,
          error: convertible.error,
          message: convertible.message,
        };
      }
      if (forcePreview || !adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: forcePreview
              ? `Safe read-only preview. After the user approves, call convert_prospect with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`
              : `Show convert preview. After approval, re-call convert_prospect with confirm=true and confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}" (prefer preview_convert_prospect for a read-only first step).`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      const [existingCases] = await pool.query<RowDataPacket[]>(
        `SELECT id, case_number, pipeline_stage
         FROM credit_repair_cases
         WHERE client_id = ? AND status = 'active'
         ORDER BY id DESC`,
        [clientId],
      );
      const prospectCase = existingCases.find(
        (r) => r.pipeline_stage === "prospect",
      );
      if (existingCases.length > 0 && !prospectCase) {
        return {
          ok: false,
          error: "already_converted",
          message: `Already has active case ${existingCases[0].case_number} past Prospect.`,
        };
      }

      const conn = await pool.getConnection();
      let caseId = 0;
      let caseNumber = "";
      try {
        await conn.beginTransaction();
        await conn.query<ResultSetHeader>(
          `UPDATE clients
           SET status = 'onboarding', pipeline_stage = 'new_client',
               pipeline_stage_changed_at = NOW(),
               package_id = COALESCE(?, package_id),
               admin_notes = CASE WHEN ? IS NOT NULL
                 THEN CONCAT(COALESCE(admin_notes, ''), CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END, ?)
                 ELSE admin_notes END
           WHERE id = ?`,
          [packageId, notes, notes ? `[AI convert] ${notes}` : null, clientId],
        );
        if (prospectCase) {
          caseId = Number(prospectCase.id);
          caseNumber =
            (prospectCase.case_number as string) ||
            `CR-${String(caseId).padStart(5, "0")}`;
          await conn.query<ResultSetHeader>(
            `UPDATE credit_repair_cases
             SET pipeline_stage = 'new_client',
                 pipeline_stage_changed_at = NOW(),
                 package_id = COALESCE(?, package_id),
                 case_number = COALESCE(case_number, ?)
             WHERE id = ?`,
            [packageId, caseNumber, caseId],
          );
          await conn.query<ResultSetHeader>(
            `UPDATE credit_repair_cases
             SET status = 'cancelled',
                 pipeline_stage_changed_at = NOW()
             WHERE client_id = ? AND status = 'active'
               AND pipeline_stage = 'prospect' AND id <> ?`,
            [clientId, caseId],
          );
        } else {
          const [caseResult] = await conn.query<ResultSetHeader>(
            `INSERT INTO credit_repair_cases (client_id, package_id, pipeline_stage, status, notes)
             VALUES (?, ?, 'new_client', 'active', ?)`,
            [clientId, packageId, notes],
          );
          caseId = caseResult.insertId;
          caseNumber = `CR-${String(caseId).padStart(5, "0")}`;
          await conn.query(
            `UPDATE credit_repair_cases SET case_number = ? WHERE id = ?`,
            [caseNumber, caseId],
          );
        }
        await conn.query<ResultSetHeader>(
          `INSERT INTO client_pipeline_history (client_id, from_stage, to_stage, changed_by_admin_id, notes)
           VALUES (?, 'prospect', 'new_client', ?, ?)`,
          [clientId, ctx.adminId, "Converted from prospect (Admin AI)"],
        );
        await conn.commit();
      } catch (e) {
        await conn.rollback();
        throw e;
      } finally {
        conn.release();
      }

      await autoAssignTasksForCase(clientId, caseId).catch((e: any) =>
        console.error(
          "[admin-ai] convert_prospect autoAssignTasks",
          e?.message ?? e,
        ),
      );

      return {
        ok: true,
        data: {
          converted: true,
          client_id: clientId,
          case_id: caseId,
          case_number: caseNumber,
          status: "onboarding",
          pipeline_stage: "new_client",
          tasks_auto_assigned: true,
          welcome_email_sent: false,
          note: "Onboarding tasks assigned. Welcome email is not sent via MCP — use admin convert UI if needed.",
          href: adminPipelineHref(clientId, caseId),
        },
      };
    }

    if (name === "update_client_status") {
      const status = String(args.status || "").trim();
      const allowed = [
        "prospect",
        "pending_payment",
        "onboarding",
        "active",
        "paused",
        "cancelled",
      ];
      const notes =
        decodeLiteralUnicodeEscapes(String(args.notes || ""))
          .trim()
          .slice(0, 2000) || null;
      const missing: string[] = [];
      if (!allowed.includes(status)) missing.push("status");
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }
      let clientId: number | null = null;
      let fromStatus: string | null = null;
      let clientName: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name, status FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        fromStatus = cRows[0] ? String(cRows[0].status) : null;
        clientName = cRows[0]
          ? `${cRows[0].first_name || ""} ${cRows[0].last_name || ""}`.trim()
          : null;
        if (clientId) {
          const enrolled = await clientHasEnrolledCase(clientId);
          if (status === "prospect" && enrolled) {
            return {
              ok: false,
              error: "invalid_args",
              message:
                "Cannot set status=prospect after the client has an enrolled case. Use update_pipeline_stage for the case.",
            };
          }
          // Prevention: never strand a lead as "paid/active" without a case.
          // Staff Clients UI is unchanged; MCP must use convert_prospect.
          const needsEnrolledCase = [
            "pending_payment",
            "onboarding",
            "active",
          ].includes(status);
          if (needsEnrolledCase && !enrolled) {
            return {
              ok: false,
              error: "use_convert_prospect",
              message:
                "Cannot set status to pending_payment/onboarding/active until the client has an enrolled case. Call preview_convert_prospect then convert_prospect (creates the case + onboarding). For unconverted leads use status=prospect, paused, or cancelled only.",
            };
          }
        }
      }
      const preview = {
        client_id: clientId,
        client_name: clientName,
        from_status: fromStatus,
        to_status: status || null,
        notes,
      };
      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
          },
        };
      }
      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show status change. After approval, confirm=true + confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }
      await pool.query(
        `UPDATE clients
         SET status = ?,
             pipeline_stage = IF(? = 'prospect', 'prospect', pipeline_stage),
             admin_notes = CASE WHEN ? IS NOT NULL
               THEN CONCAT(COALESCE(admin_notes, ''), CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END, ?)
               ELSE admin_notes END
         WHERE id = ?`,
        [
          status,
          status,
          notes,
          notes ? `[AI status→${status}] ${notes}` : null,
          clientId,
        ],
      );
      return {
        ok: true,
        data: {
          updated: true,
          client_id: clientId,
          from_status: fromStatus,
          to_status: status,
          href: `/admin/pipeline?client=${clientId}`,
        },
      };
    }

    if (name === "upsert_progress_report") {
      const round = Number(args.round);
      const summary = decodeLiteralUnicodeEscapes(String(args.summary_md || ""))
        .trim()
        .slice(0, 20000);
      const missing: string[] = [];
      // Round range validated after case resolve (uses case max_rounds)
      if (!Number.isFinite(round) || round < 1 || round > ABSOLUTE_MAX_ROUNDS) {
        missing.push(`round (1–${ABSOLUTE_MAX_ROUNDS})`);
      }
      if (!summary) missing.push("summary_md");
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }
      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;
        if (!caseId) {
          caseId = await resolveActiveCaseId(pool, clientId, null);
          if (caseId) {
            const [cr] = await pool.query<RowDataPacket[]>(
              `SELECT case_number FROM credit_repair_cases WHERE id = ? LIMIT 1`,
              [caseId],
            );
            caseNumber = cr[0]?.case_number ? String(cr[0].case_number) : null;
          }
        }
        if (caseId && Number.isFinite(round) && missing.length === 0) {
          const caseMax = await loadCaseMaxRounds(pool, caseId);
          if (round > caseMax) {
            missing.push(`round (1–${caseMax} for this case)`);
          }
        }
      }
      const scoreBefore =
        args.score_before != null && Number.isFinite(Number(args.score_before))
          ? Number(args.score_before)
          : null;
      const scoreAfter =
        args.score_after != null && Number.isFinite(Number(args.score_after))
          ? Number(args.score_after)
          : null;
      if (
        scoreBefore == null ||
        !Number.isInteger(scoreBefore) ||
        scoreBefore < 300 ||
        scoreBefore > 850
      ) {
        missing.push("score_before (integer 300–850; never invent)");
      }
      if (
        scoreAfter == null ||
        !Number.isInteger(scoreAfter) ||
        scoreAfter < 300 ||
        scoreAfter > 850
      ) {
        missing.push("score_after (integer 300–850; never invent)");
      }
      const itemsRemoved =
        args.items_removed != null &&
        Number.isFinite(Number(args.items_removed))
          ? Number(args.items_removed)
          : 0;
      const itemsDisputed =
        args.items_disputed != null &&
        Number.isFinite(Number(args.items_disputed))
          ? Number(args.items_disputed)
          : 0;
      const fileStrengthRaw =
        args.file_strength_score != null
          ? Number(args.file_strength_score)
          : null;
      const fileStrength =
        fileStrengthRaw != null && Number.isFinite(fileStrengthRaw)
          ? Math.min(100, Math.max(0, fileStrengthRaw))
          : null;
      const locale = args.report_locale === "es" ? "es" : "en";
      const replacePublished = adminAiConfirmTrue(args.replace_published);
      let existingPublished = false;
      if (missing.length === 0 && clientId && Number.isFinite(round)) {
        const [ex] = await pool.query<RowDataPacket[]>(
          `SELECT id, pdf_storage_key, wizard_session_id
           FROM client_round_reports
           WHERE client_id = ? AND round_number = ? LIMIT 1`,
          [clientId, round],
        );
        existingPublished = Boolean(
          ex[0] && (ex[0].pdf_storage_key || ex[0].wizard_session_id),
        );
      }
      let bureauJson: string | null = null;
      if (args.bureau_scores_json != null) {
        const raw = String(args.bureau_scores_json).trim();
        if (raw) {
          try {
            JSON.parse(raw);
            bureauJson = raw.slice(0, 8000);
          } catch {
            return {
              ok: false,
              error: "invalid_args",
              message: "bureau_scores_json must be valid JSON",
            };
          }
        }
      }
      const preview = {
        client_id: clientId,
        case_id: caseId,
        case_number: caseNumber,
        round: Number.isFinite(round) ? round : null,
        score_before: scoreBefore,
        score_after: scoreAfter,
        items_removed: itemsRemoved,
        items_disputed: itemsDisputed,
        file_strength_score: fileStrength,
        summary_md: summary.slice(0, 500) + (summary.length > 500 ? "…" : ""),
        report_locale: locale,
        existing_published: existingPublished,
        replace_published: replacePublished,
        client_portal_visible: false,
        note: "Staff notes only — does not upload Before/After PDFs or publish the branded client PDF. Without a Wizard PDF this stays staff-only; client portal lists PDF-published reports only.",
      };
      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
            guidance:
              "Provide real score_before + score_after from staff or the Wizard. Never invent scores. To generate/publish a round PDF, open CRM Reports → Generate.",
          },
        };
      }
      if (existingPublished && !replacePublished) {
        return {
          ok: false,
          error: "published_exists",
          message:
            "Round already has a published PDF/wizard report. Prefer CRM Reports → Generate for the next round. Pass replace_published=true only after the user explicitly approves overwriting staff+portal content.",
          crm_required: adminAiCrmRequired({
            reason: "published_progress_report",
            userMessage: `Round ${round} already has a published OFG progress PDF. Continue the next round (or re-publish) in CRM: open the client → Reports → Generate. Do not overwrite via MCP unless the user explicitly asks to replace published content.`,
            clientId,
            caseId,
            crmAction: "open_reports_wizard",
            details: {
              round,
              replace_published_required: true,
            },
          }),
        };
      }
      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show analysis preview. After approval, confirm=true + confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}". This writes staff notes only — branded PDF publish stays in the Wizard.`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }
      await pool.query(
        `INSERT INTO client_round_reports
           (client_id, case_id, round_number, score_before, score_after,
            items_removed, items_disputed, summary_md, bureau_scores_json,
            file_strength_score, report_locale, created_by_admin_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON DUPLICATE KEY UPDATE
           case_id = COALESCE(VALUES(case_id), case_id),
           score_before = VALUES(score_before),
           score_after = VALUES(score_after),
           items_removed = VALUES(items_removed),
           items_disputed = VALUES(items_disputed),
           summary_md = VALUES(summary_md),
           bureau_scores_json = COALESCE(VALUES(bureau_scores_json), bureau_scores_json),
           file_strength_score = VALUES(file_strength_score),
           report_locale = VALUES(report_locale),
           created_by_admin_id = VALUES(created_by_admin_id)`,
        [
          clientId,
          caseId,
          round,
          scoreBefore,
          scoreAfter,
          Number.isFinite(itemsRemoved) ? itemsRemoved : 0,
          Number.isFinite(itemsDisputed) ? itemsDisputed : 0,
          summary,
          bureauJson,
          fileStrength,
          locale,
          ctx.adminId,
        ],
      );
      const [rep] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM client_round_reports WHERE client_id = ? AND round_number = ? LIMIT 1`,
        [clientId, round],
      );
      let alertsCount = 0;
      try {
        const [profRows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name, phone, address_line1, city, state, zip
           FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        const profile = (profRows[0] || {}) as ClientProfileForAlerts;
        // MCP upserts lack bureau PDF/accounts — run personal-info scan on summary_md.
        const progressAlerts = buildDeterministicProgressAlerts({
          profile,
          afterPdfText: summary,
          afterAccounts: [],
          priorWins: [],
        });
        alertsCount = progressAlerts.length;
        if (progressAlerts.length > 0) {
          const clientName =
            `${profile.first_name || ""} ${profile.last_name || ""}`.trim() ||
            `Client #${clientId}`;
          const boardUrl = `${APP_URL}/admin/pipeline?client=${clientId}`;
          notifyAllTeamAdmins("progress_report_alerts", (admin) => {
            const lang = admin.preferred_language === "es" ? "es" : "en";
            const tpl = tplProgressReportAlerts({
              clientName,
              round,
              alerts: progressAlerts,
              linkUrl: boardUrl,
              lang,
              context: "mcp",
            });
            return {
              subject: tpl.subject,
              html: tpl.html,
              inAppTitle: tpl.inAppTitle,
              inAppBody: tpl.inAppBody,
              linkUrl: tpl.linkUrl,
              smsBody: tpl.smsBody,
            };
          }).catch((e: any) =>
            console.error("[progress_report_alerts:mcp]", e?.message ?? e),
          );
        }
      } catch (e: any) {
        console.error("[progress_report_alerts:mcp]", e?.message ?? e);
      }
      return {
        ok: true,
        data: {
          upserted: true,
          report_id: rep[0] ? Number(rep[0].id) : null,
          client_id: clientId,
          case_id: caseId,
          round,
          alerts_count: alertsCount,
          href: `/admin/pipeline?client=${clientId}`,
          note: "Staff analysis saved. Client-facing PDF still requires Reports → Generate (Wizard).",
        },
      };
    }

    if (name === "set_case_payment_plan") {
      const missing: string[] = [];
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }
      const totalCents = Number(args.total_cents);
      if (!(Number.isFinite(totalCents) && totalCents > 0)) {
        missing.push("total_cents (>0)");
      }

      let installments: Array<Record<string, unknown>> = [];
      const rawInstallments = args.installments_json;
      if (rawInstallments != null && String(rawInstallments).trim()) {
        try {
          const parsed =
            typeof rawInstallments === "string"
              ? JSON.parse(String(rawInstallments))
              : rawInstallments;
          if (!Array.isArray(parsed) || parsed.length === 0) {
            missing.push("installments_json (non-empty array)");
          } else {
            installments = parsed.slice(0, 20) as Array<Record<string, unknown>>;
          }
        } catch {
          return {
            ok: false,
            error: "invalid_args",
            message: "installments_json must be a JSON array",
          };
        }
      } else if (Number.isFinite(totalCents) && totalCents > 0) {
        const due =
          typeof args.due_date === "string" &&
          /^\d{4}-\d{2}-\d{2}$/.test(args.due_date.trim())
            ? args.due_date.trim()
            : laCalendarDateYmd();
        installments = [
          {
            label: String(args.label || "Agreed payment plan")
              .trim()
              .slice(0, 200),
            amount_cents: totalCents,
            due_date: due,
            notes: args.notes != null ? String(args.notes).slice(0, 2000) : null,
          },
        ];
      }

      if (installments.length > 0 && Number.isFinite(totalCents)) {
        const sum = installments.reduce(
          (a, s) => a + (Number(s.amount_cents) || 0),
          0,
        );
        if (sum !== totalCents) {
          return {
            ok: false,
            error: "total_mismatch",
            message: `Sum of installments (${sum}) must equal total_cents (${totalCents})`,
            data: { sum_cents: sum, total_cents: totalCents },
          };
        }
      }

      const markPaid = adminAiConfirmTrue(args.mark_paid);
      const replaceOpen =
        args.replace_open === undefined || args.replace_open === null
          ? true
          : adminAiConfirmTrue(args.replace_open);
      const paymentMethod = String(args.payment_method || "")
        .trim()
        .toLowerCase();
      const notesShared =
        args.notes != null ? String(args.notes).slice(0, 2000) : null;
      const caseNote =
        args.case_note != null
          ? decodeLiteralUnicodeEscapes(String(args.case_note))
              .trim()
              .slice(0, 4000)
          : "";

      const splitsForUpsert = installments.map((s, i) => ({
        label: String(s.label || `Payment ${i + 1}`)
          .trim()
          .slice(0, 200),
        amount_cents: Number(s.amount_cents),
        due_date: String(s.due_date || "").trim().slice(0, 10),
        status: markPaid ? "paid" : s.status || "pending",
        notes:
          s.notes != null
            ? String(s.notes).slice(0, 2000)
            : notesShared,
      }));

      let packagePriceCents: number | null = null;
      let packageName: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        let caseId = resolved.caseId;
        if (!caseId) {
          caseId = await resolveActiveCaseId(pool, resolved.clientId, null);
        }
        if (caseId) {
          const [pkgRows] = await pool.query<RowDataPacket[]>(
            `SELECT p.name, p.price_cents
             FROM credit_repair_cases cr
             LEFT JOIN packages p ON p.id = cr.package_id
             WHERE cr.id = ? LIMIT 1`,
            [caseId],
          );
          if (pkgRows[0]?.price_cents != null) {
            packagePriceCents = Number(pkgRows[0].price_cents);
            packageName = pkgRows[0].name ? String(pkgRows[0].name) : null;
          }
        }
      }

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            guidance:
              "Need OFG client/case + total_cents (agreed discounted total). Optional installments_json for multi-pay.",
          },
        };
      }

      const upsertArgs: Record<string, unknown> = {
        client_id: args.client_id,
        case_id: args.case_id,
        case_number: args.case_number,
        splits_json: JSON.stringify(splitsForUpsert),
        replace_open: replaceOpen,
        send_payment_link: adminAiConfirmTrue(args.send_payment_link),
        payment_method: paymentMethod || undefined,
        confirm: args.confirm,
        confirm_phrase: args.confirm_phrase,
      };

      const upsertResult = await executeAdminAiTool(
        "upsert_payment_splits",
        upsertArgs,
        ctx,
      );

      if (upsertResult.ok === false) return upsertResult;

      const enrichDeal = (data: Record<string, unknown>) => {
        const preview = (data.preview as Record<string, unknown>) || {};
        const deal = {
          kind: "discounted_payment_plan",
          total_cents: totalCents,
          package_list_price_cents: packagePriceCents,
          package_name: packageName,
          discount_vs_package_cents:
            packagePriceCents != null
              ? Math.max(0, packagePriceCents - totalCents)
              : null,
          replace_open: replaceOpen,
          mark_paid: markPaid,
          payment_method: paymentMethod || null,
          case_note_pending: caseNote || null,
          note:
            "This sets OFG installment balance — it does not create a checkout coupon code.",
        };
        return {
          ...data,
          deal,
          preview: { ...preview, deal },
        };
      };

      if (
        upsertResult.ok &&
        upsertResult.data &&
        typeof upsertResult.data === "object" &&
        (upsertResult.data as any).dry_run
      ) {
        return {
          ok: true,
          data: enrichDeal(upsertResult.data as Record<string, unknown>),
        };
      }

      // Confirmed write succeeded — optional staff case note (already gated).
      let caseNoteAppended = false;
      if (
        caseNote &&
        upsertResult.ok &&
        upsertResult.data &&
        typeof upsertResult.data === "object" &&
        (upsertResult.data as any).created
      ) {
        const clientId = Number((upsertResult.data as any).client_id);
        if (clientId > 0) {
          const stamped = `[OTHER ${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC] ${caseNote}`;
          await pool.query(
            `UPDATE clients
             SET admin_notes = TRIM(CONCAT(COALESCE(admin_notes, ''), '\n', ?))
             WHERE id = ?`,
            [stamped, clientId],
          );
          caseNoteAppended = true;
        }
      }

      return {
        ok: true,
        data: {
          ...enrichDeal(
            (upsertResult.data as Record<string, unknown>) || {},
          ),
          case_note_appended: caseNoteAppended,
        },
      };
    }

    if (name === "upsert_payment_splits") {
      const missing: string[] = [];
      if (
        !(args.client_id != null && Number(args.client_id) > 0) &&
        !(args.case_id != null && Number(args.case_id) > 0) &&
        !(typeof args.case_number === "string" && args.case_number.trim())
      ) {
        missing.push("client_id or case_id/case_number");
      }
      let parsed: Array<Record<string, unknown>> = [];
      try {
        const raw = String(args.splits_json || "").trim();
        if (!raw) missing.push("splits_json");
        else {
          const j = JSON.parse(raw);
          if (!Array.isArray(j) || j.length === 0) {
            missing.push("splits_json (non-empty array)");
          } else {
            parsed = j.slice(0, 20);
          }
        }
      } catch {
        return {
          ok: false,
          error: "invalid_args",
          message: "splits_json must be a JSON array",
        };
      }

      let clientId: number | null = null;
      let caseId: number | null = null;
      let caseNumber: string | null = null;
      if (missing.length === 0) {
        const resolved = await adminAiResolveClientId(args, scopedIds);
        if (resolved.ok === false) {
          return {
            ok: false,
            error: resolved.error,
            message: resolved.message,
          };
        }
        clientId = resolved.clientId;
        caseId = resolved.caseId;
        caseNumber = resolved.caseNumber;
        if (!caseId) {
          caseId = await resolveActiveCaseId(pool, clientId, null);
        }
        if (!caseId) {
          return {
            ok: false,
            error: "no_case",
            message:
              "Client has no active case — create/convert a case before adding payment splits",
          };
        }
        if (!caseNumber) {
          const [cr] = await pool.query<RowDataPacket[]>(
            `SELECT case_number FROM credit_repair_cases WHERE id = ? LIMIT 1`,
            [caseId],
          );
          caseNumber = cr[0]?.case_number ? String(cr[0].case_number) : null;
        }
      }

      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const normalized = parsed.map((s, i) => {
        const label = String(s.label || `Payment ${i + 1}`)
          .trim()
          .slice(0, 200);
        const amount = Number(s.amount_cents);
        const due = String(s.due_date || "")
          .trim()
          .slice(0, 10);
        let status = String(s.status || "").trim();
        const allowedSt = [
          "pending",
          "processing",
          "paid",
          "overdue",
          "cancelled",
        ];
        if (!allowedSt.includes(status)) {
          const dueD = new Date(`${due}T12:00:00`);
          status =
            !isNaN(dueD.getTime()) && dueD < today ? "overdue" : "pending";
        }
        return {
          label,
          amount_cents: amount,
          due_date: due,
          status,
          notes: s.notes != null ? String(s.notes).slice(0, 2000) : null,
          send_payment_link:
            s.send_payment_link === true ||
            s.send_payment_link === 1 ||
            s.send_payment_link === "true" ||
            (adminAiConfirmTrue(args.send_payment_link) &&
              s.send_payment_link !== false),
          valid:
            !!label &&
            Number.isFinite(amount) &&
            amount > 0 &&
            /^\d{4}-\d{2}-\d{2}$/.test(due),
        };
      });
      if (normalized.some((s) => !s.valid)) {
        missing.push(
          "each split needs label, amount_cents>0, due_date YYYY-MM-DD",
        );
      }

      const replaceOpen = adminAiConfirmTrue(args.replace_open);
      let openSplitCount = 0;
      const plan: Array<{
        label: string;
        amount_cents: number;
        due_date: string;
        status: string;
        action: "create" | "update_open_to_paid" | "skip_already_paid" | "skip_open_exists";
        match_split_id?: number;
      }> = [];
      if (caseId && missing.length === 0) {
        const [[openRow]] = await pool.query<RowDataPacket[]>(
          `SELECT COUNT(*) AS n FROM payment_splits
           WHERE case_id = ? AND status IN ('pending','overdue','processing')`,
          [caseId],
        );
        openSplitCount = Number(openRow?.n || 0);

        for (const s of normalized) {
          if (!s.valid) continue;
          if (s.status === "paid") {
            const openMatch = await findMatchingPaymentSplit({
              caseId,
              dueDate: s.due_date,
              amountCents: s.amount_cents,
              statuses: ["pending", "overdue", "processing"],
            });
            if (openMatch) {
              plan.push({
                label: s.label,
                amount_cents: s.amount_cents,
                due_date: s.due_date,
                status: s.status,
                action: "update_open_to_paid",
                match_split_id: Number(openMatch.id),
              });
              continue;
            }
            const paidMatch = await findMatchingPaymentSplit({
              caseId,
              dueDate: s.due_date,
              amountCents: s.amount_cents,
              statuses: ["paid"],
            });
            if (paidMatch) {
              plan.push({
                label: s.label,
                amount_cents: s.amount_cents,
                due_date: s.due_date,
                status: s.status,
                action: "skip_already_paid",
                match_split_id: Number(paidMatch.id),
              });
              continue;
            }
            plan.push({
              label: s.label,
              amount_cents: s.amount_cents,
              due_date: s.due_date,
              status: s.status,
              action: "create",
            });
            continue;
          }
          if (
            (s.status === "pending" || s.status === "overdue") &&
            !replaceOpen
          ) {
            const paidMatch = await findMatchingPaymentSplit({
              caseId,
              dueDate: s.due_date,
              amountCents: s.amount_cents,
              statuses: ["paid"],
            });
            if (paidMatch) {
              plan.push({
                label: s.label,
                amount_cents: s.amount_cents,
                due_date: s.due_date,
                status: s.status,
                action: "skip_already_paid",
                match_split_id: Number(paidMatch.id),
              });
              continue;
            }
            const openMatch = await findMatchingPaymentSplit({
              caseId,
              dueDate: s.due_date,
              amountCents: s.amount_cents,
              statuses: ["pending", "overdue", "processing"],
            });
            if (openMatch) {
              plan.push({
                label: s.label,
                amount_cents: s.amount_cents,
                due_date: s.due_date,
                status: s.status,
                action: "skip_open_exists",
                match_split_id: Number(openMatch.id),
              });
              continue;
            }
          }
          plan.push({
            label: s.label,
            amount_cents: s.amount_cents,
            due_date: s.due_date,
            status: s.status,
            action: "create",
          });
        }
      }

      const preview = {
        client_id: clientId,
        case_id: caseId,
        case_number: caseNumber,
        splits: normalized,
        plan,
        replace_open: replaceOpen,
        existing_open_splits: openSplitCount,
        total_cents: normalized.reduce(
          (a, s) => a + (Number.isFinite(s.amount_cents) ? s.amount_cents : 0),
          0,
        ),
        warning:
          openSplitCount > 0 &&
          !replaceOpen &&
          plan.some((p) => p.action === "create" && p.status !== "paid")
            ? "Case already has open splits — new non-matching rows will still be created. Pass replace_open=true to cancel open splits first, or use update_payment_split to mark an existing installment paid."
            : plan.some((p) => p.action === "update_open_to_paid")
              ? "status=paid will UPDATE matching open installment(s) by due_date+amount (no pending twin)."
              : null,
      };
      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
          },
        };
      }
      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show installment plan. After approval, confirm=true + confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      if (replaceOpen && caseId) {
        await pool.query(
          `UPDATE payment_splits
           SET status = 'cancelled'
           WHERE case_id = ? AND status IN ('pending','overdue','processing')`,
          [caseId],
        );
      }

      const createdIds: number[] = [];
      const updatedIds: number[] = [];
      const skipped: Array<{
        action: string;
        match_split_id: number;
        label: string;
        due_date: string;
        amount_cents: number;
      }> = [];
      const paymentLinks: Array<{
        split_id: number;
        payment_link: string | null;
      }> = [];
      for (const s of normalized) {
        const markPaid = s.status === "paid";

        if (markPaid && caseId) {
          const openMatch = await findMatchingPaymentSplit({
            caseId,
            dueDate: s.due_date,
            amountCents: s.amount_cents,
            statuses: ["pending", "overdue", "processing"],
          });
          if (openMatch) {
            const matchId = Number(openMatch.id);
            await pool.query(
              `UPDATE payment_splits
               SET status = 'paid',
                   completion_source = 'manual',
                   paid_at = COALESCE(paid_at, NOW()),
                   label = COALESCE(NULLIF(?, ''), label),
                   notes = CASE
                     WHEN ? IS NULL OR ? = '' THEN notes
                     WHEN notes IS NULL OR notes = '' THEN ?
                     ELSE CONCAT(notes, ' | ', ?)
                   END,
                   updated_at = NOW()
               WHERE id = ? AND status IN ('pending','overdue','processing')`,
              [
                s.label,
                s.notes,
                s.notes,
                s.notes,
                s.notes,
                matchId,
              ],
            );
            if (!openMatch.payments_id) {
              await adminAiRecordManualSplitPayment({
                splitId: matchId,
                clientId: clientId!,
                caseId,
                amountCents: s.amount_cents,
                label: s.label,
                paymentMethod:
                  typeof args.payment_method === "string"
                    ? args.payment_method
                    : null,
              });
            }
            updatedIds.push(matchId);
            paymentLinks.push({ split_id: matchId, payment_link: null });
            continue;
          }
          const paidMatch = await findMatchingPaymentSplit({
            caseId,
            dueDate: s.due_date,
            amountCents: s.amount_cents,
            statuses: ["paid"],
          });
          if (paidMatch) {
            skipped.push({
              action: "skip_already_paid",
              match_split_id: Number(paidMatch.id),
              label: s.label,
              due_date: s.due_date,
              amount_cents: s.amount_cents,
            });
            continue;
          }
        } else if (
          caseId &&
          (s.status === "pending" || s.status === "overdue") &&
          !replaceOpen
        ) {
          const paidMatch = await findMatchingPaymentSplit({
            caseId,
            dueDate: s.due_date,
            amountCents: s.amount_cents,
            statuses: ["paid"],
          });
          if (paidMatch) {
            skipped.push({
              action: "skip_already_paid",
              match_split_id: Number(paidMatch.id),
              label: s.label,
              due_date: s.due_date,
              amount_cents: s.amount_cents,
            });
            continue;
          }
          const openMatch = await findMatchingPaymentSplit({
            caseId,
            dueDate: s.due_date,
            amountCents: s.amount_cents,
            statuses: ["pending", "overdue", "processing"],
          });
          if (openMatch) {
            skipped.push({
              action: "skip_open_exists",
              match_split_id: Number(openMatch.id),
              label: s.label,
              due_date: s.due_date,
              amount_cents: s.amount_cents,
            });
            continue;
          }
        }

        const wantLink = !markPaid && !!s.send_payment_link;
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO payment_splits
             (case_id, client_id, label, amount_cents, due_date,
              status, completion_source, paid_at, send_payment_link, notes, created_by_admin_id)
           VALUES (?, ?, ?, ?, ?, ?, ?, ${markPaid ? "NOW()" : "NULL"}, ?, ?, ?)`,
          [
            caseId,
            clientId,
            s.label,
            s.amount_cents,
            s.due_date,
            s.status,
            markPaid ? "manual" : null,
            wantLink ? 1 : 0,
            s.notes,
            ctx.adminId,
          ],
        );
        const newId = Number(ins.insertId);
        createdIds.push(newId);
        let paymentLink: string | null = null;
        if (wantLink) {
          const tokenStr = crypto.randomUUID();
          const expiresAt = new Date(`${s.due_date}T12:00:00`);
          if (!isNaN(expiresAt.getTime())) {
            expiresAt.setDate(expiresAt.getDate() + 7);
          } else {
            expiresAt.setTime(Date.now() + 7 * 24 * 60 * 60 * 1000);
          }
          await pool.query(
            `INSERT INTO payment_split_tokens (split_id, token, expires_at) VALUES (?, ?, ?)`,
            [newId, tokenStr, expiresAt],
          );
          paymentLink = `${APP_URL}/pay/${tokenStr}`;
        }
        paymentLinks.push({ split_id: newId, payment_link: paymentLink });
        if (markPaid) {
          await adminAiRecordManualSplitPayment({
            splitId: newId,
            clientId: clientId!,
            caseId: caseId!,
            amountCents: s.amount_cents,
            label: s.label,
            paymentMethod:
              typeof args.payment_method === "string"
                ? args.payment_method
                : null,
          });
        }
      }
      return {
        ok: true,
        data: {
          created: createdIds.length > 0 || updatedIds.length > 0,
          split_ids: createdIds,
          updated_split_ids: updatedIds,
          skipped,
          payment_links: paymentLinks,
          count: createdIds.length + updatedIds.length,
          client_id: clientId,
          case_id: caseId,
          href: `/admin/pipeline?case=${caseId}`,
        },
      };
    }

    if (name === "update_payment_split") {
      const splitId =
        args.split_id != null && Number(args.split_id) > 0
          ? Number(args.split_id)
          : null;
      if (!splitId) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: ["split_id"],
          },
        };
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT ps.*, cr.case_number, c.first_name, c.last_name
         FROM payment_splits ps
         JOIN credit_repair_cases cr ON cr.id = ps.case_id
         JOIN clients c ON c.id = ps.client_id
         WHERE ps.id = ? LIMIT 1`,
        [splitId],
      );
      if (!rows[0]) {
        return { ok: false, error: "not_found", message: "Split not found" };
      }
      const cur = rows[0];
      const statusRaw = args.status != null ? String(args.status).trim() : null;
      const allowedSt = [
        "pending",
        "processing",
        "paid",
        "overdue",
        "cancelled",
      ];
      if (statusRaw && !allowedSt.includes(statusRaw)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "invalid status",
        };
      }
      const amount =
        args.amount_cents != null ? Number(args.amount_cents) : null;
      const due =
        args.due_date != null
          ? String(args.due_date).trim().slice(0, 10)
          : null;
      const notes =
        args.notes !== undefined
          ? decodeLiteralUnicodeEscapes(String(args.notes || "")).slice(0, 2000)
          : undefined;
      const preview = {
        split_id: splitId,
        client_id: cur.client_id,
        client_name: `${cur.first_name || ""} ${cur.last_name || ""}`.trim(),
        case_number: cur.case_number,
        current: {
          status: cur.status,
          amount_cents: cur.amount_cents,
          due_date: cur.due_date,
        },
        patch: {
          status: statusRaw,
          amount_cents: amount,
          due_date: due,
          notes: notes ?? null,
        },
      };
      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show split update. After approval, confirm=true + confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }
      // Don't leave orphan succeeded payments rows when leaving paid
      if (statusRaw && statusRaw !== "paid" && String(cur.status) === "paid") {
        return {
          ok: false,
          error: "cannot_unpay",
          message:
            "Cannot move a paid split back to unpaid via MCP (payments ledger already recorded). Create a correcting note or adjust in Admin → Payments.",
        };
      }
      const updates: string[] = [];
      const params: any[] = [];
      if (statusRaw) {
        updates.push("status = ?");
        params.push(statusRaw);
        if (statusRaw === "paid") {
          updates.push("paid_at = COALESCE(paid_at, NOW())");
          updates.push(
            "completion_source = COALESCE(completion_source, 'manual')",
          );
        }
      }
      if (amount != null && Number.isFinite(amount) && amount > 0) {
        updates.push("amount_cents = ?");
        params.push(amount);
      }
      if (due && /^\d{4}-\d{2}-\d{2}$/.test(due)) {
        updates.push("due_date = ?");
        params.push(due);
      }
      if (notes !== undefined) {
        updates.push("notes = ?");
        params.push(notes || null);
      }
      if (updates.length === 0) {
        return {
          ok: false,
          error: "invalid_args",
          message: "No fields to update",
        };
      }
      params.push(splitId);
      await pool.query(
        `UPDATE payment_splits SET ${updates.join(", ")} WHERE id = ?`,
        params,
      );

      let paymentId: number | null = cur.payments_id
        ? Number(cur.payments_id)
        : null;
      const transitioningToPaid =
        statusRaw === "paid" &&
        String(cur.status) !== "paid" &&
        !cur.payments_id;
      if (transitioningToPaid) {
        const finalAmount = Number(
          amount != null && Number.isFinite(amount) && amount > 0
            ? amount
            : cur.amount_cents,
        );
        paymentId = await adminAiRecordManualSplitPayment({
          splitId,
          clientId: Number(cur.client_id),
          caseId: Number(cur.case_id),
          amountCents: finalAmount,
          currency: cur.currency ? String(cur.currency) : "USD",
          label: cur.label ? String(cur.label) : null,
          paymentMethod:
            typeof args.payment_method === "string"
              ? args.payment_method
              : null,
        });
      }

      return {
        ok: true,
        data: {
          updated: true,
          split_id: splitId,
          payments_id: paymentId,
          href: `/admin/pipeline?case=${cur.case_id}`,
        },
      };
    }

    if (name === "list_coupons") {
      const activeOnly =
        args.active_only === undefined || args.active_only === null
          ? true
          : adminAiConfirmTrue(args.active_only);
      const q = String(args.q || "")
        .trim()
        .slice(0, 80);
      const limit = Math.min(
        50,
        Math.max(1, Number(args.limit) || 20),
      );
      const where: string[] = [];
      const params: unknown[] = [];
      if (activeOnly) where.push("c.is_active = 1");
      if (q) {
        where.push("(c.code LIKE ? ESCAPE '!' OR c.description LIKE ? ESCAPE '!')");
        const like = likeContains(q);
        params.push(like, like);
      }
      const whereSql = where.length ? `WHERE ${where.join(" AND ")}` : "";
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT c.id, c.code, c.description, c.discount_type, c.discount_value,
                c.min_amount_cents, c.max_uses, c.uses_count, c.applicable_packages,
                c.valid_from, c.expires_at, c.is_active, c.created_at,
                CONCAT(a.first_name,' ',a.last_name) AS created_by_name
         FROM coupons c
         LEFT JOIN admins a ON a.id = c.created_by_admin_id
         ${whereSql}
         ORDER BY c.created_at DESC
         LIMIT ${limit}`,
        params,
      );
      return {
        ok: true,
        data: {
          coupons: rows.map((r) => ({
            id: Number(r.id),
            code: String(r.code),
            description: r.description != null ? String(r.description) : null,
            discount_type: String(r.discount_type),
            discount_value: Number(r.discount_value),
            min_amount_cents: Number(r.min_amount_cents || 0),
            max_uses: r.max_uses != null ? Number(r.max_uses) : null,
            uses_count: Number(r.uses_count || 0),
            applicable_packages: r.applicable_packages ?? null,
            valid_from: r.valid_from
              ? new Date(r.valid_from).toISOString()
              : null,
            expires_at: r.expires_at
              ? new Date(r.expires_at).toISOString()
              : null,
            is_active: Number(r.is_active) === 1,
            created_by_name: r.created_by_name
              ? String(r.created_by_name).trim()
              : null,
            created_at: r.created_at
              ? new Date(r.created_at).toISOString()
              : null,
            href: "/admin/payments",
          })),
          count: rows.length,
          note: "Checkout promo codes for /register. Manage in Admin → Payments → Coupons. Offline Zelle deals → set_case_payment_plan.",
        },
      };
    }

    if (name === "create_coupon") {
      const missing: string[] = [];
      const rawCode = String(args.code || "").trim();
      // Match coupons.code VARCHAR(50) + REST sanitize
      const upperCode = rawCode
        .toUpperCase()
        .replace(/[^A-Z0-9_-]/g, "")
        .slice(0, 50);
      if (!upperCode) missing.push("code");
      const discountType = String(args.discount_type || "").trim();
      if (!["percentage", "fixed"].includes(discountType)) {
        missing.push("discount_type (percentage|fixed)");
      }
      const discountValue = Number(args.discount_value);
      if (!(Number.isFinite(discountValue) && discountValue > 0)) {
        missing.push("discount_value (>0)");
      } else if (!Number.isInteger(discountValue)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "discount_value must be a whole number (percent or cents)",
        };
      } else if (discountType === "percentage" && discountValue > 100) {
        return {
          ok: false,
          error: "invalid_args",
          message: "Percentage discount cannot exceed 100",
        };
      }

      let applicablePackages: number[] | null = null;
      if (
        args.applicable_package_ids != null &&
        String(args.applicable_package_ids).trim()
      ) {
        try {
          const parsed =
            typeof args.applicable_package_ids === "string"
              ? JSON.parse(String(args.applicable_package_ids))
              : args.applicable_package_ids;
          if (!Array.isArray(parsed)) {
            return {
              ok: false,
              error: "invalid_args",
              message: "applicable_package_ids must be a JSON array of package IDs",
            };
          }
          applicablePackages = parsed
            .map((n) => Number(n))
            .filter((n) => Number.isFinite(n) && n > 0);
          if (!applicablePackages.length) applicablePackages = null;
        } catch {
          return {
            ok: false,
            error: "invalid_args",
            message: "applicable_package_ids must be a JSON array of package IDs",
          };
        }
      }

      const description =
        args.description != null
          ? String(args.description).trim().slice(0, 255)
          : null;
      const minAmount = Number(args.min_amount_cents) || 0;
      if (minAmount < 0 || !Number.isFinite(minAmount)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "min_amount_cents must be >= 0",
        };
      }
      const maxUses =
        args.max_uses != null && args.max_uses !== ""
          ? Number(args.max_uses)
          : null;
      if (maxUses != null && !(Number.isFinite(maxUses) && maxUses > 0)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "max_uses must be a positive integer or omitted",
        };
      }
      const parseCouponDt = (
        raw: unknown,
        field: string,
      ): { ok: true; value: string | null } | { ok: false; message: string } => {
        if (raw == null || !String(raw).trim()) return { ok: true, value: null };
        const s = String(raw).trim();
        const t = Date.parse(s);
        if (!Number.isFinite(t)) {
          return {
            ok: false,
            message: `${field} must be a valid ISO datetime`,
          };
        }
        return { ok: true, value: s };
      };
      const validFromParsed = parseCouponDt(args.valid_from, "valid_from");
      if (validFromParsed.ok === false) {
        return {
          ok: false,
          error: "invalid_args",
          message: validFromParsed.message,
        };
      }
      const expiresAtParsed = parseCouponDt(args.expires_at, "expires_at");
      if (expiresAtParsed.ok === false) {
        return {
          ok: false,
          error: "invalid_args",
          message: expiresAtParsed.message,
        };
      }
      const validFrom = validFromParsed.value;
      const expiresAt = expiresAtParsed.value;
      if (validFrom && expiresAt && Date.parse(expiresAt) < Date.parse(validFrom)) {
        return {
          ok: false,
          error: "invalid_args",
          message: "expires_at must be on or after valid_from",
        };
      }
      const isActive =
        args.is_active === undefined || args.is_active === null
          ? true
          : adminAiConfirmTrue(args.is_active);

      let existingId: number | null = null;
      if (upperCode) {
        const [existing] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM coupons WHERE code = ? LIMIT 1`,
          [upperCode],
        );
        if (existing[0]) existingId = Number(existing[0].id);
      }

      const preview = {
        code: upperCode || null,
        description,
        discount_type: discountType || null,
        discount_value: Number.isFinite(discountValue) ? discountValue : null,
        min_amount_cents: minAmount,
        max_uses: maxUses,
        applicable_packages: applicablePackages,
        valid_from: validFrom,
        expires_at: expiresAt,
        is_active: isActive,
        already_exists: existingId != null,
        existing_coupon_id: existingId,
        applies_to: "Public /register checkout (not offline Zelle installment plans)",
        href: "/admin/payments",
        crm_hint: "Admin → Payments → Coupons tab",
      };

      if (missing.length > 0) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: false,
            missing_fields: missing,
            preview,
          },
        };
      }
      if (existingId != null) {
        return {
          ok: false,
          error: "duplicate_code",
          message: `Coupon code ${upperCode} already exists (id ${existingId}). Use list_coupons or Admin → Payments → Coupons.`,
          data: preview,
        };
      }
      if (!adminAiConfirmTrue(args.confirm)) {
        return {
          ok: true,
          data: {
            dry_run: true,
            ready: true,
            preview,
            required_confirm_phrase: ADMIN_AI_WRITE_CONFIRM_PHRASE,
            guidance: `Show the coupon. After approval, confirm=true + confirm_phrase="${ADMIN_AI_WRITE_CONFIRM_PHRASE}".`,
          },
        };
      }
      const writeGate = adminAiWriteConfirmed(args);
      if (writeGate.ok === false) {
        return {
          ok: false,
          error: "confirm_required",
          message: writeGate.message,
        };
      }

      let insertId = 0;
      try {
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO coupons
             (code, description, discount_type, discount_value, min_amount_cents, max_uses,
              applicable_packages, valid_from, expires_at, is_active, created_by_admin_id)
           VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
          [
            upperCode,
            description || null,
            discountType,
            discountValue,
            minAmount,
            maxUses,
            applicablePackages ? JSON.stringify(applicablePackages) : null,
            validFrom,
            expiresAt,
            isActive ? 1 : 0,
            ctx.adminId,
          ],
        );
        insertId = Number(ins.insertId);
      } catch (err: unknown) {
        if (isDuplicateKeyError(err)) {
          const [again] = await pool.query<RowDataPacket[]>(
            `SELECT id FROM coupons WHERE code = ? LIMIT 1`,
            [upperCode],
          );
          const raceId = again[0] ? Number(again[0].id) : null;
          return {
            ok: false,
            error: "duplicate_code",
            message: raceId
              ? `Coupon code ${upperCode} already exists (id ${raceId}). Use list_coupons or Admin → Payments → Coupons.`
              : `Coupon code ${upperCode} already exists.`,
            data: { ...preview, already_exists: true, existing_coupon_id: raceId },
          };
        }
        throw err;
      }
      const [created] = await pool.query<RowDataPacket[]>(
        `SELECT c.*, CONCAT(a.first_name,' ',a.last_name) AS created_by_name
         FROM coupons c LEFT JOIN admins a ON a.id = c.created_by_admin_id
         WHERE c.id = ? LIMIT 1`,
        [insertId],
      );
      return {
        ok: true,
        data: {
          created: true,
          coupon: {
            id: Number(created[0].id),
            code: String(created[0].code),
            description: created[0].description,
            discount_type: String(created[0].discount_type),
            discount_value: Number(created[0].discount_value),
            min_amount_cents: Number(created[0].min_amount_cents || 0),
            max_uses:
              created[0].max_uses != null ? Number(created[0].max_uses) : null,
            uses_count: Number(created[0].uses_count || 0),
            is_active: Number(created[0].is_active) === 1,
            created_by_name: created[0].created_by_name
              ? String(created[0].created_by_name).trim()
              : null,
          },
          href: "/admin/payments",
          crm_hint: "Admin → Payments → Coupons tab",
          note: "Client enters this code at /register checkout. For an enrolled client's Zelle deal, use set_case_payment_plan instead.",
        },
      };
    }

    return {
      ok: false,
      error: "unknown_tool",
      message: `Unknown tool: ${name}`,
    };
  } catch (err: any) {
    console.error("[admin-ai] tool failed", name, err);
    return {
      ok: false,
      error: "tool_error",
      message: "Tool execution failed",
    };
  }
}

type AdminAiAuditStatus = "success" | "failure" | "rate_limited" | "disabled";

