function mockPaymentsAllowed(): boolean {
  if (authorizeNetConfigured) return false;
  if (process.env.NODE_ENV === "production") return false;
  if (process.env.AUTHORIZENET_SANDBOX === "false") return false;
  return true;
}

// ============================================================================
// AUTH HELPERS
// ============================================================================

type ActorType = "client" | "admin";
interface JwtPayload {
  actor: ActorType;
  id: number;
  email: string;
  jti: string;
}
interface AuthedRequest extends Request {
  auth?: JwtPayload;
}

// ============================================================================
// FILE ENCRYPTION HELPERS (AES-256-GCM)
// ============================================================================

function getDocEncKey(): Buffer {
  const hex = process.env.DOC_ENCRYPTION_KEY || "";
  const isValidHex = hex.length === 64 && /^[0-9a-fA-F]{64}$/.test(hex);
  if (!isValidHex) {
    if (IS_PROD) {
      throw new Error(
        "DOC_ENCRYPTION_KEY is not set or invalid — refusing to use an insecure fallback in production",
      );
    }
    console.warn(
      "⚠️  DOC_ENCRYPTION_KEY not set or invalid — using insecure fallback (local/dev only)",
    );
    return Buffer.alloc(32, 0);
  }
  return Buffer.from(hex, "hex");
}

function encryptFile(buf: Buffer): {
  encrypted: Buffer;
  iv: string;
  tag: string;
} {
  const key = getDocEncKey();
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv("aes-256-gcm", key, iv);
  const encrypted = Buffer.concat([cipher.update(buf), cipher.final()]);
  return {
    encrypted,
    iv: iv.toString("hex"),
    tag: cipher.getAuthTag().toString("hex"),
  };
}

function decryptFile(encrypted: Buffer, ivHex: string, tagHex: string): Buffer {
  const key = getDocEncKey();
  const decipher = crypto.createDecipheriv(
    "aes-256-gcm",
    key,
    Buffer.from(ivHex, "hex"),
  );
  decipher.setAuthTag(Buffer.from(tagHex, "hex"));
  return Buffer.concat([decipher.update(encrypted), decipher.final()]);
}

function encryptJsonSecrets(payload: Record<string, unknown>): {
  ciphertext: Buffer;
  iv: string;
  tag: string;
} {
  const { encrypted, iv, tag } = encryptFile(
    Buffer.from(JSON.stringify(payload), "utf8"),
  );
  return { ciphertext: encrypted, iv, tag };
}

function decryptJsonSecrets(
  ciphertext: Buffer,
  ivHex: string,
  tagHex: string,
): Record<string, unknown> {
  const raw = decryptFile(ciphertext, ivHex, tagHex).toString("utf8");
  try {
    return JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return {};
  }
}

const CLIENT_REFERRER_ROLES = ["primary", "secondary", "tertiary"] as const;
const MAX_CLIENT_REFERRERS = 3;

type ClientReferrerRoleName = (typeof CLIENT_REFERRER_ROLES)[number];

function roleForSortOrder(sortOrder: number): ClientReferrerRoleName {
  if (sortOrder <= 0) return "primary";
  if (sortOrder === 1) return "secondary";
  return "tertiary";
}

async function listClientReferrerLinks(
  clientId: number,
): Promise<RowDataPacket[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT cr.id, cr.client_id, cr.referrer_id, cr.role, cr.sort_order,
            cr.notify_on_round, cr.created_at,
            r.category, r.first_name, r.last_name, r.email, r.phone, r.company,
            r.affiliate_id, r.preferred_language, r.notes, r.status
     FROM client_referrers cr
     INNER JOIN referrers r ON r.id = cr.referrer_id
     WHERE cr.client_id = ?
     ORDER BY cr.sort_order ASC, cr.id ASC`,
    [clientId],
  );
  return rows;
}

function mapClientReferrerLinkRow(row: RowDataPacket) {
  return {
    id: Number(row.id),
    client_id: Number(row.client_id),
    referrer_id: Number(row.referrer_id),
    role: String(row.role) as ClientReferrerRoleName,
    sort_order: Number(row.sort_order),
    notify_on_round: Number(row.notify_on_round) === 1,
    created_at: row.created_at,
    referrer: {
      id: Number(row.referrer_id),
      category: row.category,
      first_name: row.first_name,
      last_name: row.last_name,
      email: row.email ?? null,
      phone: row.phone ?? null,
      company: row.company ?? null,
      affiliate_id: row.affiliate_id ?? null,
      preferred_language: row.preferred_language ?? "en",
      notes: row.notes ?? null,
      status: row.status,
    },
  };
}

/**
 * Replace client_referrers for a client (max 3). Mirrors primary into
 * clients.referrer_id for backward compatibility.
 */
async function replaceClientReferrers(
  clientId: number,
  links: Array<{
    referrer_id: number;
    notify_on_round?: boolean;
    role?: string;
  }>,
  conn?: Pool | import("mysql2/promise").PoolConnection,
): Promise<void> {
  const db = conn || pool;
  if (links.length > MAX_CLIENT_REFERRERS) {
    throw Object.assign(new Error("At most 3 referral partners allowed"), {
      status: 400,
      code: "too_many_referrers",
    });
  }
  const ids = links.map((l) => Number(l.referrer_id));
  if (ids.some((id) => !Number.isFinite(id) || id <= 0)) {
    throw Object.assign(new Error("Invalid referrer_id"), {
      status: 400,
      code: "invalid_referrer_id",
    });
  }
  if (new Set(ids).size !== ids.length) {
    throw Object.assign(new Error("Duplicate referrer_id"), {
      status: 400,
      code: "duplicate_referrer",
    });
  }
  if (ids.length) {
    const [found] = await db.query<RowDataPacket[]>(
      `SELECT id FROM referrers WHERE id IN (${ids.map(() => "?").join(",")}) AND status = 'active'`,
      ids,
    );
    if (found.length !== ids.length) {
      throw Object.assign(new Error("One or more referrers not found/active"), {
        status: 400,
        code: "referrer_not_found",
      });
    }
  }
  await db.query(`DELETE FROM client_referrers WHERE client_id = ?`, [
    clientId,
  ]);
  for (let i = 0; i < links.length; i++) {
    const link = links[i];
    const role = CLIENT_REFERRER_ROLES.includes(
      link.role as ClientReferrerRoleName,
    )
      ? (link.role as ClientReferrerRoleName)
      : roleForSortOrder(i);
    await db.query(
      `INSERT INTO client_referrers (client_id, referrer_id, role, sort_order, notify_on_round)
       VALUES (?,?,?,?,?)`,
      [
        clientId,
        link.referrer_id,
        role,
        i,
        1, // Always notify — no staff toggle (César Sep 2026)
      ],
    );
  }
  const primaryId = links[0]?.referrer_id ?? null;
  await db.query(`UPDATE clients SET referrer_id = ? WHERE id = ?`, [
    primaryId,
    clientId,
  ]);
}

/** Validate partner name/phone/email when intake is marked referred. */
function validateReferredPartnerRequirements(
  referralCategory: string | null | undefined,
  partners: Array<{
    first_name?: string | null;
    last_name?: string | null;
    email?: string | null;
    phone?: string | null;
  }>,
): string | null {
  if (!referralCategory) return null;
  if (!partners.length) {
    return "At least one referral partner is required when referral category is set";
  }
  for (const p of partners) {
    if (
      !String(p.first_name || "").trim() ||
      !String(p.last_name || "").trim()
    ) {
      return "Each referral partner needs first_name and last_name";
    }
    if (!String(p.email || "").trim() || !String(p.email || "").includes("@")) {
      return "Each referral partner needs a valid email";
    }
    if (!String(p.phone || "").trim()) {
      return "Each referral partner needs a phone number";
    }
  }
  return null;
}

type CmsVaultPayload = {
  smart_credit?: { email?: string | null; password?: string | null };
  myfreescorenow?: { email?: string | null; password?: string | null };
};

function readClientCmsVault(row: RowDataPacket): CmsVaultPayload {
  if (
    !row.cms_secrets_ciphertext ||
    !row.cms_secrets_iv ||
    !row.cms_secrets_tag
  ) {
    return {};
  }
  try {
    const buf = Buffer.isBuffer(row.cms_secrets_ciphertext)
      ? row.cms_secrets_ciphertext
      : Buffer.from(row.cms_secrets_ciphertext);
    return decryptJsonSecrets(
      buf,
      String(row.cms_secrets_iv),
      String(row.cms_secrets_tag),
    ) as CmsVaultPayload;
  } catch {
    return {};
  }
}

async function upsertClientCmsCredentials(
  clientId: number,
  input: CmsVaultPayload,
): Promise<void> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT smart_credit_email, myfreescorenow_email,
            cms_secrets_ciphertext, cms_secrets_iv, cms_secrets_tag
     FROM clients WHERE id = ? LIMIT 1`,
    [clientId],
  );
  const row = rows[0];
  if (!row) throw Object.assign(new Error("Client not found"), { status: 404 });

  const existing = readClientCmsVault(row);
  const next: CmsVaultPayload = {
    smart_credit: {
      email:
        input.smart_credit?.email !== undefined
          ? input.smart_credit.email
          : (existing.smart_credit?.email ?? row.smart_credit_email ?? null),
      password:
        input.smart_credit?.password !== undefined
          ? input.smart_credit.password
          : (existing.smart_credit?.password ?? null),
    },
    myfreescorenow: {
      email:
        input.myfreescorenow?.email !== undefined
          ? input.myfreescorenow.email
          : (existing.myfreescorenow?.email ??
            row.myfreescorenow_email ??
            null),
      password:
        input.myfreescorenow?.password !== undefined
          ? input.myfreescorenow.password
          : (existing.myfreescorenow?.password ?? null),
    },
  };

  const scEmail =
    String(next.smart_credit?.email || "")
      .trim()
      .toLowerCase() || null;
  const mfsnEmail =
    String(next.myfreescorenow?.email || "")
      .trim()
      .toLowerCase() || null;

  const hasAnySecret =
    !!String(next.smart_credit?.password || "") ||
    !!String(next.myfreescorenow?.password || "");

  let ciphertext: Buffer | null = null;
  let iv: string | null = null;
  let tag: string | null = null;
  if (hasAnySecret || scEmail || mfsnEmail) {
    const enc = encryptJsonSecrets(next as Record<string, unknown>);
    ciphertext = enc.ciphertext;
    iv = enc.iv;
    tag = enc.tag;
  }

  await pool.query(
    `UPDATE clients SET
       smart_credit_email = ?,
       myfreescorenow_email = ?,
       cms_secrets_ciphertext = ?,
       cms_secrets_iv = ?,
       cms_secrets_tag = ?,
       smart_credit_connected_at = CASE
         WHEN ? IS NOT NULL AND smart_credit_connected_at IS NULL THEN NOW()
         ELSE smart_credit_connected_at
       END
     WHERE id = ?`,
    [scEmail, mfsnEmail, ciphertext, iv, tag, scEmail, clientId],
  );
}

/** HostGator/DisruptingLabs shared hosting — transient network/SSL/5xx blips. */
const CDN_UPLOAD_TIMEOUT_MS = Math.max(
  3_000,
  Number(process.env.CDN_UPLOAD_TIMEOUT_MS || 15_000) || 15_000,
);
const CDN_UPLOAD_MAX_ATTEMPTS = Math.max(
  1,
  Math.min(5, Number(process.env.CDN_UPLOAD_MAX_ATTEMPTS || 3) || 3),
);

function isTransientCdnFailure(err: unknown, status?: number): boolean {
  if (
    status === 408 ||
    status === 429 ||
    status === 500 ||
    status === 502 ||
    status === 503 ||
    status === 504
  ) {
    return true;
  }
  const msg = String(
    (err as { message?: string })?.message ?? err ?? "",
  ).toLowerCase();
  return (
    msg.includes("fetch failed") ||
    msg.includes("network") ||
    msg.includes("timeout") ||
    msg.includes("timed out") ||
    msg.includes("aborted") ||
    msg.includes("econnreset") ||
    msg.includes("etimedout") ||
    msg.includes("econnrefused") ||
    msg.includes("socket") ||
    msg.includes("tls") ||
    msg.includes("cert")
  );
}

function sleepMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Upload a file buffer to the Disrupting Labs CDN and return the full public URL.
 * The URL is stored as storage_key in the DB and is never sent directly to the browser —
 * all access is proxied through the authenticated Express file-serve endpoints.
 *
 * External dependency: HostGator-hosted disruptinglabs.com (historically flaky SSL /
 * AutoSSL). Production uses timeout + retries; VITEST never calls the live host so CI
 * does not fail on outside CDN blips.
 */
async function uploadToCDN(
  buffer: Buffer,
  originalname: string,
  mimetype: string,
  clientId: number | string,
): Promise<string> {
  if (!CDN_UPLOAD_SECRET)
    throw new Error("CDN_UPLOAD_SECRET is not configured");
  // Opaque folder id: a bare `client-123` folder on the CDN is guessable —
  // anyone iterating IDs could probe for other clients' folders (the CDN
  // itself has no per-tenant auth; our API is the only access control, and
  // that's bypassed once you know/guess the folder path). Appending a random
  // suffix makes the folder unguessable while the real clientId still lives
  // only in our DB metadata / storage_key, never in a URL pattern an
  // attacker could iterate.
  const folderId = `c-${clientId}-${crypto.randomUUID().slice(0, 8)}`;

  // CI/integration: never depend on HostGator reachability (same pattern as Twilio dry-run).
  if (process.env.VITEST === "true") {
    const url = `vitest://cdn/${CDN_MAIN_FOLDER}/${folderId}/${encodeURIComponent(originalname)}`;
    vitestCdnPlaintextByUrl.set(url, Buffer.from(buffer));
    return url;
  }

  let lastErr: Error | null = null;
  for (let attempt = 1; attempt <= CDN_UPLOAD_MAX_ATTEMPTS; attempt++) {
    const formData = new FormData();
    formData.append("main_folder", CDN_MAIN_FOLDER);
    formData.append("id", folderId);
    formData.append(
      "files[]",
      new Blob([new Uint8Array(buffer)], { type: mimetype }),
      originalname,
    );
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), CDN_UPLOAD_TIMEOUT_MS);
    try {
      const res = await fetch(CDN_UPLOAD_URL, {
        method: "POST",
        headers: { "X-Api-Key": CDN_UPLOAD_SECRET },
        body: formData,
        signal: controller.signal,
      });
      if (!res.ok) {
        const bodySnippet = (await res.text().catch(() => "")).slice(0, 200);
        const err = new Error(
          `CDN upload failed: ${res.status}${bodySnippet ? ` — ${bodySnippet}` : ""}`,
        );
        lastErr = err;
        if (
          attempt < CDN_UPLOAD_MAX_ATTEMPTS &&
          isTransientCdnFailure(err, res.status)
        ) {
          console.warn(
            `[cdn:upload] attempt ${attempt}/${CDN_UPLOAD_MAX_ATTEMPTS} HTTP ${res.status}; retrying`,
          );
          await sleepMs(250 * attempt);
          continue;
        }
        throw err;
      }
      const data = (await res.json()) as {
        uploaded?: Array<{ url?: string }>;
        error?: string;
        errors?: Array<{ error?: string }>;
      };
      const uploaded = data?.uploaded?.[0];
      if (!uploaded?.url) {
        throw new Error(
          "CDN upload returned no URL: " +
            (data?.error ??
              data?.errors?.[0]?.error ??
              "unknown"),
        );
      }
      if (attempt > 1) {
        console.warn(
          `[cdn:upload] succeeded on attempt ${attempt}/${CDN_UPLOAD_MAX_ATTEMPTS}`,
        );
      }
      return uploaded.url as string;
    } catch (e: unknown) {
      const raw = e instanceof Error ? e : new Error(String(e));
      const err =
        raw.name === "AbortError"
          ? new Error(
              `CDN upload timed out after ${CDN_UPLOAD_TIMEOUT_MS}ms`,
            )
          : raw;
      lastErr = err;
      // Non-retryable API shape errors (unsupported type, missing URL) stop immediately.
      const msg = err.message || "";
      if (
        msg.includes("CDN upload returned no URL") &&
        !isTransientCdnFailure(err)
      ) {
        throw err;
      }
      if (
        attempt < CDN_UPLOAD_MAX_ATTEMPTS &&
        isTransientCdnFailure(err)
      ) {
        console.warn(
          `[cdn:upload] attempt ${attempt}/${CDN_UPLOAD_MAX_ATTEMPTS} failed: ${err.message}; retrying`,
        );
        await sleepMs(250 * attempt);
        continue;
      }
      throw err;
    } finally {
      clearTimeout(timer);
    }
  }
  throw lastErr ?? new Error("CDN upload failed");
}

/** Best-effort CDN cleanup when DB writes fail after upload (requires CDN_DELETE_URL). */
async function deleteFromCDN(storageUrl: string): Promise<void> {
  const deleteUrl = process.env.CDN_DELETE_URL;
  if (!deleteUrl || !CDN_UPLOAD_SECRET || !storageUrl) return;
  const res = await fetch(deleteUrl, {
    method: "POST",
    headers: {
      "X-Api-Key": CDN_UPLOAD_SECRET,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ url: storageUrl }),
  });
  if (!res.ok) {
    console.warn(
      `[cdn:delete] Failed (${res.status}) for ${storageUrl.slice(0, 80)}…`,
    );
  }
}

// ============================================================================
// ONBOARDING TOKEN HELPERS (magic link after payment)
// ============================================================================

async function createOnboardingToken(
  clientId: number,
  ttlHours: number = ONBOARDING_TOKEN_TTL_HOURS,
): Promise<string> {
  const rawToken = crypto.randomBytes(32).toString("hex");
  const tokenHash = sha256(rawToken);
  const expiresAt = new Date(Date.now() + ttlHours * 60 * 60 * 1000);
  await pool.query<ResultSetHeader>(
    `INSERT INTO onboarding_tokens (client_id, token_hash, expires_at) VALUES (?, ?, ?)`,
    [clientId, tokenHash, expiresAt],
  );
  return rawToken;
}

async function consumeOnboardingToken(
  rawToken: string,
): Promise<number | null> {
  const tokenHash = sha256(rawToken);
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, client_id FROM onboarding_tokens
     WHERE token_hash = ? AND consumed_at IS NULL AND expires_at > NOW()
     LIMIT 1`,
    [tokenHash],
  );
  if (rows.length === 0) return null;
  await pool.query<ResultSetHeader>(
    `UPDATE onboarding_tokens SET consumed_at = NOW() WHERE id = ?`,
    [rows[0].id],
  );
  return rows[0].client_id as number;
}

/** Short-lived Round PDF download token (multi-use until expiry for email + SMS). */
const ROUND_PDF_DOWNLOAD_TTL_HOURS = 72;

async function createRoundReportDownloadToken(
  pdfId: number,
  clientId: number,
  ttlHours: number = ROUND_PDF_DOWNLOAD_TTL_HOURS,
): Promise<string> {
  const rawToken = crypto.randomBytes(32).toString("hex");
  const tokenHash = sha256(rawToken);
  const expiresAt = new Date(Date.now() + ttlHours * 60 * 60 * 1000);
  await pool.query<ResultSetHeader>(
    `INSERT INTO round_report_download_tokens
       (token_hash, pdf_id, client_id, expires_at)
     VALUES (?, ?, ?, ?)`,
    [tokenHash, pdfId, clientId, expiresAt],
  );
  return rawToken;
}

/** Latest branded Round PDF row for a client report (wizard publish path). */
async function findRoundReportPdfRow(opts: {
  clientId: number;
  pdfId?: number | null;
  roundReportId?: number | null;
  roundNumber?: number | null;
}): Promise<RowDataPacket | null> {
  if (opts.pdfId != null && Number(opts.pdfId) > 0) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, client_id, round_number, round_report_id, file_name,
              storage_key, storage_provider, encrypted, enc_iv, enc_tag
       FROM round_report_pdfs WHERE id = ? LIMIT 1`,
      [Number(opts.pdfId)],
    );
    const row = rows[0] || null;
    if (!row || Number(row.client_id) !== opts.clientId) return null;
    return row;
  }
  if (opts.roundReportId != null && Number(opts.roundReportId) > 0) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, client_id, round_number, round_report_id, file_name,
              storage_key, storage_provider, encrypted, enc_iv, enc_tag
       FROM round_report_pdfs
       WHERE client_id = ? AND round_report_id = ?
       ORDER BY id DESC LIMIT 1`,
      [opts.clientId, Number(opts.roundReportId)],
    );
    if (rows[0]) return rows[0];
  }
  if (opts.roundNumber != null && Number(opts.roundNumber) > 0) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, client_id, round_number, round_report_id, file_name,
              storage_key, storage_provider, encrypted, enc_iv, enc_tag
       FROM round_report_pdfs
       WHERE client_id = ? AND round_number = ?
       ORDER BY id DESC LIMIT 1`,
      [opts.clientId, Number(opts.roundNumber)],
    );
    if (rows[0]) return rows[0];
  }
  return null;
}

/** Load branded Round PDF bytes from `round_report_pdfs` (CDN / local / vitest stub). */
async function loadRoundReportPdfBytes(
  pdfRow: RowDataPacket,
): Promise<Buffer | null> {
  if (!pdfRow?.storage_key) return null;
  try {
    let raw: Buffer;
    if (String(pdfRow.storage_provider) === "cdn") {
      const cdnRes = await fetch(String(pdfRow.storage_key));
      if (!cdnRes.ok) return null;
      raw = Buffer.from(await cdnRes.arrayBuffer());
    } else if (String(pdfRow.storage_key).startsWith("vitest://")) {
      raw = Buffer.from("%PDF-1.4 vitest-round-report");
    } else {
      raw = await fs.promises.readFile(
        path.join(UPLOADS_DIR, String(pdfRow.storage_key)),
      );
    }
    if (raw.length === 0) return null;
    if (pdfRow.encrypted && pdfRow.enc_iv && pdfRow.enc_tag) {
      return decryptFile(
        raw,
        String(pdfRow.enc_iv),
        String(pdfRow.enc_tag),
      );
    }
    return raw;
  } catch {
    return null;
  }
}

async function loadRoundReportPdfByDownloadToken(
  rawToken: string,
): Promise<RowDataPacket | null> {
  const tokenHash = sha256(rawToken);
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT t.id AS token_id, p.file_name, p.storage_key, p.storage_provider,
            p.encrypted, p.enc_iv, p.enc_tag, p.client_id, p.id AS pdf_id
     FROM round_report_download_tokens t
     INNER JOIN round_report_pdfs p ON p.id = t.pdf_id AND p.client_id = t.client_id
     WHERE t.token_hash = ? AND t.expires_at > NOW()
     LIMIT 1`,
    [tokenHash],
  );
  if (!rows[0]) return null;
  await pool.query<ResultSetHeader>(
    `UPDATE round_report_download_tokens
     SET last_used_at = NOW(), use_count = use_count + 1
     WHERE id = ?`,
    [Number(rows[0].token_id)],
  );
  return rows[0];
}

/** Allowlisted portal paths for onboarding magic-link ?next= redirects. */
function sanitizePortalNextPath(raw: unknown): string | null {
  const s = String(raw || "").trim();
  if (!s.startsWith("/portal/")) return null;
  if (s.includes("://") || s.includes("//") || s.includes("..")) return null;
  const allowed = [
    "/portal/reports",
    "/portal/documents",
    "/portal/dashboard",
    "/portal/home",
  ];
  const pathOnly = s.split("?")[0].split("#")[0];
  if (!allowed.includes(pathOnly)) return null;
  return s.length > 200 ? pathOnly : s;
}

function sha256(input: string): string {
  return crypto.createHash("sha256").update(input).digest("hex");
}

// ============================================================================
// PREPAID ONBOARD INVITES (already-paid unknown → New Client)
// ============================================================================

const PREPAID_ONBOARD_PAYMENT_METHODS = [
  "cash",
  "zelle",
  "venmo",
  "card_offline",
  "other",
] as const;

type PrepaidOnboardPaymentMethod =
  (typeof PREPAID_ONBOARD_PAYMENT_METHODS)[number];

type PrepaidRemainingSplitDef = {
  label: string;
  amount_cents: number;
  due_date: string;
  send_payment_link?: boolean;
};

function parsePrepaidRemainingSplits(raw: unknown): {
  ok: true;
  splits: PrepaidRemainingSplitDef[];
} | { ok: false; error: string } {
  if (raw == null) return { ok: true, splits: [] };
  if (!Array.isArray(raw)) {
    return { ok: false, error: "remaining_splits must be an array" };
  }
  const splits: PrepaidRemainingSplitDef[] = [];
  for (const item of raw) {
    if (!item || typeof item !== "object") {
      return { ok: false, error: "Invalid remaining split row" };
    }
    const row = item as Record<string, unknown>;
    const label = String(row.label || "").trim();
    const amount = Number(row.amount_cents);
    const due = String(row.due_date || "").trim();
    if (!label || !Number.isFinite(amount) || amount <= 0) {
      return {
        ok: false,
        error: "Each remaining split needs label and amount_cents > 0",
      };
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) {
      return {
        ok: false,
        error: "Each remaining split due_date must be YYYY-MM-DD",
      };
    }
    splits.push({
      label: label.slice(0, 200),
      amount_cents: Math.round(amount),
      due_date: due,
      send_payment_link: !!row.send_payment_link,
    });
  }
  return { ok: true, splits };
}

function prepaidInviteIsOpen(row: RowDataPacket): boolean {
  if (row.revoked_at || row.redeemed_at) return false;
  const exp = row.expires_at ? new Date(row.expires_at).getTime() : 0;
  return exp > Date.now();
}

function serializePrepaidOnboardInvite(
  row: RowDataPacket,
  extras?: { url?: string; token?: string },
) {
  let remaining: PrepaidRemainingSplitDef[] = [];
  try {
    const raw = row.remaining_splits_json;
    if (raw != null) {
      const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
      const check = parsePrepaidRemainingSplits(parsed);
      if (check.ok) remaining = check.splits;
    }
  } catch {
    remaining = [];
  }
  return {
    id: Number(row.id),
    package_id: Number(row.package_id),
    package_name: (row.package_name as string) || null,
    paid_amount_cents: Number(row.paid_amount_cents),
    paid_label: String(row.paid_label || "Enrollment (prepaid)"),
    payment_method: String(row.payment_method || "other"),
    payment_note: (row.payment_note as string) || null,
    remaining_splits: remaining,
    preferred_language: (row.preferred_language as string) || null,
    referral_category: (row.referral_category as string) || null,
    referrer_id:
      row.referrer_id != null ? Number(row.referrer_id) : null,
    staff_notes: (row.staff_notes as string) || null,
    created_by_admin_id: Number(row.created_by_admin_id),
    expires_at: row.expires_at,
    revoked_at: row.revoked_at || null,
    redeemed_at: row.redeemed_at || null,
    redeemed_client_id:
      row.redeemed_client_id != null ? Number(row.redeemed_client_id) : null,
    redeemed_case_id:
      row.redeemed_case_id != null ? Number(row.redeemed_case_id) : null,
    created_at: row.created_at,
    is_open: prepaidInviteIsOpen(row),
    ...(extras?.url ? { url: extras.url } : {}),
    ...(extras?.token ? { token: extras.token } : {}),
  };
}

async function findClientMatchForPrepaidOnboard(
  opts: {
    email: string | null;
    phone: string | null;
  },
  executor: {
    query: typeof pool.query;
  } = pool,
): Promise<RowDataPacket | null> {
  if (opts.email) {
    const [byEmail] = await executor.query<RowDataPacket[]>(
      `SELECT id, email, phone, status, pipeline_stage, first_name, last_name,
              preferred_language, assigned_admin_id, package_id
       FROM clients WHERE email = ? LIMIT 1 FOR UPDATE`,
      [opts.email],
    );
    if (byEmail[0]) return byEmail[0];
  }
  const phoneLast10 = opts.phone ? normalizePhoneLast10(opts.phone) : null;
  if (!phoneLast10) return null;
  const [candidates] = await executor.query<RowDataPacket[]>(
    `SELECT id, email, phone, status, pipeline_stage, first_name, last_name,
            preferred_language, assigned_admin_id, package_id
     FROM clients
     WHERE phone IS NOT NULL AND phone <> ''
     ORDER BY id DESC LIMIT 80`,
  );
  const match = candidates.find(
    (r) => normalizePhoneLast10(String(r.phone || "")) === phoneLast10,
  );
  if (!match) return null;
  const [locked] = await executor.query<RowDataPacket[]>(
    `SELECT id, email, phone, status, pipeline_stage, first_name, last_name,
            preferred_language, assigned_admin_id, package_id
     FROM clients WHERE id = ? LIMIT 1 FOR UPDATE`,
    [Number(match.id)],
  );
  return locked[0] || null;
}

async function clientHasEnrolledActiveCase(
  clientId: number,
  executor: {
    query: typeof pool.query;
  } = pool,
): Promise<boolean> {
  const [rows] = await executor.query<RowDataPacket[]>(
    `SELECT id FROM credit_repair_cases
     WHERE client_id = ? AND status = 'active'
       AND pipeline_stage NOT IN ('prospect', 'cancelled')
     LIMIT 1`,
    [clientId],
  );
  return rows.length > 0;
}


/**
 * Constant-time secret comparison. Pads both buffers to the same (max)
 * length before comparing so `crypto.timingSafeEqual` never throws on a
 * length mismatch — a length-mismatch failure would otherwise itself be
 * a (crude) timing side-channel, so we always compare a fixed size.
 */
function timingSafeStringEqual(a: string, b: string): boolean {
  if (!a || !b) return false;
  const len = Math.max(a.length, b.length, 1);
  const bufA = Buffer.alloc(len);
  const bufB = Buffer.alloc(len);
  bufA.write(a);
  bufB.write(b);
  return crypto.timingSafeEqual(bufA, bufB) && a.length === b.length;
}

function isTransientDbError(err: unknown): boolean {
  const e = err as { code?: string; errno?: number; message?: string };
  const code = String(e?.code || "");
  const msg = String(e?.message || "").toLowerCase();
  return (
    code === "ER_LOCK_DEADLOCK" ||
    code === "ER_LOCK_WAIT_TIMEOUT" ||
    code === "ECONNRESET" ||
    code === "PROTOCOL_CONNECTION_LOST" ||
    code === "ETIMEDOUT" ||
    e?.errno === 1213 ||
    e?.errno === 1205 ||
    msg.includes("deadlock") ||
    msg.includes("lock wait timeout") ||
    msg.includes("try restarting transaction")
  );
}

async function withTransientDbRetry<T>(
  label: string,
  fn: () => Promise<T>,
  attempts = 3,
): Promise<T> {
  let lastErr: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      if (!isTransientDbError(err) || i === attempts - 1) throw err;
      const delayMs = 150 * (i + 1) + Math.floor(Math.random() * 100);
      console.warn(
        `[${label}] transient db error (attempt ${i + 1}/${attempts}), retry in ${delayMs}ms:`,
        (err as Error)?.message ?? err,
      );
      await new Promise((r) => setTimeout(r, delayMs));
    }
  }
  throw lastErr;
}

// ============================================================================
// IN-MEMORY RATE LIMITER
// ----------------------------------------------------------------------------
// Best-effort, per-instance limiter — good enough to blunt brute-force /
// credential-stuffing bursts on a single serverless instance without adding
// an external store. Resets on cold start; that's an acceptable trade-off
// for these endpoints (OTP, registration, payments already have their own
// DB-level guards as the real backstop).
// ============================================================================
const rateLimitBuckets = new Map<string, { count: number; resetAt: number }>();

function hitRateLimit(key: string, max: number, windowMs: number): boolean {
  const now = Date.now();
  sweepRateLimitBuckets();
  const bucket = rateLimitBuckets.get(key);
  if (!bucket || bucket.resetAt <= now) {
    rateLimitBuckets.set(key, { count: 1, resetAt: now + windowMs });
    return false;
  }
  bucket.count += 1;
  if (bucket.count > max) return true;
  return false;
}

// Opportunistic cleanup so the map doesn't grow unbounded on long-lived
// instances. Cheap since buckets are tiny; runs at most once/minute.
let lastRateLimitSweep = 0;
function sweepRateLimitBuckets() {
  const now = Date.now();
  if (now - lastRateLimitSweep < 60_000) return;
  lastRateLimitSweep = now;
  for (const [key, bucket] of rateLimitBuckets) {
    if (bucket.resetAt <= now) rateLimitBuckets.delete(key);
  }
}

function rateLimitKey(req: Request, suffix: string): string {
  const ip = req.ip || "unknown-ip";
  return `${suffix}:${ip}`;
}

function generateOtpCode(): string {
  return Math.floor(100000 + Math.random() * 900000).toString();
}

function signSessionToken(payload: Omit<JwtPayload, "jti">) {
  const jti = crypto.randomBytes(16).toString("hex");
  const token = jwt.sign({ ...payload, jti }, JWT_SECRET, {
    expiresIn: `${SESSION_TTL_DAYS}d`,
  });
  return { token, jti };
}

function verifySessionToken(token: string): JwtPayload | null {
  try {
    return jwt.verify(token, JWT_SECRET) as JwtPayload;
  } catch {
    return null;
  }
}

async function createOtp(
  actor: ActorType,
  actorId: number,
  purpose: string,
  ip?: string,
): Promise<string> {
  const code = generateOtpCode();
  const codeHash = sha256(code);
  const expiresAt = new Date(Date.now() + OTP_TTL_MIN * 60 * 1000);
  const table = actor === "admin" ? "admin_otp_codes" : "client_otp_codes";
  const idCol = actor === "admin" ? "admin_id" : "client_id";
  await pool.query<ResultSetHeader>(
    `INSERT INTO ${table} (${idCol}, code_hash, purpose, expires_at, ip_address) VALUES (?,?,?,?,?)`,
    [actorId, codeHash, purpose, expiresAt, ip || null],
  );
  return code;
}

const OTP_MAX_ATTEMPTS = 5;

/**
 * Look up the latest unconsumed, unexpired OTP for this actor+purpose
 * (regardless of code) and check the submitted code against it. This closes
 * two gaps in the old "match code_hash directly" approach: (1) a caller could
 * brute-force codes indefinitely since a wrong guess never touched the row,
 * and (2) requesting a fresh code left the old one guessable in parallel.
 * Now every wrong guess increments `attempts` on the live OTP row, and once
 * attempts >= OTP_MAX_ATTEMPTS the OTP is dead even with the right code.
 */
async function consumeOtp(
  actor: ActorType,
  actorId: number,
  code: string,
  purpose: string,
): Promise<boolean> {
  const table = actor === "admin" ? "admin_otp_codes" : "client_otp_codes";
  const idCol = actor === "admin" ? "admin_id" : "client_id";
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, code_hash, attempts FROM ${table}
     WHERE ${idCol} = ? AND purpose = ?
       AND consumed_at IS NULL AND expires_at > NOW()
     ORDER BY id DESC LIMIT 1`,
    [actorId, purpose],
  );
  if (rows.length === 0) return false;
  const otp = rows[0];

  if (Number(otp.attempts) >= OTP_MAX_ATTEMPTS) {
    // Locked out — burn it so it can't linger as a target.
    await pool.query<ResultSetHeader>(
      `UPDATE ${table} SET consumed_at = NOW() WHERE id = ?`,
      [otp.id],
    );
    return false;
  }

  const codeHash = sha256(code);
  if (codeHash !== otp.code_hash) {
    await pool.query<ResultSetHeader>(
      `UPDATE ${table} SET attempts = attempts + 1 WHERE id = ?`,
      [otp.id],
    );
    return false;
  }

  await pool.query<ResultSetHeader>(
    `UPDATE ${table} SET consumed_at = NOW() WHERE id = ?`,
    [otp.id],
  );
  return true;
}

async function createSession(
  actor: ActorType,
  actorId: number,
  email: string,
  ip?: string,
  userAgent?: string,
): Promise<string> {
  const { token, jti } = signSessionToken({ actor, id: actorId, email });
  const expiresAt = new Date(
    Date.now() + SESSION_TTL_DAYS * 24 * 60 * 60 * 1000,
  );
  const table = actor === "admin" ? "admin_sessions" : "client_sessions";
  const idCol = actor === "admin" ? "admin_id" : "client_id";
  await pool.query<ResultSetHeader>(
    `INSERT INTO ${table} (${idCol}, token_hash, ip_address, user_agent, expires_at) VALUES (?,?,?,?,?)`,
    [actorId, sha256(jti), ip || null, userAgent || null, expiresAt],
  );
  return token;
}

async function revokeSession(token: string): Promise<void> {
  const payload = verifySessionToken(token);
  if (!payload) return;
  const table =
    payload.actor === "admin" ? "admin_sessions" : "client_sessions";
  await pool.query<ResultSetHeader>(
    `UPDATE ${table} SET is_active = 0 WHERE token_hash = ?`,
    [sha256(payload.jti)],
  );
}

async function isSessionActive(payload: JwtPayload): Promise<boolean> {
  const table =
    payload.actor === "admin" ? "admin_sessions" : "client_sessions";
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM ${table}
     WHERE token_hash = ? AND is_active = 1 AND expires_at > NOW() LIMIT 1`,
    [sha256(payload.jti)],
  );
  return rows.length > 0;
}

/**
 * Kill every active session for an actor — used when an admin/client is
 * deactivated/suspended/cancelled so a leaked or still-open token can't
 * keep working until it naturally expires (up to SESSION_TTL_DAYS later).
 */
async function revokeAllSessions(
  actor: ActorType,
  actorId: number,
): Promise<void> {
  const table = actor === "admin" ? "admin_sessions" : "client_sessions";
  const idCol = actor === "admin" ? "admin_id" : "client_id";
  await pool.query<ResultSetHeader>(
    `UPDATE ${table} SET is_active = 0 WHERE ${idCol} = ? AND is_active = 1`,
    [actorId],
  );
}

function extractToken(req: Request): string | null {
  const header = req.headers.authorization;
  if (header && header.startsWith("Bearer ")) return header.slice(7);
  return null;
}

function requireAuth(actor: ActorType) {
  return async (req: AuthedRequest, res: Response, next: NextFunction) => {
    const token = extractToken(req);
    if (!token) return res.status(401).json({ error: "Unauthorized" });
    const payload = verifySessionToken(token);
    if (!payload || payload.actor !== actor) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    const ok = await isSessionActive(payload);
    if (!ok) return res.status(401).json({ error: "Session expired" });

    // Re-check the actor's current status on every request — a session
    // token stays cryptographically valid for SESSION_TTL_DAYS, so without
    // this a deactivated admin or cancelled client could keep using an
    // already-issued token until it expires on its own.
    if (actor === "admin") {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT status FROM admins WHERE id = ? LIMIT 1`,
        [payload.id],
      );
      if (rows.length === 0 || rows[0].status !== "active") {
        return res.status(401).json({ error: "Account is no longer active" });
      }
    } else {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT status FROM clients WHERE id = ? LIMIT 1`,
        [payload.id],
      );
      if (rows.length === 0 || rows[0].status === "cancelled") {
        return res.status(401).json({ error: "Account is no longer active" });
      }
    }

    req.auth = payload;
    next();
  };
}
const requireClient = requireAuth("client");
const requireAdmin = requireAuth("admin");

/**
 * Admin AI Ask / MCP tools — accepts either a normal admin session Bearer
 * or ADMIN_AI_MCP_TOKEN (scoped to ADMIN_AI_MCP_ADMIN_ID).
 */
async function requireAdminAiAccess(
  req: AuthedRequest,
  res: Response,
  next: NextFunction,
) {
  const bearer = extractToken(req);
  const mcpToken = String(process.env.ADMIN_AI_MCP_TOKEN || "").trim();
  const mcpAdminId = Number(process.env.ADMIN_AI_MCP_ADMIN_ID || 0);
  if (
    bearer &&
    mcpToken &&
    bearer === mcpToken &&
    Number.isFinite(mcpAdminId) &&
    mcpAdminId > 0
  ) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, email, role, status FROM admins WHERE id = ? LIMIT 1`,
      [mcpAdminId],
    );
    if (
      !rows[0] ||
      rows[0].status !== "active" ||
      !adminAiRoleAllowed(String(rows[0].role || ""))
    ) {
      return res.status(403).json({
        error: "MCP token admin is inactive or not allowed for Admin AI",
        code: "ai_mcp_admin_invalid",
      });
    }
    req.auth = {
      actor: "admin",
      id: mcpAdminId,
      email: String(rows[0].email),
      jti: "admin-ai-mcp",
    };
    return next();
  }
  return requireAdmin(req, res, next);
}

async function requireSuperAdmin(
  req: AuthedRequest,
  res: Response,
  next: NextFunction,
) {
  const token = extractToken(req);
  if (!token) return res.status(401).json({ error: "Unauthorized" });
  const payload = verifySessionToken(token);
  if (!payload || payload.actor !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const ok = await isSessionActive(payload);
  if (!ok) return res.status(401).json({ error: "Session expired" });
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT role FROM admins WHERE id = ? LIMIT 1`,
    [payload.id],
  );
  if (rows[0]?.role !== "super_admin") {
    return res.status(403).json({ error: "Forbidden: super_admin required" });
  }
  req.auth = payload;
  next();
}

/** super_admin + admin only — excludes agent/affiliate roles (Funding board, etc.). */
async function requireStaffManager(
  req: AuthedRequest,
  res: Response,
  next: NextFunction,
) {
  const token = extractToken(req);
  if (!token) return res.status(401).json({ error: "Unauthorized" });
  const payload = verifySessionToken(token);
  if (!payload || payload.actor !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }
  const ok = await isSessionActive(payload);
  if (!ok) return res.status(401).json({ error: "Session expired" });
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT status, role FROM admins WHERE id = ? LIMIT 1`,
    [payload.id],
  );
  if (!rows[0] || String(rows[0].status) !== "active") {
    return res.status(401).json({ error: "Account is no longer active" });
  }
  const role = String(rows[0].role || "");
  if (role !== "super_admin" && role !== "admin") {
    return res.status(403).json({ error: "Forbidden: admin access required" });
  }
  req.auth = payload;
  next();
}

// ============================================================================
// EMAIL HELPERS
// ============================================================================

interface SendEmailOptions {
  to: string;
  subject: string;
  html: string;
  text?: string;
  replyTo?: string;
  attachments?: Array<{
    filename: string;
    content: Buffer | string;
    contentType?: string;
  }>;
}

/** Vitest-only capture of dry-run emails (attachments included). */
type EmailDryRunRecord = {
  to: string;
  subject: string;
  attachmentNames: string[];
  hasCalendarAttachment: boolean;
  attachmentBytes: number[];
  /** First SEQUENCE value found in an attached .ics (if any). */
  icsSequence: number | null;
  /** True when HTML includes Optimum emailLayout logo chrome. */
  brandedChrome: boolean;
};
let emailDryRuns: EmailDryRunRecord[] = [];

export function __testClearEmailDryRuns() {
  emailDryRuns = [];
}

export function __testGetEmailDryRuns(): EmailDryRunRecord[] {
  return emailDryRuns.slice();
}

/** Test-only: payment-success side effects (promotes prospect-stage cases). */
export async function __testMarkPaymentSucceeded(
  clientId: number,
  transactionId: string,
) {
  return markPaymentSucceeded(clientId, transactionId);
}

async function sendEmail(opts: SendEmailOptions) {
  // Never hit Resend during vitest — integration suites use fake
  // @*.test addresses that bounce and pollute the sending domain.
  if (!emailClient || process.env.VITEST === "true") {
    if (process.env.VITEST === "true") {
      let icsSequence: number | null = null;
      for (const a of opts.attachments ?? []) {
        const isIcs =
          a.filename.endsWith(".ics") ||
          String(a.contentType || "").includes("text/calendar");
        if (!isIcs) continue;
        const text = Buffer.isBuffer(a.content)
          ? a.content.toString("utf8")
          : String(a.content);
        const m = /SEQUENCE:(\d+)/.exec(text);
        if (m) {
          icsSequence = Number(m[1]);
          break;
        }
      }
      emailDryRuns.push({
        to: opts.to,
        subject: opts.subject,
        attachmentNames: (opts.attachments ?? []).map((a) => a.filename),
        hasCalendarAttachment: (opts.attachments ?? []).some(
          (a) =>
            a.filename.endsWith(".ics") ||
            String(a.contentType || "").includes("text/calendar"),
        ),
        attachmentBytes: (opts.attachments ?? []).map((a) =>
          Buffer.isBuffer(a.content)
            ? a.content.length
            : Buffer.byteLength(String(a.content), "utf8"),
        ),
        icsSequence,
        brandedChrome: /logo_with_title_white\.png/i.test(
          String(opts.html || ""),
        ),
      });
    }
    console.log(
      "[email:dry-run]",
      opts.to,
      opts.subject,
      opts.attachments?.length
        ? `(${opts.attachments.length} attachment(s))`
        : "",
    );
    return { id: "dry-run" };
  }
  const { data, error } = await emailClient.emails.send({
    from: FROM_EMAIL,
    to: opts.to,
    subject: opts.subject,
    html: opts.html,
    text: opts.text,
    replyTo: opts.replyTo,
    attachments: opts.attachments?.map((a) => ({
      filename: a.filename,
      content: a.content,
      contentType: a.contentType,
    })),
  });
  if (error) throw new Error(error.message);
  console.log("[email:sent]", opts.to, opts.subject, data?.id || "(no-id)");
  return { id: data?.id };
}

/** Default spacing between expected round-completion dates (all-day). */
export const DEFAULT_ROUND_INTERVAL_DAYS = 35;

function formatDateYmd(d: Date): string {
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

/** Normalize MySQL DATE / ISO string to YYYY-MM-DD without TZ drift.
 *  Pool uses `timezone: "+00:00"`, so DATE columns arrive as UTC midnight —
 *  always read Y/M/D via UTC getters for Date objects.
 */
export function mysqlDateToYmd(v: unknown): string {
  if (typeof v === "string" && /^\d{4}-\d{2}-\d{2}/.test(v))
    return v.slice(0, 10);
  if (v instanceof Date && !Number.isNaN(v.getTime())) {
    const y = v.getUTCFullYear();
    const m = String(v.getUTCMonth() + 1).padStart(2, "0");
    const day = String(v.getUTCDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  }
  const s = String(v ?? "");
  const m = /^(\d{4}-\d{2}-\d{2})/.exec(s);
  if (m) return m[1];
  return formatDateYmd(new Date());
}

function parseDateYmd(s: string): Date | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || "").trim());
  if (!m) return null;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (
    dt.getUTCFullYear() !== y ||
    dt.getUTCMonth() !== mo - 1 ||
    dt.getUTCDate() !== d
  ) {
    return null;
  }
  return dt;
}

/** Prefill five all-day round target dates from a start day + interval. */
export function buildDefaultRoundScheduleDates(
  start: Date = new Date(),
  intervalDays = DEFAULT_ROUND_INTERVAL_DAYS,
): {
  round_1_date: string;
  round_2_date: string;
  round_3_date: string;
  round_4_date: string;
  round_5_date: string;
} {
  const base = new Date(
    Date.UTC(start.getFullYear(), start.getMonth(), start.getDate()),
  );
  const days = Math.max(
    1,
    Math.min(120, Number(intervalDays) || DEFAULT_ROUND_INTERVAL_DAYS),
  );
  const out: string[] = [];
  for (let i = 1; i <= 5; i++) {
    const d = new Date(base);
    d.setUTCDate(d.getUTCDate() + days * i);
    out.push(formatDateYmd(d));
  }
  return {
    round_1_date: out[0],
    round_2_date: out[1],
    round_3_date: out[2],
    round_4_date: out[3],
    round_5_date: out[4],
  };
}

export function validateRoundScheduleDates(input: {
  round_1_date?: string;
  round_2_date?: string;
  round_3_date?: string;
  round_4_date?: string;
  round_5_date?: string;
}):
  | {
      ok: true;
      dates: {
        round_1_date: string;
        round_2_date: string;
        round_3_date: string;
        round_4_date: string;
        round_5_date: string;
      };
    }
  | { ok: false; error: string } {
  const keys = [
    "round_1_date",
    "round_2_date",
    "round_3_date",
    "round_4_date",
    "round_5_date",
  ] as const;
  const dates: Record<(typeof keys)[number], string> = {} as any;
  const parsed: Date[] = [];
  for (const k of keys) {
    const raw = input[k];
    const dt = parseDateYmd(String(raw || ""));
    if (!dt) return { ok: false, error: `Invalid ${k} (use YYYY-MM-DD)` };
    dates[k] = formatDateYmd(dt);
    parsed.push(dt);
  }
  for (let i = 1; i < parsed.length; i++) {
    if (parsed[i].getTime() < parsed[i - 1].getTime()) {
      return {
        ok: false,
        error: "Round dates must be in non-decreasing order (R1 ≤ R2 ≤ … ≤ R5)",
      };
    }
  }
  return { ok: true, dates: dates as any };
}

function icsFoldLine(line: string): string {
  const bytes = Buffer.from(line, "utf8");
  if (bytes.length <= 75) return line;
  const parts: string[] = [];
  let start = 0;
  while (start < bytes.length) {
    let end = Math.min(start + (start === 0 ? 75 : 74), bytes.length);
    // Avoid splitting multi-byte UTF-8 mid-character
    while (end > start && (bytes[end] & 0xc0) === 0x80) end--;
    const chunk = bytes.subarray(start, end).toString("utf8");
    parts.push(start === 0 ? chunk : ` ${chunk}`);
    start = end;
  }
  return parts.join("\r\n");
}

function icsEscapeText(s: string): string {
  return String(s)
    .replace(/\\/g, "\\\\")
    .replace(/;/g, "\\;")
    .replace(/,/g, "\\,")
    .replace(/\r\n|\n|\r/g, "\\n");
}

function ymdToIcsDate(ymd: string): string {
  return ymd.replace(/-/g, "");
}

function nextDayYmd(ymd: string): string {
  const d = parseDateYmd(ymd)!;
  d.setUTCDate(d.getUTCDate() + 1);
  return formatDateYmd(d);
}

/** Build a METHOD:PUBLISH calendar with round VEVENTs (R1–5 + optional extended). */
export function buildRoundScheduleIcs(opts: {
  caseNumber: string;
  clientName: string;
  uidNs: string;
  dates: {
    round_1_date: string;
    round_2_date: string;
    round_3_date: string;
    round_4_date: string;
    round_5_date: string;
  };
  lang?: string;
  /** ICS SEQUENCE — bump on resend so clients can replace prior events. */
  sequence?: number;
  /** When >5, append projected/override dates for rounds 6..maxRounds. */
  maxRounds?: number;
  intervalDays?: number;
  extendedDates?: Record<string, string> | null;
}): string {
  const isEs = opts.lang === "es";
  const stamp = new Date()
    .toISOString()
    .replace(/[-:]/g, "")
    .replace(/\.\d{3}Z$/, "Z");
  const sequence = Math.max(0, Number(opts.sequence) || 0);
  const lines: string[] = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Optimum Credit//Round Schedule//EN",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
  ];
  const rounds: Array<{ n: number; date: string }> = [
    { n: 1, date: opts.dates.round_1_date },
    { n: 2, date: opts.dates.round_2_date },
    { n: 3, date: opts.dates.round_3_date },
    { n: 4, date: opts.dates.round_4_date },
    { n: 5, date: opts.dates.round_5_date },
  ];
  const extended = projectExtendedRoundDatesInline({
    round5Date: opts.dates.round_5_date,
    intervalDays: opts.intervalDays ?? 35,
    maxRounds: opts.maxRounds ?? DEFAULT_MAX_ROUNDS,
    overrides: opts.extendedDates ?? null,
  });
  for (const e of extended) rounds.push({ n: e.round, date: e.date });
  for (const r of rounds) {
    const summary = isEs
      ? `Optimum Credit — Meta Ronda ${r.n} (${opts.caseNumber})`
      : `Optimum Credit — Round ${r.n} target (${opts.caseNumber})`;
    const desc = isEs
      ? `Fecha objetivo de completación de la Ronda ${r.n} para ${opts.clientName}. Caso ${opts.caseNumber}. Esta es una fecha planificada — el avance real puede variar.`
      : `Target completion date for Round ${r.n} for ${opts.clientName}. Case ${opts.caseNumber}. This is a planned target — actual progress may vary.`;
    lines.push(
      "BEGIN:VEVENT",
      `UID:oc-${opts.uidNs}-r${r.n}@optimumcredit.com`,
      `DTSTAMP:${stamp}`,
      `DTSTART;VALUE=DATE:${ymdToIcsDate(r.date)}`,
      `DTEND;VALUE=DATE:${ymdToIcsDate(nextDayYmd(r.date))}`,
      `SEQUENCE:${sequence}`,
      `SUMMARY:${icsEscapeText(summary)}`,
      `DESCRIPTION:${icsEscapeText(desc)}`,
      "TRANSP:TRANSPARENT",
      "STATUS:CONFIRMED",
      "END:VEVENT",
    );
  }
  lines.push("END:VCALENDAR");
  return lines.map(icsFoldLine).join("\r\n") + "\r\n";
}

function tplRoundCalendarInvite(opts: {
  firstName: string;
  clientName: string;
  caseNumber: string;
  dates: {
    round_1_date: string;
    round_2_date: string;
    round_3_date: string;
    round_4_date: string;
    round_5_date: string;
  };
  recipientRole: "client" | "referrer" | "admin";
  lang?: string;
  isUpdate?: boolean;
}) {
  const isEs = opts.lang === "es";
  const list = [1, 2, 3, 4, 5]
    .map((n) => {
      const key = `round_${n}_date` as keyof typeof opts.dates;
      return `<li style="margin:0 0 4px;"><strong>${isEs ? "Ronda" : "Round"} ${n}:</strong> ${escapeHtml(opts.dates[key])}</li>`;
    })
    .join("");
  const roleHint =
    opts.recipientRole === "client"
      ? isEs
        ? "Adjunta el archivo .ics a tu calendario (Google, Apple u Outlook) para recordarte cada meta de ronda."
        : "Attach the .ics file to your calendar (Google, Apple, or Outlook) so each round target is on your schedule."
      : opts.recipientRole === "referrer"
        ? isEs
          ? `Estas son las metas de ronda planificadas para <strong>${escapeHtml(opts.clientName)}</strong>. Añade el .ics a tu calendario para hacer seguimiento.`
          : `These are the planned round targets for <strong>${escapeHtml(opts.clientName)}</strong>. Add the .ics to your calendar to stay aligned.`
        : isEs
          ? `Calendario de rondas para <strong>${escapeHtml(opts.clientName)}</strong> (${escapeHtml(opts.caseNumber)}).`
          : `Round schedule for <strong>${escapeHtml(opts.clientName)}</strong> (${escapeHtml(opts.caseNumber)}).`;
  const title = opts.isUpdate
    ? isEs
      ? "Calendario de rondas actualizado"
      : "Updated round calendar"
    : isEs
      ? "Fechas de ronda en tu calendario"
      : "Round dates for your calendar";
  const body = `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">${title}</h1>
    <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">
      ${isEs ? "Hola" : "Hi"} ${escapeHtml(opts.firstName)},
    </p>
    <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">${roleHint}</p>
    <ul style="margin:0 0 16px;padding-left:18px;font-size:14px;line-height:1.6;color:#334155;">${list}</ul>
    <p style="margin:0;font-size:13px;line-height:1.5;color:#64748b;">
      ${
        isEs
          ? "Si ya tenías estos eventos, vuelve a importar el archivo adjunto para actualizarlos (mismos identificadores)."
          : "If you already added these events, re-import the attached file to update them (same event IDs)."
      }
    </p>`;
  return {
    subject: opts.isUpdate
      ? isEs
        ? `Calendario actualizado — ${opts.caseNumber}`
        : `Updated calendar — ${opts.caseNumber}`
      : isEs
        ? `Calendario de rondas — ${opts.caseNumber}`
        : `Round calendar — ${opts.caseNumber}`,
    html: emailLayout({
      title,
      preheader: opts.caseNumber,
      bodyHtml: body,
      lang: opts.lang,
    }),
  };
}

async function upsertCaseRoundSchedule(
  caseId: number,
  dates: {
    round_1_date: string;
    round_2_date: string;
    round_3_date: string;
    round_4_date: string;
    round_5_date: string;
  },
  intervalDays: number,
  conn?: any,
): Promise<{ calendar_uid_ns: string; is_new: boolean }> {
  const q = conn || pool;
  const [existing] = await q.query(
    `SELECT id, calendar_uid_ns FROM case_round_schedules WHERE case_id = ? LIMIT 1`,
    [caseId],
  );
  const rows = existing as any[];
  if (rows.length > 0) {
    await q.query(
      `UPDATE case_round_schedules
       SET round_1_date = ?, round_2_date = ?, round_3_date = ?,
           round_4_date = ?, round_5_date = ?, interval_days = ?
       WHERE case_id = ?`,
      [
        dates.round_1_date,
        dates.round_2_date,
        dates.round_3_date,
        dates.round_4_date,
        dates.round_5_date,
        intervalDays,
        caseId,
      ],
    );
    return {
      calendar_uid_ns: rows[0].calendar_uid_ns as string,
      is_new: false,
    };
  }
  const uidNs = `case${caseId}-${crypto.randomBytes(6).toString("hex")}`;
  await q.query(
    `INSERT INTO case_round_schedules
      (case_id, round_1_date, round_2_date, round_3_date, round_4_date, round_5_date,
       interval_days, calendar_uid_ns)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      caseId,
      dates.round_1_date,
      dates.round_2_date,
      dates.round_3_date,
      dates.round_4_date,
      dates.round_5_date,
      intervalDays,
      uidNs,
    ],
  );
  return { calendar_uid_ns: uidNs, is_new: true };
}

async function resolveRoundCalendarRecipients(clientId: number): Promise<
  Array<{
    email: string;
    firstName: string;
    role: "client" | "referrer" | "admin";
    lang: string;
    adminId?: number;
  }>
> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT c.first_name AS client_first, c.last_name AS client_last, c.email AS client_email,
            c.preferred_language AS client_lang, c.referrer_id,
            a.id AS admin_id, a.first_name AS admin_first, a.email AS admin_email,
            a.preferred_language AS admin_lang, a.notification_prefs_json AS admin_prefs
     FROM clients c
     LEFT JOIN admins a ON a.id = c.assigned_admin_id AND a.status = 'active'
     WHERE c.id = ? LIMIT 1`,
    [clientId],
  );
  if (!rows.length) return [];
  const row = rows[0];
  const out: Array<{
    email: string;
    firstName: string;
    role: "client" | "referrer" | "admin";
    lang: string;
    adminId?: number;
  }> = [];
  const seen = new Set<string>();
  const push = (
    email: unknown,
    firstName: unknown,
    role: "client" | "referrer" | "admin",
    lang: unknown,
    adminId?: number,
  ) => {
    const e = String(email || "")
      .trim()
      .toLowerCase();
    if (!e || !e.includes("@") || seen.has(e)) return;
    seen.add(e);
    out.push({
      email: e,
      firstName: String(firstName || "there").trim() || "there",
      role,
      lang: String(lang || "en") === "es" ? "es" : "en",
      adminId,
    });
  };
  push(row.client_email, row.client_first, "client", row.client_lang);

  const [refRows] = await pool.query<RowDataPacket[]>(
    `SELECT r.first_name AS ref_first, r.email AS ref_email, r.preferred_language AS ref_lang
     FROM client_referrers cr
     INNER JOIN referrers r ON r.id = cr.referrer_id AND r.status = 'active'
     WHERE cr.client_id = ?
     ORDER BY cr.sort_order ASC`,
    [clientId],
  );
  for (const r of refRows) {
    push(r.ref_email, r.ref_first, "referrer", r.ref_lang || row.client_lang);
  }
  // 3A: no legacy clients.referrer_id fallback — partners must be in client_referrers.
  // notify_on_round is always ON at write time; do not filter it here.

  if (row.admin_id) {
    const prefs = parseAdminNotificationPrefs(row.admin_prefs);
    if (adminNotifyPrefOn(prefs, "email", "round_calendar")) {
      push(
        row.admin_email,
        row.admin_first,
        "admin",
        row.admin_lang || row.client_lang,
        Number(row.admin_id),
      );
    }
  }
  return out;
}

async function sendCaseRoundCalendarInvites(opts: {
  caseId: number;
  clientId: number;
  caseNumber: string;
  clientName: string;
  dates: {
    round_1_date: string;
    round_2_date: string;
    round_3_date: string;
    round_4_date: string;
    round_5_date: string;
  };
  uidNs: string;
  isUpdate?: boolean;
}): Promise<{ sent_to: string[]; errors: string[]; sequence: number }> {
  const [schedRows] = await pool.query<RowDataPacket[]>(
    `SELECT s.calendar_send_count, s.interval_days, s.extended_dates_json,
            cr.max_rounds
     FROM case_round_schedules s
     JOIN credit_repair_cases cr ON cr.id = s.case_id
     WHERE s.case_id = ? LIMIT 1`,
    [opts.caseId],
  );
  const priorCount = Number(schedRows[0]?.calendar_send_count ?? 0);
  const sequence = priorCount; // 0 first send, then 1, 2, …
  const maxRounds = clampMaxRounds(schedRows[0]?.max_rounds);
  const intervalDays = Math.max(
    1,
    Number(schedRows[0]?.interval_days) || 35,
  );
  let extendedDates: Record<string, string> | null = null;
  try {
    const raw = schedRows[0]?.extended_dates_json;
    if (raw) {
      extendedDates =
        typeof raw === "string" ? JSON.parse(raw) : (raw as Record<string, string>);
    }
  } catch {
    extendedDates = null;
  }
  const recipients = await resolveRoundCalendarRecipients(opts.clientId);
  const sent_to: string[] = [];
  const errors: string[] = [];

  // In-app for assigned admin even when email recipients are empty
  // (e.g. phone-only client + admin muted round_calendar email).
  try {
    const [aRows] = await pool.query<RowDataPacket[]>(
      `SELECT a.id, a.notification_prefs_json
       FROM clients c
       JOIN admins a ON a.id = c.assigned_admin_id AND a.status = 'active'
       WHERE c.id = ? LIMIT 1`,
      [opts.clientId],
    );
    if (aRows[0]) {
      const prefs = parseAdminNotificationPrefs(
        aRows[0].notification_prefs_json,
      );
      if (adminNotifyPrefOn(prefs, "in_app", "round_calendar")) {
        await insertAdminInAppNotification({
          adminId: Number(aRows[0].id),
          eventKey: "round_calendar",
          title: `Round calendar — ${opts.caseNumber}`,
          body: `Calendar invite sent for ${opts.clientName}`,
          linkUrl: `${APP_URL}/admin/pipeline?case=${opts.caseId}`,
        });
      }
    }
  } catch (e: any) {
    console.error("[round-calendar:in-app]", e?.message ?? e);
  }

  if (recipients.length === 0) {
    return {
      sent_to: [],
      errors: ["No recipients with email (client / referrer / assigned admin)"],
      sequence,
    };
  }
  for (const r of recipients) {
    try {
      const ics = buildRoundScheduleIcs({
        caseNumber: opts.caseNumber,
        clientName: opts.clientName,
        uidNs: opts.uidNs,
        dates: opts.dates,
        lang: r.lang,
        sequence,
        maxRounds,
        intervalDays,
        extendedDates,
      });
      const tpl = tplRoundCalendarInvite({
        firstName: r.firstName,
        clientName: opts.clientName,
        caseNumber: opts.caseNumber,
        dates: opts.dates,
        recipientRole: r.role,
        lang: r.lang,
        isUpdate: opts.isUpdate || sequence > 0,
      });
      await sendEmail({
        to: r.email,
        subject: tpl.subject,
        html: tpl.html,
        attachments: [
          {
            filename: `${opts.caseNumber}-round-schedule.ics`,
            content: Buffer.from(ics, "utf8"),
            contentType: "text/calendar; method=PUBLISH; charset=UTF-8",
          },
        ],
      });
      sent_to.push(r.email);
    } catch (e: any) {
      errors.push(`${r.email}: ${e?.message || "send failed"}`);
    }
  }
  if (sent_to.length > 0) {
    await pool.query(
      `UPDATE case_round_schedules
       SET last_sent_at = NOW(),
           last_sent_recipients = ?,
           calendar_send_count = calendar_send_count + 1
       WHERE case_id = ?`,
      [JSON.stringify(sent_to), opts.caseId],
    );
  }

  return { sent_to, errors, sequence };
}

async function persistAndMaybeSendRoundSchedule(opts: {
  caseId: number;
  clientId: number;
  caseNumber: string;
  clientName: string;
  scheduleInput: any;
}): Promise<{
  saved: boolean;
  sent?: { sent_to: string[]; errors: string[] };
  error?: string;
}> {
  const raw = opts.scheduleInput;
  if (!raw || typeof raw !== "object") return { saved: false };
  const sendCalendar = !!raw.send_calendar;
  const intervalDays = Math.max(
    1,
    Math.min(120, Number(raw.interval_days) || DEFAULT_ROUND_INTERVAL_DAYS),
  );
  let datesInput = raw;
  const hasAnyDate =
    raw.round_1_date ||
    raw.round_2_date ||
    raw.round_3_date ||
    raw.round_4_date ||
    raw.round_5_date;
  if (!hasAnyDate) {
    if (!sendCalendar) return { saved: false };
    datesInput = buildDefaultRoundScheduleDates(new Date(), intervalDays);
  }
  const validated = validateRoundScheduleDates(datesInput);
  if (validated.ok === false) {
    return { saved: false, error: validated.error };
  }
  const { calendar_uid_ns, is_new } = await upsertCaseRoundSchedule(
    opts.caseId,
    validated.dates,
    intervalDays,
  );
  if (!sendCalendar) return { saved: true };
  const sent = await sendCaseRoundCalendarInvites({
    caseId: opts.caseId,
    clientId: opts.clientId,
    caseNumber: opts.caseNumber,
    clientName: opts.clientName,
    dates: validated.dates,
    uidNs: calendar_uid_ns,
    isUpdate: !is_new,
  });
  return { saved: true, sent };
}

function escapeHtml(s: string) {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Escape LIKE wildcards using `!` as the ESCAPE character (MySQL/TiDB safe). */
function escapeLikePattern(raw: string): string {
  return String(raw).replace(/[!%_]/g, (ch) => `!${ch}`);
}

/** Build a contains-match LIKE value with escaped wildcards. Pair with `ESCAPE '!'`. */
function likeContains(raw: string): string {
  return `%${escapeLikePattern(raw)}%`;
}

/** Strip common phone punctuation so 9516488615 matches (951) 648-8615. */
function mysqlPhoneDigitsExpr(columnSql: string): string {
  return `REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(${columnSql}, ''), '-', ''), '(', ''), ')', ''), ' ', ''), '.', ''), '+', '')`;
}

/**
 * Name/email/phone search, plus exact numeric client id and digit-stripped phone.
 */
function clientIdentitySearchSql(search: string): {
  sql: string;
  params: any[];
} {
  const like = likeContains(search);
  const parts = [
    `c.email LIKE ? ESCAPE '!'`,
    `c.first_name LIKE ? ESCAPE '!'`,
    `c.last_name LIKE ? ESCAPE '!'`,
    `CONCAT(c.first_name,' ',c.last_name) LIKE ? ESCAPE '!'`,
    `c.phone LIKE ? ESCAPE '!'`,
  ];
  const params: any[] = [like, like, like, like, like];
  const trimmed = String(search || "").trim();
  if (/^\d{1,11}$/.test(trimmed)) {
    parts.push(`c.id = ?`);
    params.push(Number(trimmed));
  }
  const digits = trimmed.replace(/\D/g, "");
  if (digits.length >= 7 && digits.length <= 15) {
    parts.push(`${mysqlPhoneDigitsExpr("c.phone")} LIKE ?`);
    params.push(`%${digits}%`);
  }
  return { sql: `(${parts.join(" OR ")})`, params };
}

/** Name/email/phone/id search for funding_applications rows (alias `fa`). */
function fundingApplicationSearchSql(search: string): {
  sql: string;
  params: any[];
} {
  const like = likeContains(search);
  const parts = [
    `fa.email LIKE ? ESCAPE '!'`,
    `fa.first_name LIKE ? ESCAPE '!'`,
    `fa.last_name LIKE ? ESCAPE '!'`,
    `CONCAT(fa.first_name,' ',fa.last_name) LIKE ? ESCAPE '!'`,
    `fa.phone LIKE ? ESCAPE '!'`,
    `fa.llc_name LIKE ? ESCAPE '!'`,
  ];
  const params: any[] = [like, like, like, like, like, like];
  const trimmed = String(search || "").trim();
  if (/^\d{1,11}$/.test(trimmed)) {
    parts.push(`fa.id = ?`);
    params.push(Number(trimmed));
  }
  const digits = trimmed.replace(/\D/g, "");
  if (digits.length >= 7 && digits.length <= 15) {
    parts.push(`${mysqlPhoneDigitsExpr("fa.phone")} LIKE ?`);
    params.push(`%${digits}%`);
  }
  return { sql: `(${parts.join(" OR ")})`, params };
}

function emailLayout(opts: {
  title: string;
  preheader?: string;
  bodyHtml: string;
  lang?: string;
}) {
  const isEs = opts.lang === "es";
  const year = new Date().getFullYear();
  const tagline = isEs
    ? "Reparación de Crédito, Bien Hecha"
    : "Credit Repair, Done Right";
  // Legal / public brand is Optimum Financial Group (product mark on logo: OFG).
  const footer = isEs
    ? `Recibes este correo porque tienes una cuenta con Optimum Financial Group.<br/>© ${year} Optimum Financial Group. Todos los derechos reservados.`
    : `You're receiving this email because you have an account with Optimum Financial Group.<br/>© ${year} Optimum Financial Group. All rights reserved.`;
  return `<!doctype html>
<html lang="${isEs ? "es" : "en"}"><head><meta charset="utf-8" /><meta name="viewport" content="width=device-width,initial-scale=1" /><title>${escapeHtml(opts.title)}</title></head>
<body style="margin:0;padding:0;background:#f4f5f9;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#0f172a;">
${opts.preheader ? `<div style="display:none;max-height:0;overflow:hidden;">${escapeHtml(opts.preheader)}</div>` : ""}
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f4f5f9;padding:40px 16px;">
  <tr><td align="center">
    <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 8px 24px rgba(15,23,42,0.06);">
      <tr><td style="background:#121829;padding:24px 32px 20px;">
        <table width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
          <td style="vertical-align:middle;">
            <img src="https://disruptinglabs.com/data/optimum/assets/images/logos/logo_with_title_white.png" alt="Optimum Financial Group" height="40" style="display:block;height:40px;width:auto;border:0;" />
          </td>
          <td align="right" style="vertical-align:middle;font-size:12px;color:#C0A06A;font-weight:600;letter-spacing:0.03em;padding-left:12px;">${tagline}</td>
        </tr></table>
      </td></tr>
      <tr><td style="height:3px;line-height:3px;font-size:0;background:#C0A06A;">&nbsp;</td></tr>
      <tr><td style="padding:32px;">${opts.bodyHtml}</td></tr>
      <tr><td style="padding:24px 32px;background:#f8fafc;border-top:1px solid #e2e8f0;font-size:12px;color:#64748b;text-align:center;line-height:1.6;">
        ${footer}
      </td></tr>
    </table>
  </td></tr>
</table></body></html>`;
}

/**
 * Staff notify helpers sometimes pass body fragments (no chrome). Wrap those in
 * emailLayout; leave full documents alone (already branded / voice builders).
 */
export function ensureBrandedEmailHtml(opts: {
  title: string;
  html: string;
  preheader?: string;
  lang?: string;
}): string {
  const html = String(opts.html || "").trim();
  if (!html) {
    return emailLayout({
      title: opts.title,
      preheader: opts.preheader,
      bodyHtml: "",
      lang: opts.lang,
    });
  }
  if (/<!doctype\s+html/i.test(html) || /<html[\s>]/i.test(html)) {
    return html;
  }
  return emailLayout({
    title: opts.title,
    preheader: opts.preheader ?? opts.title.slice(0, 120),
    bodyHtml: html,
    lang: opts.lang,
  });
}

