// ============================================================================
// ADMIN NOTIFICATION PREFERENCES (profile mute toggles)
// ============================================================================

/** After invalid ABLY_API_KEY, skip Rest init (one log per process, no retry spam). */
let ablyKeyRejected = false;

const ADMIN_NOTIFY_EVENT_KEYS: AdminNotifyEventKey[] = [
  "purchase_enrollment",
  "payment_installment",
  "submission_ready_review",
  "submission_doc_upload",
  "submission_info_request",
  "doc_upload_link",
  "round_calendar",
  "work_task_assigned",
  "work_task_overdue",
  "inbound_sms",
  "missed_call",
  "voicemail",
  "funding_doc_upload",
  "funding_application_created",
  "get_credit_report_lead",
  "progress_report_alerts",
  "morning_digest",
];

function allAdminNotifyEventsOn(): AdminNotifyEventToggles {
  return {
    purchase_enrollment: true,
    payment_installment: true,
    submission_ready_review: true,
    submission_doc_upload: true,
    submission_info_request: true,
    doc_upload_link: true,
    round_calendar: true,
    work_task_assigned: true,
    work_task_overdue: true,
    inbound_sms: true,
    missed_call: true,
    voicemail: true,
    funding_doc_upload: true,
    funding_application_created: true,
    get_credit_report_lead: true,
    progress_report_alerts: true,
    morning_digest: true,
  };
}

function defaultAdminNotificationPrefs(): AdminNotificationPrefs {
  const all = allAdminNotifyEventsOn();
  return {
    email: { ...all },
    in_app: { ...all },
    // Morning digest is email/in-app — SMS body would be too long
    sms: { ...all, morning_digest: false },
  };
}

function mergeAdminNotifyChannel(
  raw: unknown,
  defaults: AdminNotifyEventToggles,
): AdminNotifyEventToggles {
  const out = { ...defaults };
  if (!raw || typeof raw !== "object") return out;
  const obj = raw as Record<string, unknown>;
  for (const key of ADMIN_NOTIFY_EVENT_KEYS) {
    if (typeof obj[key] === "boolean") out[key] = obj[key] as boolean;
  }
  return out;
}

function parseAdminNotificationPrefs(raw: unknown): AdminNotificationPrefs {
  const defaults = defaultAdminNotificationPrefs();
  if (!raw) return defaults;
  let parsed: unknown = raw;
  if (typeof raw === "string") {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return defaults;
    }
  }
  if (!parsed || typeof parsed !== "object") return defaults;
  const obj = parsed as Record<string, unknown>;
  return {
    email: mergeAdminNotifyChannel(obj.email, defaults.email),
    in_app: mergeAdminNotifyChannel(obj.in_app, defaults.in_app),
    sms: mergeAdminNotifyChannel(obj.sms, defaults.sms),
  };
}

function adminNotifyPrefOn(
  prefs: AdminNotificationPrefs,
  channel: AdminNotifyChannel,
  eventKey: AdminNotifyEventKey,
): boolean {
  return prefs[channel][eventKey] !== false;
}

/** Twilio account credentials present (SID/token). From numbers come from admin_phone_numbers. */
function isTwilioConfigured(): boolean {
  return !!(
    process.env.TWILIO_ACCOUNT_SID &&
    process.env.TWILIO_AUTH_TOKEN &&
    twilioClient
  );
}

/** Staff SMS (notify prefs / OTP) only when Twilio is up and this admin has an OFG number. */
async function adminSmsChannelAvailable(adminId: number): Promise<boolean> {
  if (!isTwilioConfigured()) return false;
  const phones = await listAssignedPhoneNumbers(adminId);
  return phones.length > 0;
}

async function resolveAssignedSmsFrom(adminId: number): Promise<string | null> {
  const phones = await listAssignedPhoneNumbers(adminId);
  return phones[0] ? String(phones[0].e164) : null;
}

function formatSmsClientFileNote(opts: {
  direction: "sent" | "received";
  ts: string;
  peerPhone: string;
  body: string;
  providerMessageId?: string | null;
  tag?: string;
  peerLabel?: string;
}): string {
  const verb = opts.direction === "sent" ? "Sent to" : "Received from";
  const tagPart = opts.tag ? `${opts.tag} ` : "";
  const peer =
    opts.direction === "sent" && opts.peerLabel
      ? `${opts.peerPhone} (${opts.peerLabel})`
      : opts.peerPhone;
  const parts = [
    `[SMS ${tagPart}${opts.ts} UTC] ${verb} ${peer}`,
    opts.body.slice(0, 1500),
  ];
  if (opts.providerMessageId) {
    parts.push(`Twilio SID: ${opts.providerMessageId}`);
  }
  return parts.join("\n");
}

async function appendClientFileSmsNote(
  clientId: number,
  stamped: string,
): Promise<boolean> {
  try {
    await pool.query(
      `UPDATE clients
       SET admin_notes = CONCAT(
             COALESCE(admin_notes, ''),
             CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
             ?
           )
       WHERE id = ?`,
      [stamped.slice(0, 8000), clientId],
    );
    return true;
  } catch (noteErr: any) {
    console.error("[sms] client file note", noteErr?.message ?? noteErr);
    return false;
  }
}

/** Append outreach log to CRM Contacts address-book `admin_notes`. */
async function appendContactFileNote(
  contactId: number,
  stamped: string,
): Promise<boolean> {
  try {
    await pool.query(
      `UPDATE contacts
       SET admin_notes = CONCAT(
             COALESCE(admin_notes, ''),
             CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
             ?
           )
       WHERE id = ? AND deleted_at IS NULL`,
      [stamped.slice(0, 8000), contactId],
    );
    return true;
  } catch (noteErr: any) {
    console.error("[contact] file note", noteErr?.message ?? noteErr);
    return false;
  }
}

async function adminNotifyChannelMetaForAdmin(
  adminId: number,
): Promise<
  Record<
    AdminNotifyChannel,
    { available: boolean; disabled_reason?: string | null }
  >
> {
  const twilioOk = isTwilioConfigured();
  const hasNumber = twilioOk
    ? (await listAssignedPhoneNumbers(adminId)).length > 0
    : false;
  const smsOk = twilioOk && hasNumber;
  return {
    email: { available: true, disabled_reason: null },
    in_app: { available: true, disabled_reason: null },
    sms: {
      available: smsOk,
      disabled_reason: smsOk
        ? null
        : !twilioOk
          ? "sms_twilio_not_configured"
          : "sms_ofg_number_required",
    },
  };
}

async function insertAdminInAppNotification(opts: {
  adminId: number;
  eventKey: AdminNotifyEventKey;
  title: string;
  body: string;
  linkUrl: string;
  payload?: Record<string, unknown>;
}): Promise<number | null> {
  const [ins] = await pool.query<ResultSetHeader>(
    `INSERT INTO admin_notifications
       (admin_id, event_key, title, body, link_url, payload_json)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [
      opts.adminId,
      opts.eventKey,
      opts.title.slice(0, 255),
      opts.body || null,
      opts.linkUrl || null,
      opts.payload ? JSON.stringify(opts.payload) : null,
    ],
  );
  return ins.insertId ? Number(ins.insertId) : null;
}

async function mintAdminAblyTokenRequest(adminId: number) {
  if (ablyKeyRejected) return null;
  const key = String(process.env.ABLY_API_KEY || "")
    .trim()
    .replace(/^["']|["']$/g, "");
  if (!key || !/^[-\w]+\.[-\w]+:.+$/.test(key)) return null;
  const capability: Record<string, string[]> = {
    [`admin:${adminId}:notifications`]: ["subscribe"],
  };
  if (await adminHasConversationsAccess(adminId)) {
    capability[`admin:${adminId}:conversations`] = ["subscribe", "presence"];
    // Softphone simultaneous-ring dismissal (GlobalVoiceManager)
    capability["voice:incoming"] = ["subscribe"];
  }
  const Ably = (await import("ably")).default;
  const rest = new Ably.Rest({ key });
  return rest.auth.createTokenRequest({
    clientId: `admin-${adminId}`,
    capability: capability as import("ably").TokenParams["capability"],
  });
}

async function publishAdminBellRealtime(
  adminId: number,
  payload: Record<string, unknown> = {},
): Promise<void> {
  if (ablyKeyRejected) return;
  const key = String(process.env.ABLY_API_KEY || "")
    .trim()
    .replace(/^["']|["']$/g, "");
  if (!key || !/^[-\w]+\.[-\w]+:.+$/.test(key) || process.env.VITEST === "true")
    return;
  try {
    const Ably = (await import("ably")).default;
    const rest = new Ably.Rest({ key });
    const channel = rest.channels.get(`admin:${adminId}:notifications`);
    await channel.publish("new", payload);
  } catch (e: any) {
    const msg = String(e?.message ?? e);
    if (/invalid key/i.test(msg)) ablyKeyRejected = true;
    console.warn("[ably] bell publish failed", msg);
  }
}

/** In-app bell (+ optional Ably), email, and SMS alert when inbound SMS hits an OFG line.
 * SMS alert = notify staff cell (not a relay); replies stay in Conversations.
 * Also fans out Settings → extra notify emails.
 */
async function notifyAdminInboundSms(opts: {
  adminId: number;
  fromLabel: string;
  preview: string;
  linkUrl: string;
  providerMessageId?: string | null;
  clientId?: number | null;
  unknownContactId?: number | null;
}): Promise<void> {
  const adminId = opts.adminId;
  if (!adminId) return;

  if (opts.providerMessageId) {
    const [dup] = await pool.query<RowDataPacket[]>(
      `SELECT id FROM admin_notifications
       WHERE admin_id = ? AND event_key = 'inbound_sms'
         AND JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.provider_message_id')) = ?
       LIMIT 1`,
      [adminId, opts.providerMessageId],
    );
    if (dup[0]) return;
  }

  const [aRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, phone, preferred_language, notification_prefs_json FROM admins
     WHERE id = ? AND status = 'active' LIMIT 1`,
    [adminId],
  );
  if (!aRows[0]) return;
  const prefs = parseAdminNotificationPrefs(aRows[0].notification_prefs_json);
  const title = `SMS from ${opts.fromLabel}`.slice(0, 255);
  const body = String(opts.preview || "New message").slice(0, 500);
  const absoluteLink = opts.linkUrl.startsWith("http")
    ? opts.linkUrl
    : `${APP_URL}${opts.linkUrl.startsWith("/") ? "" : "/"}${opts.linkUrl}`;

  if (adminNotifyPrefOn(prefs, "in_app", "inbound_sms")) {
    const notifId = await insertAdminInAppNotification({
      adminId,
      eventKey: "inbound_sms",
      title,
      body,
      linkUrl: opts.linkUrl,
      payload: {
        provider_message_id: opts.providerMessageId || null,
        client_id: opts.clientId ?? null,
        unknown_contact_id: opts.unknownContactId ?? null,
      },
    });
    if (notifId) {
      await publishAdminBellRealtime(adminId, {
        notification_id: notifId,
        event_key: "inbound_sms",
      });
    }
  }

  const adminEmail = String(aRows[0].email || "")
    .trim()
    .toLowerCase();
  const adminLang = aRows[0].preferred_language === "es" ? "es" : "en";
  const emailTpl = tplAdminInboundSmsAlert({
    adminFirstName: String(aRows[0].first_name || "Team"),
    fromLabel: opts.fromLabel,
    preview: body,
    linkUrl: absoluteLink,
    lang: adminLang,
  });

  const emailed = new Set<string>();
  if (
    adminEmail &&
    isValidEmail(adminEmail) &&
    adminNotifyPrefOn(prefs, "email", "inbound_sms")
  ) {
    try {
      await sendEmail({
        to: adminEmail,
        subject: emailTpl.subject,
        html: emailTpl.html,
      });
      emailed.add(adminEmail);
    } catch (e: any) {
      console.error(
        `[notify:inbound_sms:email] ${adminEmail}:`,
        e?.message ?? e,
      );
    }
  }

  await emailAdminNotifyExtraRecipients({
    subject: emailTpl.subject,
    html: emailTpl.html,
    eventKey: "inbound_sms",
    skipEmails: emailed,
  });

  // Alert SMS to personal cell (same pattern as missed_call / voicemail).
  if (adminNotifyPrefOn(prefs, "sms", "inbound_sms")) {
    const adminPhone = String(aRows[0].phone || "").trim();
    if (adminPhone) {
      try {
        const from = await resolveAssignedSmsFrom(adminId);
        if (!from) {
          // No OFG From number — skip (same as deliverAdminNotificationChannels)
        } else {
          const toDigits = normalizePhoneDigits(adminPhone);
          const fromDigits = normalizePhoneDigits(from);
          if (toDigits && fromDigits && toDigits === fromDigits) {
            // Never SMS an OFG line to itself
          } else {
            const prefix =
              adminLang === "es"
                ? `OFG SMS de ${opts.fromLabel}: ${body}`
                : `OFG SMS from ${opts.fromLabel}: ${body}`;
            const smsBody = `${prefix.slice(0, 260)}\n${absoluteLink}`.slice(
              0,
              320,
            );
            await sendSms({
              to: adminPhone,
              body: smsBody,
              from,
            });
          }
        }
      } catch (e: any) {
        console.error(
          `[notify:inbound_sms:sms] admin ${adminId}:`,
          e?.message ?? e,
        );
      }
    }
  }
}

function tplAdminInboundSmsAlert(opts: {
  adminFirstName: string;
  fromLabel: string;
  preview: string;
  linkUrl: string;
  lang?: string;
}) {
  const isEs = opts.lang === "es";
  const headline = isEs ? "SMS entrante" : "Inbound SMS";
  const body = isEs
    ? `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">${escapeHtml(headline)}</h1>
       <p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#334155;">Hola ${escapeHtml(opts.adminFirstName)},</p>
       <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">
         Mensaje de <strong>${escapeHtml(opts.fromLabel)}</strong>:
       </p>
       <p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#334155;padding:12px;background:#f8fafc;border-radius:8px;">
         ${escapeHtml(opts.preview)}
       </p>
       ${emailButton(opts.linkUrl, "Abrir conversaciones")}`
    : `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">${escapeHtml(headline)}</h1>
       <p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#334155;">Hi ${escapeHtml(opts.adminFirstName)},</p>
       <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">
         Message from <strong>${escapeHtml(opts.fromLabel)}</strong>:
       </p>
       <p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#334155;padding:12px;background:#f8fafc;border-radius:8px;">
         ${escapeHtml(opts.preview)}
       </p>
       ${emailButton(opts.linkUrl, "Open conversations")}`;
  return {
    subject: isEs ? `SMS de ${opts.fromLabel}` : `SMS from ${opts.fromLabel}`,
    html: emailLayout({
      title: headline,
      preheader: opts.preview.slice(0, 80),
      bodyHtml: body,
      lang: opts.lang,
    }),
  };
}

function parseNotifyExtraEvents(raw: unknown): AdminNotifyEventKey[] | null {
  if (raw == null || raw === "") return null;
  let parsed: unknown = raw;
  if (typeof raw === "string") {
    try {
      parsed = JSON.parse(raw);
    } catch {
      return null;
    }
  }
  if (!Array.isArray(parsed)) return null;
  const allowed = new Set<string>(ADMIN_NOTIFY_EVENT_KEYS);
  return parsed
    .map((x) => String(x))
    .filter((k): k is AdminNotifyEventKey => allowed.has(k));
}

/** undefined = omit from update; null = all events; [] = none; else selected keys. */
function normalizeNotifyExtraEventsInput(
  raw: unknown,
): AdminNotifyEventKey[] | null | undefined {
  if (raw === undefined) return undefined;
  if (raw === null) return null;
  if (!Array.isArray(raw)) return undefined;
  return parseNotifyExtraEvents(raw) ?? [];
}

function mapNotifyExtraEmailRow(r: RowDataPacket) {
  return {
    id: Number(r.id),
    email: String(r.email),
    label: r.label ? String(r.label) : null,
    is_active: !!r.is_active,
    events: parseNotifyExtraEvents(r.events_json),
    created_at: r.created_at,
    updated_at: r.updated_at,
  };
}

function notifyExtraAllowsEvent(
  events: AdminNotifyEventKey[] | null,
  eventKey: AdminNotifyEventKey,
): boolean {
  if (events == null) return true;
  return events.includes(eventKey);
}

async function listActiveNotifyExtraEmails(): Promise<
  {
    id: number;
    email: string;
    label: string | null;
    events: AdminNotifyEventKey[] | null;
  }[]
> {
  try {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, email, label, events_json FROM admin_notify_extra_emails
       WHERE is_active = 1
       ORDER BY id ASC`,
    );
    const out: {
      id: number;
      email: string;
      label: string | null;
      events: AdminNotifyEventKey[] | null;
    }[] = [];
    for (const r of rows) {
      const email = String(r.email || "")
        .trim()
        .toLowerCase();
      if (!email || !isValidEmail(email)) continue;
      if (
        isUndeliverableNotifyEmail(email) &&
        process.env.VITEST !== "true"
      ) {
        continue;
      }
      out.push({
        id: Number(r.id),
        email,
        label: r.label ? String(r.label) : null,
        events: parseNotifyExtraEvents(r.events_json),
      });
    }
    return out;
  } catch (e: any) {
    console.warn(
      "[notify:extra_emails] list failed (table missing?):",
      e?.message ?? e,
    );
    return [];
  }
}

/** Email-only fan-out to Settings → Notifications list (skips already-sent addresses). */
async function emailAdminNotifyExtraRecipients(opts: {
  subject: string;
  html: string;
  eventKey: AdminNotifyEventKey;
  skipEmails?: Set<string>;
  lang?: string;
}): Promise<number> {
  const extras = await listActiveNotifyExtraEmails();
  if (!extras.length) return 0;
  const skip = opts.skipEmails || new Set<string>();
  const brandedHtml = ensureBrandedEmailHtml({
    title: opts.subject,
    html: opts.html,
    lang: opts.lang,
  });
  let sent = 0;
  await Promise.all(
    extras.map(async (row) => {
      if (skip.has(row.email)) return;
      if (!notifyExtraAllowsEvent(row.events, opts.eventKey)) return;
      try {
        await sendEmail({
          to: row.email,
          subject: opts.subject,
          html: brandedHtml,
        });
        sent += 1;
        skip.add(row.email);
      } catch (e: any) {
        console.error(`[notify:extra_email] ${row.email}:`, e?.message ?? e);
      }
    }),
  );
  return sent;
}

/**
 * Vitest / integration-test mailbox domains. Never fan out team alerts or
 * surface these rows in production staff UI (People, Team notifications, MCP).
 * Keep in sync with api/testDbCleanup.ts TEST_EMAIL_SUFFIXES.
 */
function isIntegrationTestAdminEmail(email: string | null | undefined): boolean {
  const e = String(email || "")
    .trim()
    .toLowerCase();
  return e.endsWith("@example.test") || e.endsWith("@affiliate.test");
}

/** SQL AND-fragment for admins queries (leading AND). */
const SQL_EXCLUDE_INTEGRATION_TEST_ADMIN_EMAIL = `
  AND LOWER(TRIM(COALESCE(email, ''))) NOT LIKE '%@example.test'
  AND LOWER(TRIM(COALESCE(email, ''))) NOT LIKE '%@affiliate.test'`;

/** Hide fixture staff from People / Settings UI outside Vitest. */
function hideIntegrationTestStaffFromAdminUi(): boolean {
  return process.env.VITEST !== "true";
}

type TeamAdminRecipient = {
  id: number;
  email: string;
  first_name: string;
  phone: string | null;
  preferred_language: string | null;
  prefs: AdminNotificationPrefs;
};

/** Active Optimum staff (excludes affiliate portal users).
 * Outside Vitest, skip leftover `@example.test` / `@affiliate.test` fixture
 * admins so they never receive real purchase/inbound fan-out. Under Vitest,
 * include them so ephemeral-agent suites (e.g. notification prefs) can assert
 * delivery without mutating real staff prefs. */
async function listActiveTeamAdmins(): Promise<TeamAdminRecipient[]> {
  const excludeFixtures = process.env.VITEST !== "true";
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, phone, preferred_language, notification_prefs_json
     FROM admins
     WHERE status = 'active'
       AND role IN ('super_admin', 'admin', 'agent')
       AND email IS NOT NULL AND TRIM(email) <> ''
       ${excludeFixtures ? SQL_EXCLUDE_INTEGRATION_TEST_ADMIN_EMAIL : ""}`,
  );
  return rows.map((r) => ({
    id: Number(r.id),
    email: String(r.email),
    first_name: String(r.first_name || "Admin"),
    phone: r.phone ? String(r.phone) : null,
    preferred_language: (r.preferred_language as string) || "en",
    prefs: parseAdminNotificationPrefs(r.notification_prefs_json),
  }));
}

async function gatherMorningDigestSnapshot(
  admin: TeamAdminRecipient,
): Promise<MorningDigestSnapshot> {
  const adminId = admin.id;
  const lang: MorningDigestLang =
    admin.preferred_language === "es" ? "es" : "en";
  const dateLabel = new Intl.DateTimeFormat(lang === "es" ? "es-US" : "en-US", {
    timeZone: "America/Denver",
    weekday: "long",
    month: "short",
    day: "numeric",
  }).format(new Date());

  const [stageRows] = await pool.query<RowDataPacket[]>(
    `SELECT pipeline_stage AS stage, COUNT(*) AS cnt
     FROM clients
     WHERE assigned_admin_id = ?
       AND status <> 'cancelled'
     GROUP BY pipeline_stage
     ORDER BY cnt DESC`,
    [adminId],
  );

  const [statusRows] = await pool.query<RowDataPacket[]>(
    `SELECT
       SUM(status = 'prospect') AS prospects,
       SUM(status = 'active') AS active_clients,
       SUM(status = 'onboarding') AS onboarding,
       SUM(status = 'pending_payment') AS pending_payment
     FROM clients
     WHERE assigned_admin_id = ?
       AND status <> 'cancelled'`,
    [adminId],
  );

  const [prospectRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name, phone, pipeline_stage
     FROM clients
     WHERE assigned_admin_id = ?
       AND status = 'prospect'
     ORDER BY updated_at DESC
     LIMIT 8`,
    [adminId],
  );

  const [clientRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name, status, pipeline_stage
     FROM clients
     WHERE assigned_admin_id = ?
       AND status IN ('active', 'onboarding', 'pending_payment', 'funding')
     ORDER BY updated_at DESC
     LIMIT 12`,
    [adminId],
  );

  const [taskRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, title, status, priority, due_at
     FROM admin_work_tasks
     WHERE assignee_admin_id = ?
       AND status <> 'done'
     ORDER BY
       CASE WHEN due_at IS NOT NULL AND due_at < NOW() THEN 0 ELSE 1 END,
       due_at IS NULL, due_at ASC
     LIMIT 15`,
    [adminId],
  );

  const [convRows] = await pool.query<RowDataPacket[]>(
    `SELECT cv.id, cv.client_id, cv.unread_count, cv.last_message_preview,
            cv.last_message_at, cv.status,
            c.first_name, c.last_name
     FROM conversations cv
     LEFT JOIN clients c ON c.id = cv.client_id
     WHERE cv.assigned_admin_id = ?
       AND cv.status IN ('open', 'snoozed')
     ORDER BY cv.unread_count DESC, cv.last_message_at DESC
     LIMIT 10`,
    [adminId],
  );

  const tasks = taskRows.map((t) => {
    const due = t.due_at ? new Date(t.due_at as string) : null;
    const overdue = !!(due && due.getTime() < Date.now());
    return {
      id: Number(t.id),
      title: String(t.title || "Task"),
      status: String(t.status || ""),
      priority: t.priority != null ? String(t.priority) : null,
      due_at: t.due_at ? String(t.due_at) : null,
      overdue,
    };
  });

  const conversations = convRows.map((cv) => ({
    id: Number(cv.id),
    client_id: cv.client_id != null ? Number(cv.client_id) : null,
    who:
      `${cv.first_name || ""} ${cv.last_name || ""}`.trim() ||
      (lang === "es" ? "Contacto" : "Contact"),
    unread: Number(cv.unread_count || 0),
    preview: cv.last_message_preview
      ? decodeLiteralUnicodeEscapes(String(cv.last_message_preview)).slice(0, 140)
      : null,
    status: String(cv.status || ""),
  }));

  const st = (statusRows[0] || {}) as {
    prospects?: number | string | null;
    active_clients?: number | string | null;
    onboarding?: number | string | null;
    pending_payment?: number | string | null;
  };
  return {
    admin: {
      id: adminId,
      first_name: admin.first_name,
      preferred_language: lang,
    },
    date_label: dateLabel,
    counts: {
      prospects: Number(st.prospects || 0),
      active_clients: Number(st.active_clients || 0),
      onboarding: Number(st.onboarding || 0),
      pending_payment: Number(st.pending_payment || 0),
      open_tasks: tasks.length,
      overdue_tasks: tasks.filter((t) => t.overdue).length,
      open_conversations: conversations.length,
      unread_messages: conversations.reduce((n, c) => n + c.unread, 0),
    },
    pipeline_stages: stageRows.map((r) => ({
      stage: String(r.stage || ""),
      count: Number(r.cnt || 0),
    })),
    prospects: prospectRows.map((p) => ({
      id: Number(p.id),
      name: `${p.first_name || ""} ${p.last_name || ""}`.trim(),
      phone: p.phone ? String(p.phone) : null,
      stage: p.pipeline_stage ? String(p.pipeline_stage) : null,
    })),
    clients: clientRows.map((c) => ({
      id: Number(c.id),
      name: `${c.first_name || ""} ${c.last_name || ""}`.trim(),
      status: String(c.status || ""),
      stage: String(c.pipeline_stage || ""),
    })),
    tasks,
    conversations,
    app_url: APP_URL,
  };
}

async function runClaudeMorningDigestBrief(
  snapshot: MorningDigestSnapshot,
): Promise<{
  brief: MorningDigestClaudeBrief;
  enhanced: boolean;
  error?: string;
}> {
  const fallback = buildDeterministicMorningBrief(snapshot);
  const apiKey = String(process.env.ANTHROPIC_API_KEY || "").trim();
  if (!apiKey) {
    return {
      brief: fallback,
      enhanced: false,
      error: "ANTHROPIC_API_KEY not set",
    };
  }
  const model =
    String(process.env.ANTHROPIC_MODEL || "").trim() || "claude-sonnet-4-6";
  try {
    const resp = await axios.post(
      "https://api.anthropic.com/v1/messages",
      {
        model,
        max_tokens: 1200,
        temperature: 0.4,
        system: ADMIN_MORNING_DIGEST_SYSTEM,
        messages: [
          {
            role: "user",
            content: JSON.stringify({
              preferred_language: snapshot.admin.preferred_language,
              first_name: snapshot.admin.first_name,
              date_label: snapshot.date_label,
              counts: snapshot.counts,
              pipeline_stages: snapshot.pipeline_stages,
              prospects: snapshot.prospects,
              clients: snapshot.clients,
              tasks: snapshot.tasks,
              conversations: snapshot.conversations,
            }),
          },
        ],
      },
      {
        headers: {
          "x-api-key": apiKey,
          "anthropic-version": "2023-06-01",
          "content-type": "application/json",
        },
        timeout: 22_000,
      },
    );
    const text = String(resp.data?.content?.[0]?.text || "").trim();
    const parsed = parseClaudeMorningDigestJson(text);
    if (!parsed) {
      return {
        brief: fallback,
        enhanced: false,
        error: "Claude JSON parse failed",
      };
    }
    return { brief: parsed, enhanced: true };
  } catch (e: any) {
    return {
      brief: fallback,
      enhanced: false,
      error: String(e?.message || e).slice(0, 200),
    };
  }
}

async function morningDigestAlreadySent(
  adminId: number,
  denverYmd: string,
): Promise<boolean> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM audit_logs
     WHERE actor_type = 'system'
       AND action = 'morning_digest.sent'
       AND entity_type = 'admin'
       AND entity_id = ?
       AND JSON_UNQUOTE(JSON_EXTRACT(changes_json, '$.denver_ymd')) = ?
     LIMIT 1`,
    [adminId, denverYmd],
  );
  return !!rows[0];
}

/**
 * Atomically claim today's digest slot for an admin (one row per Denver day).
 * Returns audit_logs.id when claimed, or null if already sent/claimed today.
 */
async function claimMorningDigestDay(
  adminId: number,
  denverYmd: string,
): Promise<number | null> {
  const [result] = await pool.query<ResultSetHeader>(
    `INSERT INTO audit_logs
       (actor_type, actor_id, action, entity_type, entity_id, changes_json, status)
     SELECT 'system', NULL, 'morning_digest.sent', 'admin', ?, ?, 'success'
     FROM DUAL
     WHERE NOT EXISTS (
       SELECT 1 FROM audit_logs
       WHERE actor_type = 'system'
         AND action = 'morning_digest.sent'
         AND entity_type = 'admin'
         AND entity_id = ?
         AND JSON_UNQUOTE(JSON_EXTRACT(changes_json, '$.denver_ymd')) = ?
       LIMIT 1
     )`,
    [
      adminId,
      JSON.stringify({
        denver_ymd: denverYmd,
        claimed_at: new Date().toISOString(),
        pending: true,
      }),
      adminId,
      denverYmd,
    ],
  );
  if (!Number(result.affectedRows || 0)) return null;
  return Number(result.insertId);
}

async function finalizeMorningDigestSent(
  auditId: number,
  denverYmd: string,
  meta: Record<string, unknown>,
): Promise<void> {
  await pool.query(
    `UPDATE audit_logs
     SET changes_json = ?, status = 'success'
     WHERE id = ?`,
    [
      JSON.stringify({ denver_ymd: denverYmd, pending: false, ...meta }),
      auditId,
    ],
  );
}

async function markMorningDigestSent(
  adminId: number,
  denverYmd: string,
  meta: Record<string, unknown>,
): Promise<void> {
  await pool.query(
    `INSERT INTO audit_logs
       (actor_type, actor_id, action, entity_type, entity_id, changes_json, status)
     VALUES ('system', NULL, 'morning_digest.sent', 'admin', ?, ?, 'success')`,
    [adminId, JSON.stringify({ denver_ymd: denverYmd, ...meta })],
  );
}

type TeamAdminNotifyBuild = {
  subject: string;
  html: string;
  inAppTitle: string;
  inAppBody: string;
  linkUrl: string;
  smsBody?: string;
};

async function deliverAdminNotificationChannels(opts: {
  admin: TeamAdminRecipient;
  eventKey: AdminNotifyEventKey;
  tpl: TeamAdminNotifyBuild;
}): Promise<{ email: boolean; in_app: boolean; sms: boolean }> {
  const { admin, eventKey, tpl } = opts;
  const result = { email: false, in_app: false, sms: false };
  const adminLang = admin.preferred_language === "es" ? "es" : "en";
  const brandedHtml = ensureBrandedEmailHtml({
    title: tpl.subject,
    html: tpl.html,
    lang: adminLang,
  });

  if (adminNotifyPrefOn(admin.prefs, "email", eventKey)) {
    try {
      await sendEmail({
        to: admin.email,
        subject: tpl.subject,
        html: brandedHtml,
      });
      result.email = true;
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:email] ${admin.email}:`,
        e?.message ?? e,
      );
    }
  }

  if (adminNotifyPrefOn(admin.prefs, "in_app", eventKey)) {
    try {
      const notifId = await insertAdminInAppNotification({
        adminId: admin.id,
        eventKey,
        title: tpl.inAppTitle,
        body: tpl.inAppBody,
        linkUrl: tpl.linkUrl,
      });
      result.in_app = true;
      if (notifId) {
        await publishAdminBellRealtime(admin.id, {
          notification_id: notifId,
          event_key: eventKey,
        });
      }
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:in_app] admin ${admin.id}:`,
        e?.message ?? e,
      );
    }
  }

  if (adminNotifyPrefOn(admin.prefs, "sms", eventKey) && admin.phone) {
    try {
      const from = await resolveAssignedSmsFrom(admin.id);
      if (!from) {
        // No OFG number → SMS notifications stay off for this staff member
      } else {
        const smsText =
          tpl.smsBody || `${tpl.inAppTitle}: ${tpl.inAppBody}`.slice(0, 320);
        await sendSms({ to: admin.phone, body: smsText, from });
        result.sms = true;
      }
    } catch (e: any) {
      console.error(
        `[notify:${eventKey}:sms] ${admin.phone}:`,
        e?.message ?? e,
      );
    }
  }

  return result;
}

async function notifyAllTeamAdmins(
  eventKey: AdminNotifyEventKey,
  build: (admin: TeamAdminRecipient) => TeamAdminNotifyBuild,
): Promise<{ sent: number; errors: string[] }> {
  const admins = await listActiveTeamAdmins();
  if (admins.length === 0) {
    console.warn(
      "[notifyAllTeamAdmins] no active team admins with email — alert skipped",
    );
    return { sent: 0, errors: ["no_active_team_admins"] };
  }
  const errors: string[] = [];
  let sent = 0;
  const emailedAdmins = new Set<string>();
  let sampleEmailTpl: { subject: string; html: string } | null = null;
  await Promise.all(
    admins.map(async (admin) => {
      try {
        const tpl = build(admin);
        if (!sampleEmailTpl) {
          sampleEmailTpl = { subject: tpl.subject, html: tpl.html };
        }
        const delivered = await deliverAdminNotificationChannels({
          admin,
          eventKey,
          tpl,
        });
        if (delivered.email) {
          emailedAdmins.add(admin.email.trim().toLowerCase());
        }
        if (delivered.email || delivered.in_app || delivered.sms) sent += 1;
      } catch (e: any) {
        errors.push(`${admin.email}: ${e?.message ?? e}`);
      }
    }),
  );
  if (sampleEmailTpl) {
    const extraSent = await emailAdminNotifyExtraRecipients({
      subject: sampleEmailTpl.subject,
      html: sampleEmailTpl.html,
      eventKey,
      skipEmails: emailedAdmins,
    });
    sent += extraSent;
  }
  if (errors.length) {
    console.error("[notifyAllTeamAdmins] partial failures:", errors.join("; "));
  }
  return { sent, errors };
}

/**
 * Email the language-owner admin when a client is sent a document upload link.
 */
async function notifyLanguageOwnerDocUploadLink(opts: {
  clientId: number;
  firstName: string;
  lastName: string;
  clientEmail: string;
  lang: string;
  portalUrl: string;
  assignedAdminId?: number | null;
  caseId?: number | null;
}): Promise<void> {
  let ownerId = opts.assignedAdminId ?? null;
  if (!ownerId) {
    const [cRows] = await pool.query<RowDataPacket[]>(
      `SELECT assigned_admin_id, preferred_language FROM clients WHERE id = ? LIMIT 1`,
      [opts.clientId],
    );
    ownerId = cRows[0]?.assigned_admin_id
      ? Number(cRows[0].assigned_admin_id)
      : await resolveLanguageOwnerAdminId(
          cRows[0]?.preferred_language === "es" ? "es" : "en",
        );
  }
  if (!ownerId) return;
  const [aRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, phone, preferred_language, status, notification_prefs_json
     FROM admins WHERE id = ? LIMIT 1`,
    [ownerId],
  );
  const adminRow = aRows[0];
  if (!adminRow || adminRow.status !== "active" || !adminRow.email) return;
  const admin: TeamAdminRecipient = {
    id: Number(adminRow.id),
    email: String(adminRow.email),
    first_name: String(adminRow.first_name || "Admin"),
    phone: adminRow.phone ? String(adminRow.phone) : null,
    preferred_language: (adminRow.preferred_language as string) || "en",
    prefs: parseAdminNotificationPrefs(adminRow.notification_prefs_json),
  };
  const adminLang = admin.preferred_language === "es" ? "es" : "en";
  const caseUploadUrl = opts.caseId
    ? `${APP_URL}/admin/pipeline?case=${opts.caseId}`
    : `${APP_URL}/admin/clients`;
  const tplEmail = tplAdminDocUploadLinkAlert({
    adminFirstName: admin.first_name,
    clientName: `${opts.firstName} ${opts.lastName}`.trim(),
    clientEmail: opts.clientEmail,
    portalUrl: opts.portalUrl,
    caseUploadUrl,
    lang: adminLang,
  });
  const clientName = `${opts.firstName} ${opts.lastName}`.trim();
  await deliverAdminNotificationChannels({
    admin,
    eventKey: "doc_upload_link",
    tpl: {
      subject: tplEmail.subject,
      html: tplEmail.html,
      inAppTitle:
        adminLang === "es" ? "Enlace de carga enviado" : "Upload link sent",
      inAppBody:
        adminLang === "es"
          ? `Se envió el enlace del portal a ${clientName}.`
          : `Portal upload link sent to ${clientName}.`,
      linkUrl: caseUploadUrl,
      smsBody: `Optimum: upload link sent to ${clientName}`,
    },
  });
}

