/**
 * Resolves the primary active case for a client (package preferred, then newest).
 */
async function resolvePrimaryActiveCaseId(
  db: Pick<Pool, "query">,
  clientId: number,
): Promise<number | null> {
  const [rows] = await db.query<RowDataPacket[]>(
    `SELECT id FROM credit_repair_cases
     WHERE client_id = ? AND status = 'active'
     ORDER BY (package_id IS NOT NULL) DESC, id DESC
     LIMIT 1`,
    [clientId],
  );
  return (rows[0]?.id as number) ?? null;
}

/**
 * Creates client_task_completions rows for all active, auto_assign=1 templates
 * for a specific case. Safe to call multiple times (INSERT IGNORE).
 */
async function autoAssignTasksForCase(
  clientId: number,
  caseId: number,
): Promise<void> {
  const [templates] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM onboarding_task_templates
     WHERE is_active = 1 AND auto_assign = 1
     ORDER BY sort_order ASC, id ASC`,
  );
  if (templates.length === 0) return;

  const values = templates.map(() => "(?, ?, ?, 'pending')").join(", ");
  const params = templates.flatMap((t) => [clientId, caseId, t.id]);

  await pool.query<ResultSetHeader>(
    `INSERT IGNORE INTO client_task_completions (client_id, case_id, task_template_id, status)
     VALUES ${values}`,
    params,
  );
}

async function autoAssignTasksForClient(
  clientId: number,
  caseId?: number,
): Promise<void> {
  const resolved = caseId ?? (await resolvePrimaryActiveCaseId(pool, clientId));
  if (!resolved) return;
  await autoAssignTasksForCase(clientId, resolved);
}

/**
 * When staff uploads a case doc (id_front/id_back/ssn_card/proof_of_address),
 * mirror it onto the matching onboarding upload task as completed + approved
 * so the Tasks checklist and docs_ready rules stay in sync with portal uploads.
 */
async function syncAdminUploadToMatchingTask(opts: {
  clientId: number;
  caseId: number;
  docType: string;
  fileStorageKey: string;
  fileName: string;
  fileMime: string;
  adminId: number;
}): Promise<boolean> {
  const uploadSlugs = ["id_front", "id_back", "ssn_card", "proof_of_address"];
  if (!uploadSlugs.includes(opts.docType)) return false;

  const [tplRows] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM onboarding_task_templates
     WHERE slug = ? AND task_type = 'upload' AND is_active = 1
     LIMIT 1`,
    [opts.docType],
  );
  if (!tplRows[0]) return false;
  const templateId = Number(tplRows[0].id);

  await pool.query<ResultSetHeader>(
    `INSERT INTO client_task_completions
       (client_id, case_id, task_template_id, status,
        file_storage_key, file_name, file_mime, completed_at,
        admin_review_status, admin_notes, admin_reviewed_at)
     VALUES (?, ?, ?, 'completed', ?, ?, ?, NOW(), 'approved', ?, NOW())
     ON DUPLICATE KEY UPDATE
       status = 'completed',
       file_storage_key = VALUES(file_storage_key),
       file_name = VALUES(file_name),
       file_mime = VALUES(file_mime),
       completed_at = NOW(),
       admin_review_status = 'approved',
       admin_notes = VALUES(admin_notes),
       admin_reviewed_at = NOW()`,
    [
      opts.clientId,
      opts.caseId,
      templateId,
      opts.fileStorageKey,
      opts.fileName,
      opts.fileMime,
      `Admin upload by #${opts.adminId}`,
    ],
  );
  return true;
}

/**
 * Docs Verified auto-advance: only when EVERY active required task for the
 * case is approved (uploads + service_agreement, etc.). Never advances early.
 */
async function countRequiredTasksApproved(caseId: number): Promise<{
  requiredTotal: number;
  approvedCount: number;
}> {
  const [[reqRow]] = await pool.query<RowDataPacket[]>(
    `SELECT COUNT(*) AS required_total FROM onboarding_task_templates
     WHERE is_active = 1 AND is_required = 1`,
  );
  const [[approvedRow]] = await pool.query<RowDataPacket[]>(
    `SELECT COUNT(*) AS approved_count
     FROM client_task_completions ctc
     JOIN onboarding_task_templates ott ON ott.id = ctc.task_template_id
     WHERE ctc.case_id = ? AND ctc.admin_review_status = 'approved'
       AND ott.is_required = 1 AND ott.is_active = 1`,
    [caseId],
  );
  return {
    requiredTotal: Number(reqRow.required_total || 0),
    approvedCount: Number(approvedRow.approved_count || 0),
  };
}

/**
 * Gate Docs Verified: required templates must exist AND all must be approved
 * on this case. Prevents empty-task / migrated cases from sitting on docs_ready.
 */
async function assertDocsReadyTaskGate(
  caseId: number,
): Promise<{ ok: true } | { ok: false; message: string }> {
  const { requiredTotal, approvedCount } =
    await countRequiredTasksApproved(caseId);
  if (requiredTotal <= 0) {
    return {
      ok: false,
      message:
        "Cannot advance to Docs Verified — no required onboarding tasks are configured.",
    };
  }
  if (approvedCount < requiredTotal) {
    return {
      ok: false,
      message: `Cannot advance to Docs Verified — ${requiredTotal - approvedCount} required task(s) still need approval.`,
    };
  }
  return { ok: true };
}

async function maybeAutoAdvanceDocsReadyFromTasks(opts: {
  clientId: number;
  caseId: number;
  adminId: number;
}): Promise<boolean> {
  const [caseRows] = await pool.query<RowDataPacket[]>(
    `SELECT pipeline_stage FROM credit_repair_cases WHERE id = ? LIMIT 1`,
    [opts.caseId],
  );
  if (caseRows[0]?.pipeline_stage !== "new_client") return false;

  const gate = await assertDocsReadyTaskGate(opts.caseId);
  if (gate.ok === false) return false;

  await advanceCasePipeline(pool, {
    clientId: opts.clientId,
    caseId: opts.caseId,
    stage: "docs_ready",
    adminId: opts.adminId,
    notes: "Auto-advanced: all required tasks approved",
  });
  await pool.query<ResultSetHeader>(
    `UPDATE clients SET status = 'active' WHERE id = ? AND status <> 'active'`,
    [opts.clientId],
  );
  triggerReminderFlow("docs_ready", opts.clientId).catch((e) =>
    console.error("[flow:docs_ready]", e?.message),
  );
  return true;
}

const CASE_DOC_TYPES = [
  "id_front",
  "id_back",
  "ssn_card",
  "proof_of_address",
  "other",
  "funding_drivers_license",
  "funding_corp_statement",
  "funding_bank_m1",
  "funding_bank_m2",
  "funding_bank_m3",
  "funding_bank_m4",
  "funding_bank_m5",
  "funding_bank_m6",
] as const;

/** MIME types ATLAS / Admin AI may upload via upload_case_document (v1). */
const ADMIN_AI_DOC_ALLOWED_MIMES = new Set([
  "image/jpeg",
  "image/png",
  "image/heic",
  "image/heif",
  "application/pdf",
]);

/** Keep JSON tool payloads under Vercel body limits (~4.5MB incl. base64 overhead). */
const ADMIN_AI_DOC_MAX_BYTES = VERCEL_SAFE_UPLOAD_MAX_BYTES; // align MCP with CRM 4MB ceiling

function adminAiDocMimeFromFilename(
  fileName: string,
  mimeOverride?: string | null,
): string | null {
  const ov = mimeOverride ? String(mimeOverride).trim().toLowerCase() : "";
  if (ov && ADMIN_AI_DOC_ALLOWED_MIMES.has(ov)) return ov;
  const ext = fileName.split(".").pop()?.toLowerCase() || "";
  const byExt: Record<string, string> = {
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    png: "image/png",
    heic: "image/heic",
    heif: "image/heif",
    pdf: "application/pdf",
  };
  const mapped = byExt[ext];
  return mapped && ADMIN_AI_DOC_ALLOWED_MIMES.has(mapped) ? mapped : null;
}

function adminAiDecodeFileBase64(raw: string): Buffer | null {
  const s = String(raw || "").trim();
  if (!s) return null;
  const m = s.match(/^data:[^;]+;base64,(.+)$/i);
  const b64 = m ? m[1] : s;
  try {
    const buf = Buffer.from(b64, "base64");
    return buf.length > 0 ? buf : null;
  } catch {
    return null;
  }
}

function sha256BufferHex(buf: Buffer): string {
  return crypto.createHash("sha256").update(buf).digest("hex");
}

/** Encrypt, CDN upload, DB row, and onboarding-task sync for one admin case doc. */
async function persistAdminCaseDocumentUpload(opts: {
  clientId: number;
  caseId: number;
  docType: string;
  buffer: Buffer;
  fileName: string;
  mimeType: string;
  adminId: number;
  pipelineRound?: string | null;
}): Promise<{
  id: number;
  doc_type: string;
  file_name: string;
  file_size: number;
  mime_type: string;
  review_status: string;
  uploaded_by_admin_id: number;
  task_synced: boolean;
}> {
  const { encrypted, iv, tag } = encryptFile(opts.buffer);
  let storageProvider: "cdn" | "local" = "cdn";
  let storageKey: string;
  try {
    storageKey = await uploadToCDN(
      encrypted,
      opts.fileName + ".enc",
      "application/octet-stream",
      opts.clientId,
    );
    // uploadToCDN stubs under VITEST — mark local so file-serve never hits HostGator.
    if (storageKey.startsWith("vitest://")) storageProvider = "local";
  } catch (e: any) {
    if (process.env.VITEST !== "true") throw e;
    console.warn(
      "[admin:case-doc] CDN unavailable in VITEST — storing local key:",
      e?.message ?? e,
    );
    storageProvider = "local";
    storageKey = `vitest/case-docs/${opts.caseId}/${opts.docType}-${Date.now()}.enc`;
  }
  const [r] = await pool.query<ResultSetHeader>(
    `INSERT INTO client_documents
       (client_id, case_id, doc_type, pipeline_round, file_name, file_size, mime_type,
        storage_provider, storage_key, encrypted, enc_iv, enc_tag, review_status, uploaded_by_admin_id)
     VALUES (?,?,?,?,?,?,?, ?, ?, 1, ?, ?, 'approved', ?)`,
    [
      opts.clientId,
      opts.caseId,
      opts.docType,
      opts.pipelineRound ?? null,
      opts.fileName,
      opts.buffer.length,
      opts.mimeType,
      storageProvider,
      storageKey,
      iv,
      tag,
      opts.adminId,
    ],
  );
  const fileStorageKey = `${storageKey}|${iv}|${tag}`;
  const taskSynced = await syncAdminUploadToMatchingTask({
    clientId: opts.clientId,
    caseId: opts.caseId,
    docType: opts.docType,
    fileStorageKey,
    fileName: opts.fileName,
    fileMime: opts.mimeType,
    adminId: opts.adminId,
  });
  return {
    id: r.insertId,
    doc_type: opts.docType,
    file_name: opts.fileName,
    file_size: opts.buffer.length,
    mime_type: opts.mimeType,
    review_status: "approved",
    uploaded_by_admin_id: opts.adminId,
    task_synced: taskSynced,
  };
}

