type McpJwtLike = {
  actor: "admin";
  id: number;
  email: string;
  jti: string;
};

type McpAuthedReq = Request & { auth?: McpJwtLike };

type ToolDef = {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
};

type ExecuteTool = (
  name: string,
  args: Record<string, unknown>,
  ctx: { adminId: number },
) => Promise<AdminAiToolResult>;

