  app.get(
    "/api/admin/conversations/ably-token",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      if (ablyKeyRejected) {
        return res.status(503).json({ error: "ably_not_configured" });
      }
      try {
        const tokenRequest = await mintAdminAblyTokenRequest(req.auth!.id);
        if (!tokenRequest) {
          return res.status(503).json({ error: "ably_not_configured" });
        }
        res.json({ tokenRequest });
      } catch (e: any) {
        const msg = String(e?.message ?? e);
        console.error("[ably:token]", msg);
        // Misconfigured / revoked keys — soft-degrade (don't 500-loop the client)
        if (/invalid key/i.test(msg)) {
          ablyKeyRejected = true;
          return res.status(503).json({ error: "ably_not_configured" });
        }
        res.status(500).json({ error: "ably_token_failed" });
      }
    },
  );

  app.get(
    "/api/admin/phone-numbers",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const [roleRows] = await pool.query<RowDataPacket[]>(
        `SELECT role FROM admins WHERE id = ? LIMIT 1`,
        [req.auth!.id],
      );
      const role = String(roleRows[0]?.role || "");
      if (role === "super_admin" || role === "admin") {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT n.*, CONCAT(a.first_name,' ',a.last_name) AS assigned_admin_name
           FROM admin_phone_numbers n
           LEFT JOIN admins a ON a.id = n.assigned_admin_id
           ORDER BY n.id ASC`,
        );
        return res.json({ numbers: rows.map(mapPhoneNumberRow) });
      }
      const mine = await listAssignedPhoneNumbers(req.auth!.id);
      res.json({ numbers: mine.map(mapPhoneNumberRow) });
    },
  );

  /** Upsert Twilio IncomingPhoneNumbers into admin_phone_numbers (super_admin). */
  app.post(
    "/api/admin/phone-numbers/sync-twilio",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const [roleRows] = await pool.query<RowDataPacket[]>(
        `SELECT role FROM admins WHERE id = ? LIMIT 1`,
        [req.auth!.id],
      );
      if (String(roleRows[0]?.role || "") !== "super_admin") {
        return res.status(403).json({ error: "super_admin required" });
      }
      if (!twilioClient) {
        return res.status(503).json({ error: "Twilio not configured" });
      }
      try {
        const list = await twilioClient.incomingPhoneNumbers.list({
          limit: 200,
        });
        let upserted = 0;
        for (const n of list) {
          const e164 = String(n.phoneNumber || "").trim();
          if (!e164.startsWith("+")) continue;
          const caps = {
            sms: !!(n.capabilities as any)?.sms,
            mms: !!(n.capabilities as any)?.mms,
            voice: !!(n.capabilities as any)?.voice,
          };
          await pool.query(
            `INSERT INTO admin_phone_numbers
               (e164, friendly_name, twilio_sid, capabilities_json, is_active)
             VALUES (?, ?, ?, ?, 1)
             ON DUPLICATE KEY UPDATE
               friendly_name = VALUES(friendly_name),
               twilio_sid = VALUES(twilio_sid),
               capabilities_json = VALUES(capabilities_json),
               is_active = 1,
               updated_at = NOW()`,
            [
              e164,
              n.friendlyName || null,
              n.sid || null,
              JSON.stringify(caps),
            ],
          );
          upserted++;
        }
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT n.*, CONCAT(a.first_name,' ',a.last_name) AS assigned_admin_name
           FROM admin_phone_numbers n
           LEFT JOIN admins a ON a.id = n.assigned_admin_id
           ORDER BY n.id ASC`,
        );
        res.json({
          ok: true,
          upserted,
          numbers: rows.map(mapPhoneNumberRow),
        });
      } catch (e: any) {
        console.error("[phone-numbers:sync-twilio]", e?.message ?? e);
        res.status(500).json({
          error: e?.message || "Twilio sync failed",
        });
      }
    },
  );

  app.patch(
    "/api/admin/phone-numbers/:id",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const [roleRows] = await pool.query<RowDataPacket[]>(
        `SELECT role FROM admins WHERE id = ? LIMIT 1`,
        [req.auth!.id],
      );
      const role = String(roleRows[0]?.role || "");
      if (role !== "super_admin" && role !== "admin") {
        return res.status(403).json({ error: "Forbidden" });
      }
      const id = Number(req.params.id);
      const assignedRaw = req.body?.assigned_admin_id;
      const assignedAdminId =
        assignedRaw === null || assignedRaw === "" ? null : Number(assignedRaw);
      if (
        assignedAdminId != null &&
        (!Number.isFinite(assignedAdminId) || assignedAdminId <= 0)
      ) {
        return res.status(400).json({ error: "Invalid assigned_admin_id" });
      }
      if (assignedAdminId != null) {
        const [aRows] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM admins
           WHERE id = ? AND status = 'active'
             AND role IN ('super_admin','admin','agent')
           LIMIT 1`,
          [assignedAdminId],
        );
        if (!aRows[0]) {
          return res.status(400).json({ error: "Assignee admin not found" });
        }
      }
      const friendly =
        req.body?.friendly_name !== undefined
          ? String(req.body.friendly_name || "").trim() || null
          : undefined;
      if (friendly !== undefined) {
        await pool.query(
          `UPDATE admin_phone_numbers
           SET assigned_admin_id = ?, friendly_name = COALESCE(?, friendly_name)
           WHERE id = ?`,
          [assignedAdminId, friendly, id],
        );
      } else {
        await pool.query(
          `UPDATE admin_phone_numbers SET assigned_admin_id = ? WHERE id = ?`,
          [assignedAdminId, id],
        );
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT n.*, CONCAT(a.first_name,' ',a.last_name) AS assigned_admin_name
         FROM admin_phone_numbers n
         LEFT JOIN admins a ON a.id = n.assigned_admin_id
         WHERE n.id = ? LIMIT 1`,
        [id],
      );
      if (!rows[0]) return res.status(404).json({ error: "Not found" });
      res.json({ number: mapPhoneNumberRow(rows[0]) });
    },
  );

  app.get(
    "/api/admin/conversations",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const view = String(req.query.view || "all");
      const q = String(req.query.q || "")
        .trim()
        .slice(0, 120);
      const page = Math.max(1, parseInt((req.query.page as string) || "1", 10));
      const limit = Math.min(
        100,
        Math.max(1, parseInt((req.query.limit as string) || "50", 10)),
      );
      const adminId = req.auth!.id;
      const ofgIds = await adminAssignedPhoneNumberIds(adminId);
      const clientScope = adminClientConversationScopeSql("cv", adminId, ofgIds);

      // Contact-centric: aggregate client threads visible on my OFG lines or assigned to me
      const where: string[] = ["cv.client_id IS NOT NULL", clientScope.sql];
      const args: any[] = [...clientScope.params];
      if (view === "mine") {
        where.push("cv.assigned_admin_id = ?");
        where.push("cv.status NOT IN ('closed','archived')");
        args.push(adminId);
      } else if (view === "unassigned") {
        where.push("cv.assigned_admin_id IS NULL");
        where.push("cv.status = 'open'");
      } else if (view === "open") {
        where.push("cv.status = 'open'");
      } else if (view === "closed") {
        where.push("cv.status IN ('closed','archived')");
      } else if (view === "unread") {
        where.push("cv.unread_count > 0");
        where.push("cv.status NOT IN ('closed','archived')");
      } else if (view === "all") {
        // Active inbox: hide closed/archived (use Closed filter to find them)
        where.push("cv.status NOT IN ('closed','archived')");
      }
      if (q) {
        const like = likeContains(q);
        where.push(
          `(c.first_name LIKE ? ESCAPE '!' OR c.last_name LIKE ? ESCAPE '!'
            OR c.email LIKE ? ESCAPE '!' OR c.phone LIKE ? ESCAPE '!'
            OR cv.last_message_preview LIKE ? ESCAPE '!')`,
        );
        args.push(like, like, like, like, like);
      }

      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT
           c.id AS contact_id,
           c.id AS client_id,
           CONCAT(c.first_name,' ',c.last_name) AS display_name,
           c.phone, c.email, c.pipeline_stage, c.status AS client_status,
           MAX(cv.last_message_at) AS last_message_at,
           SUBSTRING_INDEX(
             GROUP_CONCAT(cv.last_message_preview ORDER BY cv.last_message_at DESC SEPARATOR '\n'),
             '\n', 1
           ) AS last_message_preview,
           SUM(cv.unread_count) AS unread_count,
           SUBSTRING_INDEX(
             GROUP_CONCAT(cv.status ORDER BY cv.last_message_at DESC),
             ',', 1
           ) AS status,
           SUBSTRING_INDEX(
             GROUP_CONCAT(IFNULL(cv.assigned_admin_id,'') ORDER BY cv.last_message_at DESC),
             ',', 1
           ) AS assigned_admin_id,
           SUBSTRING_INDEX(
             GROUP_CONCAT(cv.id ORDER BY cv.last_message_at DESC),
             ',', 1
           ) AS primary_conversation_id,
           GROUP_CONCAT(DISTINCT cv.channel) AS channels
         FROM conversations cv
         JOIN clients c ON c.id = cv.client_id
         WHERE ${where.join(" AND ")}
         GROUP BY c.id, c.first_name, c.last_name, c.phone, c.email, c.pipeline_stage, c.status
         ORDER BY last_message_at DESC`,
        args,
      );

      const contacts = rows.map((r) => {
        const assignedId = r.assigned_admin_id
          ? Number(r.assigned_admin_id)
          : null;
        return {
          kind: "client" as const,
          contact_id: Number(r.contact_id),
          client_id: Number(r.client_id),
          display_name: String(r.display_name || "").trim() || "Client",
          phone: r.phone,
          email: r.email,
          last_message_at: r.last_message_at,
          last_message_preview: r.last_message_preview
            ? decodeLiteralUnicodeEscapes(String(r.last_message_preview))
            : r.last_message_preview,
          unread_count: Number(r.unread_count || 0),
          status: (r.status as string) || "open",
          assigned_admin_id: assignedId && assignedId > 0 ? assignedId : null,
          channels: String(r.channels || "sms")
            .split(",")
            .filter(Boolean) as any[],
          primary_conversation_id: r.primary_conversation_id
            ? Number(r.primary_conversation_id)
            : null,
          pipeline_stage: r.pipeline_stage,
          client_status: r.client_status,
        };
      });

      let clientTotal = 0;
      if (view !== "unknown") {
        const [clientCountRow] = await pool.query<RowDataPacket[]>(
          `SELECT COUNT(*) AS cnt FROM (
             SELECT c.id
             FROM conversations cv
             JOIN clients c ON c.id = cv.client_id
             WHERE ${where.join(" AND ")}
             GROUP BY c.id
           ) grouped_clients`,
          args,
        );
        clientTotal = Number(clientCountRow[0]?.cnt ?? contacts.length);
      }

      // Unknown queue (when view allows). Close ≠ dismiss: thread status lives on
      // conversations; unknown_contacts.status stays open until linked/dismissed.
      let unknowns: any[] = [];
      let unknownTotal = 0;
      let unkWhereSql = "";
      let unkArgsForCount: any[] = [];
      if (
        view === "unknown" ||
        view === "all" ||
        view === "unassigned" ||
        view === "closed" ||
        view === "open" ||
        view === "mine" ||
        view === "unread"
      ) {
        const phoneIds = await adminAssignedPhoneNumberIds(req.auth!.id);
        if (phoneIds.length) {
          const unkWhere: string[] = [
            `u.status = 'open'`,
            `u.ofg_number_id IN (${phoneIds.map(() => "?").join(",")})`,
          ];
          const unkArgs: any[] = [...phoneIds];
          if (view === "closed") {
            unkWhere.push(
              `EXISTS (
                 SELECT 1 FROM conversations cvu
                 WHERE cvu.unknown_contact_id = u.id
                   AND cvu.status IN ('closed','archived')
               )`,
            );
          } else if (
            view === "open" ||
            view === "unassigned" ||
            view === "mine"
          ) {
            unkWhere.push(
              `(
                 NOT EXISTS (
                   SELECT 1 FROM conversations cvu WHERE cvu.unknown_contact_id = u.id
                 )
                 OR EXISTS (
                   SELECT 1 FROM conversations cvu
                   WHERE cvu.unknown_contact_id = u.id AND cvu.status = 'open'
                 )
               )`,
            );
            if (view === "mine") {
              unkWhere.push(
                `EXISTS (
                   SELECT 1 FROM conversations cvu
                   WHERE cvu.unknown_contact_id = u.id
                     AND cvu.assigned_admin_id = ?
                     AND cvu.status NOT IN ('closed','archived')
                 )`,
              );
              unkArgs.push(adminId);
            }
          } else if (view === "unknown" || view === "all") {
            // Active inbox: hide closed/archived unknown threads
            unkWhere.push(
              `(
                 NOT EXISTS (
                   SELECT 1 FROM conversations cvu WHERE cvu.unknown_contact_id = u.id
                 )
                 OR EXISTS (
                   SELECT 1 FROM conversations cvu
                   WHERE cvu.unknown_contact_id = u.id
                     AND cvu.status NOT IN ('closed','archived')
                 )
               )`,
            );
          } else if (view === "unread") {
            unkWhere.push(
              `(
                 NOT EXISTS (
                   SELECT 1 FROM conversations cvu WHERE cvu.unknown_contact_id = u.id
                 )
                 OR EXISTS (
                   SELECT 1 FROM conversations cvu
                   WHERE cvu.unknown_contact_id = u.id AND cvu.status = 'open'
                 )
               )`,
            );
            unkWhere.push(`u.unread_count > 0`);
          }
          if (q) {
            const like = likeContains(q);
            unkWhere.push(
              `(u.display_name LIKE ? ESCAPE '!' OR u.phone_e164 LIKE ? ESCAPE '!' OR u.email LIKE ? ESCAPE '!' OR u.last_message_preview LIKE ? ESCAPE '!')`,
            );
            unkArgs.push(like, like, like, like);
          }
          unkWhereSql = unkWhere.join(" AND ");
          unkArgsForCount = [...unkArgs];
          const [unknownCountRow] = await pool.query<RowDataPacket[]>(
            `SELECT COUNT(*) AS cnt FROM conversation_unknown_contacts u WHERE ${unkWhereSql}`,
            unkArgsForCount,
          );
          unknownTotal = Number(unknownCountRow[0]?.cnt ?? 0);
          const [urows] = await pool.query<RowDataPacket[]>(
            `SELECT u.*,
               (
                 SELECT cv.status FROM conversations cv
                 WHERE cv.unknown_contact_id = u.id
                 ORDER BY cv.last_message_at DESC, cv.id DESC
                 LIMIT 1
               ) AS thread_status,
               (
                 SELECT cv.id FROM conversations cv
                 WHERE cv.unknown_contact_id = u.id
                 ORDER BY cv.last_message_at DESC, cv.id DESC
                 LIMIT 1
               ) AS primary_conversation_id,
               (
                 SELECT cv.assigned_admin_id FROM conversations cv
                 WHERE cv.unknown_contact_id = u.id
                 ORDER BY cv.last_message_at DESC, cv.id DESC
                 LIMIT 1
               ) AS thread_assigned_admin_id
             FROM conversation_unknown_contacts u
             WHERE ${unkWhereSql}
             ORDER BY u.last_message_at DESC`,
            unkArgs,
          );
          unknowns = urows.map((u) => ({
            kind: "unknown" as const,
            contact_id: Number(u.id),
            unknown_contact_id: Number(u.id),
            display_name:
              String(u.display_name || "").trim() ||
              String(u.phone_e164 || u.email || "Unknown"),
            phone: u.phone_e164,
            email: u.email,
            last_message_at: u.last_message_at,
            last_message_preview: u.last_message_preview
              ? decodeLiteralUnicodeEscapes(String(u.last_message_preview))
              : u.last_message_preview,
            unread_count: Number(u.unread_count || 0),
            status: String(u.thread_status || "open"),
            assigned_admin_id: u.thread_assigned_admin_id
              ? Number(u.thread_assigned_admin_id)
              : null,
            channels: ["sms"],
            primary_conversation_id: u.primary_conversation_id
              ? Number(u.primary_conversation_id)
              : null,
          }));
        }
      }

      // CRM contacts with conversation threads (exclude unknown-only view)
      let crmContacts: any[] = [];
      let crmTotal = 0;
      if (view !== "unknown") {
        const crmWhere: string[] = [
          "ct.deleted_at IS NULL",
          "cv.contact_id IS NOT NULL",
        ];
        const crmArgs: any[] = [];
        if (view === "closed") {
          crmWhere.push("cv.status IN ('closed','archived')");
        } else if (view === "unread") {
          crmWhere.push("cv.status NOT IN ('closed','archived')");
          crmWhere.push("cv.unread_count > 0");
        } else if (view === "mine") {
          crmWhere.push("cv.status NOT IN ('closed','archived')");
          crmWhere.push("cv.assigned_admin_id = ?");
          crmArgs.push(adminId);
        } else if (
          view === "open" ||
          view === "unassigned" ||
          view === "all"
        ) {
          crmWhere.push("cv.status NOT IN ('closed','archived')");
          if (view === "unassigned") {
            crmWhere.push("cv.assigned_admin_id IS NULL");
          }
        }
        if (q) {
          const like = likeContains(q);
          crmWhere.push(
            `(ct.first_name LIKE ? ESCAPE '!' OR ct.last_name LIKE ? ESCAPE '!'
              OR ct.email LIKE ? ESCAPE '!' OR ct.phone LIKE ? ESCAPE '!'
              OR cv.last_message_preview LIKE ? ESCAPE '!')`,
          );
          crmArgs.push(like, like, like, like, like);
        }
        const crmWhereSql = crmWhere.join(" AND ");
        const [crmCountRow] = await pool.query<RowDataPacket[]>(
          `SELECT COUNT(*) AS cnt FROM (
             SELECT ct.id
             FROM conversations cv
             JOIN contacts ct ON ct.id = cv.contact_id
             WHERE ${crmWhereSql}
             GROUP BY ct.id
           ) grouped_crm`,
          crmArgs,
        );
        crmTotal = Number(crmCountRow[0]?.cnt ?? 0);
        const [crmRows] = await pool.query<RowDataPacket[]>(
          `SELECT
             ct.id AS contact_id,
             CONCAT(ct.first_name,' ',ct.last_name) AS display_name,
             ct.phone, ct.email,
             MAX(cv.last_message_at) AS last_message_at,
             SUBSTRING_INDEX(
               GROUP_CONCAT(cv.last_message_preview ORDER BY cv.last_message_at DESC SEPARATOR '\n'),
               '\n', 1
             ) AS last_message_preview,
             SUM(cv.unread_count) AS unread_count,
             SUBSTRING_INDEX(
               GROUP_CONCAT(cv.status ORDER BY cv.last_message_at DESC),
               ',', 1
             ) AS status,
             SUBSTRING_INDEX(
               GROUP_CONCAT(IFNULL(cv.assigned_admin_id,'') ORDER BY cv.last_message_at DESC),
               ',', 1
             ) AS assigned_admin_id,
             SUBSTRING_INDEX(
               GROUP_CONCAT(cv.id ORDER BY cv.last_message_at DESC),
               ',', 1
             ) AS primary_conversation_id,
             GROUP_CONCAT(DISTINCT cv.channel) AS channels
           FROM conversations cv
           JOIN contacts ct ON ct.id = cv.contact_id
           WHERE ${crmWhereSql}
           GROUP BY ct.id, ct.first_name, ct.last_name, ct.phone, ct.email
           ORDER BY last_message_at DESC`,
          crmArgs,
        );
        crmContacts = crmRows.map((r) => {
          const assignedId = r.assigned_admin_id
            ? Number(r.assigned_admin_id)
            : null;
          return {
            kind: "contact" as const,
            contact_id: Number(r.contact_id),
            crm_contact_id: Number(r.contact_id),
            display_name: String(r.display_name || "").trim() || "Contact",
            phone: r.phone,
            email: r.email,
            last_message_at: r.last_message_at,
            last_message_preview: r.last_message_preview
              ? decodeLiteralUnicodeEscapes(String(r.last_message_preview))
              : r.last_message_preview,
            unread_count: Number(r.unread_count || 0),
            status: (r.status as string) || "open",
            assigned_admin_id: assignedId && assignedId > 0 ? assignedId : null,
            channels: String(r.channels || "sms")
              .split(",")
              .filter(Boolean) as any[],
            primary_conversation_id: r.primary_conversation_id
              ? Number(r.primary_conversation_id)
              : null,
          };
        });
      }

      const items =
        view === "unknown"
          ? unknowns
          : [...unknowns, ...contacts, ...crmContacts];
      items.sort((a, b) => {
        const ta = a.last_message_at
          ? new Date(a.last_message_at).getTime()
          : 0;
        const tb = b.last_message_at
          ? new Date(b.last_message_at).getTime()
          : 0;
        return tb - ta;
      });

      const total =
        view === "unknown"
          ? unknownTotal
          : unknownTotal + clientTotal + crmTotal;
      const offset = (page - 1) * limit;
      const paginated = items.slice(offset, offset + limit);

      res.json({
        contacts: paginated,
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.max(1, Math.ceil(total / limit)),
        },
      });
    },
  );

  app.get(
    "/api/admin/conversations/contact/:kind/:id/timeline",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const kind = String(req.params.kind);
      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid id" });

      if (kind === "unknown") {
        if (!(await adminCanAccessUnknownContact(req.auth!.id, id))) {
          return res.status(404).json({ error: "Not found" });
        }
        const [urows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM conversation_unknown_contacts WHERE id = ? LIMIT 1`,
          [id],
        );
        if (!urows[0]) return res.status(404).json({ error: "Not found" });
        const [convRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, channel, status, assigned_admin_id, ofg_number_id, unread_count, last_message_at
           FROM conversations WHERE unknown_contact_id = ? ORDER BY last_message_at DESC`,
          [id],
        );
        const convIds = convRows.map((c) => Number(c.id));
        let messages: RowDataPacket[] = [];
        if (convIds.length) {
          const [m] = await pool.query<RowDataPacket[]>(
            `SELECT m.*, CONCAT(a.first_name,' ',a.last_name) AS sent_by_admin_name
             FROM conversation_messages m
             LEFT JOIN admins a ON a.id = m.sent_by_admin_id
             WHERE m.conversation_id IN (?)
             ORDER BY m.id ASC LIMIT 500`,
            [convIds],
          );
          messages = m;
        }
        await pool.query(
          `UPDATE conversation_unknown_contacts SET unread_count = 0 WHERE id = ?`,
          [id],
        );
        return res.json({
          kind: "unknown",
          contact: urows[0],
          threads: convRows,
          messages: messages.map(mapConversationMessageApiRow),
        });
      }

      if (kind === "contact") {
        const [crows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM contacts WHERE id = ? AND deleted_at IS NULL LIMIT 1`,
          [id],
        );
        if (!crows[0]) return res.status(404).json({ error: "Not found" });
        const [convRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, channel, status, assigned_admin_id, ofg_number_id, unread_count, last_message_at
           FROM conversations WHERE contact_id = ? ORDER BY last_message_at DESC`,
          [id],
        );
        const convIds = convRows.map((c) => Number(c.id));
        let messages: RowDataPacket[] = [];
        if (convIds.length) {
          const [m] = await pool.query<RowDataPacket[]>(
            `SELECT m.*, CONCAT(a.first_name,' ',a.last_name) AS sent_by_admin_name
             FROM conversation_messages m
             LEFT JOIN admins a ON a.id = m.sent_by_admin_id
             WHERE m.conversation_id IN (?)
             ORDER BY m.id ASC LIMIT 500`,
            [convIds],
          );
          messages = m;
          await pool.query(
            `UPDATE conversations SET unread_count = 0
             WHERE contact_id = ? AND id IN (?)`,
            [id, convIds],
          );
        }
        return res.json({
          kind: "contact",
          contact: mapCrmContactRow(crows[0]),
          threads: convRows,
          messages: messages.map(mapConversationMessageApiRow),
        });
      }

      // client — only threads on my OFG line(s) or assigned to me
      if (!(await adminCanAccessClientConversations(req.auth!.id, id))) {
        return res.status(404).json({ error: "Not found" });
      }
      const [crows] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, last_name, email, phone, status, pipeline_stage, preferred_language
         FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!crows[0]) return res.status(404).json({ error: "Client not found" });
      const ofgIds = await adminAssignedPhoneNumberIds(req.auth!.id);
      const scope = adminClientConversationScopeSql("cv", req.auth!.id, ofgIds);
      const [threads] = await pool.query<RowDataPacket[]>(
        `SELECT cv.id, cv.channel, cv.status, cv.assigned_admin_id, cv.ofg_number_id,
                cv.unread_count, cv.last_message_at
         FROM conversations cv
         WHERE cv.client_id = ? AND ${scope.sql}
         ORDER BY cv.last_message_at DESC`,
        [id, ...scope.params],
      );
      const convIds = threads.map((t) => Number(t.id));
      let messages: RowDataPacket[] = [];
      if (convIds.length) {
        const [m] = await pool.query<RowDataPacket[]>(
          `SELECT m.*, CONCAT(a.first_name,' ',a.last_name) AS sent_by_admin_name
           FROM conversation_messages m
           LEFT JOIN admins a ON a.id = m.sent_by_admin_id
           WHERE m.conversation_id IN (?)
           ORDER BY m.id ASC LIMIT 500`,
          [convIds],
        );
        messages = m;
        await pool.query(
          `UPDATE conversations SET unread_count = 0
           WHERE client_id = ? AND id IN (?)`,
          [id, convIds],
        );
      }
      res.json({
        kind: "client",
        contact: crows[0],
        threads,
        messages: messages.map(mapConversationMessageApiRow),
      });
    },
  );

  app.post(
    "/api/admin/conversations/messages/:messageId/retry-call-insights",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const messageId = Number(req.params.messageId);
      if (!(messageId > 0)) {
        return res.status(400).json({ error: "Invalid message id" });
      }
      try {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT m.id, m.channel, m.recording_url, m.provider_message_id,
                  m.metadata_json, m.conversation_id,
                  c.client_id, c.unknown_contact_id, c.contact_id,
                  c.ofg_number_id, c.assigned_admin_id
           FROM conversation_messages m
           JOIN conversations c ON c.id = m.conversation_id
           WHERE m.id = ?
           LIMIT 1`,
          [messageId],
        );
        const row = rows[0];
        if (!row || String(row.channel) !== "call") {
          return res.status(404).json({ error: "Not found" });
        }

        const adminId = req.auth!.id;
        let allowed = false;
        if (row.client_id != null) {
          allowed = await adminCanAccessClientConversations(
            adminId,
            Number(row.client_id),
          );
        } else if (row.unknown_contact_id != null) {
          allowed = await adminCanAccessUnknownContact(
            adminId,
            Number(row.unknown_contact_id),
          );
        } else if (row.contact_id != null) {
          // CRM contacts: any conversations-enabled admin can retry
          allowed = true;
        } else {
          const ofgIds = await adminAssignedPhoneNumberIds(adminId);
          const ofgOk =
            row.ofg_number_id != null &&
            ofgIds.includes(Number(row.ofg_number_id));
          const assigneeOk =
            row.assigned_admin_id != null &&
            Number(row.assigned_admin_id) === adminId;
          allowed = ofgOk || assigneeOk;
        }
        if (!allowed) {
          return res.status(403).json({ error: "Forbidden" });
        }

        if (!row.recording_url) {
          let meta: Record<string, unknown> = {};
          try {
            meta =
              typeof row.metadata_json === "string"
                ? JSON.parse(row.metadata_json)
                : (row.metadata_json as any) || {};
          } catch {
            meta = {};
          }
          await pullAndAttachTwilioRecording(messageId, [
            String(row.provider_message_id || ""),
            String(meta.call_sid || ""),
            String(meta.parent_call_sid || ""),
          ]);
        }

        const [hasRec] = await pool.query<RowDataPacket[]>(
          `SELECT recording_url FROM conversation_messages WHERE id = ? LIMIT 1`,
          [messageId],
        );
        if (!hasRec[0]?.recording_url) {
          return res
            .status(409)
            .json({ error: "Recording not available yet" });
        }

        // Force re-queue even from ready (e.g. transcript-only, Claude retry).
        await pool.query(
          `UPDATE conversation_messages
           SET call_insights_status = 'pending',
               call_insights_error = NULL,
               call_insights_updated_at = NOW()
           WHERE id = ? AND channel = 'call'`,
          [messageId],
        );
        await publishCallInsightsRealtime(
          Number(row.conversation_id),
          messageId,
          { call_insights_status: "pending", call_insights_error: null },
        );
        await processCallInsightsForMessage(messageId);

        const [out] = await pool.query<RowDataPacket[]>(
          `SELECT m.*, CONCAT(a.first_name,' ',a.last_name) AS sent_by_admin_name
           FROM conversation_messages m
           LEFT JOIN admins a ON a.id = m.sent_by_admin_id
           WHERE m.id = ?
           LIMIT 1`,
          [messageId],
        );
        const updated = out[0];
        if (!updated) {
          return res.status(500).json({ error: "Message missing after retry" });
        }
        return res.json({
          ok: true,
          message: mapConversationMessageApiRow(updated),
        });
      } catch (e: any) {
        console.error("[call-insights] retry", messageId, e?.message ?? e);
        return res
          .status(500)
          .json({ error: String(e?.message || "Retry failed") });
      }
    },
  );

  app.post(
    "/api/admin/conversations/media/upload",
    requireAdmin,
    denyAffiliateAccess,
    upload.single("file"),
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const file = req.file;
      if (!file) {
        return res.status(400).json({ error: "No file provided" });
      }
      if (!MMS_ALLOWED_CONTENT_TYPES.has(file.mimetype)) {
        return res.status(400).json({ error: "Unsupported file type" });
      }
      if (file.size > MMS_MAX_BYTES) {
        return res.status(400).json({ error: "File too large (max 4MB)" });
      }
      try {
        const stored = await persistMmsMedia({
          buffer: file.buffer,
          contentType: file.mimetype,
          filename: file.originalname,
          adminId: req.auth!.id,
        });
        return res.json({
          success: true,
          url: stored.publicUrl,
          content_type: file.mimetype,
          filename: file.originalname,
          cdn_url: stored.cdnUrl,
        });
      } catch (e: any) {
        console.error("[mms:upload]", e);
        return res
          .status(500)
          .json({ error: String(e?.message || "Upload failed") });
      }
    },
  );

  app.get("/api/conversations/media/public/:id", async (req, res) => {
    const id = String(req.params.id || "");
    if (!MMS_UUID_RE.test(id)) {
      return res.status(400).json({ error: "Invalid media ID" });
    }
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT content_type, data FROM mms_media
       WHERE id = ? AND expires_at > NOW() LIMIT 1`,
      [id],
    );
    if (!rows[0]) {
      return res.status(404).json({ error: "Media not found or expired" });
    }
    const contentType = String(
      rows[0].content_type || "application/octet-stream",
    );
    const raw = rows[0].data;
    let buf: Buffer;
    if (Buffer.isBuffer(raw)) buf = raw;
    else if (raw instanceof Uint8Array) buf = Buffer.from(raw);
    else if (typeof raw === "string") buf = Buffer.from(raw, "binary");
    else buf = Buffer.from(raw as ArrayBuffer);
    res.set("Content-Type", contentType);
    res.set("Cache-Control", "public, max-age=3600");
    res.set("Content-Length", String(buf.length));
    return res.end(buf);
  });

  /**
   * Proxy Twilio (and allowed CDN) MMS URLs for <img>/<video> tags.
   * Browsers cannot send Authorization on media elements — same pattern as
   * real-state GET /api/sms/media (?token= + Basic fetch upstream).
   */
  app.get("/api/conversations/media", async (req, res) => {
    const token = String(req.query.token || "").trim();
    if (!token) return res.status(401).json({ error: "Missing token" });
    const payload = verifySessionToken(token);
    if (!payload || payload.actor !== "admin") {
      return res.status(401).json({ error: "Invalid token" });
    }
    if (!(await isSessionActive(payload))) {
      return res.status(401).json({ error: "Invalid token" });
    }

    const rawUrl = String(req.query.url || "").trim();
    if (!rawUrl) return res.status(400).json({ error: "Missing url" });

    const isTwilioUrl = rawUrl.startsWith("https://api.twilio.com/");
    const isCdnUrl = rawUrl.startsWith("https://disruptinglabs.com/");
    if (!isTwilioUrl && !isCdnUrl) {
      return res.status(400).json({ error: "Invalid media URL" });
    }

    const twilioAccountSid = process.env.TWILIO_ACCOUNT_SID;
    const twilioAuthToken = process.env.TWILIO_AUTH_TOKEN;
    if (isTwilioUrl && (!twilioAccountSid || !twilioAuthToken)) {
      return res.status(503).json({ error: "Twilio not configured" });
    }

    try {
      const upstream = await fetch(rawUrl, {
        headers: isTwilioUrl
          ? {
              Authorization: `Basic ${Buffer.from(
                `${twilioAccountSid}:${twilioAuthToken}`,
              ).toString("base64")}`,
            }
          : {},
        redirect: "follow",
      });
      if (!upstream.ok) {
        console.warn(
          "[conversations:media-proxy] upstream",
          upstream.status,
          rawUrl.slice(0, 120),
        );
        return res
          .status(upstream.status)
          .json({ error: "Media fetch failed" });
      }
      const contentType =
        upstream.headers.get("content-type") || "application/octet-stream";
      res.set("Content-Type", contentType);
      res.set("Cache-Control", "private, max-age=86400");
      const buffer = Buffer.from(await upstream.arrayBuffer());
      return res.send(buffer);
    } catch (e: any) {
      console.warn("[conversations:media-proxy]", e?.message || e);
      return res.status(500).json({ error: "Internal error" });
    }
  });

  app.post(
    "/api/admin/conversations/send",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const {
        client_id,
        unknown_contact_id,
        contact_id,
        channel,
        body,
        is_internal_note,
        ofg_number_id,
        media_url,
        media_content_type,
      } = req.body || {};
      const mediaUrlRaw =
        media_url != null && String(media_url).trim()
          ? String(media_url).trim()
          : null;
      const textBody = body != null ? String(body) : "";
      const hasClient = client_id != null && Number(client_id) > 0;
      const hasUnknown =
        unknown_contact_id != null && Number(unknown_contact_id) > 0;
      const hasCrm = contact_id != null && Number(contact_id) > 0;
      if (
        [hasClient, hasUnknown, hasCrm].filter(Boolean).length !== 1 ||
        (!textBody.trim() && !mediaUrlRaw)
      ) {
        return res.status(400).json({ error: "Missing fields" });
      }
      try {
        const mediaUrl = mediaUrlRaw
          ? await resolveConversationOutboundMedia(mediaUrlRaw)
          : null;
        const result = await deliverHubConversationMessage({
          adminId: req.auth!.id,
          clientId: hasClient ? Number(client_id) : undefined,
          unknownContactId: hasUnknown ? Number(unknown_contact_id) : undefined,
          crmContactId: hasCrm ? Number(contact_id) : undefined,
          channel: String(channel || "sms"),
          textBody,
          isInternalNote: !!is_internal_note,
          ofgNumberId:
            ofg_number_id != null ? Number(ofg_number_id) : undefined,
          mediaUrl,
          mediaContentType: media_content_type,
        });
        return res.json(result);
      } catch (e: any) {
        const msg = String(e?.message || e);
        if (
          e?.code === "conversation_closed" ||
          msg === "conversation_closed"
        ) {
          return res.status(409).json({ error: "conversation_closed" });
        }
        if (/not found/i.test(msg)) {
          return res.status(404).json({ error: msg });
        }
        if (
          /required|unsupported|internal notes|invalid media|expired|exceeds/i.test(
            msg,
          )
        ) {
          return res.status(400).json({ error: msg });
        }
        console.error("[conversations:send]", msg);
        return res.status(500).json({ error: "Send failed" });
      }
    },
  );

  app.post(
    "/api/admin/conversations/start",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      try {
        const phoneRaw = String(req.body?.phone || "").trim();
        const textBody = req.body?.body != null ? String(req.body.body) : "";
        const {
          ofg_number_id,
          media_url,
          media_content_type,
          channel,
          is_internal_note,
        } = req.body || {};
        if (!phoneRaw) {
          return res.status(400).json({ error: "phone is required" });
        }
        if (!textBody.trim() && !media_url) {
          return res.status(400).json({ error: "body or media required" });
        }
        if (!normalizePhoneLast10(phoneRaw)) {
          return res.status(400).json({
            error: "phone must include at least 10 digits",
          });
        }
        const assigned = await listAssignedPhoneNumbers(req.auth!.id);
        const ofgNumberId =
          ofg_number_id != null
            ? Number(ofg_number_id)
            : assigned[0]
              ? Number(assigned[0].id)
              : null;
        if (
          !ofgNumberId ||
          !assigned.some((n) => Number(n.id) === ofgNumberId)
        ) {
          return res.status(400).json({
            error: "No OFG phone number assigned — cannot send SMS",
          });
        }
        const mediaUrlRaw =
          media_url != null && String(media_url).trim()
            ? String(media_url).trim()
            : null;
        const mediaUrl = mediaUrlRaw
          ? await resolveConversationOutboundMedia(mediaUrlRaw)
          : null;

        const existingClientId = await findClientIdByPhone(phoneRaw);
        if (existingClientId) {
          const result = await deliverHubConversationMessage({
            adminId: req.auth!.id,
            clientId: existingClientId,
            channel: String(channel || "sms"),
            textBody,
            isInternalNote: !!is_internal_note,
            ofgNumberId,
            mediaUrl,
            mediaContentType: media_content_type,
          });
          return res.json({ kind: "client", ...result });
        }

        const existingContactId = await findContactIdByPhone(phoneRaw);
        if (existingContactId) {
          const result = await deliverHubConversationMessage({
            adminId: req.auth!.id,
            crmContactId: existingContactId,
            channel: "sms",
            textBody,
            ofgNumberId,
            mediaUrl,
            mediaContentType: media_content_type,
          });
          return res.json({ kind: "contact", ...result });
        }

        const { unknownId, created, phoneE164 } =
          await findOrCreateOpenUnknownContact({
            phoneRaw,
            ofgNumberId,
            assignedAdminId: req.auth!.id,
          });
        // deliverHub owns getOrCreate (with reopenIfClosed:false) after closed gate
        const result = await deliverHubConversationMessage({
          adminId: req.auth!.id,
          unknownContactId: unknownId,
          channel: "sms",
          textBody,
          ofgNumberId,
          mediaUrl,
          mediaContentType: media_content_type,
        });
        return res.json({
          kind: "unknown",
          unknown_created: created,
          phone: phoneE164,
          ...result,
        });
      } catch (e: any) {
        const msg = String(e?.message || e);
        if (
          e?.code === "conversation_closed" ||
          msg === "conversation_closed"
        ) {
          return res.status(409).json({ error: "conversation_closed" });
        }
        if (/not found/i.test(msg)) {
          return res.status(404).json({ error: msg });
        }
        if (/required|invalid media|expired|digits|exceeds/i.test(msg)) {
          return res.status(400).json({ error: msg });
        }
        console.error("[conversations:start]", msg);
        return res.status(500).json({ error: "Start failed" });
      }
    },
  );

  app.post(
    "/api/admin/conversations/suggest-replies",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!(await requireConversationsAccess(req, res))) return;
      const kind = String(req.body?.kind || "").trim();
      const contactId = Number(req.body?.contact_id);
      const recentMessages = Array.isArray(req.body?.recent_messages)
        ? req.body.recent_messages.slice(-8).map((m: any) => ({
            direction: String(m?.direction || ""),
            body: String(m?.body || "").slice(0, 400),
          }))
        : [];
      if (!["client", "unknown", "contact"].includes(kind) || !contactId) {
        return res.status(400).json({ error: "Invalid kind or contact_id" });
      }

      let context: {
        displayName: string;
        phone?: string | null;
        pipelineStage?: string | null;
        clientStatus?: string | null;
        preferredLanguage?: string | null;
      } = { displayName: "there" };

      if (kind === "client") {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name, phone, pipeline_stage, status, preferred_language
           FROM clients WHERE id = ? LIMIT 1`,
          [contactId],
        );
        if (!rows[0])
          return res.status(404).json({ error: "Client not found" });
        const c = rows[0];
        context = {
          displayName:
            `${c.first_name || ""} ${c.last_name || ""}`.trim() || "there",
          phone: c.phone,
          pipelineStage: c.pipeline_stage,
          clientStatus: c.status,
          preferredLanguage: c.preferred_language,
        };
      } else if (kind === "contact") {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name, phone, preferred_language
           FROM contacts
           WHERE id = ? AND deleted_at IS NULL LIMIT 1`,
          [contactId],
        );
        if (!rows[0])
          return res.status(404).json({ error: "Contact not found" });
        const c = rows[0];
        context = {
          displayName:
            `${c.first_name || ""} ${c.last_name || ""}`.trim() || "there",
          phone: c.phone,
          preferredLanguage: c.preferred_language,
        };
      } else {
        if (!(await adminCanAccessUnknownContact(req.auth!.id, contactId))) {
          return res.status(404).json({ error: "Not found" });
        }
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT phone_e164, display_name FROM conversation_unknown_contacts
           WHERE id = ? LIMIT 1`,
          [contactId],
        );
        if (!rows[0]) return res.status(404).json({ error: "Not found" });
        context = {
          displayName:
            String(rows[0].display_name || "").trim() ||
            String(rows[0].phone_e164 || "there"),
          phone: rows[0].phone_e164,
          pipelineStage: "unknown",
          clientStatus: "unknown",
        };
      }

      const lang = context.preferredLanguage === "es" ? "es" : "en";
      const aiSuggestions: Array<{ id: string; label: string; body: string }> =
        [];

      if (
        adminAiFeatureEnabled() &&
        String(process.env.ANTHROPIC_API_KEY || "").trim() &&
        req.body?.include_ai !== false
      ) {
        try {
          const threadLines = recentMessages
            .filter((m) => m.body.trim())
            .map(
              (m) =>
                `${m.direction === "inbound" ? "Contact" : "Staff"}: ${m.body}`,
            )
            .join("\n");
          const sys = `You suggest short SMS replies for Optimum Credit staff (credit repair). Return ONLY valid JSON: {"suggestions":[{"label":"short chip","body":"full SMS under 320 chars"}]}. Max 3 suggestions. Language: ${lang === "es" ? "Spanish" : "English"}. Context: ${context.clientStatus || "unknown"} / stage ${context.pipelineStage || "unknown"}. Be warm, professional, actionable. No markdown.`;
          const userMsg = `Contact: ${context.displayName}\nThread:\n${threadLines || "(no messages yet)"}\n\nSuggest replies to move toward enrollment (prospect → new client) or help with docs.`;
          const aiRes = await axios.post(
            "https://api.anthropic.com/v1/messages",
            {
              model:
                String(process.env.ANTHROPIC_MODEL || "").trim() ||
                "claude-sonnet-4-6",
              max_tokens: 800,
              system: sys,
              messages: [{ role: "user", content: userMsg }],
            },
            {
              headers: {
                "x-api-key": String(process.env.ANTHROPIC_API_KEY || "").trim(),
                "anthropic-version": "2023-06-01",
                "content-type": "application/json",
              },
              timeout: 25_000,
              validateStatus: () => true,
            },
          );
          if (aiRes.status >= 200 && aiRes.status < 300) {
            const text = (
              Array.isArray(aiRes.data?.content) ? aiRes.data.content : []
            )
              .filter((b: any) => b?.type === "text")
              .map((b: any) => b.text)
              .join("");
            const jsonMatch = text.match(/\{[\s\S]*\}/);
            if (jsonMatch) {
              const parsed = JSON.parse(jsonMatch[0]) as {
                suggestions?: Array<{ label?: string; body?: string }>;
              };
              for (const [i, s] of (parsed.suggestions || [])
                .slice(0, 3)
                .entries()) {
                const body = decodeLiteralUnicodeEscapes(
                  String(s.body || "").trim(),
                ).slice(0, 480);
                if (!body) continue;
                aiSuggestions.push({
                  id: `ai-${i}`,
                  label: decodeLiteralUnicodeEscapes(
                    String(s.label || body),
                  ).slice(0, 48),
                  body,
                });
              }
            }
          }
        } catch (e: any) {
          console.warn("[conversations:suggest]", e?.message || e);
        }
      }

      res.json({
        ok: true,
        context,
        ai_suggestions: aiSuggestions,
      });
    },
  );

